# ---------------------------------------------------------------------------
# Hardware interface protocols (enable loose coupling & testability)
# ---------------------------------------------------------------------------

@runtime_checkable
class XYStageProtocol(Protocol):
    """Minimal interface for any XY stage driver."""
    def move_x(self, steps: int) -> None: ...
    def move_y(self, steps: int) -> None: ...
    def close(self) -> None: ...


@runtime_checkable
class ZStageProtocol(Protocol):
    """Minimal interface for any Z axis driver."""
    def move_up(self, step: float) -> None: ...
    def move_down(self, step: float) -> None: ...
    def close(self) -> None: ...


# ---------------------------------------------------------------------------
# PID Controller (adaptive, anti-windup)
# ---------------------------------------------------------------------------

class PIDController:
    """Discrete PID controller with anti-windup and adaptive gain scheduling.

    Adopted from deep-learning adaptive optics research:
    instead of fixed step sizes, a PID loop converts pixel error
    directly into motor steps, enabling smoother convergence and
    reduced overshoot.
    """

    def __init__(
        self,
        kp: float = 1.0,
        ki: float = 0.0,
        kd: float = 0.0,
        output_min: Optional[int] = None,
        output_max: Optional[int] = None,
        integral_limit: Optional[float] = None,
        setpoint: float = 0.0,
    ):
        self.kp = float(kp)
        self.ki = float(ki)
        self.kd = float(kd)
        self.output_min = output_min
        self.output_max = output_max
        self.integral_limit = integral_limit
        self.setpoint = float(setpoint)
        self._integral: float = 0.0
        self._prev_error: Optional[float] = None
        self._prev_time: Optional[float] = None

    def reset(self) -> None:
        self._integral = 0.0
        self._prev_error = None
        self._prev_time = None

    def update(self, measurement: float, current_time: Optional[float] = None) -> int:
        if current_time is None:
            current_time = time.time()
        error = self.setpoint - measurement
        dt = (current_time - self._prev_time) if self._prev_time is not None else 0.0
        self._prev_time = current_time

        # Proportional
        p_term = self.kp * error

        # Integral with anti-windup
        if dt > 0:
            self._integral += error * dt
            if self.integral_limit is not None:
                self._integral = max(-self.integral_limit, min(self.integral_limit, self._integral))
        i_term = self.ki * self._integral

        # Derivative (on measurement to avoid setpoint kick)
        d_term = 0.0
        if self._prev_error is not None and dt > 0:
            d_term = self.kd * (error - self._prev_error) / dt
        self._prev_error = error

        output = p_term + i_term + d_term
        output_int = int(round(output))

        if self.output_min is not None:
            output_int = max(self.output_min, output_int)
        if self.output_max is not None:
            output_int = min(self.output_max, output_int)

        return output_int

    def set_gains(self, kp: Optional[float] = None, ki: Optional[float] = None, kd: Optional[float] = None) -> None:
        if kp is not None:
            self.kp = float(kp)
        if ki is not None:
            self.ki = float(ki)
        if kd is not None:
            self.kd = float(kd)


# ---------------------------------------------------------------------------
# Logging setup with file rotation
# ---------------------------------------------------------------------------

def setup_logging(
    level: str = "INFO",
    log_file: Optional[str] = None,
    max_bytes: int = 5 * 1024 * 1024,
    backup_count: int = 3,
) -> None:
    """Configure root SpotZoom logger with console + optional rotating file handler."""
    log_level = getattr(logging, level.upper(), logging.INFO)
    root_logger = logging.getLogger("SpotZoom")
    root_logger.setLevel(log_level)

    fmt = _LocalizedLogFormatter("%(asctime)s [%(levelname)s] %(name)s: %(message)s")

    if not root_logger.handlers:
        console = logging.StreamHandler(sys.stdout)
        console.setLevel(log_level)
        console.setFormatter(fmt)
        root_logger.addHandler(console)

    if log_file:
        log_path = Path(log_file).expanduser()
        log_path.parent.mkdir(parents=True, exist_ok=True)
        file_handler = logging.handlers.RotatingFileHandler(
            str(log_path), maxBytes=max_bytes, backupCount=backup_count, encoding="utf-8"
        )
        file_handler.setLevel(log_level)
        file_handler.setFormatter(fmt)
        root_logger.addHandler(file_handler)


# ---------------------------------------------------------------------------
# Configuration file support (YAML / JSON)
# ---------------------------------------------------------------------------

def load_config_file(config_path: str) -> Dict:
    """Load configuration from a YAML or JSON file.

    Returns a flat dictionary of parameter names to values, suitable
    for overriding argparse defaults.
    """
    path = Path(config_path).expanduser()
    if not path.exists():
        raise FileNotFoundError(f"Configuration file not found: {config_path}")

    if path.suffix.lower() in (".yaml", ".yml"):
        try:
            import yaml
        except ModuleNotFoundError as exc:
            raise RuntimeError(
                "PyYAML is required to load .yaml config files. "
                "Install with: python -m pip install pyyaml"
            ) from exc
        with path.open("r", encoding="utf-8") as fp:
            data = yaml.safe_load(fp) or {}
    elif path.suffix.lower() == ".json":
        with path.open("r", encoding="utf-8") as fp:
            data = json.load(fp)
    else:
        raise ValueError(f"Unsupported config file format: {path.suffix}. Use .yaml, .yml, or .json")

    if not isinstance(data, dict):
        raise ValueError(f"Configuration file root must be a mapping, got {type(data).__name__}")
    return data


