def apply_open_source_bundle(args: argparse.Namespace) -> argparse.Namespace:
    """Apply additive open-source feature bundle presets to parsed CLI args."""
    bundle_name = str(getattr(args, "frontier_open_source_bundle", "none") or "none").strip().lower()
    if bundle_name not in _OPEN_SOURCE_BUNDLE_PRESETS:
        allowed = ", ".join(sorted(_OPEN_SOURCE_BUNDLE_PRESETS))
        raise ValueError(f"Unsupported --frontier-open-source-bundle value: {bundle_name}. Allowed: {allowed}")

    setattr(args, "frontier_open_source_bundle", bundle_name)
    preset = _OPEN_SOURCE_BUNDLE_PRESETS[bundle_name]
    if not preset:
        return args

    enabled_features: List[str] = []
    for attr, desired in preset.items():
        if not desired or not hasattr(args, attr):
            continue
        current = bool(getattr(args, attr))
        if not current:
            setattr(args, attr, True)
            enabled_features.append(attr)

    if enabled_features:
        LOGGER.info(
            "Applied open-source bundle '%s' (%d feature flags): %s",
            bundle_name,
            len(enabled_features),
            ", ".join(enabled_features),
        )
    else:
        LOGGER.info("Open-source bundle '%s' active; all mapped feature flags already enabled", bundle_name)
    return args


@dataclass
class SpotDetection:
    center: Tuple[int, int]
    bbox: Tuple[int, int, int, int]
    confidence: float
    label: str
    class_id: int

    def to_payload(self) -> dict:
        return {
            "center": [int(self.center[0]), int(self.center[1])],
            "bbox": [int(v) for v in self.bbox],
            "confidence": float(self.confidence),
            "label": self.label,
            "class_id": int(self.class_id),
        }

    @classmethod
    def from_payload(cls, payload: dict) -> "SpotDetection":
        return cls(
            center=(int(payload["center"][0]), int(payload["center"][1])),
            bbox=tuple(int(v) for v in payload["bbox"]),
            confidence=float(payload["confidence"]),
            label=str(payload["label"]),
            class_id=int(payload["class_id"]),
        )


