class RunLockFile:
    """Best-effort run lock to prevent concurrent hardware-control runs."""

    def __init__(self, lock_path: str, stale_seconds: float = 7200.0):
        self.lock_path = Path(lock_path).expanduser()
        self.stale_seconds = max(1.0, float(stale_seconds))
        self._acquired = False
        self._pid = os.getpid()

    @staticmethod
    def _pid_exists(pid: int) -> bool:
        if pid <= 0:
            return False
        try:
            os.kill(pid, 0)
            return True
        except PermissionError:
            return True
        except OSError:
            return False

    def _read_lock_payload(self) -> Optional[dict]:
        try:
            with self.lock_path.open("r", encoding="utf-8-sig") as fp:
                payload = json.load(fp)
                return payload if isinstance(payload, dict) else None
        except Exception:
            return None

    def _try_remove_stale(self) -> bool:
        payload = self._read_lock_payload() or {}
        pid = int(payload.get("pid", 0) or 0)
        created_unix = float(payload.get("created_unix", 0.0) or 0.0)
        age_s = max(0.0, time.time() - created_unix) if created_unix > 0 else None
        stale = (age_s is not None and age_s >= self.stale_seconds) or not self._pid_exists(pid)
        if not stale:
            return False
        try:
            self.lock_path.unlink()
            LOGGER.warning("Removed stale run lock: %s (pid=%s age_s=%s)", self.lock_path, pid, age_s)
            return True
        except FileNotFoundError:
            return True
        except Exception:
            return False

    def acquire(self) -> None:
        self.lock_path.parent.mkdir(parents=True, exist_ok=True)
        for _ in range(3):
            try:
                with self.lock_path.open("x", encoding="utf-8") as fp:
                    json.dump(
                        {
                            "pid": int(self._pid),
                            "created_at": _utc_iso_now(),
                            "created_unix": float(time.time()),
                            "command": " ".join(sys.argv),
                        },
                        fp,
                        ensure_ascii=False,
                        indent=2,
                    )
                self._acquired = True
                return
            except FileExistsError:
                if not self._try_remove_stale():
                    payload = self._read_lock_payload() or {}
                    holder_pid = payload.get("pid", "unknown")
                    holder_since = payload.get("created_at", "unknown")
                    raise RuntimeError(
                        f"已有其他 SpotZoom 进程持有运行锁：{self.lock_path} (pid={holder_pid}, created_at={holder_since})"
                    )
        raise RuntimeError(f"多次重试后仍无法获取运行锁：{self.lock_path}")

    def release(self) -> bool:
        if not self._acquired:
            return False
        try:
            payload = self._read_lock_payload() or {}
            holder_pid = int(payload.get("pid", 0) or 0)
            if holder_pid in (0, self._pid):
                self.lock_path.unlink(missing_ok=True)
            else:
                LOGGER.warning("锁文件不属于当前 PID，跳过释放：%s", self.lock_path)
        finally:
            self._acquired = False
        return True


class RunReporter:
    def __init__(self, report_path: Optional[str], event_stream_path: Optional[str] = None):
        self.report_path = Path(report_path).expanduser() if report_path else None
        self.event_stream_path = Path(event_stream_path).expanduser() if event_stream_path else None
        self.metrics = RuntimeMetrics()
        self._events: Deque[dict] = deque(maxlen=300)
        self._detector_latency_ms: Deque[float] = deque(maxlen=800)

    def event(self, name: str, **payload) -> None:
        event = {"ts": _utc_iso_now(), "event": name}
        if payload:
            event.update(payload)
        self._events.append(event)
        if self.event_stream_path is not None:
            try:
                self.event_stream_path.parent.mkdir(parents=True, exist_ok=True)
                with self.event_stream_path.open("a", encoding="utf-8") as fp:
                    fp.write(json.dumps(event, ensure_ascii=False) + "\n")
            except Exception as exc:
                LOGGER.warning("追加事件流失败 %s：%s", self.event_stream_path, exc)

    def _detector_latency_percentiles(self) -> Dict[str, Optional[float]]:
        if not self._detector_latency_ms:
            return {
                "count": 0,
                "mean_ms": None,
                "p50_ms": None,
                "p95_ms": None,
                "p99_ms": None,
            }
        data = np.asarray(self._detector_latency_ms, dtype=np.float64)
        return {
            "count": int(data.size),
            "mean_ms": round(float(np.mean(data)), 6),
            "p50_ms": round(float(np.percentile(data, 50)), 6),
            "p95_ms": round(float(np.percentile(data, 95)), 6),
            "p99_ms": round(float(np.percentile(data, 99)), 6),
        }

    def record_detector_inference(
        self,
        latency_ms: float,
        *,
        tag: Optional[str] = None,
        attempt: Optional[int] = None,
        source: str = "primary",
        succeeded: bool = True,
    ) -> None:
        latency = max(0.0, float(latency_ms))
        self._detector_latency_ms.append(latency)
        self.metrics.detector_inference_calls += 1
        if not succeeded:
            self.metrics.detector_inference_failures += 1

        self.metrics.detector_inference_peak_ms = max(
            float(self.metrics.detector_inference_peak_ms),
            float(latency),
        )
        if latency >= 50.0:
            self.metrics.detector_inference_over_50ms += 1
        if latency >= 100.0:
            self.metrics.detector_inference_over_100ms += 1
        if latency >= 200.0:
            self.metrics.detector_inference_over_200ms += 1
            self.metrics.frontier_v48_latency_alerts += 1
            percentiles = self._detector_latency_percentiles()
            self.event(
                "frontier_v48_latency_alert",
                tag=tag,
                attempt=attempt,
                source=str(source),
                latency_ms=round(latency, 6),
                p95_ms=percentiles.get("p95_ms"),
                p99_ms=percentiles.get("p99_ms"),
                succeeded=bool(succeeded),
            )

    def flush(self, status: str, error: Optional[str] = None) -> None:
        if self.report_path is None:
            return
        self.report_path.parent.mkdir(parents=True, exist_ok=True)
        elapsed_s = round(time.time() - self.metrics.start_time_s, 3)
        metrics_payload = dict(self.metrics.__dict__)
        metrics_payload.pop("start_time_s", None)
        latency_summary = self._detector_latency_percentiles()
        content = {
            "status": status,
            "error": error,
            "finished_at": _utc_iso_now(),
            "elapsed_s": elapsed_s,
            "metrics": metrics_payload,
            "detector_latency_ms": latency_summary,
            "events": list(self._events),
        }
        with self.report_path.open("w", encoding="utf-8") as fp:
            json.dump(content, fp, ensure_ascii=False, indent=2)


def _utc_iso_now() -> str:
    return datetime.now(timezone.utc).isoformat(timespec="seconds")


class ToupViewWindow:
    def __init__(
        self,
        title_keyword: str = "NIS",            # 默认为toupview
        margins: Optional[CaptureMargins] = None,
        wait_timeout_s: float = 10.0,
        wait_poll_s: float = 0.5,
    ):
        try:
            import pyautogui
            import win32api
            import win32con
            import win32gui
        except ModuleNotFoundError as exc:
            raise RuntimeError(
                "ToupView dependencies are missing. Install pyautogui and pywin32 in the main runtime."
            ) from exc

        self.pyautogui = pyautogui
        self.win32api = win32api
        self.win32con = win32con
        self.win32gui = win32gui
        self.title_keyword = title_keyword
        self.margins = margins or CaptureMargins()
        self.wait_timeout_s = max(0.0, float(wait_timeout_s))
        self.wait_poll_s = max(0.1, float(wait_poll_s))
        self.hwnd: Optional[int] = None
        self.scroll_hwnd: Optional[int] = None
        self.roi: Optional[Tuple[int, int, int, int]] = None
        self.connect()

    def connect(self) -> None:
        """Find and connect to the ToupView window by title keyword."""
        deadline = time.time() + self.wait_timeout_s
        last_titles = []

        while True:
            windows = []

            def _enum_cb(hwnd: int, _) -> bool:
                if not self.win32gui.IsWindowVisible(hwnd):
                    return True
                title = self.win32gui.GetWindowText(hwnd)
                if title:
                    last_titles.append(title)
                if self.title_keyword in title:
                    windows.append((hwnd, title))
                return True

            self.win32gui.EnumWindows(_enum_cb, None)
            if windows:
                self.hwnd, title = windows[0]
                self.scroll_hwnd = self._find_scroll_child(self.hwnd) or self.hwnd
                LOGGER.info("Connected window: %s (hwnd=%s, scroll_hwnd=%s)", title, self.hwnd, self.scroll_hwnd)
                return

            if time.time() >= deadline:
                raise RuntimeError(
                    f"在 {self.wait_timeout_s:.1f}s 内未找到包含“{self.title_keyword}”的窗口"
                )
            time.sleep(self.wait_poll_s)

    def _find_scroll_child(self, parent: int) -> Optional[int]:
        candidates = []

        def _enum_cb(hwnd: int, _) -> bool:
            style = self.win32api.GetWindowLong(hwnd, self.win32con.GWL_STYLE)
            if (style & self.win32con.WS_VSCROLL) or (style & self.win32con.WS_HSCROLL):
                candidates.append(hwnd)
            return True

        try:
            self.win32gui.EnumChildWindows(parent, _enum_cb, None)
        except Exception:
            return None
        return candidates[-1] if candidates else None

    def get_window_rect(self) -> Tuple[int, int, int, int]:
        if self.hwnd is None or not self.win32gui.IsWindow(self.hwnd):
            self.connect()
        if self.win32gui.IsIconic(self.hwnd):
            raise RuntimeError("ToupView 窗口已最小化，请先恢复窗口后再运行。")
        left, top, right, bottom = self.win32gui.GetWindowRect(self.hwnd)
        if left <= -30000 or top <= -30000:
            raise RuntimeError("ToupView 窗口位于屏幕可视区域之外，请先移动到可见区域后再运行。")
        return left, top, right, bottom

    def get_capture_region(self) -> Tuple[int, int, int, int]:
        left, top, right, bottom = self.get_window_rect()
        width = right - left
        height = bottom - top

        cap_left = left + self.margins.left
        cap_top = top + self.margins.top
        cap_width = width - self.margins.left - self.margins.right
        cap_height = height - self.margins.top - self.margins.bottom
        if cap_width <= 0 or cap_height <= 0:
            cap_left, cap_top, cap_width, cap_height = left, top, width, height
        if cap_width <= 0 or cap_height <= 0:
            raise RuntimeError(
                f"ToupView 采集区域无效：({cap_left}, {cap_top}, {cap_width}, {cap_height})"
            )
        return cap_left, cap_top, cap_width, cap_height

    def grab_frame(self) -> np.ndarray:
        """Capture a BGR frame from the ToupView window, cropped to ROI if set."""
        region = self.get_capture_region()
        screenshot = self.pyautogui.screenshot(region=region)
        frame = cv2.cvtColor(np.array(screenshot), cv2.COLOR_RGB2BGR)
        if self.roi is None:
            return frame

        x, y, w, h = self.roi
        h0, w0 = frame.shape[:2]
        x = max(0, min(x, w0 - 1))
        y = max(0, min(y, h0 - 1))
        w = max(1, min(w, w0 - x))
        h = max(1, min(h, h0 - y))
        return frame[y:y + h, x:x + w].copy()

    def select_roi(self) -> None:
        """Open an interactive ROI selection dialog on the current frame."""
        frame = self.grab_frame() if self.roi is None else self._grab_uncropped_frame()
        win_name = "SpotZoom ROI"
        cv2.namedWindow(win_name, cv2.WINDOW_NORMAL)
        cv2.resizeWindow(win_name, min(frame.shape[1], 1400), min(frame.shape[0], 900))
        hint = frame.copy()
        cv2.putText(
            hint,
            "Drag ROI and press Enter; press ESC to cancel",
            (10, 32),
            cv2.FONT_HERSHEY_SIMPLEX,
            0.8,
            (0, 255, 255),
            2,
        )
        roi = cv2.selectROI(win_name, hint, showCrosshair=True, fromCenter=False)
        cv2.destroyWindow(win_name)
        x, y, w, h = roi
        if w > 10 and h > 10:
            self.roi = (int(x), int(y), int(w), int(h))
            LOGGER.info("ROI set: x=%d, y=%d, w=%d, h=%d", x, y, w, h)
        else:
            self.roi = None
            LOGGER.info("ROI not set; using full capture area")

    def _grab_uncropped_frame(self) -> np.ndarray:
        region = self.get_capture_region()
        screenshot = self.pyautogui.screenshot(region=region)
        return cv2.cvtColor(np.array(screenshot), cv2.COLOR_RGB2BGR)

    def _window_center_lparam(self) -> int:
        left, top, right, bottom = self.get_window_rect()
        cx = (left + right) // 2
        cy = (top + bottom) // 2
        return ((cy & 0xFFFF) << 16) | (cx & 0xFFFF)

    def wheel(self, clicks: int) -> None:
        """Send mouse wheel messages to the ToupView scroll area."""
        if clicks == 0:
            return
        if self.scroll_hwnd is None:
            self.connect()
        lparam = self._window_center_lparam()
        direction = 1 if clicks > 0 else -1
        for _ in range(abs(int(clicks))):
            delta = direction * WHEEL_DELTA
            wparam = (delta & 0xFFFF) << 16
            self.win32api.SendMessage(self.scroll_hwnd, self.win32con.WM_MOUSEWHEEL, wparam, lparam)


class SimulatedFrameWindow:
    """Headless frame source for smoke tests without GUI window dependencies."""

    def __init__(self, image_path: str, jitter_px: int = 0, noise_std: float = 0.0):
        frame_path = Path(image_path).expanduser()
        if not frame_path.exists():
            raise RuntimeError(f"未找到模拟图像：{frame_path}")
        frame = cv2.imread(str(frame_path))
        if frame is None:
            raise RuntimeError(f"无法解码模拟图像：{frame_path}")
        self.frame_path = frame_path
        self.base_frame = frame
        self.jitter_px = max(0, int(jitter_px))
        self.noise_std = max(0.0, float(noise_std))
        self.roi: Optional[Tuple[int, int, int, int]] = None
        self._rng = np.random.default_rng(seed=int(time.time()))
        LOGGER.info(
            "Simulated frame source enabled: image=%s jitter_px=%d noise_std=%.2f",
            frame_path,
            self.jitter_px,
            self.noise_std,
        )

    def get_capture_region(self) -> Tuple[int, int, int, int]:
        h, w = self.base_frame.shape[:2]
        return 0, 0, int(w), int(h)

    def _synthesize_frame(self) -> np.ndarray:
        frame = self.base_frame.copy()
        if self.jitter_px > 0:
            dx = int(self._rng.integers(-self.jitter_px, self.jitter_px + 1))
            dy = int(self._rng.integers(-self.jitter_px, self.jitter_px + 1))
            mat = np.float32([[1, 0, dx], [0, 1, dy]])
            frame = cv2.warpAffine(frame, mat, (frame.shape[1], frame.shape[0]), borderMode=cv2.BORDER_REFLECT)
        if self.noise_std > 0:
            noise = self._rng.normal(0.0, self.noise_std, size=frame.shape)
            frame = np.clip(frame.astype(np.float32) + noise, 0, 255).astype(np.uint8)
        return frame

    def grab_frame(self) -> np.ndarray:
        frame = self._synthesize_frame()
        if self.roi is None:
            return frame
        x, y, w, h = self.roi
        h0, w0 = frame.shape[:2]
        x = max(0, min(int(x), w0 - 1))
        y = max(0, min(int(y), h0 - 1))
        w = max(1, min(int(w), w0 - x))
        h = max(1, min(int(h), h0 - y))
        return frame[y:y + h, x:x + w].copy()

    def select_roi(self) -> None:
        frame = self.grab_frame()
        win_name = "SpotZoom ROI (Simulated)"
        cv2.namedWindow(win_name, cv2.WINDOW_NORMAL)
        cv2.resizeWindow(win_name, min(frame.shape[1], 1400), min(frame.shape[0], 900))
        roi = cv2.selectROI(win_name, frame, showCrosshair=True, fromCenter=False)
        cv2.destroyWindow(win_name)
        x, y, w, h = roi
        if w > 10 and h > 10:
            self.roi = (int(x), int(y), int(w), int(h))
            LOGGER.info("Simulated ROI set: x=%d, y=%d, w=%d, h=%d", x, y, w, h)
        else:
            self.roi = None
            LOGGER.info("Simulated ROI not set; using full frame")

    def wheel(self, clicks: int) -> None:
        LOGGER.debug("Simulated wheel ignored: clicks=%d", clicks)


class UCCFrameSource:
    """UCC CCD相机帧源，通过OpenCV直接访问USB视频设备（UVC协议）。
    
    硬件信息：
    - 芯片型号：Nextchip 2040E + SONY 639CCD
    - 传感器：1/3 Sony 960H CCD Sensor
    - 像素：PAL: 976(H)×582(V), NTSC: 976(H)×494(V)
    - 分辨率：600 TVL
    - 信号制式：PAL/NTSC
    - 视频输出：1.0Vp-p/75Ω
    - 工作电压：DC 12V
    
    使用示例：
        ucc = UCCFrameSource(device_index=0, resolution="PAL")
        frame = ucc.grab_frame()
    """
    
    # 预定义分辨率配置
    RESOLUTIONS = {
        "PAL": {"width": 976, "height": 582, "fps": 25},
        "NTSC": {"width": 976, "height": 494, "fps": 30},
        "AUTO": {"width": 0, "height": 0, "fps": 0},  # 使用设备默认
    }
    
    def __init__(
        self,
        device_index: int = 0,
        resolution: str = "PAL",
        exposure: Optional[float] = None,
        gain: Optional[float] = None,
        brightness: Optional[float] = None,
        contrast: Optional[float] = None,
    ):
        self.device_index = device_index
        self.resolution = resolution.upper()
        self.cap = None
        self.roi = None
        
        # 相机参数
        self.exposure = exposure
        self.gain = gain
        self.brightness = brightness
        self.contrast = contrast
        
        # 验证分辨率
        if self.resolution not in self.RESOLUTIONS:
            raise ValueError(f"不支持的分辨率: {resolution}，支持: {list(self.RESOLUTIONS.keys())}")
        
        # 连接相机
        self._connect()
        
        LOGGER.info("UCCFrameSource initialized: device=%d, resolution=%s, region=%s",
                   device_index, self.resolution, self.get_capture_region())
    
    def _connect(self):
        """连接UCC相机并配置参数。"""
        self.cap = cv2.VideoCapture(self.device_index)
        
        if not self.cap.isOpened():
            raise RuntimeError(f"无法打开UCC相机设备 {self.device_index}，请检查：\n"
                             f"1. 相机是否已连接\n"
                             f"2. 驱动是否已安装\n"
                             f"3. 设备索引是否正确（可用cv2.VideoCapture(index)测试）")
        
        # 配置分辨率
        res_config = self.RESOLUTIONS[self.resolution]
        if res_config["width"] > 0:
            self.cap.set(cv2.CAP_PROP_FRAME_WIDTH, res_config["width"])
            self.cap.set(cv2.CAP_PROP_FRAME_HEIGHT, res_config["height"])
        if res_config["fps"] > 0:
            self.cap.set(cv2.CAP_PROP_FPS, res_config["fps"])
        
        # 配置相机参数
        if self.exposure is not None:
            self.cap.set(cv2.CAP_PROP_EXPOSURE, self.exposure)
        if self.gain is not None:
            self.cap.set(cv2.CAP_PROP_GAIN, self.gain)
        if self.brightness is not None:
            self.cap.set(cv2.CAP_PROP_BRIGHTNESS, self.brightness)
        if self.contrast is not None:
            self.cap.set(cv2.CAP_PROP_CONTRAST, self.contrast)
        
        # 读取实际参数
        actual_width = int(self.cap.get(cv2.CAP_PROP_FRAME_WIDTH))
        actual_height = int(self.cap.get(cv2.CAP_PROP_FRAME_HEIGHT))
        actual_fps = self.cap.get(cv2.CAP_PROP_FPS)
        
        LOGGER.info("UCC相机已连接: device=%d, 实际分辨率=%dx%d, FPS=%.1f",
                   self.device_index, actual_width, actual_height, actual_fps)
    
    def grab_frame(self) -> np.ndarray:
        """采集单帧图像。"""
        if self.cap is None or not self.cap.isOpened():
            raise RuntimeError("UCC相机未连接或已断开")
        
        ret, frame = self.cap.read()
        if not ret or frame is None:
            raise RuntimeError("UCC相机帧采集失败，请检查设备连接")
        
        # ROI裁剪
        if self.roi is not None:
            x, y, w, h = self.roi
            h0, w0 = frame.shape[:2]
            x = max(0, min(x, w0 - 1))
            y = max(0, min(y, h0 - 1))
            w = min(w, w0 - x)
            h = min(h, h0 - y)
            frame = frame[y:y + h, x:x + w]
        
        return frame
    
    def get_capture_region(self):
        """获取采集区域信息。"""
        if self.cap is not None and self.cap.isOpened():
            width = int(self.cap.get(cv2.CAP_PROP_FRAME_WIDTH))
            height = int(self.cap.get(cv2.CAP_PROP_FRAME_HEIGHT))
            return (0, 0, width, height)
        return (0, 0, 0, 0)
    
    def select_roi(self) -> None:
        """交互式选择ROI区域。"""
        frame = self.grab_frame()
        win_name = "UCC Camera ROI Selection"
        cv2.namedWindow(win_name, cv2.WINDOW_NORMAL)
        cv2.resizeWindow(win_name, min(frame.shape[1], 1400), min(frame.shape[0], 900))
        roi = cv2.selectROI(win_name, frame, showCrosshair=True, fromCenter=False)
        cv2.destroyWindow(win_name)
        x, y, w, h = roi
        if w > 10 and h > 10:
            self.roi = (int(x), int(y), int(w), int(h))
            LOGGER.info("UCC ROI set: x=%d, y=%d, w=%d, h=%d", x, y, w, h)
        else:
            self.roi = None
            LOGGER.info("UCC ROI not set; using full frame")
    
    def set_camera_param(self, param: str, value: float):
        """动态设置相机参数。
        
        Args:
            param: 参数名 (exposure, gain, brightness, contrast)
            value: 参数值
        """
        if self.cap is None:
            raise RuntimeError("UCC相机未连接")
        
        param_map = {
            "exposure": cv2.CAP_PROP_EXPOSURE,
            "gain": cv2.CAP_PROP_GAIN,
            "brightness": cv2.CAP_PROP_BRIGHTNESS,
            "contrast": cv2.CAP_PROP_CONTRAST,
        }
        
        if param not in param_map:
            raise ValueError(f"不支持的参数: {param}，支持: {list(param_map.keys())}")
        
        self.cap.set(param_map[param], value)
        actual = self.cap.get(param_map[param])
        LOGGER.info("UCC相机参数设置: %s=%.2f (实际=%.2f)", param, value, actual)
    
    def get_camera_info(self) -> dict:
        """获取相机信息。"""
        if self.cap is None:
            return {}
        
        return {
            "device_index": self.device_index,
            "resolution": self.resolution,
            "width": int(self.cap.get(cv2.CAP_PROP_FRAME_WIDTH)),
            "height": int(self.cap.get(cv2.CAP_PROP_FRAME_HEIGHT)),
            "fps": self.cap.get(cv2.CAP_PROP_FPS),
            "exposure": self.cap.get(cv2.CAP_PROP_EXPOSURE),
            "gain": self.cap.get(cv2.CAP_PROP_GAIN),
            "brightness": self.cap.get(cv2.CAP_PROP_BRIGHTNESS),
            "contrast": self.cap.get(cv2.CAP_PROP_CONTRAST),
        }
    
    def release(self):
        """释放相机资源。"""
        if self.cap is not None:
            self.cap.release()
            self.cap = None
            LOGGER.info("UCC相机已断开: device=%d", self.device_index)
    
    def __del__(self):
        """析构时自动释放资源。"""
        self.release()
    
    def wheel(self, clicks: int) -> None:
        """UCC相机不支持滚轮操作。"""
        LOGGER.debug("UCC camera wheel ignored: clicks=%d", clicks)


class FrameSourcePair:
    def __init__(self, source_pos, source_ang=None):
        self.source_pos = source_pos
        self.source_ang = source_ang
        LOGGER.info("FrameSourcePair initialized: pos_source=%s, ang_source=%s",
                    source_pos.__class__.__name__,
                    source_ang.__class__.__name__ if source_ang else "None")

    def grab_frames(self) -> Tuple[np.ndarray, Optional[np.ndarray]]:
        frame_pos = self.source_pos.grab_frame()
        frame_ang = self.source_ang.grab_frame() if self.source_ang else None
        return frame_pos, frame_ang

    def select_rois(self) -> None:
        LOGGER.info("Selecting ROI for position detector...")
        self.source_pos.select_roi()
        if self.source_ang:
            LOGGER.info("Selecting ROI for angle detector...")
            self.source_ang.select_roi()

    def wheel(self, clicks: int) -> None:
        self.source_pos.wheel(clicks)
        if self.source_ang:
            self.source_ang.wheel(clicks)

    def get_capture_regions(self) -> Tuple[Tuple[int, int, int, int], Optional[Tuple[int, int, int, int]]]:
        pos_region = self.source_pos.get_capture_region()
        ang_region = self.source_ang.get_capture_region() if self.source_ang else None
        return pos_region, ang_region


class FourAxisController:
    """4轴双镜闭环控制器，支持双探测器和单探测器两种模式。
    
    双探测器模式（dual_detector）：
        - Detector1测量位置误差（近端镜子后）
        - Detector2测量角度误差（远端镜子后+透镜）
        - 两个镜子同时控制
    
    单探测器模式（single_detector）：
        - 仅在远端镜子后有一个探测器
        - 采用顺序控制：先调镜子1（粗调），再调镜子2（细调）
        - 保留双探测器接口，后续可扩展
    """
    
    def __init__(
        self,
        stage1_kp: float = 1.0,
        stage1_ki: float = 0.1,
        stage2_kp: float = 1.0,
        stage2_ki: float = 0.1,
        coupling_c12: float = 0.0,
        coupling_c21: float = 0.0,
        tolerance_pos_px: int = 4,
        tolerance_ang_px: int = 4,
        converge_stable_frames: int = 5,
        detector2_focal_length: float = 200.0,
        detector_mode: str = "single_detector",  # "single_detector" 或 "dual_detector"
        stage1_gain_factor: float = 2.0,  # 单探测器模式下镜子1的增益系数（杠杆效应）
        sequential_stage1_iterations: int = 3,  # 单探测器模式下先调镜子1的迭代次数
    ):
        self.stage1_kp = stage1_kp
        self.stage1_ki = stage1_ki
        self.stage2_kp = stage2_kp
        self.stage2_ki = stage2_ki
        self.coupling_c12 = coupling_c12
        self.coupling_c21 = coupling_c21
        self.tolerance_pos_px = tolerance_pos_px
        self.tolerance_ang_px = tolerance_ang_px
        self.converge_stable_frames = converge_stable_frames
        self.detector2_focal_length = detector2_focal_length
        self.detector_mode = detector_mode
        self.stage1_gain_factor = stage1_gain_factor
        self.sequential_stage1_iterations = sequential_stage1_iterations

        self.integral_pos_x = 0.0
        self.integral_pos_y = 0.0
        self.integral_ang_x = 0.0
        self.integral_ang_y = 0.0

        self.stable_frame_count = 0
        self.jacobian_matrix = None
        self._current_stage = 1  # 单探测器模式下当前控制阶段
        LOGGER.info("FourAxisController initialized: mode=%s stage1_kp=%.2f stage1_ki=%.2f stage2_kp=%.2f stage2_ki=%.2f coupling=(%.2f,%.2f)",
                    detector_mode, stage1_kp, stage1_ki, stage2_kp, stage2_ki, coupling_c12, coupling_c21)

    def reset_integrators(self) -> None:
        self.integral_pos_x = 0.0
        self.integral_pos_y = 0.0
        self.integral_ang_x = 0.0
        self.integral_ang_y = 0.0
        self.stable_frame_count = 0

    def set_jacobian(self, J: np.ndarray) -> None:
        if J.shape != (4, 4):
            raise ValueError(f"Jacobian must be 4x4 matrix, got {J.shape}")
        self.jacobian_matrix = J
        LOGGER.info("Jacobian matrix set:\n%s", J)

    def estimate_jacobian(self, xy_stage, frame_source_pair, calibration_steps: int = 5) -> np.ndarray:
        LOGGER.info("Starting 4x4 Jacobian calibration with %d steps per axis", calibration_steps)
        J = np.zeros((4, 4))
        reference_pos = self._capture_reference(frame_source_pair)
        if reference_pos is None:
            raise RuntimeError("Failed to capture reference positions for calibration")

        axes = [('stage1_x', 'move_x1'), ('stage1_y', 'move_y1'),
                ('stage2_x', 'move_x2'), ('stage2_y', 'move_y2')]

        for i, (axis_name, move_method) in enumerate(axes):
            for sign in [1, -1]:
                step = sign * calibration_steps
                getattr(xy_stage, move_method)(step)
                time.sleep(0.2)
                pos, ang = self._capture_reference(frame_source_pair)
                if pos is None or ang is None:
                    LOGGER.warning("Skipping calibration point for %s", axis_name)
                    continue

                dx_pos = pos[0] - reference_pos[0]
                dy_pos = pos[1] - reference_pos[1]
                dx_ang = ang[0] - reference_pos[2]
                dy_ang = ang[1] - reference_pos[3]

                J[0, i] += dx_pos / step
                J[1, i] += dy_pos / step
                J[2, i] += dx_ang / step
                J[3, i] += dy_ang / step

                getattr(xy_stage, move_method)(-step)
                time.sleep(0.2)

            J[:, i] /= 2.0

        self.jacobian_matrix = J
        LOGGER.info("Jacobian calibration completed:\n%s", J)
        return J

    def _capture_reference(self, frame_source_pair) -> Optional[Tuple[int, int, int, int]]:
        frame_pos, frame_ang = frame_source_pair.grab_frames()
        if frame_pos is None:
            return None
        h_pos, w_pos = frame_pos.shape[:2]
        center_pos = (w_pos // 2, h_pos // 2)

        if frame_ang is None:
            return (center_pos[0], center_pos[1], center_pos[0], center_pos[1])

        h_ang, w_ang = frame_ang.shape[:2]
        center_ang = (w_ang // 2, h_ang // 2)
        return (center_pos[0], center_pos[1], center_ang[0], center_ang[1])

    def compute_control(self, e_pos: Tuple[int, int], e_ang: Tuple[int, int]) -> Tuple[int, int, int, int]:
        """计算控制量，支持双探测器和单探测器两种模式。"""
        e_pos_x, e_pos_y = e_pos
        e_ang_x, e_ang_y = e_ang

        if self.detector_mode == "single_detector":
            return self._compute_control_single_detector(e_pos_x, e_pos_y)
        else:
            return self._compute_control_dual_detector(e_pos_x, e_pos_y, e_ang_x, e_ang_y)

    def _compute_control_dual_detector(self, e_pos_x, e_pos_y, e_ang_x, e_ang_y) -> Tuple[int, int, int, int]:
        """双探测器模式：同时控制两个镜子。"""
        self.integral_pos_x = max(-1000.0, min(1000.0, self.integral_pos_x + e_pos_x))
        self.integral_pos_y = max(-1000.0, min(1000.0, self.integral_pos_y + e_pos_y))
        self.integral_ang_x = max(-1000.0, min(1000.0, self.integral_ang_x + e_ang_x))
        self.integral_ang_y = max(-1000.0, min(1000.0, self.integral_ang_y + e_ang_y))

        u1_x = int(round(self.stage1_kp * e_pos_x + self.stage1_ki * self.integral_pos_x + self.coupling_c12 * e_ang_x))
        u1_y = int(round(self.stage1_kp * e_pos_y + self.stage1_ki * self.integral_pos_y + self.coupling_c12 * e_ang_y))
        u2_x = int(round(self.stage2_kp * e_ang_x + self.stage2_ki * self.integral_ang_x + self.coupling_c21 * e_pos_x))
        u2_y = int(round(self.stage2_kp * e_ang_y + self.stage2_ki * self.integral_ang_y + self.coupling_c21 * e_pos_y))

        u1_x = max(-2000, min(2000, u1_x))
        u1_y = max(-2000, min(2000, u1_y))
        u2_x = max(-2000, min(2000, u2_x))
        u2_y = max(-2000, min(2000, u2_y))

        return (u1_x, u1_y, u2_x, u2_y)

    def _compute_control_single_detector(self, e_pos_x, e_pos_y) -> Tuple[int, int, int, int]:
        """单探测器模式：顺序控制。
        
        阶段1：用镜子1进行粗调（增益较大，因为镜子1离探测器远，杠杆效应大）
        阶段2：用镜子2进行细调（增益较小，因为镜子2离探测器近，调节更精细）
        """
        self.integral_pos_x = max(-1000.0, min(1000.0, self.integral_pos_x + e_pos_x))
        self.integral_pos_y = max(-1000.0, min(1000.0, self.integral_pos_y + e_pos_y))

        error_norm = math.hypot(e_pos_x, e_pos_y)
        
        # 阶段1：粗调 - 使用镜子1（近端镜子）
        if self._current_stage == 1:
            # 镜子1的增益乘以杠杆系数（离探测器远，影响大）
            u1_x = int(round(self.stage1_kp * self.stage1_gain_factor * e_pos_x + 
                           self.stage1_ki * self.integral_pos_x))
            u1_y = int(round(self.stage1_kp * self.stage1_gain_factor * e_pos_y + 
                           self.stage1_ki * self.integral_pos_y))
            u2_x, u2_y = 0, 0  # 阶段1不动镜子2
            
            LOGGER.debug("Single-detector Stage 1: error_norm=%.2f, u1=(%d, %d)", 
                        error_norm, u1_x, u1_y)
        
        # 阶段2：细调 - 使用镜子2（远端镜子）
        else:
            # 镜子2的增益较小（离探测器近，调节精细）
            u2_x = int(round(self.stage2_kp * e_pos_x + self.stage2_ki * self.integral_pos_x))
            u2_y = int(round(self.stage2_kp * e_pos_y + self.stage2_ki * self.integral_pos_y))
            u1_x, u1_y = 0, 0  # 阶段2不动镜子1
            
            LOGGER.debug("Single-detector Stage 2: error_norm=%.2f, u2=(%d, %d)", 
                        error_norm, u2_x, u2_y)

        u1_x = max(-2000, min(2000, u1_x))
        u1_y = max(-2000, min(2000, u1_y))
        u2_x = max(-2000, min(2000, u2_x))
        u2_y = max(-2000, min(2000, u2_y))

        return (u1_x, u1_y, u2_x, u2_y)

    def update_stage(self, iteration: int) -> None:
        """单探测器模式下更新控制阶段。"""
        if self.detector_mode == "single_detector":
            if iteration <= self.sequential_stage1_iterations:
                self._current_stage = 1
                LOGGER.info("Single-detector mode: Stage 1 (coarse adjustment with mirror 1)")
            else:
                self._current_stage = 2
                LOGGER.info("Single-detector mode: Stage 2 (fine adjustment with mirror 2)")

    def is_converged(self, e_pos: Tuple[int, int], e_ang: Tuple[int, int]) -> bool:
        """收敛判据，单探测器模式下只检查位置误差。"""
        pos_norm = math.hypot(e_pos[0], e_pos[1])
        
        if self.detector_mode == "dual_detector":
            ang_norm = math.hypot(e_ang[0], e_ang[1])
            if pos_norm <= self.tolerance_pos_px and ang_norm <= self.tolerance_ang_px:
                self.stable_frame_count += 1
                if self.stable_frame_count >= self.converge_stable_frames:
                    return True
            else:
                self.stable_frame_count = 0
        else:
            # 单探测器模式：只检查位置误差
            if pos_norm <= self.tolerance_pos_px:
                self.stable_frame_count += 1
                if self.stable_frame_count >= self.converge_stable_frames:
                    return True
            else:
                self.stable_frame_count = 0

        return False

    def angle_to_pixels(self, angle_rad: float) -> float:
        return angle_rad * self.detector2_focal_length * 1000.0


def _module_available_in_current_python(module_name: str) -> bool:
    try:
        __import__(module_name)
        return True
    except (ImportError, ModuleNotFoundError):
        return False


def _module_available_in_python(python_exe: str, module_name: str) -> bool:
    if not python_exe or not Path(python_exe).exists():
        return False
    try:
        result = subprocess.run(
            [python_exe, "-c", f"import {module_name}"],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            encoding="utf-8",
            errors="replace",
            timeout=20,
            check=False,
        )
    except Exception:
        return False
    return result.returncode == 0


def _format_ultralytics_install_hint(python_exe: str) -> str:
    python_exe = str(Path(python_exe))
    hint = [f"ultralytics not found in: {python_exe}"]
    if sys.version_info >= (3, 13):
        hint.append("Current main interpreter is newer; prefer Python 3.10-3.12 for YOLO dependencies.")
    hint.append(f"Install command: \"{python_exe}\" -m pip install ultralytics")
    hint.append(f"Or provide an alternate runtime: --yolo-python \"{python_exe}\"")
    return " ".join(hint)


def _candidate_thorlabs_dll_dirs(extra_dir: Optional[str] = None) -> List[Path]:
    candidates: List[Path] = []
    for value in (extra_dir, os.environ.get("THORLABS_KINESIS_DIR")):
        if value:
            candidates.append(Path(value))

    candidates.extend(
        [
            Path(r"C:\Program Files\Thorlabs\Kinesis"),
            Path(r"C:\Program Files\Thorlabs\APT"),
            Path(r"C:\Program Files\Thorlabs\Kinesis\Drivers\Kinesis\USB Driver\amd64"),
            Path(r"C:\Program Files\Thorlabs\Kinesis\Drivers\APT\USB Driver\amd64"),
        ]
    )

    seen = set()
    deduped: List[Path] = []
    for path in candidates:
        key = str(path).lower()
        if key in seen:
            continue
        seen.add(key)
        deduped.append(path)
    return deduped


def _ensure_thorlabs_ftdi_dll(extra_dir: Optional[str] = None) -> Optional[Path]:
    for directory in _candidate_thorlabs_dll_dirs(extra_dir):
        dll_path = directory / "ftd2xx.dll"
        if not dll_path.exists():
            continue

        current_path = os.environ.get("PATH", "")
        path_entries = current_path.split(os.pathsep) if current_path else []
        if str(directory) not in path_entries:
            os.environ["PATH"] = str(directory) + os.pathsep + current_path

        if hasattr(os, "add_dll_directory"):
            try:
                os.add_dll_directory(str(directory))
            except OSError:
                pass
        return directory
    return None


class SpotYOLODetector:
    def __init__(
        self,
        model_path: str,
        target_class_name: Optional[str] = "lightspot",
        target_class_id: Optional[int] = 0,
        conf_threshold: float = 0.25,
    ):
        self.model_path = model_path
        self.target_class_name = target_class_name
        self.target_class_id = target_class_id
        self.conf_threshold = conf_threshold
        try:
            from ultralytics import YOLO
        except ModuleNotFoundError as exc:
            raise RuntimeError(_format_ultralytics_install_hint(sys.executable)) from exc

        self.model = YOLO(model_path)
        LOGGER.info("YOLO model loaded: %s", model_path)

    def detect(self, frame: np.ndarray) -> Optional[SpotDetection]:
        """Run YOLO inference on a frame and return the best matching detection."""
        results = self.model(frame, conf=self.conf_threshold, verbose=False)
        names = getattr(self.model, "names", {})
        best: Optional[SpotDetection] = None

        for result in results:
            boxes = getattr(result, "boxes", None)
            if boxes is None:
                continue
            for box in boxes:
                cls_id = int(box.cls.item())
                conf = float(box.conf.item())
                x1, y1, x2, y2 = map(int, box.xyxy[0].tolist())
                label = names.get(cls_id, str(cls_id)) if isinstance(names, dict) else str(cls_id)

                if self.target_class_name is not None and label != self.target_class_name:
                    if self.target_class_id is None or cls_id != self.target_class_id:
                        continue
                elif self.target_class_name is None and self.target_class_id is not None and cls_id != self.target_class_id:
                    continue

                detection = SpotDetection(
                    center=((x1 + x2) // 2, (y1 + y2) // 2),
                    bbox=(x1, y1, x2, y2),
                    confidence=conf,
                    label=label,
                    class_id=cls_id,
                )
                if best is None or detection.confidence > best.confidence:
                    best = detection
        return best


class SpotClassicDetector:
    """OpenCV-based detector adapter for environments without YOLO runtime."""

    _METHOD_CHOICES = ("otsu", "adaptive", "tophat", "gmm", "meanshift")
    _SELECTION_CHOICES = ("brightest", "largest", "central")

    def __init__(
        self,
        target_class_name: Optional[str] = "lightspot",
        target_class_id: Optional[int] = 0,
        *,
        method: str = "otsu",
        selection: str = "brightest",
        min_area: int = 20,
        max_area: int = 0,
        min_circularity: float = 0.2,
        min_intensity_ratio: float = 1.5,
        morph_kernel_size: int = 5,
    ):
        if _ml_classic_detector is None or not hasattr(_ml_classic_detector, "ClassicSpotDetector"):
            raise RuntimeError("classic_spot_detector 模块不可用")

        method_norm = str(method).strip().lower()
        selection_norm = str(selection).strip().lower()
        if method_norm not in self._METHOD_CHOICES:
            raise ValueError(f"不支持的经典检测器方法：{method_norm}")
        if selection_norm not in self._SELECTION_CHOICES:
            raise ValueError(f"不支持的经典检测器候选选择策略：{selection_norm}")

        self.target_class_name = target_class_name
        self.target_class_id = target_class_id
        self.detector = _ml_classic_detector.ClassicSpotDetector(
            method=method_norm,
            selection=selection_norm,
            min_area=max(1, int(min_area)),
            max_area=max(0, int(max_area)),
            min_circularity=max(0.0, float(min_circularity)),
            min_intensity_ratio=max(0.1, float(min_intensity_ratio)),
            morph_kernel_size=max(3, int(morph_kernel_size) | 1),
            use_subpixel=True,
        )
        LOGGER.info(
            "Classic detector loaded: method=%s selection=%s min_area=%d max_area=%d",
            method_norm,
            selection_norm,
            max(1, int(min_area)),
            max(0, int(max_area)),
        )

    @classmethod
    def supported_methods(cls) -> Tuple[str, ...]:
        return cls._METHOD_CHOICES

    @classmethod
    def supported_selection_strategies(cls) -> Tuple[str, ...]:
        return cls._SELECTION_CHOICES

    def detect(self, frame: np.ndarray) -> Optional[SpotDetection]:
        det = self.detector.detect(frame)
        if det is None:
            return None

        label = self.target_class_name if self.target_class_name is not None else str(getattr(det, "label", "lightspot"))
        class_id = 0 if self.target_class_id is None else int(self.target_class_id)
        confidence = float(np.clip(float(getattr(det, "confidence", 0.0)), 0.0, 1.0))
        center = tuple(int(v) for v in getattr(det, "center", (0, 0)))
        bbox = tuple(int(v) for v in getattr(det, "bbox", (0, 0, 0, 0)))
        return SpotDetection(
            center=(int(center[0]), int(center[1])),
            bbox=(int(bbox[0]), int(bbox[1]), int(bbox[2]), int(bbox[3])),
            confidence=confidence,
            label=label,
            class_id=class_id,
        )

    def reset(self) -> None:
        detector_reset = getattr(self.detector, "reset", None)
        if callable(detector_reset):
            detector_reset()

    def close(self) -> None:
        self.reset()


class SpotYOLOWorkerClient:
    def __init__(
        self,
        python_exe: str,
        model_path: str,
        target_class_name: Optional[str],
        target_class_id: Optional[int],
        conf_threshold: float,
    ):
        self.python_exe = str(Path(python_exe))
        self.proc = None
        self._stderr_lines = []
        self._stderr_lock = threading.Lock()
        self._max_stderr_lines = 80
        self._stderr_thread = None
        self._proc_lock = threading.Lock()

        cmd = [
            self.python_exe,
            str(Path(__file__).resolve()),
            "--worker-detect",
            "--model-path",
            model_path,
            "--conf-thres",
            str(conf_threshold),
            "--log-level",
            "ERROR",
        ]
        if target_class_name is not None:
            cmd.extend(["--target-class-name", target_class_name])
        if target_class_id is not None:
            cmd.extend(["--target-class-id", str(target_class_id)])

        try:
            self.proc = subprocess.Popen(
                cmd,
                stdin=subprocess.PIPE,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                text=True,
                encoding="utf-8",
                errors="replace",
                bufsize=1,
            )
            self._start_stderr_drain()
            ready_line = self.proc.stdout.readline() if self.proc.stdout is not None else ""
            if not ready_line:
                details = self._bootstrap_error_details()
                raise RuntimeError(f"YOLO worker failed to start: {self.python_exe}{details}")
            try:
                payload = json.loads(ready_line)
            except json.JSONDecodeError as exc:
                raise RuntimeError(f"YOLO worker returned invalid JSON: {ready_line.strip()}") from exc
            if not payload.get("ok"):
                raise RuntimeError(payload.get("error", "YOLO worker initialization failed"))
            LOGGER.info("YOLO worker started: %s", self.python_exe)
        except Exception:
            self._cleanup_failed_startup()
            raise

    def _start_stderr_drain(self) -> None:
        if self.proc is None or self.proc.stderr is None:
            return

        def _reader() -> None:
            try:
                for line in self.proc.stderr:
                    text = line.strip()
                    if not text:
                        continue
                    with self._stderr_lock:
                        self._stderr_lines.append(text)
                        if len(self._stderr_lines) > self._max_stderr_lines:
                            self._stderr_lines = self._stderr_lines[-self._max_stderr_lines:]
            except Exception:
                return

        self._stderr_thread = threading.Thread(
            target=_reader,
            name="spotzoom_yolo_worker_stderr",
            daemon=True,
        )
        self._stderr_thread.start()

    def _recent_stderr(self, limit: int = 3) -> str:
        with self._stderr_lock:
            if not self._stderr_lines:
                return ""
            return " | ".join(self._stderr_lines[-limit:])

    def _bootstrap_error_details(self) -> str:
        if self.proc is None:
            return ""
        exit_code = self.proc.poll()
        suffix = "" if exit_code is None else f" (exit={exit_code})"
        stderr_text = self._recent_stderr(limit=5)
        if stderr_text:
            if len(stderr_text) > 240:
                stderr_text = stderr_text[:240] + "..."
            return f"{suffix} stderr={stderr_text}"
        return suffix

    def _cleanup_failed_startup(self) -> None:
        if self.proc is not None:
            try:
                if self.proc.poll() is None:
                    self.proc.terminate()
                    self.proc.wait(timeout=2)
            except Exception:
                try:
                    self.proc.kill()
                except Exception:
                    pass

    def _read_worker_json(self, timeout_s: float = 20.0) -> dict:
        with self._proc_lock:
            if self.proc is None or self.proc.stdout is None:
                raise RuntimeError("YOLO worker stdout is unavailable")

            deadline = time.time() + max(0.1, float(timeout_s))
            while time.time() < deadline:
                line = self.proc.stdout.readline()
                if not line:
                    break
                line = line.strip()
                if not line:
                    continue
                if not line.startswith("{"):
                    LOGGER.warning("YOLO worker non-JSON output: %s", line[:200])
                    continue
                try:
                    return json.loads(line)
                except json.JSONDecodeError:
                    LOGGER.warning("YOLO worker malformed JSON output: %s", line[:200])
                    continue

        details = self._bootstrap_error_details()
        raise RuntimeError(f"YOLO worker did not return valid JSON response{details}")

    def detect(self, frame: np.ndarray) -> Optional[SpotDetection]:
        """Send frame to the YOLO worker process and return the detection result."""
        with self._proc_lock:
            if self.proc is None:
                raise RuntimeError("YOLO worker is not initialized")
            if self.proc.poll() is not None:
                raise RuntimeError(f"YOLO worker already exited (code={self.proc.returncode})")
            if self.proc.stdin is None or self.proc.stdout is None:
                raise RuntimeError("YOLO worker I/O pipes are unavailable")

            ok, encoded = cv2.imencode(".jpg", frame, [int(cv2.IMWRITE_JPEG_QUALITY), 90])
            if not ok:
                raise RuntimeError("Failed to JPEG-encode frame for YOLO worker")

            request = {
                "cmd": "detect",
                "image_jpg_b64": base64.b64encode(encoded.tobytes()).decode("ascii"),
            }
            self.proc.stdin.write(json.dumps(request, ensure_ascii=False) + "\n")
            self.proc.stdin.flush()

        response = self._read_worker_json(timeout_s=20.0)
        if not response.get("ok"):
            raise RuntimeError(response.get("error", "YOLO worker detection failed"))

        detection_payload = response.get("detection")
        if detection_payload is None:
            return None
        return SpotDetection.from_payload(detection_payload)

    def close(self) -> None:
        """Shut down the YOLO worker process gracefully."""
        with self._proc_lock:
            try:
                if self.proc is not None and self.proc.poll() is None and self.proc.stdin is not None:
                    self.proc.stdin.write(json.dumps({"cmd": "quit"}, ensure_ascii=False) + "\n")
                    self.proc.stdin.flush()
            except Exception:
                pass
            finally:
                try:
                    if self.proc is not None and self.proc.poll() is None:
                        self.proc.terminate()
                        self.proc.wait(timeout=2)
                except Exception:
                    try:
                        if self.proc is not None and self.proc.poll() is None:
                            self.proc.kill()
                    except Exception:
                        pass

class DryRunStage:
    def move_x(self, steps: int) -> None:
        LOGGER.info("[DryRun] move X by %s steps", steps)

    def move_y(self, steps: int) -> None:
        LOGGER.info("[DryRun] move Y by %s steps", steps)

    def close(self) -> None:
        return

    def __enter__(self):
        if self.dev is None:
            self.open()
        return self

    def __exit__(self, *args):
        self.close()


class ThorlabsXYStage:
    def __init__(
        self,
        device_id: str,
        x_channel: int = 4,
        y_channel: int = 3,
        x_hw_sign: int = 1,
        y_hw_sign: int = 1,
        horizontal_velocity: int = 20,
        horizontal_acceleration: int = 20,
        vertical_velocity: int = 400,
        vertical_acceleration: int = 400,
        max_voltage: int = 100,
        dll_dir: Optional[str] = None,
    ):
        dll_loaded_from = _ensure_thorlabs_ftdi_dll(dll_dir)
        from pylablib.devices import Thorlabs

        devices = []
        try:
            devices = Thorlabs.list_kinesis_devices()
        except Exception as exc:
            LOGGER.warning("Unable to enumerate Thorlabs Kinesis devices before connect: %s", exc)

        if dll_loaded_from is not None:
            LOGGER.info("Thorlabs FTDI DLL loaded from: %s", dll_loaded_from)
        else:
            LOGGER.warning(
                "ftd2xx.dll was not found in common Kinesis locations. "
                "If connection fails, pass --thorlabs-dll-dir or set THORLABS_KINESIS_DIR."
            )

        if not devices:
            raise RuntimeError(
                "未枚举到任何 Thorlabs Kinesis 设备。"
                "请检查 USB 连接、Kinesis 驱动安装、电源状态，以及设备是否被其他进程占用。"
            )

        available_ids = [str(device[0]) for device in devices if device]
        LOGGER.info("Enumerated Thorlabs devices: %s", devices)
        if device_id and str(device_id) not in available_ids:
            raise RuntimeError(
                f"未找到请求的 Thorlabs 设备“{device_id}”。可用设备 ID：{available_ids}"
            )

        try:
            self.device = Thorlabs.KinesisPiezoMotor(device_id)
        except Exception as exc:
            raise RuntimeError(
                f"打开 Thorlabs 设备“{device_id}”失败。"
                f"已枚举设备 ID：{available_ids}。原始错误：{exc}"
            ) from exc
        self.device.open()
        self.x_channel = x_channel
        self.y_channel = y_channel
        self.x_hw_sign = 1 if x_hw_sign >= 0 else -1
        self.y_hw_sign = 1 if y_hw_sign >= 0 else -1
        self._setup_drive(self.x_channel, horizontal_velocity, horizontal_acceleration, max_voltage)
        self._setup_drive(self.y_channel, vertical_velocity, vertical_acceleration, max_voltage)
        LOGGER.info("Thorlabs 8821/8742 controller connected: %s", device_id)

    def _setup_drive(self, channel: int, velocity: int, acceleration: int, max_voltage: int) -> None:
        try:
            self.device.setup_drive(
                max_voltage=max_voltage,
                velocity=velocity,
                acceleration=acceleration,
                channel=channel,
            )
        except Exception as exc:
            LOGGER.warning("Channel %d setup_drive failed: %s", channel, exc)

    def _move(self, channel: int, steps: int, sign: int) -> None:
        steps = int(steps)
        if steps == 0:
            return
        try:
            self.device.move_by(distance=sign * steps, auto_enable=True, channel=channel)
        except Exception as exc:
            raise RuntimeError(
                f"Thorlabs 通道 {channel} 移动失败（steps={sign * steps}）。"
                f"设备可能已断开，请检查 USB 连接。原始错误：{exc}"
            ) from exc

    def move_x(self, steps: int) -> None:
        self._move(self.x_channel, steps, self.x_hw_sign)

    def move_y(self, steps: int) -> None:
        self._move(self.y_channel, steps, self.y_hw_sign)

    def stop_all(self) -> None:
        for channel in (self.x_channel, self.y_channel):
            try:
                self.device.stop(channel=channel)
            except Exception:
                pass

    def close(self) -> None:
        try:
            self.stop_all()
        finally:
            try:
                self.device.close()
            except Exception:
                pass

    def __enter__(self):
        return self

    def __exit__(self, *args):
        self.close()


class PicoMotor8742Controller:
    def __init__(
        self,
        conn: int = 0,
        *,
        backend: str = "auto",
        timeout: float = 5.0,
        multiaddr: bool = False,
        scan: bool = True,
    ):
        self.conn = conn
        self.backend = backend
        self.timeout = timeout
        self.multiaddr = multiaddr
        self.scan = scan
        self.dev = None

    @staticmethod
    def usb_device_count() -> int:
        from pylablib.devices import Newport

        return int(Newport.get_usb_devices_number_picomotor())

    def open(self) -> "PicoMotor8742Controller":
        from pylablib.devices import Newport

        self.dev = Newport.Picomotor8742(
            self.conn,
            backend=self.backend,
            timeout=self.timeout,
            multiaddr=self.multiaddr,
            scan=self.scan,
        )
        return self

    def close(self) -> None:
        if self.dev is not None:
            try:
                self.dev.close()
            except Exception as exc:
                LOGGER.warning("Newport Picomotor close failed: %s", exc)
            finally:
                self.dev = None

    def __enter__(self):
        return self

    def __exit__(self, *args):
        self.close()

    def _check(self) -> None:
        if self.dev is None:
            raise RuntimeError("Newport Picomotor controller is not open")

    def get_id(self):
        self._check()
        return self.dev.get_id()

    def axes(self):
        self._check()
        return list(self.dev.get_all_axes())

    def require_axes(self, axes: List[int]) -> List[int]:
        requested = [int(axis) for axis in axes]
        available = self.axes()
        missing = [axis for axis in requested if axis not in available]
        if missing:
            raise RuntimeError(f"请求的 Newport 轴不可用：{missing}。当前可用轴：{available}")
        return available

    def get_pos(self, axis: int = 1) -> int:
        self._check()
        return int(self.dev.get_position(axis=axis))

    def set_zero_here(self, axis: int = 1, position: int = 0):
        self._check()
        return self.dev.set_position_reference(axis=axis, position=position)

    def move_rel(self, axis: int = 1, steps: int = 100, wait: bool = True):
        self._check()
        self.dev.move_by(axis=axis, steps=int(steps))
        if wait:
            self.dev.wait_move(axis=axis)

    def move_abs(self, axis: int = 1, position: int = 0, wait: bool = True):
        self._check()
        self.dev.move_to(axis=axis, position=int(position))
        if wait:
            self.dev.wait_move(axis=axis)

    def is_moving(self, axis: int = 1) -> bool:
        self._check()
        return bool(self.dev.is_moving(axis=axis))

    def wait(self, axis: int = 1) -> None:
        self._check()
        self.dev.wait_move(axis=axis)

    def stop(self, axis="all", immediate: bool = False):
        self._check()
        self.dev.stop(axis=axis, immediate=immediate)

    def get_vel(self, axis: int = 1):
        self._check()
        return self.dev.get_velocity_parameters(axis=axis)

    def set_vel(self, axis: int = 1, speed=None, accel=None):
        self._check()
        return self.dev.setup_velocity(axis=axis, speed=speed, accel=accel)

    def jog(self, axis: int = 1, direction: str = "+"):
        self._check()
        self.dev.jog(axis=axis, direction=(direction == "+"))

    def jog_for(
        self,
        axis: int = 1,
        direction: str = "+",
        duration_s: float = 1.0,
        *,
        immediate: bool = False,
    ) -> None:
        self.jog(axis=axis, direction=direction)
        try:
            time.sleep(max(0.0, float(duration_s)))
        finally:
            self.stop(axis=axis, immediate=immediate)

    def raw_query(self, cmd: str, *, axis=None):
        self._check()
        return self.dev.query(cmd, axis=axis)


def _normalize_motor_sign(value: int) -> int:
    return 1 if int(value) >= 0 else -1


def _quantize_picomotor_steps(step: float) -> int:
    return max(1, int(round(abs(float(step)))))


class NewportXYStage:
    def __init__(
        self,
        conn: int = 0,
        x_axis: int = 1,
        y_axis: int = 2,
        x_hw_sign: int = 1,
        y_hw_sign: int = 1,
        backend: str = "auto",
        timeout: float = 5.0,
        multiaddr: bool = False,
        scan: bool = True,
        velocity: Optional[int] = None,
        acceleration: Optional[int] = None,
        wait_each_move: bool = True,
    ):
        device_count = PicoMotor8742Controller.usb_device_count()
        if device_count <= 0:
            raise RuntimeError("未找到 Newport Picomotor USB 设备")

        self.controller = PicoMotor8742Controller(
            conn=conn,
            backend=backend,
            timeout=timeout,
            multiaddr=multiaddr,
            scan=scan,
        ).open()
        self.x_axis = x_axis
        self.y_axis = y_axis
        self.x_hw_sign = _normalize_motor_sign(x_hw_sign)
        self.y_hw_sign = _normalize_motor_sign(y_hw_sign)
        self.wait_each_move = bool(wait_each_move)

        controller_id = self.controller.get_id()
        axes = self.controller.require_axes([self.x_axis, self.y_axis])
        LOGGER.info("Newport Picomotor connected: id=%s, usb_count=%d, axes=%s", controller_id, device_count, axes)

        if velocity is not None or acceleration is not None:
            self.controller.set_vel(axis=self.x_axis, speed=velocity, accel=acceleration)
            self.controller.set_vel(axis=self.y_axis, speed=velocity, accel=acceleration)
            LOGGER.info(
                "Newport velocity configured: x_axis=%s, y_axis=%s, speed=%s, accel=%s",
                self.x_axis,
                self.y_axis,
                velocity,
                acceleration,
            )

    def move_x(self, steps: int) -> None:
        steps = int(steps)
        if steps != 0:
            self.controller.move_rel(self.x_axis, steps=self.x_hw_sign * steps, wait=self.wait_each_move)

    def move_y(self, steps: int) -> None:
        steps = int(steps)
        if steps != 0:
            self.controller.move_rel(self.y_axis, steps=self.y_hw_sign * steps, wait=self.wait_each_move)

    def wait_startup_axis(self, axis: Optional[str] = None) -> None:
        if self.wait_each_move:
            return
        if axis == "x":
            self.controller.wait(axis=self.x_axis)
        elif axis == "y":
            self.controller.wait(axis=self.y_axis)

    def close(self) -> None:
        try:
            self.controller.stop(axis=self.x_axis, immediate=False)
        except Exception:
            pass
        try:
            self.controller.stop(axis=self.y_axis, immediate=False)
        except Exception:
            pass
        self.controller.close()

    def __enter__(self):
        return self

    def __exit__(self, *args):
        self.close()


class NewportMRC4MirrorStage:
    """Four-axis Newport mirror stage for dual-mirror MRC beam steering."""

    _VALID_VIRTUAL_AXIS_MODES = {"mirror1", "mirror2", "shared"}

    def __init__(
        self,
        conn: int = 0,
        *,
        mirror1_x_axis: int = 1,
        mirror1_y_axis: int = 2,
        mirror2_x_axis: int = 3,
        mirror2_y_axis: int = 4,
        mirror1_x_sign: int = 1,
        mirror1_y_sign: int = 1,
        mirror2_x_sign: int = 1,
        mirror2_y_sign: int = 1,
        backend: str = "auto",
        timeout: float = 5.0,
        multiaddr: bool = False,
        scan: bool = True,
        velocity: Optional[int] = None,
        acceleration: Optional[int] = None,
        wait_each_move: bool = True,
        virtual_axis_mode: str = "shared",
        controller: Optional[PicoMotor8742Controller] = None,
    ):
        if controller is None:
            device_count = PicoMotor8742Controller.usb_device_count()
            if device_count <= 0:
                raise RuntimeError("未找到 Newport Picomotor USB 设备")
            controller = PicoMotor8742Controller(
                conn=conn,
                backend=backend,
                timeout=timeout,
                multiaddr=multiaddr,
                scan=scan,
            ).open()
        else:
            device_count = -1

        self.controller = controller
        self.wait_each_move = bool(wait_each_move)
        self.virtual_axis_mode = str(virtual_axis_mode).strip().lower()
        if self.virtual_axis_mode not in self._VALID_VIRTUAL_AXIS_MODES:
            raise ValueError(
                f"Unsupported MRC virtual axis mode: {virtual_axis_mode}. "
                f"Expected one of {sorted(self._VALID_VIRTUAL_AXIS_MODES)}"
            )

        self.axis_map = {
            "mirror1_x": int(mirror1_x_axis),
            "mirror1_y": int(mirror1_y_axis),
            "mirror2_x": int(mirror2_x_axis),
            "mirror2_y": int(mirror2_y_axis),
        }
        if len(set(self.axis_map.values())) != 4:
            raise RuntimeError("MRC 4 轴映射必须使用 4 个不同的 Picomotor 轴")

        self.sign_map = {
            "mirror1_x": _normalize_motor_sign(mirror1_x_sign),
            "mirror1_y": _normalize_motor_sign(mirror1_y_sign),
            "mirror2_x": _normalize_motor_sign(mirror2_x_sign),
            "mirror2_y": _normalize_motor_sign(mirror2_y_sign),
        }

        controller_id = self.controller.get_id()
        axes = self.controller.require_axes(list(self.axis_map.values()))
        LOGGER.info(
            "Newport MRC 4-axis connected: id=%s, usb_count=%s, axes=%s, mode=%s",
            controller_id,
            device_count if device_count >= 0 else "injected",
            axes,
            self.virtual_axis_mode,
        )

        if velocity is not None or acceleration is not None:
            for axis in sorted(set(self.axis_map.values())):
                self.controller.set_vel(axis=axis, speed=velocity, accel=acceleration)
            LOGGER.info(
                "Newport MRC 4-axis velocity configured: axes=%s speed=%s accel=%s",
                sorted(set(self.axis_map.values())),
                velocity,
                acceleration,
            )

    def _move_named_axis(self, axis_name: str, steps: int) -> None:
        steps = int(steps)
        if steps == 0:
            return
        axis = self.axis_map[axis_name]
        signed_steps = self.sign_map[axis_name] * steps
        self.controller.move_rel(axis=axis, steps=signed_steps, wait=self.wait_each_move)

    def move_mirror1_x(self, steps: int) -> None:
        self._move_named_axis("mirror1_x", steps)

    def move_mirror1_y(self, steps: int) -> None:
        self._move_named_axis("mirror1_y", steps)

    def move_mirror2_x(self, steps: int) -> None:
        self._move_named_axis("mirror2_x", steps)

    def move_mirror2_y(self, steps: int) -> None:
        self._move_named_axis("mirror2_y", steps)

    def move_mirrors(
        self,
        *,
        mirror1_x_steps: int = 0,
        mirror1_y_steps: int = 0,
        mirror2_x_steps: int = 0,
        mirror2_y_steps: int = 0,
    ) -> None:
        self.move_mirror1_x(mirror1_x_steps)
        self.move_mirror1_y(mirror1_y_steps)
        self.move_mirror2_x(mirror2_x_steps)
        self.move_mirror2_y(mirror2_y_steps)

    def _virtual_axis_keys(self, axis: str) -> List[str]:
        axis = str(axis).strip().lower()
        if axis not in {"x", "y"}:
            raise ValueError(f"Unsupported virtual axis: {axis}")
        if self.virtual_axis_mode == "mirror1":
            return [f"mirror1_{axis}"]
        if self.virtual_axis_mode == "mirror2":
            return [f"mirror2_{axis}"]
        return [f"mirror1_{axis}", f"mirror2_{axis}"]

    def move_x(self, steps: int) -> None:
        axis_keys = self._virtual_axis_keys("x")
        if axis_keys == ["mirror1_x"]:
            self.move_mirror1_x(steps)
            return
        if axis_keys == ["mirror2_x"]:
            self.move_mirror2_x(steps)
            return
        self.move_mirrors(mirror1_x_steps=steps, mirror2_x_steps=steps)

    def move_y(self, steps: int) -> None:
        axis_keys = self._virtual_axis_keys("y")
        if axis_keys == ["mirror1_y"]:
            self.move_mirror1_y(steps)
            return
        if axis_keys == ["mirror2_y"]:
            self.move_mirror2_y(steps)
            return
        self.move_mirrors(mirror1_y_steps=steps, mirror2_y_steps=steps)

    def wait_startup_axis(self, axis: Optional[str] = None) -> None:
        if self.wait_each_move:
            return
        axis_names = list(self.axis_map.keys()) if axis is None else self._virtual_axis_keys(axis)
        for axis_name in axis_names:
            self.controller.wait(axis=self.axis_map[axis_name])

    def close(self) -> None:
        for axis in sorted(set(self.axis_map.values())):
            try:
                self.controller.stop(axis=axis, immediate=False)
            except Exception:
                pass
        self.controller.close()

    def __enter__(self):
        return self

    def __exit__(self, *args):
        self.close()


