    def _inc_metric(self, name: str, delta: int = 1) -> None:
        """Increment a reporter metric if reporter is available."""
        if self.reporter is not None:
            setattr(self.reporter.metrics, name, getattr(self.reporter.metrics, name) + delta)

    def _detect_with_runtime_metrics(
        self,
        frame: np.ndarray,
        *,
        tag: str,
        attempt: int,
        source: str,
    ) -> Optional[SpotDetection]:
        started = time.perf_counter()
        detection: Optional[SpotDetection] = None
        succeeded = False
        try:
            detection = self.detector.detect(frame)
            succeeded = True
            return detection
        finally:
            if self.reporter is not None:
                latency_ms = (time.perf_counter() - started) * 1000.0
                self.reporter.record_detector_inference(
                    latency_ms=latency_ms,
                    tag=tag,
                    attempt=int(attempt),
                    source=str(source),
                    succeeded=bool(succeeded),
                )

    def run(self) -> bool:
        strategy = getattr(self.cfg, "alignment_strategy", "z_scan_legacy")
        LOGGER.info("Selected alignment strategy: %s", strategy)

        if strategy == "dual_detector_4axis":
            return self._run_4axis()
        elif strategy == "detector_comparison":
            return self._run_detector_comparison()
        else:
            return self._run_z_scan_legacy()

    def _run_z_scan_legacy(self) -> bool:
        target = self._detect_center_with_retry(tag="Initial P1")
        LOGGER.info("Initial target P1 = %s", target.center)
        if self.reporter is not None:
            self.reporter.event("target_initialized", target=list(target.center))

        for iteration in range(1, self.cfg.max_iterations + 1):
            LOGGER.info("========== Iteration %d/%d ==========", iteration, self.cfg.max_iterations)

            self.z_stage.move_up(self.cfg.z_move_step)
            if self.reporter is not None:
                self.reporter.metrics.z_up_commands += 1
            time.sleep(self.cfg.settle_time_s)
            p2_before = self._detect_center_with_retry(tag=f"Iter {iteration} after Z up (P2 before)")
            LOGGER.info("P2 (before align) = %s", p2_before.center)
            p2_after = self._align_to_target(target.center, tag=f"Iter {iteration} align P2")
            LOGGER.info("P2 (after align) = %s", p2_after.center)

            self.z_stage.move_down(self.cfg.z_move_step)
            if self.reporter is not None:
                self.reporter.metrics.z_down_commands += 1
            time.sleep(self.cfg.settle_time_s)
            p3_before = self._detect_center_with_retry(tag=f"Iter {iteration} after Z down (P3 before)")
            LOGGER.info("P3 (before align) = %s", p3_before.center)
            p3_after = self._align_to_target(target.center, tag=f"Iter {iteration} align P3")
            LOGGER.info("P3 (after align) = %s", p3_after.center)

            if self._is_converged(target.center, p2_after.center, p3_after.center):
                LOGGER.info("Converged: P1=%s, P2=%s, P3=%s", target.center, p2_after.center, p3_after.center)
                if self.reporter is not None:
                    self.reporter.event("converged", p1=list(target.center), p2=list(p2_after.center), p3=list(p3_after.center))
                return True

        LOGGER.warning("Reached max iterations without meeting P1>=P2>=P3 convergence")
        if self.reporter is not None:
            self.reporter.event("not_converged", max_iterations=self.cfg.max_iterations)
        return False

    def _run_4axis(self) -> bool:
        """4轴闭环对准，支持单探测器和双探测器两种模式。"""
        LOGGER.info("Starting 4-axis closed-loop alignment")
        if not hasattr(self, 'four_axis_controller') or self.four_axis_controller is None:
            raise RuntimeError("FourAxisController not initialized for 4-axis strategy")
        if not hasattr(self, 'frame_source_pair') or self.frame_source_pair is None:
            raise RuntimeError("FrameSourcePair not initialized for 4-axis strategy")

        # 判断探测器模式
        is_dual_detector = (self.frame_source_pair.source_ang is not None and 
                           self.four_axis_controller.detector_mode == "dual_detector")
        
        if is_dual_detector:
            LOGGER.info("Dual-detector mode: using separate position and angle detectors")
            return self._run_4axis_dual_detector()
        else:
            LOGGER.info("Single-detector mode: using sequential control with one detector")
            return self._run_4axis_single_detector()

    def _run_4axis_dual_detector(self) -> bool:
        """双探测器模式：两个探测器分别测量位置和角度。"""
        target_pos = self._detect_center_with_retry(tag="Initial position target")
        target_ang = self._detect_center_with_retry(tag="Initial angle target", frame_source_idx=1)
        LOGGER.info("Initial targets: pos=%s, ang=%s", target_pos.center, target_ang.center)

        if self.reporter is not None:
            self.reporter.event("target_initialized_4axis", pos_target=list(target_pos.center), ang_target=list(target_ang.center))

        self.four_axis_controller.reset_integrators()

        for iteration in range(1, self.cfg.max_iterations + 1):
            LOGGER.info("========== 4-Axis Iteration %d/%d ==========", iteration, self.cfg.max_iterations)

            frame_pos, frame_ang = self.frame_source_pair.grab_frames()

            det_pos = self._detect_on_frame(frame_pos, tag=f"Iter {iteration} position detection")
            det_ang = self._detect_on_frame(frame_ang, tag=f"Iter {iteration} angle detection") if frame_ang is not None else det_pos

            if det_pos is None or det_ang is None:
                LOGGER.warning("Detection failed on iteration %d", iteration)
                time.sleep(self.cfg.settle_time_s)
                continue

            e_pos = (target_pos.center[0] - det_pos.center[0], target_pos.center[1] - det_pos.center[1])
            e_ang = (target_ang.center[0] - det_ang.center[0], target_ang.center[1] - det_ang.center[1])

            LOGGER.info("Error: pos=(%d, %d), ang=(%d, %d)", e_pos[0], e_pos[1], e_ang[0], e_ang[1])

            if self.reporter is not None:
                self.reporter.event("4axis_error", e_pos=list(e_pos), e_ang=list(e_ang), iteration=iteration)

            if self.four_axis_controller.is_converged(e_pos, e_ang):
                LOGGER.info("4-axis converged: e_pos=%s, e_ang=%s", e_pos, e_ang)
                if self.reporter is not None:
                    self.reporter.event("converged_4axis", e_pos=list(e_pos), e_ang=list(e_ang))
                return True

            u1_x, u1_y, u2_x, u2_y = self.four_axis_controller.compute_control(e_pos, e_ang)
            LOGGER.info("Control output: stage1=(%d, %d), stage2=(%d, %d)", u1_x, u1_y, u2_x, u2_y)

            if hasattr(self.xy_stage, 'move_x1') and hasattr(self.xy_stage, 'move_y1'):
                self.xy_stage.move_x1(u1_x)
                self.xy_stage.move_y1(u1_y)
            else:
                self.xy_stage.move_x(u1_x)
                self.xy_stage.move_y(u1_y)

            if hasattr(self.xy_stage, 'move_x2') and hasattr(self.xy_stage, 'move_y2'):
                self.xy_stage.move_x2(u2_x)
                self.xy_stage.move_y2(u2_y)

            if self.reporter is not None:
                self.reporter.metrics.x_move_commands += 1
                self.reporter.metrics.y_move_commands += 1

            time.sleep(self.cfg.settle_time_s)

        LOGGER.warning("4-axis alignment reached max iterations without convergence")
        if self.reporter is not None:
            self.reporter.event("not_converged_4axis", max_iterations=self.cfg.max_iterations)
        return False

    def _run_4axis_single_detector(self) -> bool:
        """单探测器模式：顺序控制策略。
        
        阶段1：用镜子1（近端）进行粗调
        - 镜子1离探测器远，转动时光斑移动大（杠杆效应）
        - 适合快速将光斑拉到目标附近
        
        阶段2：用镜子2（远端）进行细调
        - 镜子2离探测器近，转动时光斑移动小
        - 适合精细调整，提高精度
        """
        target = self._detect_center_with_retry(tag="Initial target")
        LOGGER.info("Initial target: %s", target.center)

        if self.reporter is not None:
            self.reporter.event("target_initialized_4axis_single", target=list(target.center))

        self.four_axis_controller.reset_integrators()

        for iteration in range(1, self.cfg.max_iterations + 1):
            LOGGER.info("========== Single-Detector Iteration %d/%d ==========", iteration, self.cfg.max_iterations)
            
            # 更新控制阶段
            self.four_axis_controller.update_stage(iteration)
            stage = self.four_axis_controller._current_stage

            # 采集帧（只有一个探测器）
            frame = self.window.grab_frame()
            det = self._detect_on_frame(frame, tag=f"Iter {iteration} detection")

            if det is None:
                LOGGER.warning("Detection failed on iteration %d", iteration)
                time.sleep(self.cfg.settle_time_s)
                continue

            # 计算误差
            e_pos = (target.center[0] - det.center[0], target.center[1] - det.center[1])
            e_ang = (0, 0)  # 单探测器模式没有角度测量
            
            LOGGER.info("Error: pos=(%d, %d), Stage=%d", e_pos[0], e_pos[1], stage)

            if self.reporter is not None:
                self.reporter.event("4axis_single_error", e_pos=list(e_pos), stage=stage, iteration=iteration)

            # 收敛检查
            if self.four_axis_controller.is_converged(e_pos, e_ang):
                LOGGER.info("Single-detector converged: e_pos=%s", e_pos)
                if self.reporter is not None:
                    self.reporter.event("converged_4axis_single", e_pos=list(e_pos), stage=stage)
                return True

            # 计算控制量
            u1_x, u1_y, u2_x, u2_y = self.four_axis_controller.compute_control(e_pos, e_ang)
            
            if stage == 1:
                LOGGER.info("Stage 1 (coarse): mirror1=(%d, %d)", u1_x, u1_y)
            else:
                LOGGER.info("Stage 2 (fine): mirror2=(%d, %d)", u2_x, u2_y)

            # 执行控制
            if hasattr(self.xy_stage, 'move_x1') and hasattr(self.xy_stage, 'move_y1'):
                if u1_x != 0 or u1_y != 0:
                    self.xy_stage.move_x1(u1_x)
                    self.xy_stage.move_y1(u1_y)
                if u2_x != 0 or u2_y != 0:
                    self.xy_stage.move_x2(u2_x)
                    self.xy_stage.move_y2(u2_y)
            else:
                # 如果没有独立控制接口，使用虚拟轴模式
                if u1_x != 0 or u1_y != 0:
                    self.xy_stage.move_x(u1_x)
                    self.xy_stage.move_y(u1_y)

            if self.reporter is not None:
                self.reporter.metrics.x_move_commands += 1
                self.reporter.metrics.y_move_commands += 1

            time.sleep(self.cfg.settle_time_s)

        LOGGER.warning("Single-detector alignment reached max iterations without convergence")
        if self.reporter is not None:
            self.reporter.event("not_converged_4axis_single", max_iterations=self.cfg.max_iterations)
        return False

    def _run_detector_comparison(self) -> bool:
        """探测器效果对比策略：同时使用ToupView和探测器进行对比校准。
        
        三种模式：
        1. detector_primary: 以探测器为主，ToupView辅助验证
        2. touview_verify: 以ToupView为主，探测器辅助验证  
        3. auto_switch: 根据误差自动切换主源
        
        核心思想：
        - 同时采集ToupView和探测器的图像
        - 分别计算光斑位置误差
        - 加权融合误差或根据模式选择主源
        - 当两者差异大时发出警告（可能表示光路问题）
        """
        LOGGER.info("Starting detector comparison alignment (mode=%s)", self.cfg.comparison_mode)
        
        # 初始化两个目标（ToupView和探测器）
        target_touview = self._detect_center_with_retry(tag="Initial ToupView target")
        LOGGER.info("Initial ToupView target: %s", target_touview.center)
        
        # 检查是否有探测器帧源
        has_detector_source = (hasattr(self, 'frame_source_pair') and 
                              self.frame_source_pair is not None and
                              self.frame_source_pair.source_ang is not None)
        
        if not has_detector_source:
            LOGGER.warning("No detector source available, falling back to ToupView only")
            target_detector = target_touview
        else:
            target_detector = self._detect_center_with_retry(tag="Initial detector target", frame_source_idx=1)
            LOGGER.info("Initial detector target: %s", target_detector.center)

        if self.reporter is not None:
            self.reporter.event("target_initialized_comparison", 
                              touview_target=list(target_touview.center),
                              detector_target=list(target_detector.center) if has_detector_source else None)

        # 初始化4轴控制器（用于单探测器模式）
        if hasattr(self, 'four_axis_controller') and self.four_axis_controller is not None:
            self.four_axis_controller.reset_integrators()

        # 初始化稳定帧计数器
        stable_frame_count = 0

        for iteration in range(1, self.cfg.max_iterations + 1):
            LOGGER.info("========== Comparison Iteration %d/%d ==========", iteration, self.cfg.max_iterations)

            # 采集ToupView帧
            frame_touview = self.window.grab_frame()
            det_touview = self._detect_on_frame(frame_touview, tag=f"Iter {iteration} ToupView detection")

            # 采集探测器帧（如果有）
            det_detector = None
            if has_detector_source:
                frame_detector = self.frame_source_pair.source_ang.grab_frame()
                det_detector = self._detect_on_frame(frame_detector, tag=f"Iter {iteration} detector detection")

            if det_touview is None:
                LOGGER.warning("ToupView detection failed on iteration %d", iteration)
                time.sleep(self.cfg.settle_time_s)
                continue

            # 计算误差
            e_touview = (target_touview.center[0] - det_touview.center[0], 
                        target_touview.center[1] - det_touview.center[1])
            
            if det_detector is not None:
                e_detector = (target_detector.center[0] - det_detector.center[0],
                             target_detector.center[1] - det_detector.center[1])
            else:
                e_detector = e_touview  # 如果没有探测器，使用ToupView误差

            # 计算差异（用于监控和警告）
            disagreement = math.hypot(e_touview[0] - e_detector[0], e_touview[1] - e_detector[1])
            
            # 根据模式选择或融合误差
            if self.cfg.comparison_mode == "detector_primary":
                # 以探测器为主
                e_pos = e_detector
                primary_source = "detector"
                if det_detector is None:
                    e_pos = e_touview
                    primary_source = "touview (fallback)"
            elif self.cfg.comparison_mode == "touview_verify":
                # 以ToupView为主
                e_pos = e_touview
                primary_source = "touview"
            else:  # auto_switch
                # 自动切换：选择误差较小的源
                if det_detector is not None:
                    norm_touview = math.hypot(e_touview[0], e_touview[1])
                    norm_detector = math.hypot(e_detector[0], e_detector[1])
                    if norm_detector < norm_touview:
                        e_pos = e_detector
                        primary_source = "detector"
                    else:
                        e_pos = e_touview
                        primary_source = "touview"
                else:
                    e_pos = e_touview
                    primary_source = "touview"

            # 加权融合（可选，用于日志和监控）
            e_fused = (self.cfg.detector_weight * e_detector[0] + self.cfg.touview_weight * e_touview[0],
                      self.cfg.detector_weight * e_detector[1] + self.cfg.touview_weight * e_touview[1])

            # 日志输出
            if iteration % self.cfg.comparison_log_interval == 0:
                LOGGER.info("Comparison results:")
                LOGGER.info("  ToupView error: (%d, %d), norm=%.2f", e_touview[0], e_touview[1], math.hypot(*e_touview))
                if det_detector is not None:
                    LOGGER.info("  Detector error: (%d, %d), norm=%.2f", e_detector[0], e_detector[1], math.hypot(*e_detector))
                LOGGER.info("  Disagreement: %.2f px (threshold=%.2f)", disagreement, self.cfg.disagreement_threshold_px)
                LOGGER.info("  Primary source: %s, Fused error: (%.1f, %.1f)", primary_source, e_fused[0], e_fused[1])

            # 差异警告
            if disagreement > self.cfg.disagreement_threshold_px:
                LOGGER.warning("Large disagreement between ToupView and detector: %.2f px", disagreement)
                if self.reporter is not None:
                    self.reporter.event("disagreement_warning", 
                                      disagreement=disagreement,
                                      threshold=self.cfg.disagreement_threshold_px,
                                      e_touview=list(e_touview),
                                      e_detector=list(e_detector))

            # 收敛检查（使用主源误差）
            error_norm = math.hypot(e_pos[0], e_pos[1])
            if error_norm <= self.cfg.tolerance_pos_px:
                stable_frame_count += 1
                LOGGER.info("Error within tolerance (%.2f <= %d), stable_count=%d/%d", 
                           error_norm, self.cfg.tolerance_pos_px, stable_frame_count, self.cfg.converge_stable_frames)
                if stable_frame_count >= self.cfg.converge_stable_frames:
                    LOGGER.info("Comparison alignment converged: error=%s, source=%s", e_pos, primary_source)
                    if self.reporter is not None:
                        self.reporter.event("converged_comparison", 
                                          error=list(e_pos),
                                          primary_source=primary_source,
                                          disagreement=disagreement)
                    return True
            else:
                if stable_frame_count > 0:
                    LOGGER.info("Error outside tolerance (%.2f > %d), reset stable_count", 
                               error_norm, self.cfg.tolerance_pos_px)
                stable_frame_count = 0

            # 计算控制量
            if hasattr(self, 'four_axis_controller') and self.four_axis_controller is not None:
                u1_x, u1_y, u2_x, u2_y = self.four_axis_controller.compute_control(e_pos, (0, 0))
            else:
                # 简化的PI控制
                u1_x = int(round(self.cfg.stage1_kp * e_pos[0]))
                u1_y = int(round(self.cfg.stage1_kp * e_pos[1]))
                u2_x, u2_y = 0, 0

            LOGGER.info("Control output: stage1=(%d, %d), stage2=(%d, %d), source=%s", 
                       u1_x, u1_y, u2_x, u2_y, primary_source)

            # 执行控制
            if hasattr(self.xy_stage, 'move_x1') and hasattr(self.xy_stage, 'move_y1'):
                if u1_x != 0 or u1_y != 0:
                    self.xy_stage.move_x1(u1_x)
                    self.xy_stage.move_y1(u1_y)
                if u2_x != 0 or u2_y != 0:
                    self.xy_stage.move_x2(u2_x)
                    self.xy_stage.move_y2(u2_y)
            else:
                if u1_x != 0 or u1_y != 0:
                    self.xy_stage.move_x(u1_x)
                    self.xy_stage.move_y(u1_y)

            if self.reporter is not None:
                self.reporter.metrics.x_move_commands += 1
                self.reporter.metrics.y_move_commands += 1
                self.reporter.event("comparison_control", 
                                  iteration=iteration,
                                  primary_source=primary_source,
                                  e_pos=list(e_pos),
                                  u1=(u1_x, u1_y),
                                  u2=(u2_x, u2_y),
                                  disagreement=disagreement)

            time.sleep(self.cfg.settle_time_s)

        LOGGER.warning("Comparison alignment reached max iterations without convergence")
        if self.reporter is not None:
            self.reporter.event("not_converged_comparison", max_iterations=self.cfg.max_iterations)
        return False

    def _detect_on_frame(self, frame: np.ndarray, tag: str) -> Optional[SpotDetection]:
        if frame is None:
            return None
        try:
            prepared = self._prepare_detection_frame(frame)
            det = self.detector.detect(prepared)
            if det is not None:
                return det
            for attempt in range(1, self.cfg.detect_retry + 1):
                time.sleep(self.cfg.detect_retry_interval)
                prepared = self._prepare_detection_frame(frame)
                det = self.detector.detect(prepared)
                if det is not None:
                    return det
            return None
        except Exception as exc:
            LOGGER.warning("Detection failed: %s", exc)
            return None

    def _align_to_target(self, target: Tuple[int, int], tag: str) -> SpotDetection:
        last_detection: Optional[SpotDetection] = None

        for round_idx in range(1, self.cfg.max_align_rounds + 1):
            detection = self._detect_center_with_retry(tag=f"{tag} round {round_idx}", target=target)
            last_detection = detection
            dx = target[0] - detection.center[0]
            dy = target[1] - detection.center[1]

            LOGGER.info(
                "%s: detection=%s, target=%s, offset=(dx=%d, dy=%d)",
                tag,
                detection.center,
                target,
                dx,
                dy,
            )

            if abs(dx) <= self.cfg.tolerance_px and abs(dy) <= self.cfg.tolerance_px:
                return detection

            if self.reporter is not None:
                self.reporter.metrics.align_rounds += 1

            if abs(dx) > self.cfg.tolerance_px:
                x_step_mag = self._calc_axis_steps("x", dx)
                x_steps = x_step_mag * self.cfg.x_error_to_stage_sign * (1 if dx > 0 else -1)
                # --- 安全检查 ---
                if self._safety is not None and not self._safety.check_move_x(x_steps):
                    raise RuntimeError(f"Safety: X move blocked. {self._safety.state.last_violation}")
                self.xy_stage.move_x(x_steps)
                if self._safety is not None:
                    self._safety.record_move_x(x_steps)
                # --- 轨迹记录 ---
                if self._trajectory is not None:
                    self._trajectory.record_move_x(x_steps)
                if self.reporter is not None:
                    self.reporter.metrics.x_move_commands += 1
            if abs(dy) > self.cfg.tolerance_px:
                y_step_mag = self._calc_axis_steps("y", dy)
                y_steps = y_step_mag * self.cfg.y_error_to_stage_sign * (1 if dy > 0 else -1)
                # --- 安全检查 ---
                if self._safety is not None and not self._safety.check_move_y(y_steps):
                    raise RuntimeError(f"Safety: Y move blocked. {self._safety.state.last_violation}")
                self.xy_stage.move_y(y_steps)
                if self._safety is not None:
                    self._safety.record_move_y(y_steps)
                # --- 轨迹记录 ---
                if self._trajectory is not None:
                    self._trajectory.record_move_y(y_steps)
                if self.reporter is not None:
                    self.reporter.metrics.y_move_commands += 1

            time.sleep(self.cfg.settle_time_s)

        if last_detection is None:
            raise RuntimeError(f"{tag}: no valid detection during alignment")
        raise RuntimeError(f"{tag}: max alignment rounds reached; last={last_detection.center}")

    def _prepare_detection_frame(self, frame: np.ndarray) -> np.ndarray:
        prepared = frame

        if self._frontier_v7_denoiser is not None:
            self._inc_metric("frontier_v7_denoise_calls")
            try:
                denoise_input = self._to_grayscale(prepared)
                denoise_report = self._frontier_v7_denoiser.denoise(denoise_input)
                denoised = getattr(denoise_report, "denoised_image", None)
                if not isinstance(denoised, np.ndarray) or denoised.size == 0:
                    raise ValueError("v7 denoiser returned empty image")
                denoised_bgr = self._as_uint8_bgr(denoised)
                if denoised_bgr.shape[:2] != prepared.shape[:2]:
                    denoised_bgr = cv2.resize(
                        denoised_bgr,
                        (prepared.shape[1], prepared.shape[0]),
                        interpolation=cv2.INTER_CUBIC,
                    )
                blend = float(np.clip(float(self.cfg.frontier_v7_denoiser_blend), 0.0, 1.0))
                if blend >= 1.0:
                    prepared = denoised_bgr
                elif blend > 0.0:
                    prepared = cv2.addWeighted(
                        self._as_uint8_bgr(prepared),
                        1.0 - blend,
                        denoised_bgr,
                        blend,
                        0.0,
                    )
                if self.reporter is not None:
                    self.reporter.event(
                        "frontier_v7_denoise_applied",
                        blend=round(blend, 4),
                        sigma=round(float(getattr(denoise_report, "estimated_sigma", 0.0) or 0.0), 6),
                        snr_improvement_db=round(float(getattr(denoise_report, "snr_improvement", 0.0) or 0.0), 6),
                        elapsed_ms=round(float(getattr(denoise_report, "processing_time_ms", 0.0) or 0.0), 4),
                    )
            except Exception as exc:
                self._inc_metric("frontier_v7_denoise_failures")
                LOGGER.warning("Frontier v7 denoiser failed; fallback to raw frame: %s", exc)
                if self.reporter is not None:
                    self.reporter.event("frontier_v7_denoise_failed", error=str(exc))
                prepared = frame

        if self._frontier_v6_diffusion is not None:
            self._inc_metric("frontier_v6_diffusion_calls")
            try:
                diffusion_report = self._frontier_v6_diffusion.enhance(prepared)
                enhanced = getattr(diffusion_report, "enhanced_image", None)
                if not isinstance(enhanced, np.ndarray) or enhanced.size == 0:
                    raise ValueError("v6 diffusion enhancer returned empty image")
                enhanced_bgr = self._as_uint8_bgr(enhanced)
                if enhanced_bgr.shape[:2] != prepared.shape[:2]:
                    enhanced_bgr = cv2.resize(
                        enhanced_bgr,
                        (prepared.shape[1], prepared.shape[0]),
                        interpolation=cv2.INTER_CUBIC,
                    )
                blend = float(np.clip(float(self.cfg.frontier_v6_diffusion_blend), 0.0, 1.0))
                if blend >= 1.0:
                    prepared = enhanced_bgr
                elif blend > 0.0:
                    prepared = cv2.addWeighted(
                        self._as_uint8_bgr(prepared),
                        1.0 - blend,
                        enhanced_bgr,
                        blend,
                        0.0,
                    )
                if self.reporter is not None:
                    self.reporter.event(
                        "frontier_v6_diffusion_applied",
                        blend=round(blend, 4),
                        iterations=int(getattr(diffusion_report, "iterations_used", 0) or 0),
                        snr_before=round(float(getattr(diffusion_report, "snr_before", 0.0) or 0.0), 6),
                        snr_after=round(float(getattr(diffusion_report, "snr_after", 0.0) or 0.0), 6),
                        enhancement=round(float(getattr(diffusion_report, "enhancement_factor", 0.0) or 0.0), 6),
                    )
            except Exception as exc:
                self._inc_metric("frontier_v6_diffusion_failures")
                LOGGER.warning("Frontier v6 diffusion preprocess failed; fallback to current frame: %s", exc)
                if self.reporter is not None:
                    self.reporter.event("frontier_v6_diffusion_failed", error=str(exc))

        if self._frontier_v26_foundation is not None:
            self._inc_metric("frontier_v26_foundation_calls")
            try:
                enhanced = self._frontier_v26_foundation.process(prepared)
                enhanced_image = getattr(enhanced, "enhanced_image", None)
                if not isinstance(enhanced_image, np.ndarray) or enhanced_image.size == 0:
                    raise ValueError("frontier v26 foundation enhancer returned empty image")
                prepared = self._ensure_bgr(enhanced_image)
                if self.reporter is not None:
                    self.reporter.event(
                        "frontier_v26_foundation_applied",
                        psnr=round(float(getattr(enhanced, "psnr_improvement", 0.0)), 4),
                        ssim=round(float(getattr(enhanced, "ssim_score", 0.0)), 6),
                        elapsed_ms=round(float(getattr(enhanced, "processing_time_ms", 0.0)), 4),
                    )
            except Exception as exc:
                self._inc_metric("frontier_v26_foundation_failures")
                LOGGER.warning("Frontier v26 foundation enhancer failed; fallback to raw frame: %s", exc)
                if self.reporter is not None:
                    self.reporter.event("frontier_v26_foundation_failed", error=str(exc))
                prepared = frame

        if self._frontier_multiframe_denoiser is not None:
            self._inc_metric("frontier_v25_denoise_calls")
            try:
                gray = self._to_grayscale(prepared)
                denoise_result = self._frontier_multiframe_denoiser.denoise(gray)
                denoised = denoise_result.denoised
                if not isinstance(denoised, np.ndarray) or denoised.size == 0:
                    raise ValueError("multi-frame denoiser returned empty image")
                prepared = self._ensure_bgr(denoised)
                if self.reporter is not None:
                    self.reporter.event(
                        "frontier_v25_denoise_applied",
                        snr_improvement_db=round(float(getattr(denoise_result, "snr_improvement", 0.0) or 0.0), 4),
                        frames_used=int(getattr(denoise_result, "num_frames_used", 1) or 1),
                        outliers_rejected=int(getattr(denoise_result, "outliers_rejected", 0) or 0),
                    )
            except Exception as exc:
                self._inc_metric("frontier_v25_denoise_failures")
                LOGGER.warning("Frontier v25 multi-frame denoiser failed; fallback to raw frame: %s", exc)
                if self.reporter is not None:
                    self.reporter.event("frontier_v25_denoise_failed", error=str(exc))
                prepared = frame

        if self._frontier_flow_restorer is None:
            return self._ensure_bgr(prepared)

        self._inc_metric("frontier_flow_calls")
        try:
            flow_input = prepared
            if isinstance(prepared, np.ndarray) and prepared.ndim == 3 and prepared.shape[2] >= 3:
                flow_input = cv2.cvtColor(prepared, cv2.COLOR_BGR2GRAY)
            result = self._frontier_flow_restorer.restore(flow_input)
            restored = result.restored_image
            if not isinstance(restored, np.ndarray) or restored.size == 0:
                raise ValueError("flow restorer returned empty image")

            if restored.ndim == 2:
                restored = cv2.cvtColor(restored, cv2.COLOR_GRAY2BGR)
            elif restored.ndim == 3 and restored.shape[2] == 1:
                restored = cv2.cvtColor(restored, cv2.COLOR_GRAY2BGR)
            elif restored.ndim == 3 and restored.shape[2] > 3:
                restored = restored[:, :, :3]

            if restored.dtype != np.uint8:
                restored_f = restored.astype(np.float64)
                if float(np.max(restored_f)) <= 1.5:
                    restored = np.clip(restored_f, 0.0, 1.0) * 255.0
                else:
                    restored = np.clip(restored_f, 0.0, 255.0)
                restored = restored.astype(np.uint8)
            else:
                restored = np.ascontiguousarray(restored)

            if restored.shape[:2] != prepared.shape[:2]:
                restored = cv2.resize(restored, (prepared.shape[1], prepared.shape[0]), interpolation=cv2.INTER_CUBIC)

            if self.reporter is not None:
                self.reporter.event(
                    "frontier_flow_applied",
                    ode_steps=int(getattr(result, "num_ode_steps", 0) or 0),
                    processing_ms=round(float(getattr(result, "processing_time_ms", 0.0) or 0.0), 3),
                )
            return restored
        except Exception as exc:
            self._inc_metric("frontier_flow_failures")
            LOGGER.warning("Frontier flow restoration failed; fallback to raw frame: %s", exc)
            if self.reporter is not None:
                self.reporter.event("frontier_flow_failed", error=str(exc))
            return self._ensure_bgr(prepared)

    @staticmethod
    def _to_grayscale(frame: np.ndarray) -> np.ndarray:
        if frame.ndim == 2:
            return frame
        if frame.ndim == 3 and frame.shape[2] == 1:
            return frame[:, :, 0]
        return cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)

    @staticmethod
    def _ensure_bgr(frame: np.ndarray) -> np.ndarray:
        if frame.ndim == 3 and frame.shape[2] >= 3:
            return np.ascontiguousarray(frame[:, :, :3])
        if frame.ndim == 3 and frame.shape[2] == 1:
            return cv2.cvtColor(frame, cv2.COLOR_GRAY2BGR)
        if frame.ndim == 2:
            return cv2.cvtColor(frame, cv2.COLOR_GRAY2BGR)
        raise ValueError(f"Unsupported frame shape: {frame.shape}")

    @staticmethod
    def _as_uint8_bgr(frame: np.ndarray) -> np.ndarray:
        if not isinstance(frame, np.ndarray) or frame.size == 0:
            raise ValueError("frame is empty")
        arr = frame
        if arr.dtype != np.uint8:
            arr_f = arr.astype(np.float64)
            if float(np.max(arr_f)) <= 1.5:
                arr_f = np.clip(arr_f, 0.0, 1.0) * 255.0
            else:
                arr_f = np.clip(arr_f, 0.0, 255.0)
            arr = arr_f.astype(np.uint8)
        return SpotZoomController._ensure_bgr(arr)

    @staticmethod
    def _clip_center(center: Tuple[int, int], frame_shape: Tuple[int, int]) -> Tuple[int, int]:
        h, w = frame_shape[:2]
        cx = max(0, min(int(center[0]), w - 1))
        cy = max(0, min(int(center[1]), h - 1))
        return (cx, cy)

    def _recenter_bbox(
        self,
        bbox: Tuple[int, int, int, int],
        center: Tuple[int, int],
        frame_shape: Tuple[int, int],
    ) -> Tuple[int, int, int, int]:
        h, w = frame_shape[:2]
        x1, y1, x2, y2 = (int(v) for v in bbox)
        bw = max(2, x2 - x1)
        bh = max(2, y2 - y1)
        cx, cy = center
        nx1 = int(round(cx - bw / 2.0))
        ny1 = int(round(cy - bh / 2.0))
        nx2 = nx1 + bw
        ny2 = ny1 + bh
        nx1 = max(0, min(nx1, w - 2))
        ny1 = max(0, min(ny1, h - 2))
        nx2 = max(nx1 + 1, min(nx2, w))
        ny2 = max(ny1 + 1, min(ny2, h))
        return (nx1, ny1, nx2, ny2)

    def _extract_detection_patch(
        self,
        gray_frame: np.ndarray,
        detection: SpotDetection,
    ) -> Optional[np.ndarray]:
        h, w = gray_frame.shape[:2]
        x1, y1, x2, y2 = detection.bbox
        x1 = max(0, min(int(x1), w - 1))
        y1 = max(0, min(int(y1), h - 1))
        x2 = max(x1 + 1, min(int(x2), w))
        y2 = max(y1 + 1, min(int(y2), h))
        patch = gray_frame[y1:y2, x1:x2]
        if patch.size < 9:
            return None
        return patch

    def _update_klt_reference(self, frame: np.ndarray, detection: SpotDetection) -> None:
        if not (
            bool(self.cfg.frontier_klt_recovery_enabled)
            or bool(self.cfg.frontier_phase_recovery_enabled)
            or bool(self.cfg.frontier_ecc_recovery_enabled)
            or bool(self.cfg.frontier_cmc_recovery_enabled)
            or bool(self.cfg.frontier_orb_recovery_enabled)
            or bool(self.cfg.frontier_kalman_recovery_enabled)
            or bool(self.cfg.frontier_pyramid_recovery_enabled)
            or bool(self.cfg.frontier_logpolar_recovery_enabled)
        ):
            return
        try:
            gray = self._to_grayscale(frame)
        except Exception as exc:
            LOGGER.debug("KLT reference update skipped due to grayscale conversion error: %s", exc)
            return
        self._klt_reference_gray = np.ascontiguousarray(gray)
        self._klt_reference_detection = SpotDetection(
            center=(int(detection.center[0]), int(detection.center[1])),
            bbox=tuple(int(v) for v in detection.bbox),
            confidence=float(detection.confidence),
            label=str(detection.label),
            class_id=int(detection.class_id),
        )

    def _recover_with_klt_flow(
        self,
        frame: np.ndarray,
        *,
        tag: str,
        attempt: int,
    ) -> Optional[SpotDetection]:
        if not bool(self.cfg.frontier_klt_recovery_enabled):
            return None
        if self._klt_reference_gray is None or self._klt_reference_detection is None:
            return None

        self._inc_metric("frontier_klt_attempts")
        ref_detection = self._klt_reference_detection
        ref_gray = self._klt_reference_gray
        curr_gray = self._to_grayscale(frame)
        if ref_gray.shape[:2] != curr_gray.shape[:2]:
            self._inc_metric("frontier_klt_failures")
            if self.reporter is not None:
                self.reporter.event(
                    "frontier_klt_recovery_rejected",
                    tag=tag,
                    attempt=attempt,
                    reason="frame_shape_changed",
                    ref_shape=list(ref_gray.shape[:2]),
                    curr_shape=list(curr_gray.shape[:2]),
                )
            return None
        ref_gray = np.ascontiguousarray(ref_gray)
        curr_gray = np.ascontiguousarray(curr_gray)
        h, w = curr_gray.shape[:2]
        x1, y1, x2, y2 = ref_detection.bbox
        x1 = max(0, min(int(x1), w - 1))
        y1 = max(0, min(int(y1), h - 1))
        x2 = max(x1 + 1, min(int(x2), w))
        y2 = max(y1 + 1, min(int(y2), h))
        if (x2 - x1) < 4 or (y2 - y1) < 4:
            self._inc_metric("frontier_klt_failures")
            return None

        roi = ref_gray[y1:y2, x1:x2]
        pts = cv2.goodFeaturesToTrack(
            roi,
            maxCorners=max(4, int(self.cfg.frontier_klt_max_corners)),
            qualityLevel=max(1e-6, float(self.cfg.frontier_klt_quality_level)),
            minDistance=max(1.0, float(self.cfg.frontier_klt_min_distance)),
            blockSize=5,
        )
        if pts is None or len(pts) < max(1, int(self.cfg.frontier_klt_min_tracked_points)):
            self._inc_metric("frontier_klt_failures")
            if self.reporter is not None:
                self.reporter.event(
                    "frontier_klt_recovery_rejected",
                    tag=tag,
                    attempt=attempt,
                    reason="insufficient_features",
                )
            return None

        pts = np.asarray(pts, dtype=np.float32)
        pts[:, 0, 0] += float(x1)
        pts[:, 0, 1] += float(y1)
        lk_kwargs = {
            "winSize": (15, 15),
            "maxLevel": 2,
            "criteria": (cv2.TERM_CRITERIA_EPS | cv2.TERM_CRITERIA_COUNT, 20, 0.03),
        }
        next_pts, st_fwd, _ = cv2.calcOpticalFlowPyrLK(ref_gray, curr_gray, pts, None, **lk_kwargs)
        if next_pts is None or st_fwd is None:
            self._inc_metric("frontier_klt_failures")
            return None
        back_pts, st_bwd, _ = cv2.calcOpticalFlowPyrLK(curr_gray, ref_gray, next_pts, None, **lk_kwargs)
        if back_pts is None or st_bwd is None:
            self._inc_metric("frontier_klt_failures")
            return None

        fwd_ok = st_fwd.reshape(-1) > 0
        bwd_ok = st_bwd.reshape(-1) > 0
        fb_err = np.linalg.norm(pts.reshape(-1, 2) - back_pts.reshape(-1, 2), axis=1)
        valid = fwd_ok & bwd_ok & np.isfinite(fb_err) & (
            fb_err <= float(self.cfg.frontier_klt_bidirectional_error_px)
        )
        valid_count = int(np.count_nonzero(valid))
        min_points = max(1, int(self.cfg.frontier_klt_min_tracked_points))
        if valid_count < min_points:
            self._inc_metric("frontier_klt_failures")
            if self.reporter is not None:
                self.reporter.event(
                    "frontier_klt_recovery_rejected",
                    tag=tag,
                    attempt=attempt,
                    reason="insufficient_bidirectional_points",
                    valid_points=valid_count,
                    required_points=min_points,
                )
            return None

        disp = next_pts.reshape(-1, 2)[valid] - pts.reshape(-1, 2)[valid]
        dx = float(np.median(disp[:, 0]))
        dy = float(np.median(disp[:, 1]))
        shift_px = float(math.hypot(dx, dy))
        max_shift = max(0.0, float(self.cfg.frontier_klt_max_shift_px))
        if shift_px > max_shift:
            self._inc_metric("frontier_klt_failures")
            if self.reporter is not None:
                self.reporter.event(
                    "frontier_klt_recovery_rejected",
                    tag=tag,
                    attempt=attempt,
                    reason="shift_too_large",
                    shift_px=round(shift_px, 6),
                    max_shift_px=round(max_shift, 6),
                )
            return None

        center = self._clip_center(
            (
                int(round(float(ref_detection.center[0]) + dx)),
                int(round(float(ref_detection.center[1]) + dy)),
            ),
            frame.shape[:2],
        )
        bbox = self._recenter_bbox(ref_detection.bbox, center, frame.shape[:2])
        decay = float(np.clip(float(self.cfg.frontier_klt_confidence_decay), 0.01, 1.0))
        recovered = SpotDetection(
            center=center,
            bbox=bbox,
            confidence=float(np.clip(float(ref_detection.confidence) * decay, 0.05, 0.99)),
            label="klt_recovery",
            class_id=ref_detection.class_id,
        )
        self._inc_metric("frontier_klt_success")
        if self.reporter is not None:
            self.reporter.event(
                "frontier_klt_recovery_hit",
                tag=tag,
                attempt=attempt,
                center=list(recovered.center),
                conf=round(float(recovered.confidence), 6),
                shift_px=round(shift_px, 6),
                valid_points=valid_count,
            )
        return recovered

    def _recover_with_phase_correlation(
        self,
        frame: np.ndarray,
        *,
        tag: str,
        attempt: int,
    ) -> Optional[SpotDetection]:
        if not bool(self.cfg.frontier_phase_recovery_enabled):
            return None
        if self._klt_reference_gray is None or self._klt_reference_detection is None:
            return None
        if not hasattr(cv2, "phaseCorrelate"):
            return None

        def _reject(reason: str, **payload) -> None:
            self._inc_metric("frontier_phase_failures")
            if self.reporter is not None:
                event = {"tag": tag, "attempt": attempt, "reason": reason}
                if payload:
                    event.update(payload)
                self.reporter.event("frontier_phase_recovery_rejected", **event)

        self._inc_metric("frontier_phase_attempts")
        ref_detection = self._klt_reference_detection
        ref_gray = np.ascontiguousarray(self._klt_reference_gray)
        try:
            curr_gray = np.ascontiguousarray(self._to_grayscale(frame))
        except Exception as exc:
            _reject("grayscale_conversion_error", error=str(exc))
            return None
        if ref_gray.shape[:2] != curr_gray.shape[:2]:
            _reject(
                "frame_shape_changed",
                ref_shape=list(ref_gray.shape[:2]),
                curr_shape=list(curr_gray.shape[:2]),
            )
            return None

        h, w = curr_gray.shape[:2]
        bx1, by1, bx2, by2 = ref_detection.bbox
        bbox_w = max(4, int(bx2) - int(bx1))
        bbox_h = max(4, int(by2) - int(by1))
        max_shift = max(0.0, float(self.cfg.frontier_phase_max_shift_px))
        span = int(max(max_shift + 4.0, float(max(bbox_w, bbox_h)) * 1.6))
        cx, cy = ref_detection.center
        x1 = max(0, int(cx) - span)
        y1 = max(0, int(cy) - span)
        x2 = min(w, int(cx) + span)
        y2 = min(h, int(cy) + span)
        if (x2 - x1) < 8 or (y2 - y1) < 8:
            _reject("insufficient_roi")
            return None

        ref_roi = ref_gray[y1:y2, x1:x2].astype(np.float32, copy=False)
        curr_roi = curr_gray[y1:y2, x1:x2].astype(np.float32, copy=False)
        window = None
        if bool(self.cfg.frontier_phase_hann_window_enabled) and hasattr(cv2, "createHanningWindow"):
            try:
                window = cv2.createHanningWindow((ref_roi.shape[1], ref_roi.shape[0]), cv2.CV_32F)
            except Exception:
                window = None

        try:
            (dx, dy), response = cv2.phaseCorrelate(ref_roi, curr_roi, window)
        except Exception as exc:
            _reject("phase_correlation_error", error=str(exc))
            return None

        response = float(response)
        if not np.isfinite(response):
            _reject("invalid_response", response=response)
            return None
        min_response = float(np.clip(float(self.cfg.frontier_phase_min_response), 0.0, 1.0))
        if response < min_response:
            _reject(
                "response_too_low",
                response=round(response, 6),
                min_response=round(min_response, 6),
            )
            return None

        dx = float(dx)
        dy = float(dy)
        shift_px = float(math.hypot(dx, dy))
        if not np.isfinite(shift_px):
            _reject("invalid_shift")
            return None
        if shift_px > max_shift:
            _reject(
                "shift_too_large",
                shift_px=round(shift_px, 6),
                max_shift_px=round(max_shift, 6),
            )
            return None

        center = self._clip_center(
            (
                int(round(float(ref_detection.center[0]) + dx)),
                int(round(float(ref_detection.center[1]) + dy)),
            ),
            frame.shape[:2],
        )
        bbox = self._recenter_bbox(ref_detection.bbox, center, frame.shape[:2])
        decay = float(np.clip(float(self.cfg.frontier_phase_confidence_decay), 0.01, 1.0))
        recovered = SpotDetection(
            center=center,
            bbox=bbox,
            confidence=float(np.clip(float(ref_detection.confidence) * decay, 0.05, 0.99)),
            label="phase_recovery",
            class_id=ref_detection.class_id,
        )
        self._inc_metric("frontier_phase_success")
        if self.reporter is not None:
            self.reporter.event(
                "frontier_phase_recovery_hit",
                tag=tag,
                attempt=attempt,
                center=list(recovered.center),
                conf=round(float(recovered.confidence), 6),
                response=round(response, 6),
                shift_px=round(shift_px, 6),
            )
        return recovered

    def _recover_with_ecc_alignment(
        self,
        frame: np.ndarray,
        *,
        tag: str,
        attempt: int,
    ) -> Optional[SpotDetection]:
        if not bool(self.cfg.frontier_ecc_recovery_enabled):
            return None
        if self._klt_reference_gray is None or self._klt_reference_detection is None:
            return None
        if not hasattr(cv2, "findTransformECC"):
            return None

        def _reject(reason: str, **payload) -> None:
            self._inc_metric("frontier_ecc_failures")
            if self.reporter is not None:
                event = {"tag": tag, "attempt": attempt, "reason": reason}
                if payload:
                    event.update(payload)
                self.reporter.event("frontier_ecc_recovery_rejected", **event)

        self._inc_metric("frontier_ecc_attempts")
        ref_detection = self._klt_reference_detection
        ref_gray = np.ascontiguousarray(self._klt_reference_gray)
        try:
            curr_gray = np.ascontiguousarray(self._to_grayscale(frame))
        except Exception as exc:
            _reject("grayscale_conversion_error", error=str(exc))
            return None
        if ref_gray.shape[:2] != curr_gray.shape[:2]:
            _reject(
                "frame_shape_changed",
                ref_shape=list(ref_gray.shape[:2]),
                curr_shape=list(curr_gray.shape[:2]),
            )
            return None

        motion_name = str(self.cfg.frontier_ecc_motion_model).strip().lower()
        motion_map = {
            "translation": int(getattr(cv2, "MOTION_TRANSLATION", -1)),
            "euclidean": int(getattr(cv2, "MOTION_EUCLIDEAN", -1)),
            "affine": int(getattr(cv2, "MOTION_AFFINE", -1)),
        }
        motion_mode = int(motion_map.get(motion_name, -1))
        if motion_mode < 0:
            _reject("unsupported_motion_model", motion_model=motion_name)
            return None

        h, w = curr_gray.shape[:2]
        bx1, by1, bx2, by2 = ref_detection.bbox
        bbox_w = max(4, int(bx2) - int(bx1))
        bbox_h = max(4, int(by2) - int(by1))
        max_shift = max(0.0, float(self.cfg.frontier_ecc_max_shift_px))
        span = int(max(max_shift + 8.0, float(max(bbox_w, bbox_h)) * 2.0))
        cx, cy = ref_detection.center
        x1 = max(0, int(cx) - span)
        y1 = max(0, int(cy) - span)
        x2 = min(w, int(cx) + span)
        y2 = min(h, int(cy) + span)
        if (x2 - x1) < 12 or (y2 - y1) < 12:
            _reject("insufficient_roi")
            return None

        ref_roi = ref_gray[y1:y2, x1:x2].astype(np.float32, copy=False)
        curr_roi = curr_gray[y1:y2, x1:x2].astype(np.float32, copy=False)
        if ref_roi.size == 0 or curr_roi.size == 0:
            _reject("empty_roi")
            return None
        ref_std = float(np.std(ref_roi))
        curr_std = float(np.std(curr_roi))
        if (not np.isfinite(ref_std)) or (not np.isfinite(curr_std)) or ref_std < 1e-3 or curr_std < 1e-3:
            _reject("low_texture", ref_std=round(ref_std, 6), curr_std=round(curr_std, 6))
            return None

        ref_roi = ref_roi / 255.0
        curr_roi = curr_roi / 255.0
        warp = np.eye(2, 3, dtype=np.float32)
        criteria = (
            cv2.TERM_CRITERIA_EPS | cv2.TERM_CRITERIA_COUNT,
            max(1, int(self.cfg.frontier_ecc_max_iterations)),
            max(1e-8, float(self.cfg.frontier_ecc_termination_eps)),
        )
        gauss = max(0, int(self.cfg.frontier_ecc_gauss_filt_size))
        if gauss > 0 and (gauss % 2 == 0):
            gauss += 1

        try:
            if gauss > 0:
                correlation, warp = cv2.findTransformECC(
                    ref_roi,
                    curr_roi,
                    warp,
                    motion_mode,
                    criteria,
                    None,
                    gauss,
                )
            else:
                correlation, warp = cv2.findTransformECC(
                    ref_roi,
                    curr_roi,
                    warp,
                    motion_mode,
                    criteria,
                )
        except Exception as exc:
            _reject("ecc_failed", error=str(exc))
            return None

        correlation = float(correlation)
        if not np.isfinite(correlation):
            _reject("invalid_correlation", correlation=correlation)
            return None
        min_corr = float(np.clip(float(self.cfg.frontier_ecc_min_correlation), -1.0, 1.0))
        if correlation < min_corr:
            _reject(
                "correlation_too_low",
                correlation=round(correlation, 6),
                min_correlation=round(min_corr, 6),
            )
            return None

        local_center = np.array(
            [float(ref_detection.center[0] - x1), float(ref_detection.center[1] - y1), 1.0],
            dtype=np.float32,
        )
        projected_local = np.matmul(warp, local_center)
        center_x = float(projected_local[0] + x1)
        center_y = float(projected_local[1] + y1)
        if not np.isfinite(center_x) or not np.isfinite(center_y):
            _reject("invalid_projected_center")
            return None

        shift_px = float(
            math.hypot(
                center_x - float(ref_detection.center[0]),
                center_y - float(ref_detection.center[1]),
            )
        )
        if not np.isfinite(shift_px) or shift_px > max_shift:
            _reject(
                "shift_too_large",
                shift_px=round(shift_px, 6),
                max_shift_px=round(max_shift, 6),
            )
            return None

        if motion_mode != int(getattr(cv2, "MOTION_TRANSLATION", -1)):
            angle_rad = math.atan2(float(warp[1, 0]), float(warp[0, 0]))
            angle_deg = abs(math.degrees(angle_rad))
            max_rot = max(0.0, float(self.cfg.frontier_ecc_max_rotation_deg))
            if angle_deg > max_rot:
                _reject(
                    "rotation_too_large",
                    rotation_deg=round(angle_deg, 6),
                    max_rotation_deg=round(max_rot, 6),
                )
                return None
        else:
            angle_deg = 0.0

        center = self._clip_center(
            (int(round(center_x)), int(round(center_y))),
            frame.shape[:2],
        )
        bbox = self._recenter_bbox(ref_detection.bbox, center, frame.shape[:2])
        decay = float(np.clip(float(self.cfg.frontier_ecc_confidence_decay), 0.01, 1.0))
        recovered = SpotDetection(
            center=center,
            bbox=bbox,
            confidence=float(np.clip(float(ref_detection.confidence) * decay, 0.05, 0.99)),
            label="ecc_recovery",
            class_id=ref_detection.class_id,
        )
        self._inc_metric("frontier_ecc_success")
        if self.reporter is not None:
            self.reporter.event(
                "frontier_ecc_recovery_hit",
                tag=tag,
                attempt=attempt,
                center=list(recovered.center),
                conf=round(float(recovered.confidence), 6),
                motion_model=motion_name,
                correlation=round(correlation, 6),
                rotation_deg=round(float(angle_deg), 6),
                shift_px=round(shift_px, 6),
            )
        return recovered

    def _recover_with_cmc_affine(
        self,
        frame: np.ndarray,
        *,
        tag: str,
        attempt: int,
    ) -> Optional[SpotDetection]:
        if not bool(self.cfg.frontier_cmc_recovery_enabled):
            return None
        if self._klt_reference_gray is None or self._klt_reference_detection is None:
            return None
        if not (
            hasattr(cv2, "goodFeaturesToTrack")
            and hasattr(cv2, "calcOpticalFlowPyrLK")
            and hasattr(cv2, "estimateAffinePartial2D")
        ):
            return None

        def _reject(reason: str, **payload) -> None:
            self._inc_metric("frontier_cmc_failures")
            if self.reporter is not None:
                event = {"tag": tag, "attempt": attempt, "reason": reason}
                if payload:
                    event.update(payload)
                self.reporter.event("frontier_cmc_recovery_rejected", **event)

        self._inc_metric("frontier_cmc_attempts")
        ref_detection = self._klt_reference_detection
        ref_gray = np.ascontiguousarray(self._klt_reference_gray)
        try:
            curr_gray = np.ascontiguousarray(self._to_grayscale(frame))
        except Exception as exc:
            _reject("grayscale_conversion_error", error=str(exc))
            return None

        if ref_gray.shape[:2] != curr_gray.shape[:2]:
            _reject(
                "frame_shape_changed",
                ref_shape=list(ref_gray.shape[:2]),
                curr_shape=list(curr_gray.shape[:2]),
            )
            return None

        h, w = curr_gray.shape[:2]
        bx1, by1, bx2, by2 = ref_detection.bbox
        bbox_w = max(4, int(bx2) - int(bx1))
        bbox_h = max(4, int(by2) - int(by1))
        max_shift = max(0.0, float(self.cfg.frontier_cmc_max_shift_px))
        span = int(max(max_shift + 10.0, float(max(bbox_w, bbox_h)) * 2.4))
        cx, cy = ref_detection.center
        x1 = max(0, int(cx) - span)
        y1 = max(0, int(cy) - span)
        x2 = min(w, int(cx) + span)
        y2 = min(h, int(cy) + span)
        if (x2 - x1) < 16 or (y2 - y1) < 16:
            _reject("insufficient_roi")
            return None

        ref_roi = ref_gray[y1:y2, x1:x2]
        curr_roi = curr_gray[y1:y2, x1:x2]
        if ref_roi.size == 0 or curr_roi.size == 0:
            _reject("empty_roi")
            return None

        ref_std = float(np.std(ref_roi))
        curr_std = float(np.std(curr_roi))
        if (not np.isfinite(ref_std)) or (not np.isfinite(curr_std)) or ref_std < 1e-3 or curr_std < 1e-3:
            _reject("low_texture", ref_std=round(ref_std, 6), curr_std=round(curr_std, 6))
            return None

        mask = np.full(ref_roi.shape, 255, dtype=np.uint8)
        mx1 = max(0, int(bx1) - x1 - 2)
        my1 = max(0, int(by1) - y1 - 2)
        mx2 = min(mask.shape[1], int(bx2) - x1 + 2)
        my2 = min(mask.shape[0], int(by2) - y1 + 2)
        if mx2 > mx1 and my2 > my1:
            mask[my1:my2, mx1:mx2] = 0

        pts = cv2.goodFeaturesToTrack(
            ref_roi,
            maxCorners=max(4, int(self.cfg.frontier_cmc_max_corners)),
            qualityLevel=max(1e-6, float(self.cfg.frontier_cmc_quality_level)),
            minDistance=max(1.0, float(self.cfg.frontier_cmc_min_distance)),
            mask=mask,
            blockSize=5,
        )
        min_points = max(1, int(self.cfg.frontier_cmc_min_tracked_points))
        if pts is None or len(pts) < min_points:
            _reject(
                "insufficient_features",
                points=0 if pts is None else int(len(pts)),
                required_points=min_points,
            )
            return None

        lk_kwargs = {
            "winSize": (19, 19),
            "maxLevel": 3,
            "criteria": (cv2.TERM_CRITERIA_EPS | cv2.TERM_CRITERIA_COUNT, 24, 0.03),
        }
        next_pts, st_fwd, _ = cv2.calcOpticalFlowPyrLK(ref_roi, curr_roi, pts, None, **lk_kwargs)
        if next_pts is None or st_fwd is None:
            _reject("forward_flow_failed")
            return None
        back_pts, st_bwd, _ = cv2.calcOpticalFlowPyrLK(curr_roi, ref_roi, next_pts, None, **lk_kwargs)
        if back_pts is None or st_bwd is None:
            _reject("backward_flow_failed")
            return None

        pts_flat = pts.reshape(-1, 2)
        next_flat = next_pts.reshape(-1, 2)
        back_flat = back_pts.reshape(-1, 2)
        fb_err = np.linalg.norm(pts_flat - back_flat, axis=1)
        fwd_ok = st_fwd.reshape(-1) > 0
        bwd_ok = st_bwd.reshape(-1) > 0
        valid = fwd_ok & bwd_ok & np.isfinite(fb_err) & (fb_err <= 3.2)
        valid_count = int(np.count_nonzero(valid))
        if valid_count < min_points:
            _reject(
                "insufficient_bidirectional_points",
                valid_points=valid_count,
                required_points=min_points,
            )
            return None

        src_pts = pts_flat[valid]
        dst_pts = next_flat[valid]
        ransac_thresh = max(0.5, float(self.cfg.frontier_cmc_ransac_reproj_threshold))
        affine, inlier_mask = cv2.estimateAffinePartial2D(
            src_pts,
            dst_pts,
            method=cv2.RANSAC,
            ransacReprojThreshold=ransac_thresh,
            maxIters=2000,
            confidence=0.995,
            refineIters=10,
        )
        if affine is None:
            _reject("affine_unavailable")
            return None

        if inlier_mask is None:
            inlier_count = int(valid_count)
            inlier_ratio = 1.0
        else:
            inlier_count = int(np.count_nonzero(inlier_mask.reshape(-1) > 0))
            inlier_ratio = float(inlier_count / max(1, valid_count))
        if inlier_count < min_points:
            _reject(
                "insufficient_inliers",
                inliers=inlier_count,
                required_inliers=min_points,
            )
            return None

        local_center = np.array(
            [float(ref_detection.center[0] - x1), float(ref_detection.center[1] - y1), 1.0],
            dtype=np.float32,
        )
        projected_local = np.matmul(affine, local_center)
        center_x = float(projected_local[0] + x1)
        center_y = float(projected_local[1] + y1)
        if not np.isfinite(center_x) or not np.isfinite(center_y):
            _reject("invalid_projected_center")
            return None

        shift_px = float(
            math.hypot(
                center_x - float(ref_detection.center[0]),
                center_y - float(ref_detection.center[1]),
            )
        )
        if not np.isfinite(shift_px) or shift_px > max_shift:
            _reject(
                "shift_too_large",
                shift_px=round(shift_px, 6),
                max_shift_px=round(max_shift, 6),
            )
            return None

        angle_rad = math.atan2(float(affine[1, 0]), float(affine[0, 0]))
        angle_deg = abs(math.degrees(angle_rad))
        max_rot = max(0.0, float(self.cfg.frontier_cmc_max_rotation_deg))
        if angle_deg > max_rot:
            _reject(
                "rotation_too_large",
                rotation_deg=round(angle_deg, 6),
                max_rotation_deg=round(max_rot, 6),
            )
            return None

        center = self._clip_center(
            (int(round(center_x)), int(round(center_y))),
            frame.shape[:2],
        )
        bbox = self._recenter_bbox(ref_detection.bbox, center, frame.shape[:2])
        decay = float(np.clip(float(self.cfg.frontier_cmc_confidence_decay), 0.01, 1.0))
        recovered = SpotDetection(
            center=center,
            bbox=bbox,
            confidence=float(np.clip(float(ref_detection.confidence) * decay, 0.05, 0.99)),
            label="cmc_recovery",
            class_id=ref_detection.class_id,
        )
        self._inc_metric("frontier_cmc_success")
        if self.reporter is not None:
            self.reporter.event(
                "frontier_cmc_recovery_hit",
                tag=tag,
                attempt=attempt,
                center=list(recovered.center),
                conf=round(float(recovered.confidence), 6),
                inliers=inlier_count,
                inlier_ratio=round(inlier_ratio, 6),
                rotation_deg=round(angle_deg, 6),
                shift_px=round(shift_px, 6),
            )
        return recovered

    def _recover_with_orb_homography(
        self,
        frame: np.ndarray,
        *,
        tag: str,
        attempt: int,
    ) -> Optional[SpotDetection]:
        if not bool(self.cfg.frontier_orb_recovery_enabled):
            return None
        if self._klt_reference_gray is None or self._klt_reference_detection is None:
            return None
        if not hasattr(cv2, "ORB_create") or not hasattr(cv2, "BFMatcher") or not hasattr(cv2, "findHomography"):
            return None

        def _reject(reason: str, **payload) -> None:
            self._inc_metric("frontier_orb_failures")
            if self.reporter is not None:
                event = {"tag": tag, "attempt": attempt, "reason": reason}
                if payload:
                    event.update(payload)
                self.reporter.event("frontier_orb_recovery_rejected", **event)

        self._inc_metric("frontier_orb_attempts")
        ref_detection = self._klt_reference_detection
        ref_gray = np.ascontiguousarray(self._klt_reference_gray)
        try:
            curr_gray = np.ascontiguousarray(self._to_grayscale(frame))
        except Exception as exc:
            _reject("grayscale_conversion_error", error=str(exc))
            return None

        if ref_gray.shape[:2] != curr_gray.shape[:2]:
            _reject(
                "frame_shape_changed",
                ref_shape=list(ref_gray.shape[:2]),
                curr_shape=list(curr_gray.shape[:2]),
            )
            return None

        h, w = curr_gray.shape[:2]
        bx1, by1, bx2, by2 = ref_detection.bbox
        bbox_w = max(4, int(bx2) - int(bx1))
        bbox_h = max(4, int(by2) - int(by1))
        max_shift = max(0.0, float(self.cfg.frontier_orb_max_shift_px))
        span = int(max(max_shift + 8.0, float(max(bbox_w, bbox_h)) * 2.2))
        cx, cy = ref_detection.center
        x1 = max(0, int(cx) - span)
        y1 = max(0, int(cy) - span)
        x2 = min(w, int(cx) + span)
        y2 = min(h, int(cy) + span)
        if (x2 - x1) < 16 or (y2 - y1) < 16:
            _reject("insufficient_roi")
            return None

        ref_roi = ref_gray[y1:y2, x1:x2]
        curr_roi = curr_gray[y1:y2, x1:x2]
        if ref_roi.size == 0 or curr_roi.size == 0:
            _reject("empty_roi")
            return None

        nfeatures = max(64, int(self.cfg.frontier_orb_nfeatures))
        orb = cv2.ORB_create(nfeatures=nfeatures, fastThreshold=8)
        kp_ref, des_ref = orb.detectAndCompute(ref_roi, None)
        kp_cur, des_cur = orb.detectAndCompute(curr_roi, None)
        if des_ref is None or des_cur is None or not kp_ref or not kp_cur:
            _reject("descriptor_unavailable")
            return None

        matcher = cv2.BFMatcher(cv2.NORM_HAMMING, crossCheck=False)
        try:
            knn = matcher.knnMatch(des_ref, des_cur, k=2)
        except Exception as exc:
            _reject("match_failed", error=str(exc))
            return None

        ratio = float(np.clip(float(self.cfg.frontier_orb_ratio_test), 0.01, 0.99))
        good_matches = []
        for pair in knn:
            if len(pair) < 2:
                continue
            m, n = pair[0], pair[1]
            if m.distance < ratio * n.distance:
                good_matches.append(m)

        min_matches = max(4, int(self.cfg.frontier_orb_min_matches))
        if len(good_matches) < min_matches:
            _reject(
                "insufficient_matches",
                good_matches=int(len(good_matches)),
                required_matches=min_matches,
            )
            return None

        src_pts = np.float32([kp_ref[m.queryIdx].pt for m in good_matches]).reshape(-1, 1, 2)
        dst_pts = np.float32([kp_cur[m.trainIdx].pt for m in good_matches]).reshape(-1, 1, 2)
        roi_offset = np.array([[[float(x1), float(y1)]]], dtype=np.float32)
        src_pts = src_pts + roi_offset
        dst_pts = dst_pts + roi_offset

        ransac_thresh = max(0.5, float(self.cfg.frontier_orb_ransac_reproj_threshold))
        try:
            homography, inlier_mask = cv2.findHomography(src_pts, dst_pts, cv2.RANSAC, ransac_thresh)
        except Exception as exc:
            _reject("homography_failed", error=str(exc))
            return None
        if homography is None or inlier_mask is None:
            _reject("homography_unavailable")
            return None

        inlier_mask = inlier_mask.reshape(-1).astype(bool)
        inlier_count = int(np.count_nonzero(inlier_mask))
        min_inliers = max(4, int(self.cfg.frontier_orb_min_inliers))
        if inlier_count < min_inliers:
            _reject(
                "insufficient_inliers",
                inliers=inlier_count,
                required_inliers=min_inliers,
            )
            return None

        center_pt = np.array([[[float(ref_detection.center[0]), float(ref_detection.center[1])]]], dtype=np.float32)
        projected_center = cv2.perspectiveTransform(center_pt, homography)
        center_x = float(projected_center[0, 0, 0])
        center_y = float(projected_center[0, 0, 1])
        if not np.isfinite(center_x) or not np.isfinite(center_y):
            _reject("invalid_projected_center")
            return None

        shift_px = float(math.hypot(center_x - float(ref_detection.center[0]), center_y - float(ref_detection.center[1])))
        if shift_px > max_shift:
            _reject(
                "shift_too_large",
                shift_px=round(shift_px, 6),
                max_shift_px=round(max_shift, 6),
            )
            return None

        projected_pts = cv2.perspectiveTransform(src_pts, homography).reshape(-1, 2)
        observed_pts = dst_pts.reshape(-1, 2)
        reproj_err = np.linalg.norm(projected_pts - observed_pts, axis=1)
        if inlier_mask.any():
            reproj_err = reproj_err[inlier_mask]
        median_err = float(np.median(reproj_err)) if reproj_err.size else float("inf")
        max_median_err = max(0.0, float(self.cfg.frontier_orb_max_median_error_px))
        if not np.isfinite(median_err) or median_err > max_median_err:
            _reject(
                "reprojection_error_too_large",
                median_error_px=round(median_err, 6),
                max_median_error_px=round(max_median_err, 6),
            )
            return None

        center = self._clip_center(
            (int(round(center_x)), int(round(center_y))),
            frame.shape[:2],
        )
        bbox = self._recenter_bbox(ref_detection.bbox, center, frame.shape[:2])
        decay = float(np.clip(float(self.cfg.frontier_orb_confidence_decay), 0.01, 1.0))
        recovered = SpotDetection(
            center=center,
            bbox=bbox,
            confidence=float(np.clip(float(ref_detection.confidence) * decay, 0.05, 0.99)),
            label="orb_recovery",
            class_id=ref_detection.class_id,
        )
        self._inc_metric("frontier_orb_success")
        if self.reporter is not None:
            self.reporter.event(
                "frontier_orb_recovery_hit",
                tag=tag,
                attempt=attempt,
                center=list(recovered.center),
                conf=round(float(recovered.confidence), 6),
                good_matches=int(len(good_matches)),
                inliers=inlier_count,
                inlier_ratio=round(float(inlier_count / max(1, len(good_matches))), 6),
                median_error_px=round(median_err, 6),
                shift_px=round(shift_px, 6),
            )
        return recovered

    def _recover_with_kalman_template(
        self,
        frame: np.ndarray,
        *,
        tag: str,
        attempt: int,
    ) -> Optional[SpotDetection]:
        if not bool(self.cfg.frontier_kalman_recovery_enabled):
            return None
        if self._kalman is None or not hasattr(self._kalman, "predict"):
            return None
        if self._klt_reference_gray is None or self._klt_reference_detection is None:
            return None
        if not hasattr(cv2, "matchTemplate") or not hasattr(cv2, "minMaxLoc"):
            return None

        def _reject(reason: str, **payload) -> None:
            self._inc_metric("frontier_kalman_failures")
            if self.reporter is not None:
                event = {"tag": tag, "attempt": attempt, "reason": reason}
                if payload:
                    event.update(payload)
                self.reporter.event("frontier_kalman_recovery_rejected", **event)

        self._inc_metric("frontier_kalman_attempts")
        ref_detection = self._klt_reference_detection
        ref_gray = np.ascontiguousarray(self._klt_reference_gray)
        try:
            curr_gray = np.ascontiguousarray(self._to_grayscale(frame))
        except Exception as exc:
            _reject("grayscale_conversion_error", error=str(exc))
            return None

        if ref_gray.shape[:2] != curr_gray.shape[:2]:
            _reject(
                "frame_shape_changed",
                ref_shape=list(ref_gray.shape[:2]),
                curr_shape=list(curr_gray.shape[:2]),
            )
            return None

        try:
            predicted = self._kalman.predict()
        except Exception as exc:
            _reject("kalman_predict_failed", error=str(exc))
            return None
        if predicted is None:
            _reject("kalman_predict_unavailable")
            return None
        pred_center = self._clip_center(
            (int(predicted[0]), int(predicted[1])),
            frame.shape[:2],
        )

        template = self._extract_detection_patch(ref_gray, ref_detection)
        if template is None:
            _reject("template_unavailable")
            return None
        template = np.ascontiguousarray(template)
        th, tw = template.shape[:2]
        if th < 4 or tw < 4:
            _reject("template_too_small", template_shape=[int(th), int(tw)])
            return None

        min_std = max(0.0, float(self.cfg.frontier_kalman_min_template_std))
        template_std = float(np.std(template))
        if (not np.isfinite(template_std)) or template_std < min_std:
            _reject(
                "template_low_texture",
                template_std=round(template_std, 6),
                min_template_std=round(min_std, 6),
            )
            return None

        h, w = curr_gray.shape[:2]
        radius = max(2, int(self.cfg.frontier_kalman_search_radius))
        cx, cy = pred_center
        sx1 = max(0, cx - radius)
        sy1 = max(0, cy - radius)
        sx2 = min(w, cx + radius + 1)
        sy2 = min(h, cy + radius + 1)
        search = np.ascontiguousarray(curr_gray[sy1:sy2, sx1:sx2])
        if search.shape[0] < th or search.shape[1] < tw:
            _reject(
                "search_roi_too_small",
                search_shape=[int(search.shape[0]), int(search.shape[1])],
                template_shape=[int(th), int(tw)],
                search_radius=radius,
            )
            return None

        try:
            response_map = cv2.matchTemplate(search, template, cv2.TM_CCOEFF_NORMED)
        except Exception as exc:
            _reject("template_match_failed", error=str(exc))
            return None
        if response_map is None or response_map.size == 0:
            _reject("empty_response_map")
            return None

        _, max_response, _, max_loc = cv2.minMaxLoc(response_map)
        max_response = float(max_response)
        if not np.isfinite(max_response):
            _reject("invalid_match_response")
            return None

        min_response = float(np.clip(float(self.cfg.frontier_kalman_min_response), 0.0, 1.0))
        if max_response < min_response:
            _reject(
                "match_response_too_low",
                response=round(max_response, 6),
                min_response=round(min_response, 6),
            )
            return None

        hit_x = float(sx1 + int(max_loc[0]) + tw * 0.5)
        hit_y = float(sy1 + int(max_loc[1]) + th * 0.5)
        if not np.isfinite(hit_x) or not np.isfinite(hit_y):
            _reject("invalid_match_center")
            return None

        shift_px = float(
            math.hypot(
                hit_x - float(ref_detection.center[0]),
                hit_y - float(ref_detection.center[1]),
            )
        )
        max_shift = max(0.0, float(self.cfg.frontier_kalman_max_shift_px))
        if not np.isfinite(shift_px) or shift_px > max_shift:
            _reject(
                "shift_too_large",
                shift_px=round(shift_px, 6),
                max_shift_px=round(max_shift, 6),
                predicted_center=list(pred_center),
            )
            return None

        center = self._clip_center(
            (int(round(hit_x)), int(round(hit_y))),
            frame.shape[:2],
        )
        bbox = self._recenter_bbox(ref_detection.bbox, center, frame.shape[:2])
        decay = float(np.clip(float(self.cfg.frontier_kalman_confidence_decay), 0.01, 1.0))
        recovered = SpotDetection(
            center=center,
            bbox=bbox,
            confidence=float(np.clip(float(ref_detection.confidence) * decay, 0.05, 0.99)),
            label="kalman_template_recovery",
            class_id=ref_detection.class_id,
        )
        self._inc_metric("frontier_kalman_success")
        if self.reporter is not None:
            self.reporter.event(
                "frontier_kalman_recovery_hit",
                tag=tag,
                attempt=attempt,
                predicted_center=list(pred_center),
                center=list(recovered.center),
                conf=round(float(recovered.confidence), 6),
                response=round(max_response, 6),
                shift_px=round(shift_px, 6),
                search_radius=radius,
            )
        return recovered

    def _recover_with_pyramid_template(
        self,
        frame: np.ndarray,
        *,
        tag: str,
        attempt: int,
    ) -> Optional[SpotDetection]:
        if not bool(self.cfg.frontier_pyramid_recovery_enabled):
            return None
        if self._klt_reference_gray is None or self._klt_reference_detection is None:
            return None
        if not hasattr(cv2, "matchTemplate") or not hasattr(cv2, "minMaxLoc") or not hasattr(cv2, "resize"):
            return None

        def _reject(reason: str, **payload) -> None:
            self._inc_metric("frontier_pyramid_failures")
            if self.reporter is not None:
                event = {"tag": tag, "attempt": attempt, "reason": reason}
                if payload:
                    event.update(payload)
                self.reporter.event("frontier_pyramid_recovery_rejected", **event)

        self._inc_metric("frontier_pyramid_attempts")
        ref_detection = self._klt_reference_detection
        ref_gray = np.ascontiguousarray(self._klt_reference_gray)
        try:
            curr_gray = np.ascontiguousarray(self._to_grayscale(frame))
        except Exception as exc:
            _reject("grayscale_conversion_error", error=str(exc))
            return None

        if ref_gray.shape[:2] != curr_gray.shape[:2]:
            _reject(
                "frame_shape_changed",
                ref_shape=list(ref_gray.shape[:2]),
                curr_shape=list(curr_gray.shape[:2]),
            )
            return None

        template = self._extract_detection_patch(ref_gray, ref_detection)
        if template is None:
            _reject("template_unavailable")
            return None
        template = np.ascontiguousarray(template)
        base_h, base_w = template.shape[:2]
        if base_h < 4 or base_w < 4:
            _reject("template_too_small", template_shape=[int(base_h), int(base_w)])
            return None

        min_std = max(0.0, float(self.cfg.frontier_pyramid_min_template_std))
        base_std = float(np.std(template))
        if (not np.isfinite(base_std)) or base_std < min_std:
            _reject(
                "template_low_texture",
                template_std=round(base_std, 6),
                min_template_std=round(min_std, 6),
            )
            return None

        h, w = curr_gray.shape[:2]
        radius = max(2, int(self.cfg.frontier_pyramid_search_radius))
        ref_cx = int(ref_detection.center[0])
        ref_cy = int(ref_detection.center[1])
        sx1 = max(0, ref_cx - radius)
        sy1 = max(0, ref_cy - radius)
        sx2 = min(w, ref_cx + radius + 1)
        sy2 = min(h, ref_cy + radius + 1)
        search = np.ascontiguousarray(curr_gray[sy1:sy2, sx1:sx2])
        if search.size == 0:
            _reject("empty_search_roi", search_radius=radius)
            return None

        levels = max(0, int(self.cfg.frontier_pyramid_levels))
        scale_step = max(1e-3, float(self.cfg.frontier_pyramid_scale_step))
        scales: List[float] = [1.0]
        for level in range(1, levels + 1):
            plus = 1.0 + scale_step * float(level)
            minus = 1.0 - scale_step * float(level)
            if plus > 0.2:
                scales.append(plus)
            if minus > 0.2:
                scales.append(minus)
        deduped_scales: List[float] = []
        seen = set()
        for scale in scales:
            key = round(float(scale), 6)
            if key in seen:
                continue
            seen.add(key)
            deduped_scales.append(float(scale))

        best_candidate = None
        valid_scales = 0
        max_shift = max(0.0, float(self.cfg.frontier_pyramid_max_shift_px))
        for scale in deduped_scales:
            tw = max(4, int(round(float(base_w) * scale)))
            th = max(4, int(round(float(base_h) * scale)))
            if search.shape[1] < tw or search.shape[0] < th:
                continue
            interp = cv2.INTER_LINEAR if scale >= 1.0 else cv2.INTER_AREA
            try:
                scaled_template = cv2.resize(template, (tw, th), interpolation=interp)
            except Exception:
                continue
            if scaled_template is None or scaled_template.size == 0:
                continue
            scaled_template = np.ascontiguousarray(scaled_template)
            template_std = float(np.std(scaled_template))
            if (not np.isfinite(template_std)) or template_std < min_std:
                continue
            valid_scales += 1
            try:
                response_map = cv2.matchTemplate(search, scaled_template, cv2.TM_CCOEFF_NORMED)
            except Exception:
                continue
            if response_map is None or response_map.size == 0:
                continue
            _, max_response, _, max_loc = cv2.minMaxLoc(response_map)
            max_response = float(max_response)
            if not np.isfinite(max_response):
                continue
            center_x = float(sx1 + int(max_loc[0]) + tw * 0.5)
            center_y = float(sy1 + int(max_loc[1]) + th * 0.5)
            if not np.isfinite(center_x) or not np.isfinite(center_y):
                continue
            shift_px = float(
                math.hypot(
                    center_x - float(ref_detection.center[0]),
                    center_y - float(ref_detection.center[1]),
                )
            )
            if not np.isfinite(shift_px) or shift_px > max_shift:
                continue
            if best_candidate is None or max_response > float(best_candidate["response"]):
                best_candidate = {
                    "response": max_response,
                    "center_x": center_x,
                    "center_y": center_y,
                    "scale": float(scale),
                    "shift_px": shift_px,
                }

        if best_candidate is None:
            _reject(
                "no_valid_candidate",
                evaluated_scales=len(deduped_scales),
                valid_scales=int(valid_scales),
                search_radius=radius,
            )
            return None

        min_response = float(np.clip(float(self.cfg.frontier_pyramid_min_response), 0.0, 1.0))
        best_response = float(best_candidate["response"])
        if best_response < min_response:
            _reject(
                "match_response_too_low",
                response=round(best_response, 6),
                min_response=round(min_response, 6),
                best_scale=round(float(best_candidate["scale"]), 6),
            )
            return None

        center = self._clip_center(
            (
                int(round(float(best_candidate["center_x"]))),
                int(round(float(best_candidate["center_y"]))),
            ),
            frame.shape[:2],
        )
        bbox = self._recenter_bbox(ref_detection.bbox, center, frame.shape[:2])
        decay = float(np.clip(float(self.cfg.frontier_pyramid_confidence_decay), 0.01, 1.0))
        recovered = SpotDetection(
            center=center,
            bbox=bbox,
            confidence=float(np.clip(float(ref_detection.confidence) * decay, 0.05, 0.99)),
            label="pyramid_template_recovery",
            class_id=ref_detection.class_id,
        )
        self._inc_metric("frontier_pyramid_success")
        if self.reporter is not None:
            self.reporter.event(
                "frontier_pyramid_recovery_hit",
                tag=tag,
                attempt=attempt,
                center=list(recovered.center),
                conf=round(float(recovered.confidence), 6),
                response=round(best_response, 6),
                shift_px=round(float(best_candidate["shift_px"]), 6),
                best_scale=round(float(best_candidate["scale"]), 6),
                evaluated_scales=len(deduped_scales),
                valid_scales=int(valid_scales),
                search_radius=radius,
            )
        return recovered

    def _recover_with_logpolar_phase(
        self,
        frame: np.ndarray,
        *,
        tag: str,
        attempt: int,
    ) -> Optional[SpotDetection]:
        if not bool(self.cfg.frontier_logpolar_recovery_enabled):
            return None
        if self._klt_reference_gray is None or self._klt_reference_detection is None:
            return None
        if (
            not hasattr(cv2, "phaseCorrelate")
            or not hasattr(cv2, "warpPolar")
            or not hasattr(cv2, "matchTemplate")
            or not hasattr(cv2, "minMaxLoc")
            or not hasattr(cv2, "getRotationMatrix2D")
            or not hasattr(cv2, "warpAffine")
        ):
            return None

        def _reject(reason: str, **payload) -> None:
            self._inc_metric("frontier_logpolar_failures")
            if self.reporter is not None:
                event = {"tag": tag, "attempt": attempt, "reason": reason}
                if payload:
                    event.update(payload)
                self.reporter.event("frontier_logpolar_recovery_rejected", **event)

        self._inc_metric("frontier_logpolar_attempts")
        ref_detection = self._klt_reference_detection
        ref_gray = np.ascontiguousarray(self._klt_reference_gray)
        try:
            curr_gray = np.ascontiguousarray(self._to_grayscale(frame))
        except Exception as exc:
            _reject("grayscale_conversion_error", error=str(exc))
            return None

        if ref_gray.shape[:2] != curr_gray.shape[:2]:
            _reject(
                "frame_shape_changed",
                ref_shape=list(ref_gray.shape[:2]),
                curr_shape=list(curr_gray.shape[:2]),
            )
            return None

        template = self._extract_detection_patch(ref_gray, ref_detection)
        if template is None:
            _reject("template_unavailable")
            return None
        template = np.ascontiguousarray(template)
        th, tw = template.shape[:2]
        if th < 8 or tw < 8:
            _reject("template_too_small", template_shape=[int(th), int(tw)])
            return None

        min_std = max(0.0, float(self.cfg.frontier_logpolar_min_template_std))
        template_std = float(np.std(template))
        if (not np.isfinite(template_std)) or template_std < min_std:
            _reject(
                "template_low_texture",
                template_std=round(template_std, 6),
                min_template_std=round(min_std, 6),
            )
            return None

        h, w = curr_gray.shape[:2]
        radius = max(8, int(self.cfg.frontier_logpolar_search_radius))
        ref_cx = int(ref_detection.center[0])
        ref_cy = int(ref_detection.center[1])
        sx1 = max(0, ref_cx - radius)
        sy1 = max(0, ref_cy - radius)
        sx2 = min(w, ref_cx + radius + 1)
        sy2 = min(h, ref_cy + radius + 1)
        search = np.ascontiguousarray(curr_gray[sy1:sy2, sx1:sx2])
        if search.shape[0] < th or search.shape[1] < tw:
            _reject(
                "search_roi_too_small",
                search_shape=[int(search.shape[0]), int(search.shape[1])],
                template_shape=[int(th), int(tw)],
                search_radius=radius,
            )
            return None

        try:
            base_response_map = cv2.matchTemplate(search, template, cv2.TM_CCOEFF_NORMED)
        except Exception as exc:
            _reject("template_match_failed", error=str(exc))
            return None
        if base_response_map is None or base_response_map.size == 0:
            _reject("empty_response_map")
            return None

        _, base_response, _, base_loc = cv2.minMaxLoc(base_response_map)
        base_response = float(base_response)
        if not np.isfinite(base_response):
            _reject("invalid_base_response")
            return None

        base_center_x = float(sx1 + int(base_loc[0]) + tw * 0.5)
        base_center_y = float(sy1 + int(base_loc[1]) + th * 0.5)
        if not np.isfinite(base_center_x) or not np.isfinite(base_center_y):
            _reject("invalid_base_center")
            return None

        px1 = int(round(base_center_x - tw * 0.5))
        py1 = int(round(base_center_y - th * 0.5))
        px1 = max(0, min(px1, w - tw))
        py1 = max(0, min(py1, h - th))
        px2 = px1 + tw
        py2 = py1 + th
        curr_patch = curr_gray[py1:py2, px1:px2]
        if curr_patch.shape[0] != th or curr_patch.shape[1] != tw:
            _reject("curr_patch_shape_mismatch")
            return None

        ref_patch_f = template.astype(np.float32, copy=False)
        curr_patch_f = np.ascontiguousarray(curr_patch.astype(np.float32, copy=False))
        ref_patch_f = ref_patch_f - float(np.mean(ref_patch_f))
        curr_patch_f = curr_patch_f - float(np.mean(curr_patch_f))

        ref_mag = np.log1p(np.abs(np.fft.fftshift(np.fft.fft2(ref_patch_f))).astype(np.float32))
        curr_mag = np.log1p(np.abs(np.fft.fftshift(np.fft.fft2(curr_patch_f))).astype(np.float32))

        angular_bins = max(64, int(self.cfg.frontier_logpolar_num_angular_bins))
        radial_bins = max(32, int(self.cfg.frontier_logpolar_num_radial_bins))
        max_radius = float(max(3.0, min(ref_mag.shape[0], ref_mag.shape[1]) * 0.5))
        lp_center = (float(ref_mag.shape[1]) * 0.5, float(ref_mag.shape[0]) * 0.5)
        flags = int(getattr(cv2, "INTER_LINEAR", 1)) | int(getattr(cv2, "WARP_POLAR_LOG", 256))
        try:
            ref_lp = cv2.warpPolar(ref_mag, (radial_bins, angular_bins), lp_center, max_radius, flags)
            curr_lp = cv2.warpPolar(curr_mag, (radial_bins, angular_bins), lp_center, max_radius, flags)
        except Exception as exc:
            _reject("warp_polar_failed", error=str(exc))
            return None
        if ref_lp is None or curr_lp is None or ref_lp.size == 0 or curr_lp.size == 0:
            _reject("empty_logpolar")
            return None

        ref_lp = np.ascontiguousarray(ref_lp.astype(np.float32, copy=False))
        curr_lp = np.ascontiguousarray(curr_lp.astype(np.float32, copy=False))
        try:
            (shift_x, shift_y), lp_response = cv2.phaseCorrelate(ref_lp, curr_lp)
        except Exception as exc:
            _reject("phase_correlation_failed", error=str(exc))
            return None
        lp_response = float(lp_response)
        if not np.isfinite(lp_response):
            _reject("invalid_logpolar_response")
            return None

        min_response = float(np.clip(float(self.cfg.frontier_logpolar_min_response), 0.0, 1.0))
        if lp_response < min_response:
            _reject(
                "response_too_low",
                response=round(lp_response, 6),
                min_response=round(min_response, 6),
            )
            return None

        klog = float(radial_bins) / max(1e-6, math.log(max(max_radius, 1.000001)))
        raw_scale = math.exp(float(shift_x) / max(1e-6, klog))
        if not np.isfinite(raw_scale) or raw_scale <= 0:
            _reject("invalid_scale_estimate", raw_scale=float(raw_scale))
            return None
        base_rotation_deg = float(shift_y) * 360.0 / float(max(1, angular_bins))

        max_scale_ratio = max(1.0, float(self.cfg.frontier_logpolar_max_scale_ratio))
        max_rotation_deg = max(0.0, float(self.cfg.frontier_logpolar_max_rotation_deg))
        max_shift_px = max(0.0, float(self.cfg.frontier_logpolar_max_shift_px))
        decay = float(np.clip(float(self.cfg.frontier_logpolar_confidence_decay), 0.01, 1.0))

        def _wrap_angle_deg(angle: float) -> float:
            return ((float(angle) + 180.0) % 360.0) - 180.0

        candidate_params: List[Tuple[float, float]] = []
        angle_variants = {
            _wrap_angle_deg(base_rotation_deg),
            _wrap_angle_deg(-base_rotation_deg),
            _wrap_angle_deg(base_rotation_deg + 180.0),
            _wrap_angle_deg(base_rotation_deg - 180.0),
            _wrap_angle_deg(((base_rotation_deg + 90.0) % 180.0) - 90.0),
        }
        scale_variants = {
            float(raw_scale),
            float(1.0 / raw_scale),
            1.0,
        }
        for angle in angle_variants:
            for scale in scale_variants:
                ratio = max(scale, 1.0 / max(scale, 1e-6))
                if ratio > max_scale_ratio:
                    continue
                if abs(angle) > max_rotation_deg:
                    continue
                candidate_params.append((float(angle), float(scale)))

        if max_rotation_deg > 0:
            coarse_span = min(max_rotation_deg, 24.0)
            coarse_angles = np.linspace(-coarse_span, coarse_span, num=7).tolist()
        else:
            coarse_angles = [0.0]
        coarse_scales = [1.0]
        if max_scale_ratio > 1.0:
            coarse_scales.extend(
                [
                    float(np.clip(0.92, 1.0 / max_scale_ratio, max_scale_ratio)),
                    float(np.clip(1.08, 1.0 / max_scale_ratio, max_scale_ratio)),
                ]
            )
        for angle in coarse_angles:
            for scale in coarse_scales:
                ratio = max(scale, 1.0 / max(scale, 1e-6))
                if ratio > max_scale_ratio or abs(float(angle)) > max_rotation_deg:
                    continue
                candidate_params.append((float(angle), float(scale)))

        deduped_candidates: List[Tuple[float, float]] = []
        seen_candidates = set()
        for angle, scale in candidate_params:
            key = (round(float(angle), 4), round(float(scale), 4))
            if key in seen_candidates:
                continue
            seen_candidates.add(key)
            deduped_candidates.append((float(angle), float(scale)))
        candidate_params = deduped_candidates
        if not candidate_params:
            _reject(
                "estimate_out_of_bounds",
                raw_scale=round(float(raw_scale), 6),
                raw_rotation_deg=round(float(base_rotation_deg), 6),
                max_scale_ratio=round(float(max_scale_ratio), 6),
                max_rotation_deg=round(float(max_rotation_deg), 6),
            )
            return None

        best = None
        for angle_deg, scale in candidate_params:
            matrix = cv2.getRotationMatrix2D((tw * 0.5, th * 0.5), angle_deg, scale)
            transformed = cv2.warpAffine(
                template,
                matrix,
                (tw, th),
                flags=cv2.INTER_LINEAR,
                borderMode=cv2.BORDER_REPLICATE,
            )
            transformed = np.ascontiguousarray(transformed)
            std_val = float(np.std(transformed))
            if (not np.isfinite(std_val)) or std_val < min_std:
                continue
            try:
                response_map = cv2.matchTemplate(search, transformed, cv2.TM_CCOEFF_NORMED)
            except Exception:
                continue
            if response_map is None or response_map.size == 0:
                continue
            _, response, _, loc = cv2.minMaxLoc(response_map)
            response = float(response)
            if not np.isfinite(response):
                continue
            center_x = float(sx1 + int(loc[0]) + tw * 0.5)
            center_y = float(sy1 + int(loc[1]) + th * 0.5)
            if not np.isfinite(center_x) or not np.isfinite(center_y):
                continue
            shift_px = float(
                math.hypot(
                    center_x - float(ref_detection.center[0]),
                    center_y - float(ref_detection.center[1]),
                )
            )
            if (not np.isfinite(shift_px)) or shift_px > max_shift_px:
                continue
            if best is None or response > float(best["response"]):
                best = {
                    "response": response,
                    "center_x": center_x,
                    "center_y": center_y,
                    "shift_px": shift_px,
                    "rotation_deg": float(angle_deg),
                    "scale": float(scale),
                }

        if best is None:
            _reject(
                "no_valid_candidate",
                candidates=len(candidate_params),
                max_shift_px=round(max_shift_px, 6),
                base_response=round(base_response, 6),
            )
            return None

        if float(best["response"]) < min_response:
            _reject(
                "match_response_too_low",
                response=round(float(best["response"]), 6),
                min_response=round(min_response, 6),
            )
            return None

        center = self._clip_center(
            (int(round(float(best["center_x"]))), int(round(float(best["center_y"])))),
            frame.shape[:2],
        )
        bbox = self._recenter_bbox(ref_detection.bbox, center, frame.shape[:2])
        recovered = SpotDetection(
            center=center,
            bbox=bbox,
            confidence=float(np.clip(float(ref_detection.confidence) * decay, 0.05, 0.99)),
            label="logpolar_recovery",
            class_id=ref_detection.class_id,
        )
        self._inc_metric("frontier_logpolar_success")
        if self.reporter is not None:
            self.reporter.event(
                "frontier_logpolar_recovery_hit",
                tag=tag,
                attempt=attempt,
                center=list(recovered.center),
                conf=round(float(recovered.confidence), 6),
                response=round(float(best["response"]), 6),
                logpolar_response=round(lp_response, 6),
                shift_px=round(float(best["shift_px"]), 6),
                rotation_deg=round(float(best["rotation_deg"]), 6),
                scale=round(float(best["scale"]), 6),
                search_radius=radius,
                base_response=round(base_response, 6),
            )
        return recovered

    def _apply_frontier_v25_stack(
        self,
        frame: np.ndarray,
        detection: SpotDetection,
        *,
        tag: str,
        attempt: int,
    ) -> Optional[SpotDetection]:
        if (
            self._frontier_uncertainty_localizer is None
            and self._frontier_drift_corrector is None
            and self._frontier_psf_estimator is None
            and self._frontier_bayesian_gate is None
            and self._frontier_artifact_assessor is None
        ):
            return detection

        gray = self._to_grayscale(frame)
        updated = detection
        h, w = gray.shape[:2]

        if self._frontier_uncertainty_localizer is not None:
            try:
                local = self._frontier_uncertainty_localizer.localize(gray, updated.center)
                if self.reporter is not None:
                    self.reporter.event(
                        "frontier_v25_uncertainty_localizer",
                        tag=tag,
                        attempt=attempt,
                        confidence=round(float(local.confidence), 6),
                        uncertainty_px=round(float(local.uncertainty_px), 6),
                        snr=round(float(local.snr), 6),
                        stable=bool(local.is_stable),
                        center=None if local.center is None else [round(float(local.center[0]), 3), round(float(local.center[1]), 3)],
                    )
                uncertainty_limit = max(1.0, float(self.cfg.track_max_jump_px) * 0.5)
                if (
                    local.center is not None
                    and float(local.confidence) >= 0.25
                    and float(local.uncertainty_px) <= uncertainty_limit
                ):
                    rc = self._clip_center(
                        (int(round(local.center[0])), int(round(local.center[1]))),
                        (h, w),
                    )
                    rb = self._recenter_bbox(updated.bbox, rc, (h, w))
                    if rc != updated.center:
                        self._inc_metric("frontier_v25_uncertainty_refines")
                    updated = SpotDetection(
                        center=rc,
                        bbox=rb,
                        confidence=max(float(updated.confidence), float(local.confidence)),
                        label=updated.label,
                        class_id=updated.class_id,
                    )
            except Exception as exc:
                LOGGER.warning("Frontier v25 uncertainty localizer failed; bypassing: %s", exc)
                if self.reporter is not None:
                    self.reporter.event("frontier_v25_uncertainty_localizer_failed", tag=tag, attempt=attempt, error=str(exc))

        if self._frontier_drift_corrector is not None:
            try:
                drift = self._frontier_drift_corrector.update(gray)
                drift_mag = math.hypot(float(drift.dx), float(drift.dy))
                if drift_mag >= 0.25:
                    corrected_center = self._clip_center(
                        (
                            int(round(updated.center[0] - float(drift.dx))),
                            int(round(updated.center[1] - float(drift.dy))),
                        ),
                        (h, w),
                    )
                    corrected_bbox = self._recenter_bbox(updated.bbox, corrected_center, (h, w))
                    if corrected_center != updated.center:
                        self._inc_metric("frontier_v25_drift_adjustments")
                    updated = SpotDetection(
                        center=corrected_center,
                        bbox=corrected_bbox,
                        confidence=updated.confidence,
                        label=updated.label,
                        class_id=updated.class_id,
                    )
                if self.reporter is not None:
                    self.reporter.event(
                        "frontier_v25_drift",
                        tag=tag,
                        attempt=attempt,
                        dx=round(float(drift.dx), 6),
                        dy=round(float(drift.dy), 6),
                        corr=round(float(drift.correlation), 6),
                        ref_updated=bool(drift.reference_updated),
                    )
            except Exception as exc:
                LOGGER.warning("Frontier v25 drift corrector failed; bypassing: %s", exc)
                if self.reporter is not None:
                    self.reporter.event("frontier_v25_drift_failed", tag=tag, attempt=attempt, error=str(exc))

        patch = self._extract_detection_patch(gray, updated)
        artifact_quality = 1.0

        if patch is not None and self._frontier_psf_estimator is not None:
            try:
                self._frontier_psf_estimator.add_spot(patch)
                psf = self._frontier_psf_estimator.estimate()
                if psf is not None:
                    self._inc_metric("frontier_v25_psf_updates")
                    if self.reporter is not None:
                        self.reporter.event(
                            "frontier_v25_psf_estimate",
                            tag=tag,
                            attempt=attempt,
                            sigma_avg=round(float(psf.sigma_avg), 6),
                            ellipticity=round(float(psf.ellipticity), 6),
                            p2b=round(float(psf.peak_to_background), 6),
                            spots=int(psf.num_spots_used),
                            converged=bool(psf.converged),
                        )
            except Exception as exc:
                LOGGER.warning("Frontier v25 PSF estimator failed; bypassing: %s", exc)
                if self.reporter is not None:
                    self.reporter.event("frontier_v25_psf_failed", tag=tag, attempt=attempt, error=str(exc))

        if patch is not None and self._frontier_artifact_assessor is not None:
            try:
                assessment = self._frontier_artifact_assessor.assess(patch)
                artifact_quality = float(assessment.overall_quality)
                if self.reporter is not None:
                    self.reporter.event(
                        "frontier_v25_artifact_assessment",
                        tag=tag,
                        attempt=attempt,
                        quality=round(float(assessment.overall_quality), 6),
                        artifact_score=round(float(assessment.artifact_score), 6),
                        flags=list(assessment.flags),
                    )
                if float(assessment.artifact_score) >= 0.75:
                    self._inc_metric("frontier_v25_artifact_rejects")
                    return None
            except Exception as exc:
                LOGGER.warning("Frontier v25 artifact assessor failed; bypassing: %s", exc)
                if self.reporter is not None:
                    self.reporter.event("frontier_v25_artifact_failed", tag=tag, attempt=attempt, error=str(exc))

        if self._frontier_bayesian_gate is not None:
            try:
                quality_obs = 0.6 * max(0.0, min(1.0, float(updated.confidence))) + 0.4 * max(
                    0.0,
                    min(1.0, artifact_quality),
                )
                gate = self._frontier_bayesian_gate.update(quality_obs)
                if self.reporter is not None:
                    self.reporter.event(
                        "frontier_v25_bayesian_gate",
                        tag=tag,
                        attempt=attempt,
                        decision=str(gate.decision),
                        posterior=round(float(gate.posterior_quality), 6),
                        uncertainty=round(float(gate.uncertainty), 6),
                        expected_loss=round(float(gate.expected_loss), 6),
                    )
                gate_decision = str(gate.decision).lower()
                reject_threshold = float(getattr(getattr(self._frontier_bayesian_gate, "config", None), "quality_reject_threshold", 0.3))
                hard_reject = gate_decision == "reject" and float(gate.posterior_quality) <= (reject_threshold + 0.05)
                if hard_reject:
                    self._inc_metric("frontier_v25_bayes_rejects")
                    return None
            except Exception as exc:
                LOGGER.warning("Frontier v25 Bayesian gate failed; bypassing: %s", exc)
                if self.reporter is not None:
                    self.reporter.event("frontier_v25_bayesian_failed", tag=tag, attempt=attempt, error=str(exc))

        return updated

    def _apply_frontier_v26_aberration_gate(
        self,
        frame: np.ndarray,
        detection: SpotDetection,
        *,
        tag: str,
        attempt: int,
        source: str,
    ) -> Optional[SpotDetection]:
        if self._frontier_v26_aberration is None:
            return detection

        min_patch = max(8, int(self.cfg.frontier_v26_aberration_min_patch))
        patch = self._extract_detection_patch(self._to_grayscale(frame), detection)
        if patch is None or min(patch.shape[:2]) < min_patch:
            return detection

        self._inc_metric("frontier_v26_aberration_checks")
        try:
            result = self._frontier_v26_aberration.process(patch)
            strehl = float(getattr(result, "estimated_psf_quality", 0.0))
            rms = float(getattr(result, "rms_wavefront_error", 0.0))
            dominant_mode = int(getattr(result, "dominant_mode", 0) or 0)

            min_strehl = float(self.cfg.frontier_v26_aberration_strehl_min)
            max_rms = float(self.cfg.frontier_v26_aberration_rms_max)
            accepted = strehl >= min_strehl and rms <= max_rms

            if self.reporter is not None:
                self.reporter.event(
                    "frontier_v26_aberration_probe",
                    tag=tag,
                    attempt=attempt,
                    source=source,
                    accepted=bool(accepted),
                    strehl=round(strehl, 6),
                    rms_wavefront_error=round(rms, 6),
                    dominant_mode=dominant_mode,
                    min_strehl=round(min_strehl, 6),
                    max_rms=round(max_rms, 6),
                )

            if not accepted:
                self._inc_metric("frontier_v26_aberration_rejects")
                return None
            return detection
        except Exception as exc:
            self._inc_metric("frontier_v26_aberration_failures")
            LOGGER.warning("Frontier v26 aberration gate failed; bypassing: %s", exc)
            if self.reporter is not None:
                self.reporter.event(
                    "frontier_v26_aberration_failed",
                    tag=tag,
                    attempt=attempt,
                    source=source,
                    error=str(exc),
                )
            return detection

    def _apply_frontier_optics_quality_gate(
        self,
        frame: np.ndarray,
        detection: SpotDetection,
        *,
        tag: str,
        attempt: int,
        source: str,
    ) -> Optional[SpotDetection]:
        if self._frontier_otf_gate is None and self._frontier_phase_gate is None:
            return detection

        gray = self._to_grayscale(frame)
        patch = self._extract_detection_patch(gray, detection)
        if patch is None:
            return detection

        if self._frontier_otf_gate is not None:
            min_patch = max(8, int(self.cfg.frontier_otf_min_patch))
            if min(patch.shape[:2]) >= min_patch:
                self._inc_metric("frontier_otf_checks")
                try:
                    otf_result = self._frontier_otf_gate.analyze(patch)
                    strehl = float(getattr(otf_result, "strehl_ratio", 0.0))
                    mtf50 = float(getattr(otf_result, "mtf50_frequency", 0.0))
                    min_strehl = float(self.cfg.frontier_otf_strehl_min)
                    min_mtf50 = float(self.cfg.frontier_otf_mtf50_min)
                    accepted = strehl >= min_strehl and mtf50 >= min_mtf50
                    if self.reporter is not None:
                        self.reporter.event(
                            "frontier_otf_probe",
                            tag=tag,
                            attempt=attempt,
                            source=source,
                            accepted=bool(accepted),
                            strehl=round(strehl, 6),
                            mtf50=round(mtf50, 6),
                            min_strehl=round(min_strehl, 6),
                            min_mtf50=round(min_mtf50, 6),
                        )
                    if not accepted:
                        self._inc_metric("frontier_otf_rejects")
                        return None
                except Exception as exc:
                    self._inc_metric("frontier_otf_failures")
                    LOGGER.warning("Frontier OTF gate failed; bypassing: %s", exc)
                    if self.reporter is not None:
                        self.reporter.event(
                            "frontier_otf_failed",
                            tag=tag,
                            attempt=attempt,
                            source=source,
                            error=str(exc),
                        )

        if self._frontier_phase_gate is not None:
            min_patch = max(8, int(self.cfg.frontier_phase_min_patch))
            if min(patch.shape[:2]) >= min_patch:
                self._inc_metric("frontier_phase_checks")
                try:
                    phase_result = self._frontier_phase_gate.analyze(patch)
                    strehl = float(getattr(phase_result, "strehl_estimate", 0.0))
                    rms = float(getattr(phase_result, "wavefront_rms", 0.0))
                    iterations = int(getattr(phase_result, "iteration_count", 0) or 0)
                    is_converged = bool(getattr(phase_result, "is_converged", False))
                    min_strehl = float(self.cfg.frontier_phase_strehl_min)
                    max_rms = float(self.cfg.frontier_phase_rms_max)
                    accepted = strehl >= min_strehl and rms <= max_rms
                    if self.reporter is not None:
                        self.reporter.event(
                            "frontier_phase_probe",
                            tag=tag,
                            attempt=attempt,
                            source=source,
                            accepted=bool(accepted),
                            strehl=round(strehl, 6),
                            wavefront_rms=round(rms, 6),
                            min_strehl=round(min_strehl, 6),
                            max_rms=round(max_rms, 6),
                            iter=iterations,
                            converged=is_converged,
                        )
                    if not accepted:
                        self._inc_metric("frontier_phase_rejects")
                        return None
                except Exception as exc:
                    self._inc_metric("frontier_phase_gate_failures")
                    LOGGER.warning("Frontier phase gate failed; bypassing: %s", exc)
                    if self.reporter is not None:
                        self.reporter.event(
                            "frontier_phase_failed",
                            tag=tag,
                            attempt=attempt,
                            source=source,
                            error=str(exc),
                        )

        return detection

    def _passes_uncertainty_gate(
        self,
        frame: np.ndarray,
        detection: SpotDetection,
        *,
        tag: str,
        attempt: int,
    ) -> bool:
        if self._frontier_uncertainty is None:
            return True

        noise_std = max(0.0, float(self.cfg.frontier_uncertainty_noise_std))
        base = frame.astype(np.float64)

        def _model_forward(_: np.ndarray) -> np.ndarray:
            if noise_std > 0:
                probe = np.clip(base + np.random.normal(0.0, noise_std, base.shape), 0.0, 255.0).astype(np.uint8)
            else:
                probe = np.clip(base, 0, 255).astype(np.uint8)
            probe_det = self.detector.detect(probe)
            if probe_det is None:
                return np.array([float(detection.center[0]), float(detection.center[1]), 0.0], dtype=np.float64)
            return np.array(
                [
                    float(probe_det.center[0]),
                    float(probe_det.center[1]),
                    float(probe_det.confidence),
                ],
                dtype=np.float64,
            )

        try:
            estimate = self._frontier_uncertainty.quantify(_model_forward, base)
            total = np.array(estimate.total_uncertainty, dtype=np.float64).reshape(-1)
            pos_var = float(np.mean(total[:2])) if total.size >= 2 else float(np.mean(total))
            threshold = float(self.cfg.frontier_uncertainty_max_var_px2)
            accepted = pos_var <= threshold
            if self.reporter is not None:
                self.reporter.event(
                    "frontier_uncertainty",
                    tag=tag,
                    attempt=attempt,
                    pos_var_px2=round(pos_var, 6),
                    threshold_px2=round(threshold, 6),
                    accepted=bool(accepted),
                )
            if not accepted:
                self._inc_metric("uncertainty_rejects")
            return accepted
        except Exception as exc:
            LOGGER.warning("Frontier uncertainty quantification failed; bypass gate: %s", exc)
            if self.reporter is not None:
                self.reporter.event(
                    "frontier_uncertainty_failed",
                    tag=tag,
                    attempt=attempt,
                    error=str(exc),
                )
            return True

    def _memory_recover_detection(
        self,
        frame: np.ndarray,
        *,
        tag: str,
        attempt: int,
    ) -> Optional[SpotDetection]:
        if self._frontier_memory is None:
            return None
        try:
            result = self._frontier_memory.recover(frame)
            if not bool(getattr(result, "accepted", False)):
                return None
            center = getattr(result, "center", None)
            if center is None:
                return None
            h, w = frame.shape[:2]
            cx = int(center[0])
            cy = int(center[1])
            half = max(6, min(h, w) // 24)
            x1 = max(0, cx - half)
            y1 = max(0, cy - half)
            x2 = min(w, cx + half)
            y2 = min(h, cy + half)
            if x2 <= x1:
                x2 = min(w, x1 + 1)
            if y2 <= y1:
                y2 = min(h, y1 + 1)
            recovered = SpotDetection(
                center=(cx, cy),
                bbox=(x1, y1, x2, y2),
                confidence=max(0.01, min(0.6, float(getattr(result, "score", 0.0)))),
                label="memory_recovery",
                class_id=-1,
            )
            self._inc_metric("frontier_memory_recoveries")
            if self.reporter is not None:
                self.reporter.event(
                    "frontier_memory_recovered",
                    tag=tag,
                    attempt=attempt,
                    center=list(recovered.center),
                    score=round(float(getattr(result, "score", 0.0)), 6),
                )
            return recovered
        except Exception as exc:
            LOGGER.warning("Frontier memory recovery failed: %s", exc)
            if self.reporter is not None:
                self.reporter.event("frontier_memory_failed", tag=tag, attempt=attempt, error=str(exc))
            return None

    def _apply_domain_probe(
        self,
        frame: np.ndarray,
        detection: SpotDetection,
        *,
        tag: str,
        attempt: int,
    ) -> Optional[SpotDetection]:
        if self._frontier_domain_probe is None:
            return detection

        def _probe_detect_fn(probe_frame: np.ndarray) -> Optional[Tuple[Tuple[int, int], float]]:
            probe_detection = self.detector.detect(probe_frame)
            if probe_detection is None:
                return None
            return (
                (int(probe_detection.center[0]), int(probe_detection.center[1])),
                float(probe_detection.confidence),
            )

        try:
            result = self._frontier_domain_probe.evaluate(
                frame,
                detection.center,
                float(detection.confidence),
                _probe_detect_fn,
            )
            if self.reporter is not None:
                self.reporter.event(
                    "frontier_domain_probe",
                    tag=tag,
                    attempt=attempt,
                    unstable=bool(result.unstable),
                    reason=str(result.reason),
                    center_std_px=round(float(result.center_std_px), 6),
                    mean_confidence=round(float(result.mean_confidence), 6),
                    valid_ratio=round(float(result.valid_ratio), 6),
                )
            if bool(result.unstable):
                self._inc_metric("frontier_domain_shift_alerts")
                if bool(self.cfg.frontier_domain_probe_hard_gate):
                    LOGGER.warning(
                        "Frontier domain probe rejected detection: shift=%.3f reason=%s",
                        float(result.center_std_px),
                        str(result.reason),
                    )
                    return None
            return detection
        except Exception as exc:
            LOGGER.warning("Frontier domain probe failed; bypassing: %s", exc)
            if self.reporter is not None:
                self.reporter.event(
                    "frontier_domain_probe_failed",
                    tag=tag,
                    attempt=attempt,
                    error=str(exc),
                )
            return detection

    def _bootstrap_lodestar_reference(
        self,
        frame: np.ndarray,
        detection: Optional[SpotDetection],
        *,
        tag: str,
        attempt: int,
    ) -> bool:
        if self._lodestar is None:
            return False
        if bool(getattr(self._lodestar, "is_ready", False)):
            return True

        h, w = frame.shape[:2]
        candidates: List[np.ndarray] = []
        if detection is not None:
            x1, y1, x2, y2 = (int(v) for v in detection.bbox)
            bbox_w = max(1, x2 - x1)
            bbox_h = max(1, y2 - y1)
            margin_x = max(8, bbox_w)
            margin_y = max(8, bbox_h)
            rx1 = max(0, x1 - margin_x)
            ry1 = max(0, y1 - margin_y)
            rx2 = min(w, x2 + margin_x)
            ry2 = min(h, y2 + margin_y)
            roi = frame[ry1:ry2, rx1:rx2]
            if roi.size > 0:
                candidates.append(roi)
        candidates.append(frame)

        for idx, candidate in enumerate(candidates):
            try:
                learned = bool(self._lodestar.learn_reference(candidate))
            except Exception as exc:
                LOGGER.warning("LodeSTAR bootstrap failed on candidate #%d: %s", idx, exc)
                if self.reporter is not None:
                    self.reporter.event(
                        "lodestar_reference_bootstrap_failed",
                        tag=tag,
                        attempt=attempt,
                        candidate_index=idx,
                        error=str(exc),
                    )
                continue
            if not learned:
                continue
            self._inc_metric("lodestar_bootstrap_success")
            LOGGER.info("LodeSTAR reference learned from candidate #%d", idx)
            if self.reporter is not None:
                self.reporter.event(
                    "lodestar_reference_bootstrapped",
                    tag=tag,
                    attempt=attempt,
                    candidate_index=idx,
                )
            return True
        return False

    def _refine_with_sam2_segmenter(
        self,
        frame: np.ndarray,
        detection: SpotDetection,
        *,
        tag: str,
        attempt: int,
        source: str,
    ) -> SpotDetection:
        if self._sam2_refiner is None:
            return detection

        h, w = frame.shape[:2]
        try:
            seg_result = self._sam2_refiner.segment(frame, bbox=detection.bbox)
        except Exception as exc:
            self._inc_metric("sam2_refine_failures")
            LOGGER.warning("SAM2-style refinement failed; bypassing: %s", exc)
            if self.reporter is not None:
                self.reporter.event(
                    "sam2_refiner_failed",
                    tag=tag,
                    attempt=attempt,
                    source=source,
                    error=str(exc),
                )
            return detection

        morphology = getattr(seg_result, "morphology", {})
        area = int(morphology.get("area", 0) if isinstance(morphology, dict) else 0)
        min_area = max(1, int(self.cfg.sam2_refiner_min_area))
        if area < min_area:
            self._inc_metric("sam2_refine_skips")
            if self.reporter is not None:
                self.reporter.event(
                    "sam2_refiner_skip_small_area",
                    tag=tag,
                    attempt=attempt,
                    source=source,
                    area=area,
                    min_area=min_area,
                )
            return detection

        sx1, sy1, sx2, sy2 = detection.bbox
        raw_bbox = getattr(seg_result, "bbox", detection.bbox)
        try:
            sx1, sy1, sx2, sy2 = (int(v) for v in raw_bbox)
        except Exception:
            sx1, sy1, sx2, sy2 = detection.bbox
        sx1 = max(0, min(int(sx1), w - 1))
        sy1 = max(0, min(int(sy1), h - 1))
        sx2 = max(sx1 + 1, min(int(sx2), w))
        sy2 = max(sy1 + 1, min(int(sy2), h))

        centroid = morphology.get("centroid") if isinstance(morphology, dict) else None
        if (
            isinstance(centroid, (tuple, list))
            and len(centroid) >= 2
            and np.isfinite(float(centroid[0]))
            and np.isfinite(float(centroid[1]))
        ):
            center = self._clip_center(
                (int(round(float(centroid[0]))), int(round(float(centroid[1])))),
                (h, w),
            )
        else:
            center = self._clip_center((int(round((sx1 + sx2) * 0.5)), int(round((sy1 + sy2) * 0.5))), (h, w))

        bbox = self._recenter_bbox((sx1, sy1, sx2, sy2), center, (h, w))
        seg_conf = float(np.clip(float(getattr(seg_result, "confidence", 0.0)), 0.0, 1.0))
        gain = max(0.0, float(self.cfg.sam2_refiner_confidence_gain))
        confidence = float(np.clip(max(float(detection.confidence), seg_conf * gain), 0.0, 1.0))
        refined = SpotDetection(
            center=center,
            bbox=bbox,
            confidence=confidence,
            label=detection.label,
            class_id=detection.class_id,
        )
        self._inc_metric("sam2_refine_success")
        if self.reporter is not None:
            self.reporter.event(
                "sam2_refiner_applied",
                tag=tag,
                attempt=attempt,
                source=source,
                center_before=list(detection.center),
                center_after=list(refined.center),
                area=area,
                conf_before=round(float(detection.confidence), 6),
                conf_after=round(float(refined.confidence), 6),
            )
        return refined

    def _detect_with_lodestar_fallback(
        self,
        frame: np.ndarray,
        *,
        tag: str,
        attempt: int,
    ) -> Optional[SpotDetection]:
        if self._lodestar is None or not bool(getattr(self._lodestar, "is_ready", False)):
            return None

        try:
            lodestar_detection = self._lodestar.detect(frame)
        except Exception as exc:
            LOGGER.warning("LodeSTAR fallback detection failed; bypassing: %s", exc)
            if self.reporter is not None:
                self.reporter.event("lodestar_fallback_failed", tag=tag, attempt=attempt, error=str(exc))
            return None

        if lodestar_detection is None:
            self._inc_metric("lodestar_fallback_miss")
            if self.reporter is not None:
                self.reporter.event("lodestar_fallback_miss", tag=tag, attempt=attempt)
            return None

        h, w = frame.shape[:2]
        cx = int(round(float(lodestar_detection.center[0])))
        cy = int(round(float(lodestar_detection.center[1])))
        center = self._clip_center((cx, cy), (h, w))

        lx1, ly1, lx2, ly2 = (int(v) for v in lodestar_detection.bbox)
        lx1 = max(0, min(lx1, w - 1))
        ly1 = max(0, min(ly1, h - 1))
        lx2 = max(lx1 + 1, min(lx2, w))
        ly2 = max(ly1 + 1, min(ly2, h))
        bbox = self._recenter_bbox((lx1, ly1, lx2, ly2), center, (h, w))

        fallback = SpotDetection(
            center=center,
            bbox=bbox,
            confidence=float(np.clip(float(getattr(lodestar_detection, "confidence", 0.0)), 0.05, 0.95)),
            label="lodestar_fallback",
            class_id=-2,
        )
        self._inc_metric("lodestar_fallback_hits")
        if self.reporter is not None:
            self.reporter.event(
                "lodestar_fallback_hit",
                tag=tag,
                attempt=attempt,
                center=list(fallback.center),
                conf=round(float(fallback.confidence), 6),
                ncc=round(float(getattr(lodestar_detection, "ncc_score", 0.0)), 6),
                phase=round(float(getattr(lodestar_detection, "phase_score", 0.0)), 6),
                gradient=round(float(getattr(lodestar_detection, "gradient_score", 0.0)), 6),
                snr=round(float(getattr(lodestar_detection, "snr", 0.0)), 6),
            )
        return fallback

    def _detect_with_multiscale_fallback(
        self,
        frame: np.ndarray,
        *,
        tag: str,
        attempt: int,
    ) -> Optional[SpotDetection]:
        detector = self._frontier_v6_multiscale
        if detector is None:
            return None

        self._inc_metric("frontier_v6_multiscale_attempts")
        try:
            result = detector.detect(frame)
        except Exception as exc:
            self._inc_metric("frontier_v6_multiscale_failures")
            LOGGER.warning("Frontier v6 multi-scale fallback failed; bypassing: %s", exc)
            if self.reporter is not None:
                self.reporter.event(
                    "frontier_v6_multiscale_failed",
                    tag=tag,
                    attempt=attempt,
                    error=str(exc),
                )
            return None

        center_raw = getattr(result, "center", None)
        if not isinstance(center_raw, (tuple, list)) or len(center_raw) < 2:
            self._inc_metric("frontier_v6_multiscale_miss")
            if self.reporter is not None:
                self.reporter.event("frontier_v6_multiscale_miss", tag=tag, attempt=attempt)
            return None

        cx = float(center_raw[0])
        cy = float(center_raw[1])
        if not np.isfinite(cx) or not np.isfinite(cy):
            self._inc_metric("frontier_v6_multiscale_miss")
            if self.reporter is not None:
                self.reporter.event(
                    "frontier_v6_multiscale_miss",
                    tag=tag,
                    attempt=attempt,
                    reason="non_finite_center",
                )
            return None

        h, w = frame.shape[:2]
        center = self._clip_center((int(round(cx)), int(round(cy))), (h, w))
        raw_scale_idx = getattr(result, "best_scale", -1)
        try:
            scale_idx = int(raw_scale_idx)
        except (TypeError, ValueError):
            scale_idx = -1
        detector_scales = getattr(getattr(detector, "config", None), "scales", ())
        scale_hint = 0
        if isinstance(detector_scales, (tuple, list)) and 0 <= scale_idx < len(detector_scales):
            try:
                scale_hint = int(detector_scales[scale_idx])
            except Exception:
                scale_hint = 0

        if self._last_detection is not None:
            bbox = self._recenter_bbox(self._last_detection.bbox, center, (h, w))
            class_id = int(self._last_detection.class_id)
        elif self._klt_reference_detection is not None:
            bbox = self._recenter_bbox(self._klt_reference_detection.bbox, center, (h, w))
            class_id = int(self._klt_reference_detection.class_id)
        else:
            radius = max(6, int(round(max(3, scale_hint or 7) * 1.5)))
            x1 = max(0, center[0] - radius)
            y1 = max(0, center[1] - radius)
            x2 = min(w, center[0] + radius + 1)
            y2 = min(h, center[1] + radius + 1)
            bbox = (x1, y1, x2, y2)
            class_id = -4

        base_confidence = float(getattr(result, "confidence", 0.0) or 0.0)
        if not np.isfinite(base_confidence):
            base_confidence = 0.0
        confidence_scale = float(np.clip(float(self.cfg.frontier_v6_multiscale_confidence_scale), 0.0, 1.0))
        confidence = float(np.clip(base_confidence * confidence_scale, 0.0, 0.95))
        min_confidence = float(np.clip(float(self.cfg.frontier_v6_multiscale_min_confidence), 0.0, 1.0))
        if confidence < min_confidence:
            self._inc_metric("frontier_v6_multiscale_rejects")
            if self.reporter is not None:
                self.reporter.event(
                    "frontier_v6_multiscale_rejected",
                    tag=tag,
                    attempt=attempt,
                    reason="confidence_too_low",
                    conf=round(confidence, 6),
                    min_conf=round(min_confidence, 6),
                    base_conf=round(base_confidence, 6),
                )
            return None

        fallback = SpotDetection(
            center=center,
            bbox=bbox,
            confidence=confidence,
            label="multiscale_fallback",
            class_id=class_id,
        )
        self._inc_metric("frontier_v6_multiscale_hits")
        if self.reporter is not None:
            self.reporter.event(
                "frontier_v6_multiscale_hit",
                tag=tag,
                attempt=attempt,
                center=list(fallback.center),
                conf=round(float(fallback.confidence), 6),
                base_conf=round(base_confidence, 6),
                best_scale_index=scale_idx,
                best_scale=scale_hint,
                candidates=len(getattr(result, "all_detections", []) or []),
            )
        return fallback

    def _detect_with_stardist_fallback(
        self,
        frame: np.ndarray,
        *,
        tag: str,
        attempt: int,
    ) -> Optional[SpotDetection]:
        if self._frontier_stardist is None:
            return None

        self._inc_metric("frontier_stardist_attempts")
        try:
            candidates = list(self._frontier_stardist.detect(frame))
        except Exception as exc:
            self._inc_metric("frontier_stardist_failures")
            LOGGER.warning("Frontier StarDist fallback failed; bypassing: %s", exc)
            if self.reporter is not None:
                self.reporter.event(
                    "frontier_stardist_failed",
                    tag=tag,
                    attempt=attempt,
                    error=str(exc),
                )
            return None

        if not candidates:
            if self.reporter is not None:
                self.reporter.event("frontier_stardist_miss", tag=tag, attempt=attempt)
            return None

        h, w = frame.shape[:2]
        min_area = max(1.0, float(self.cfg.frontier_stardist_min_area))
        confidence_scale = float(np.clip(float(self.cfg.frontier_stardist_confidence_scale), 0.0, 1.0))
        best: Optional[SpotDetection] = None
        best_conf = -1.0
        best_area = 0.0
        skipped_small = 0

        for item in candidates:
            polygon = getattr(item, "polygon", None)
            centroid = getattr(item, "centroid", None)
            if not isinstance(centroid, (tuple, list)) or len(centroid) < 2:
                continue
            cx = float(centroid[0])
            cy = float(centroid[1])
            if not np.isfinite(cx) or not np.isfinite(cy):
                continue

            center = self._clip_center((int(round(cx)), int(round(cy))), (h, w))
            area = float(max(0.0, float(getattr(polygon, "area", 0.0))))
            if area < min_area:
                skipped_small += 1
                continue

            contour = None
            to_contour = getattr(polygon, "to_contour", None)
            if callable(to_contour):
                try:
                    contour = np.asarray(to_contour(), dtype=np.float64).reshape(-1, 2)
                except Exception:
                    contour = None

            if contour is not None and contour.size >= 4:
                x_coords = contour[:, 0]
                y_coords = contour[:, 1]
                x1 = int(np.floor(float(np.min(x_coords))))
                y1 = int(np.floor(float(np.min(y_coords))))
                x2 = int(np.ceil(float(np.max(x_coords))))
                y2 = int(np.ceil(float(np.max(y_coords))))
            else:
                radius = float(max(2.0, np.sqrt(max(area, 1.0) / np.pi)))
                x1 = int(round(center[0] - radius))
                y1 = int(round(center[1] - radius))
                x2 = int(round(center[0] + radius))
                y2 = int(round(center[1] + radius))

            x1 = max(0, min(x1, w - 1))
            y1 = max(0, min(y1, h - 1))
            x2 = max(x1 + 1, min(x2, w))
            y2 = max(y1 + 1, min(y2, h))
            bbox = self._recenter_bbox((x1, y1, x2, y2), center, (h, w))

            base_conf = float(getattr(polygon, "confidence", getattr(item, "confidence", 0.0)))
            confidence = float(np.clip(base_conf * confidence_scale, 0.01, 0.95))
            candidate = SpotDetection(
                center=center,
                bbox=bbox,
                confidence=confidence,
                label="stardist_fallback",
                class_id=-3,
            )
            if (
                best is None
                or confidence > best_conf
                or (abs(confidence - best_conf) <= 1e-6 and area > best_area)
            ):
                best = candidate
                best_conf = confidence
                best_area = area

        if best is None:
            self._inc_metric("frontier_stardist_rejects")
            if self.reporter is not None:
                self.reporter.event(
                    "frontier_stardist_rejected",
                    tag=tag,
                    attempt=attempt,
                    reason="all_candidates_filtered",
                    min_area=round(min_area, 3),
                    skipped_small=skipped_small,
                )
            return None

        self._inc_metric("frontier_stardist_success")
        if self.reporter is not None:
            self.reporter.event(
                "frontier_stardist_hit",
                tag=tag,
                attempt=attempt,
                center=list(best.center),
                conf=round(float(best.confidence), 6),
                area=round(float(best_area), 3),
                candidates=len(candidates),
                skipped_small=skipped_small,
            )
        return best

    def _detect_with_frontier_v27_wavelet(
        self,
        frame: np.ndarray,
        *,
        tag: str,
        attempt: int,
    ) -> Optional[SpotDetection]:
        if self._frontier_v27_wavelet is None:
            return None

        self._inc_metric("frontier_v27_wavelet_attempts")
        try:
            result = self._frontier_v27_wavelet.detect(frame)
        except Exception as exc:
            self._inc_metric("frontier_v27_wavelet_failures")
            LOGGER.warning("Frontier v27 wavelet fallback failed; bypassing: %s", exc)
            if self.reporter is not None:
                self.reporter.event(
                    "frontier_v27_wavelet_failed",
                    tag=tag,
                    attempt=attempt,
                    error=str(exc),
                )
            return None

        spots = list(getattr(result, "spots", []) or [])
        if not spots:
            if self.reporter is not None:
                self.reporter.event(
                    "frontier_v27_wavelet_miss",
                    tag=tag,
                    attempt=attempt,
                )
            return None

        h, w = frame.shape[:2]
        max_shift = max(0.0, float(self.cfg.frontier_v27_wavelet_max_shift_px))
        ref_center: Optional[Tuple[int, int]] = None
        if self._last_detection is not None:
            ref_center = (
                int(self._last_detection.center[0]),
                int(self._last_detection.center[1]),
            )
        elif self._klt_reference_detection is not None:
            ref_center = (
                int(self._klt_reference_detection.center[0]),
                int(self._klt_reference_detection.center[1]),
            )

        best_item = None
        best_score = -np.inf
        best_shift = None
        best_intensity = 0.0
        for item in spots:
            if not isinstance(item, (tuple, list)) or len(item) < 3:
                continue
            x, y, intensity = float(item[0]), float(item[1]), float(item[2])
            if not np.isfinite(x) or not np.isfinite(y) or not np.isfinite(intensity):
                continue
            center = self._clip_center((int(round(x)), int(round(y))), (h, w))
            shift_px = 0.0
            if ref_center is not None:
                shift_px = float(
                    math.hypot(
                        float(center[0] - ref_center[0]),
                        float(center[1] - ref_center[1]),
                    )
                )
                if shift_px > max_shift:
                    continue
            score = float(intensity) - (0.035 * shift_px)
            if score > best_score:
                best_score = score
                best_item = center
                best_shift = shift_px
                best_intensity = float(intensity)

        if best_item is None:
            self._inc_metric("frontier_v27_wavelet_rejects")
            if self.reporter is not None:
                self.reporter.event(
                    "frontier_v27_wavelet_rejected",
                    tag=tag,
                    attempt=attempt,
                    reason="all_candidates_filtered",
                    max_shift_px=round(float(max_shift), 6),
                )
            return None

        if self._last_detection is not None:
            bbox = self._recenter_bbox(self._last_detection.bbox, best_item, (h, w))
            class_id = int(self._last_detection.class_id)
        elif self._klt_reference_detection is not None:
            bbox = self._recenter_bbox(self._klt_reference_detection.bbox, best_item, (h, w))
            class_id = int(self._klt_reference_detection.class_id)
        else:
            radius = max(8, int(round(min(h, w) * 0.04)))
            x1 = max(0, best_item[0] - radius)
            y1 = max(0, best_item[1] - radius)
            x2 = min(w, best_item[0] + radius + 1)
            y2 = min(h, best_item[1] + radius + 1)
            bbox = (x1, y1, x2, y2)
            class_id = -5

        intensity_ref = max(1e-6, abs(float(spots[0][2])))
        intensity_norm = float(np.clip(best_intensity / intensity_ref, 0.0, 1.0))
        conf_scale = float(np.clip(float(self.cfg.frontier_v27_wavelet_confidence_scale), 0.0, 1.0))
        confidence = float(np.clip(0.05 + conf_scale * intensity_norm, 0.05, 0.9))
        detection = SpotDetection(
            center=best_item,
            bbox=bbox,
            confidence=confidence,
            label="v27_wavelet_fallback",
            class_id=class_id,
        )
        self._inc_metric("frontier_v27_wavelet_success")
        if self.reporter is not None:
            self.reporter.event(
                "frontier_v27_wavelet_hit",
                tag=tag,
                attempt=attempt,
                center=list(detection.center),
                conf=round(float(detection.confidence), 6),
                intensity=round(float(best_intensity), 6),
                shift_px=None if best_shift is None else round(float(best_shift), 6),
                candidates=len(spots),
            )
        return detection

    def _detect_center_with_retry(
        self,
        tag: str,
        target: Optional[Tuple[int, int]] = None,
        frame_source_idx: int = 0,
    ) -> SpotDetection:
        last_frame: Optional[np.ndarray] = None
        focus_score: Optional[float] = None  # [FIX] 初始化为 None，防止 UnboundLocalError
        for attempt in range(1, self.cfg.detect_retry + 1):
            if self.reporter is not None:
                self.reporter.metrics.detect_attempts += 1
            if frame_source_idx == 1 and self.frame_source_pair is not None and self.frame_source_pair.source_ang is not None:
                frame = self.frame_source_pair.source_ang.grab_frame()
            else:
                frame = self.window.grab_frame()
            last_frame = frame
            self._last_frame = frame  # 缂撳瓨甯х敤浜庝簹鍍忕礌璐ㄥ績
            detect_frame = self._prepare_detection_frame(frame)
            detection = self._detect_with_runtime_metrics(
                detect_frame,
                tag=tag,
                attempt=attempt,
                source="detect_retry_primary",
            )
            miss_recorded = False
            if detection is not None and self._lodestar is not None:
                self._bootstrap_lodestar_reference(
                    detect_frame,
                    detection,
                    tag=tag,
                    attempt=attempt,
                )
            if detection is not None:
                detection = self._apply_frontier_v25_stack(
                    frame,
                    detection,
                    tag=tag,
                    attempt=attempt,
                )
            if detection is not None:
                detection = self._refine_with_sam2_segmenter(
                    frame,
                    detection,
                    tag=tag,
                    attempt=attempt,
                    source="primary",
                )
            if detection is not None:
                detection = self._apply_frontier_v26_aberration_gate(
                    frame,
                    detection,
                    tag=tag,
                    attempt=attempt,
                    source="primary",
                )
            if detection is not None:
                detection = self._apply_frontier_optics_quality_gate(
                    frame,
                    detection,
                    tag=tag,
                    attempt=attempt,
                    source="primary",
                )
            if detection is not None:
                focus_score = self._focus_score(frame, detection.bbox)
                if focus_score < float(self.cfg.min_focus_score):
                    if self.reporter is not None:
                        self.reporter.metrics.focus_rejects += 1
                        self.reporter.metrics.detect_miss += 1
                        miss_recorded = True
                        self.reporter.event(
                            "focus_rejected",
                            tag=tag,
                            attempt=attempt,
                            focus_score=round(float(focus_score), 3),
                            min_focus_score=float(self.cfg.min_focus_score),
                            detection_center=list(detection.center),
                        )
                    detection = None
                else:
                    detection = self._gate_detection_confidence(detection, tag=tag, attempt=attempt)
                    if detection is not None:
                        if not self._passes_uncertainty_gate(detect_frame, detection, tag=tag, attempt=attempt):
                            detection = None
                    if detection is not None:
                        detection = self._apply_domain_probe(frame, detection, tag=tag, attempt=attempt)
                    if detection is not None:
                        detection = self._smooth_detection(detection)
                        if self._frontier_memory is not None:
                            self._frontier_memory.update(frame, detection.center)
                        self._last_detection = detection
                        self._track_miss_streak = 0
                        self._update_klt_reference(frame, detection)
                        if self.reporter is not None:
                            self.reporter.metrics.detect_success += 1
                            self.reporter.event(
                                "detection_ok",
                                tag=tag,
                                attempt=attempt,
                                center=list(detection.center),
                                conf=round(float(detection.confidence), 4),
                                focus_score=round(float(focus_score), 3),
                            )

            if detection is None:
                detection = self._detect_with_multiscale_fallback(
                    detect_frame,
                    tag=tag,
                    attempt=attempt,
                )
                if detection is not None:
                    detection = self._refine_with_sam2_segmenter(
                        frame,
                        detection,
                        tag=tag,
                        attempt=attempt,
                        source="multiscale_fallback",
                    )
                    detection = self._apply_frontier_v26_aberration_gate(
                        frame,
                        detection,
                        tag=tag,
                        attempt=attempt,
                        source="multiscale_fallback",
                    )
                    if detection is not None:
                        detection = self._apply_frontier_optics_quality_gate(
                            frame,
                            detection,
                            tag=tag,
                            attempt=attempt,
                            source="multiscale_fallback",
                        )
                    if detection is not None:
                        detection = self._smooth_detection(detection)
                        self._last_detection = detection
                        self._track_miss_streak = 0
                        self._update_klt_reference(frame, detection)
                        if self.reporter is not None:
                            self.reporter.metrics.detect_success += 1

            if detection is None:
                detection = self._detect_with_lodestar_fallback(
                    detect_frame,
                    tag=tag,
                    attempt=attempt,
                )
                if detection is not None:
                    detection = self._refine_with_sam2_segmenter(
                        frame,
                        detection,
                        tag=tag,
                        attempt=attempt,
                        source="lodestar_fallback",
                    )
                    detection = self._apply_frontier_v26_aberration_gate(
                        frame,
                        detection,
                        tag=tag,
                        attempt=attempt,
                        source="lodestar_fallback",
                    )
                    if detection is not None:
                        detection = self._apply_frontier_optics_quality_gate(
                            frame,
                            detection,
                            tag=tag,
                            attempt=attempt,
                            source="lodestar_fallback",
                        )
                    if detection is not None:
                        detection = self._smooth_detection(detection)
                        self._last_detection = detection
                        self._track_miss_streak = 0
                        self._update_klt_reference(frame, detection)
                        if self.reporter is not None:
                            self.reporter.metrics.detect_success += 1

            if detection is None:
                detection = self._detect_with_stardist_fallback(
                    detect_frame,
                    tag=tag,
                    attempt=attempt,
                )
                if detection is not None:
                    detection = self._refine_with_sam2_segmenter(
                        frame,
                        detection,
                        tag=tag,
                        attempt=attempt,
                        source="stardist_fallback",
                    )
                    detection = self._apply_frontier_v26_aberration_gate(
                        frame,
                        detection,
                        tag=tag,
                        attempt=attempt,
                        source="stardist_fallback",
                    )
                    if detection is not None:
                        detection = self._apply_frontier_optics_quality_gate(
                            frame,
                            detection,
                            tag=tag,
                            attempt=attempt,
                            source="stardist_fallback",
                        )
                    if detection is not None:
                        detection = self._smooth_detection(detection)
                        self._last_detection = detection
                        self._track_miss_streak = 0
                        self._update_klt_reference(frame, detection)
                        if self.reporter is not None:
                            self.reporter.metrics.detect_success += 1

            if detection is None:
                detection = self._memory_recover_detection(frame, tag=tag, attempt=attempt)
                if detection is not None:
                    detection = self._smooth_detection(detection)
                    self._last_detection = detection
                    self._track_miss_streak = 0
                    self._update_klt_reference(frame, detection)
                    if self.reporter is not None:
                        self.reporter.metrics.detect_success += 1

            if detection is None:
                detection = self._detect_with_frontier_v27_wavelet(
                    detect_frame,
                    tag=tag,
                    attempt=attempt,
                )
                if detection is not None:
                    detection = self._smooth_detection(detection)
                    self._last_detection = detection
                    self._track_miss_streak = 0
                    self._update_klt_reference(frame, detection)
                    if self.reporter is not None:
                        self.reporter.metrics.detect_success += 1

            if detection is None:
                detection = self._recover_with_kalman_template(frame, tag=tag, attempt=attempt)
                if detection is not None:
                    focus_score = self._focus_score(frame, detection.bbox)
                    if focus_score < float(self.cfg.min_focus_score):
                        detection = None
                        self._inc_metric("frontier_kalman_failures")
                        if self.reporter is not None:
                            self.reporter.metrics.focus_rejects += 1
                            self.reporter.event(
                                "frontier_kalman_recovery_rejected",
                                tag=tag,
                                attempt=attempt,
                                reason="focus_too_low",
                                focus_score=round(float(focus_score), 3),
                                min_focus_score=float(self.cfg.min_focus_score),
                            )
                    else:
                        detection = self._smooth_detection(detection)
                        self._last_detection = detection
                        self._track_miss_streak = 0
                        self._update_klt_reference(frame, detection)
                        if self.reporter is not None:
                            self.reporter.metrics.detect_success += 1

            if detection is None:
                detection = self._recover_with_klt_flow(frame, tag=tag, attempt=attempt)
                if detection is not None:
                    focus_score = self._focus_score(frame, detection.bbox)
                    if focus_score < float(self.cfg.min_focus_score):
                        detection = None
                        self._inc_metric("frontier_klt_failures")
                        if self.reporter is not None:
                            self.reporter.metrics.focus_rejects += 1
                            self.reporter.event(
                                "frontier_klt_recovery_rejected",
                                tag=tag,
                                attempt=attempt,
                                reason="focus_too_low",
                                focus_score=round(float(focus_score), 3),
                                min_focus_score=float(self.cfg.min_focus_score),
                            )
                    else:
                        detection = self._smooth_detection(detection)
                        self._last_detection = detection
                        self._track_miss_streak = 0
                        self._update_klt_reference(frame, detection)
                        if self.reporter is not None:
                            self.reporter.metrics.detect_success += 1

            if detection is None:
                detection = self._recover_with_pyramid_template(frame, tag=tag, attempt=attempt)
                if detection is not None:
                    focus_score = self._focus_score(frame, detection.bbox)
                    if focus_score < float(self.cfg.min_focus_score):
                        detection = None
                        self._inc_metric("frontier_pyramid_failures")
                        if self.reporter is not None:
                            self.reporter.metrics.focus_rejects += 1
                            self.reporter.event(
                                "frontier_pyramid_recovery_rejected",
                                tag=tag,
                                attempt=attempt,
                                reason="focus_too_low",
                                focus_score=round(float(focus_score), 3),
                                min_focus_score=float(self.cfg.min_focus_score),
                            )
                    else:
                        detection = self._smooth_detection(detection)
                        self._last_detection = detection
                        self._track_miss_streak = 0
                        self._update_klt_reference(frame, detection)
                        if self.reporter is not None:
                            self.reporter.metrics.detect_success += 1

            if detection is None:
                detection = self._recover_with_logpolar_phase(frame, tag=tag, attempt=attempt)
                if detection is not None:
                    focus_score = self._focus_score(frame, detection.bbox)
                    if focus_score < float(self.cfg.min_focus_score):
                        detection = None
                        self._inc_metric("frontier_logpolar_failures")
                        if self.reporter is not None:
                            self.reporter.metrics.focus_rejects += 1
                            self.reporter.event(
                                "frontier_logpolar_recovery_rejected",
                                tag=tag,
                                attempt=attempt,
                                reason="focus_too_low",
                                focus_score=round(float(focus_score), 3),
                                min_focus_score=float(self.cfg.min_focus_score),
                            )
                    else:
                        detection = self._smooth_detection(detection)
                        self._last_detection = detection
                        self._track_miss_streak = 0
                        self._update_klt_reference(frame, detection)
                        if self.reporter is not None:
                            self.reporter.metrics.detect_success += 1

            if detection is None:
                detection = self._recover_with_phase_correlation(frame, tag=tag, attempt=attempt)
                if detection is not None:
                    focus_score = self._focus_score(frame, detection.bbox)
                    if focus_score < float(self.cfg.min_focus_score):
                        detection = None
                        self._inc_metric("frontier_phase_failures")
                        if self.reporter is not None:
                            self.reporter.metrics.focus_rejects += 1
                            self.reporter.event(
                                "frontier_phase_recovery_rejected",
                                tag=tag,
                                attempt=attempt,
                                reason="focus_too_low",
                                focus_score=round(float(focus_score), 3),
                                min_focus_score=float(self.cfg.min_focus_score),
                            )
                    else:
                        detection = self._smooth_detection(detection)
                        self._last_detection = detection
                        self._track_miss_streak = 0
                        self._update_klt_reference(frame, detection)
                        if self.reporter is not None:
                            self.reporter.metrics.detect_success += 1

            if detection is None:
                detection = self._recover_with_ecc_alignment(frame, tag=tag, attempt=attempt)
                if detection is not None:
                    focus_score = self._focus_score(frame, detection.bbox)
                    if focus_score < float(self.cfg.min_focus_score):
                        detection = None
                        self._inc_metric("frontier_ecc_failures")
                        if self.reporter is not None:
                            self.reporter.metrics.focus_rejects += 1
                            self.reporter.event(
                                "frontier_ecc_recovery_rejected",
                                tag=tag,
                                attempt=attempt,
                                reason="focus_too_low",
                                focus_score=round(float(focus_score), 3),
                                min_focus_score=float(self.cfg.min_focus_score),
                            )
                    else:
                        detection = self._smooth_detection(detection)
                        self._last_detection = detection
                        self._track_miss_streak = 0
                        self._update_klt_reference(frame, detection)
                        if self.reporter is not None:
                            self.reporter.metrics.detect_success += 1

            if detection is None:
                detection = self._recover_with_cmc_affine(frame, tag=tag, attempt=attempt)
                if detection is not None:
                    focus_score = self._focus_score(frame, detection.bbox)
                    if focus_score < float(self.cfg.min_focus_score):
                        detection = None
                        self._inc_metric("frontier_cmc_failures")
                        if self.reporter is not None:
                            self.reporter.metrics.focus_rejects += 1
                            self.reporter.event(
                                "frontier_cmc_recovery_rejected",
                                tag=tag,
                                attempt=attempt,
                                reason="focus_too_low",
                                focus_score=round(float(focus_score), 3),
                                min_focus_score=float(self.cfg.min_focus_score),
                            )
                    else:
                        detection = self._smooth_detection(detection)
                        self._last_detection = detection
                        self._track_miss_streak = 0
                        self._update_klt_reference(frame, detection)
                        if self.reporter is not None:
                            self.reporter.metrics.detect_success += 1

            if detection is None:
                detection = self._recover_with_orb_homography(frame, tag=tag, attempt=attempt)
                if detection is not None:
                    focus_score = self._focus_score(frame, detection.bbox)
                    if focus_score < float(self.cfg.min_focus_score):
                        detection = None
                        self._inc_metric("frontier_orb_failures")
                        if self.reporter is not None:
                            self.reporter.metrics.focus_rejects += 1
                            self.reporter.event(
                                "frontier_orb_recovery_rejected",
                                tag=tag,
                                attempt=attempt,
                                reason="focus_too_low",
                                focus_score=round(float(focus_score), 3),
                                min_focus_score=float(self.cfg.min_focus_score),
                            )
                    else:
                        detection = self._smooth_detection(detection)
                        self._last_detection = detection
                        self._track_miss_streak = 0
                        self._update_klt_reference(frame, detection)
                        if self.reporter is not None:
                            self.reporter.metrics.detect_success += 1

            temporal_before_none = detection is None
            detection = self._apply_frontier_temporal_ensemble(
                frame,
                detection,
                tag=tag,
                attempt=attempt,
                source="detect_retry",
            )
            if temporal_before_none and detection is not None:
                focus_score = self._focus_score(frame, detection.bbox)
                if focus_score < float(self.cfg.min_focus_score):
                    detection = None
                    self._inc_metric("frontier_temporal_rejects")
                    if self.reporter is not None:
                        self.reporter.metrics.focus_rejects += 1
                        self.reporter.event(
                            "frontier_temporal_recovery_rejected",
                            tag=tag,
                            attempt=attempt,
                            source="detect_retry",
                            reason="focus_too_low",
                            focus_score=round(float(focus_score), 3),
                            min_focus_score=float(self.cfg.min_focus_score),
                        )
                else:
                    detection = self._smooth_detection(detection)
                    if self._frontier_memory is not None:
                        self._frontier_memory.update(frame, detection.center)
                    self._last_detection = detection
                    self._track_miss_streak = 0
                    self._update_klt_reference(frame, detection)
                    if self.reporter is not None:
                        self.reporter.metrics.detect_success += 1

            if detection is None:
                if self.reporter is not None and not miss_recorded:
                    self.reporter.metrics.detect_miss += 1
                    self.reporter.event(
                        "detection_miss",
                        tag=tag,
                        attempt=attempt,
                        retry_limit=int(self.cfg.detect_retry),
                    )
                detection = self._reuse_last_detection_if_buffered(tag=tag, attempt=attempt)

            self._show_preview(frame, detection, target=target, title=tag, focus_score=focus_score if detection is not None else None)
            if detection is not None:
                return detection
            LOGGER.warning("%s: detection not found (%d/%d)", tag, attempt, self.cfg.detect_retry)
            time.sleep(self.cfg.detect_retry_interval_s)

        if self.cfg.enable_recovery_scan:
            recovered = self._attempt_recovery_scan(tag=tag, target=target)
            if recovered is not None:
                return recovered

        if last_frame is not None:
            self._show_preview(last_frame, None, target=target, title=f"{tag} (not found)")
        raise RuntimeError(f"{tag}: detection failed after {self.cfg.detect_retry} attempts")

    def _apply_frontier_v7_phase_refine(self, detection: SpotDetection) -> SpotDetection:
        phase = self._frontier_v7_phase
        if phase is None or self._last_frame is None:
            return detection

        self._inc_metric("frontier_v7_phase_calls")
        try:
            curr_gray = self._to_grayscale(self._last_frame).astype(np.float64)
            curr_gray = np.ascontiguousarray(curr_gray)

            prev_gray = self._frontier_v7_prev_gray
            prev_detection = self._frontier_v7_prev_detection
            if prev_gray is None or prev_detection is None:
                self._frontier_v7_prev_gray = curr_gray
                self._frontier_v7_prev_detection = SpotDetection(
                    center=tuple(int(v) for v in detection.center),
                    bbox=tuple(int(v) for v in detection.bbox),
                    confidence=float(detection.confidence),
                    label=str(detection.label),
                    class_id=int(detection.class_id),
                )
                return detection

            if prev_gray.shape[:2] != curr_gray.shape[:2]:
                self._inc_metric("frontier_v7_phase_rejects")
                self._frontier_v7_prev_gray = curr_gray
                self._frontier_v7_prev_detection = detection
                return detection

            phase_result = phase.register(prev_gray, curr_gray)
            shift_x = float(getattr(phase_result, "shift_x", 0.0) or 0.0)
            shift_y = float(getattr(phase_result, "shift_y", 0.0) or 0.0)
            if not np.isfinite(shift_x) or not np.isfinite(shift_y):
                self._inc_metric("frontier_v7_phase_rejects")
                self._frontier_v7_prev_gray = curr_gray
                self._frontier_v7_prev_detection = detection
                return detection

            predicted_center = (
                int(round(float(prev_detection.center[0]) - shift_x)),
                int(round(float(prev_detection.center[1]) - shift_y)),
            )
            predicted_center = self._clip_center(predicted_center, self._last_frame.shape[:2])

            blend = float(np.clip(float(self.cfg.frontier_v7_phase_blend), 0.0, 1.0))
            fused_center = (
                int(round((1.0 - blend) * float(detection.center[0]) + blend * float(predicted_center[0]))),
                int(round((1.0 - blend) * float(detection.center[1]) + blend * float(predicted_center[1]))),
            )
            fused_center = self._clip_center(fused_center, self._last_frame.shape[:2])

            shift_from_det = float(
                math.hypot(
                    float(fused_center[0] - detection.center[0]),
                    float(fused_center[1] - detection.center[1]),
                )
            )
            max_shift = max(0.0, float(self.cfg.frontier_v7_phase_max_shift_px))
            if shift_from_det > max_shift:
                self._inc_metric("frontier_v7_phase_rejects")
                if self.reporter is not None:
                    self.reporter.event(
                        "frontier_v7_phase_rejected",
                        reason="shift_too_large",
                        shift_px=round(shift_from_det, 6),
                        max_shift_px=round(max_shift, 6),
                    )
                self._frontier_v7_prev_gray = curr_gray
                self._frontier_v7_prev_detection = detection
                return detection

            refined = detection
            if fused_center != detection.center:
                refined = SpotDetection(
                    center=fused_center,
                    bbox=self._recenter_bbox(detection.bbox, fused_center, self._last_frame.shape[:2]),
                    confidence=float(np.clip(max(float(detection.confidence), float(getattr(phase_result, "confidence", 0.0) or 0.0)), 0.01, 0.99)),
                    label=detection.label,
                    class_id=detection.class_id,
                )
                self._inc_metric("frontier_v7_phase_refines")
                if self.reporter is not None:
                    self.reporter.event(
                        "frontier_v7_phase_refined",
                        center_before=list(detection.center),
                        center_after=list(refined.center),
                        predicted_center=list(predicted_center),
                        shift_x=round(shift_x, 6),
                        shift_y=round(shift_y, 6),
                        shift_px=round(shift_from_det, 6),
                        corr_conf=round(float(getattr(phase_result, "confidence", 0.0) or 0.0), 6),
                    )

            if self._frontier_v7_causal is not None:
                prev_c = prev_detection.center
                obs = np.array(
                    [
                        float(refined.center[0]),
                        float(refined.center[1]),
                        float(refined.center[0] - prev_c[0]),
                        float(refined.center[1] - prev_c[1]),
                    ],
                    dtype=np.float64,
                )
                try:
                    self._frontier_v7_causal.update(obs)
                except Exception:
                    pass

            self._frontier_v7_prev_gray = curr_gray
            self._frontier_v7_prev_detection = refined
            return refined
        except Exception as exc:
            self._inc_metric("frontier_v7_phase_failures")
            LOGGER.warning("Frontier v7 phase refinement failed; bypassing: %s", exc)
            if self.reporter is not None:
                self.reporter.event("frontier_v7_phase_failed", error=str(exc))
            return detection

    def _apply_frontier_v27_mle_refine(self, detection: SpotDetection) -> SpotDetection:
        fitter = self._frontier_v27_mle_fitter
        if fitter is None or self._last_frame is None:
            return detection

        self._inc_metric("frontier_v27_mle_calls")
        try:
            gray = self._to_grayscale(self._last_frame)
            patch = self._extract_detection_patch(gray, detection)
            min_patch = max(8, int(self.cfg.frontier_v27_mle_min_patch))
            if patch is None or min(patch.shape[:2]) < min_patch:
                self._inc_metric("frontier_v27_mle_rejects")
                return detection

            fit_result = fitter.fit(
                patch,
                x_init=float(patch.shape[1] * 0.5),
                y_init=float(patch.shape[0] * 0.5),
            )
            if fit_result is None:
                self._inc_metric("frontier_v27_mle_rejects")
                return detection

            refined_cx = float(fit_result.x + detection.bbox[0])
            refined_cy = float(fit_result.y + detection.bbox[1])
            if not np.isfinite(refined_cx) or not np.isfinite(refined_cy):
                self._inc_metric("frontier_v27_mle_rejects")
                return detection

            crlb_x, crlb_y = getattr(fit_result, "crlb_precision", (np.inf, np.inf))
            crlb_max = max(float(crlb_x), float(crlb_y))
            max_crlb = max(0.0, float(self.cfg.frontier_v27_mle_max_crlb_px))
            if not np.isfinite(crlb_max) or crlb_max > max_crlb:
                self._inc_metric("frontier_v27_mle_rejects")
                if self.reporter is not None:
                    self.reporter.event(
                        "frontier_v27_mle_rejected",
                        reason="crlb_too_large",
                        crlb_max=round(float(crlb_max), 6) if np.isfinite(crlb_max) else None,
                        crlb_limit=round(float(max_crlb), 6),
                    )
                return detection

            center = self._clip_center(
                (int(round(refined_cx)), int(round(refined_cy))),
                self._last_frame.shape[:2],
            )
            shift_px = float(
                math.hypot(
                    float(center[0] - detection.center[0]),
                    float(center[1] - detection.center[1]),
                )
            )
            max_shift = float(max(1.0, self.cfg.frontier_v27_mle_min_patch * 1.5))
            if shift_px > max_shift:
                self._inc_metric("frontier_v27_mle_rejects")
                if self.reporter is not None:
                    self.reporter.event(
                        "frontier_v27_mle_rejected",
                        reason="shift_too_large",
                        shift_px=round(float(shift_px), 6),
                        max_shift_px=round(float(max_shift), 6),
                    )
                return detection

            if center == detection.center:
                return detection

            refined_bbox = self._recenter_bbox(
                detection.bbox,
                center,
                self._last_frame.shape[:2],
            )
            conf_gain = max(0.0, float(self.cfg.frontier_v27_mle_confidence_gain))
            refined = SpotDetection(
                center=center,
                bbox=refined_bbox,
                confidence=float(np.clip(float(detection.confidence) * conf_gain, 0.01, 0.99)),
                label=detection.label,
                class_id=detection.class_id,
            )
            self._inc_metric("frontier_v27_mle_refines")
            if self.reporter is not None:
                self.reporter.event(
                    "frontier_v27_mle_refined",
                    center_before=list(detection.center),
                    center_after=list(refined.center),
                    shift_px=round(float(shift_px), 6),
                    crlb_x=round(float(crlb_x), 6) if np.isfinite(crlb_x) else None,
                    crlb_y=round(float(crlb_y), 6) if np.isfinite(crlb_y) else None,
                    conf_before=round(float(detection.confidence), 6),
                    conf_after=round(float(refined.confidence), 6),
                )
            return refined
        except Exception as exc:
            self._inc_metric("frontier_v27_mle_failures")
            LOGGER.warning("Frontier v27 MLE refinement failed; bypassing: %s", exc)
            if self.reporter is not None:
                self.reporter.event("frontier_v27_mle_failed", error=str(exc))
            return detection

    def _apply_frontier_v28_consensus(self, detection: SpotDetection) -> SpotDetection:
        consensus = self._frontier_v28_consensus
        if consensus is None:
            return detection

        self._inc_metric("frontier_v28_consensus_calls")
        try:
            result = consensus.update(
                (
                    float(detection.center[0]),
                    float(detection.center[1]),
                ),
                float(detection.confidence),
            )
            if result is None:
                return detection

            if bool(getattr(result, "rejected", False)):
                self._inc_metric("frontier_v28_consensus_rejects")
                if self.reporter is not None:
                    self.reporter.event(
                        "frontier_v28_consensus_rejected",
                        reason=str(getattr(result, "reason", "unknown")),
                        center=list(detection.center),
                        conf=round(float(detection.confidence), 6),
                        uncertainty_px=round(float(getattr(result, "uncertainty_px", 0.0) or 0.0), 6),
                    )
                return detection

            center_raw = getattr(result, "center", None)
            if (
                not isinstance(center_raw, (tuple, list))
                or len(center_raw) < 2
                or self._last_frame is None
            ):
                return detection

            cx = float(center_raw[0])
            cy = float(center_raw[1])
            if not np.isfinite(cx) or not np.isfinite(cy):
                self._inc_metric("frontier_v28_consensus_rejects")
                return detection

            center = self._clip_center(
                (int(round(cx)), int(round(cy))),
                self._last_frame.shape[:2],
            )
            if center == detection.center:
                return detection

            shift_px = float(
                math.hypot(
                    float(center[0] - detection.center[0]),
                    float(center[1] - detection.center[1]),
                )
            )
            max_shift = max(0.0, float(self.cfg.frontier_v28_max_shift_px))
            if shift_px > max_shift:
                self._inc_metric("frontier_v28_consensus_rejects")
                if self.reporter is not None:
                    self.reporter.event(
                        "frontier_v28_consensus_rejected",
                        reason="shift_too_large",
                        shift_px=round(float(shift_px), 6),
                        max_shift_px=round(float(max_shift), 6),
                    )
                return detection

            conf_gain = max(0.0, float(self.cfg.frontier_v28_confidence_gain))
            refined = SpotDetection(
                center=center,
                bbox=self._recenter_bbox(detection.bbox, center, self._last_frame.shape[:2]),
                confidence=float(np.clip(float(detection.confidence) * conf_gain, 0.01, 0.99)),
                label=detection.label,
                class_id=detection.class_id,
            )
            self._inc_metric("frontier_v28_consensus_refines")
            if self.reporter is not None:
                self.reporter.event(
                    "frontier_v28_consensus_refined",
                    center_before=list(detection.center),
                    center_after=list(refined.center),
                    shift_px=round(float(shift_px), 6),
                    uncertainty_px=round(float(getattr(result, "uncertainty_px", 0.0) or 0.0), 6),
                    conf_before=round(float(detection.confidence), 6),
                    conf_after=round(float(refined.confidence), 6),
                    history_count=int(getattr(result, "history_count", 0) or 0),
                )
            return refined
        except Exception as exc:
            self._inc_metric("frontier_v28_consensus_failures")
            LOGGER.warning("Frontier v28 consensus failed; bypassing: %s", exc)
            if self.reporter is not None:
                self.reporter.event("frontier_v28_consensus_failed", error=str(exc))
            return detection

    def _apply_frontier_v29_reliability(self, detection: SpotDetection) -> SpotDetection:
        reliability = self._frontier_v29_reliability
        if reliability is None:
            return detection

        self._inc_metric("frontier_v29_reliability_calls")
        try:
            result = reliability.update(
                (
                    float(detection.center[0]),
                    float(detection.center[1]),
                ),
                float(detection.confidence),
                timestamp_s=time.perf_counter(),
            )
            if result is None:
                return detection

            if bool(getattr(result, "rejected", False)):
                self._inc_metric("frontier_v29_reliability_rejects")
                if self.reporter is not None:
                    self.reporter.event(
                        "frontier_v29_reliability_rejected",
                        reason=str(getattr(result, "reason", "unknown")),
                        center=list(detection.center),
                        conf=round(float(detection.confidence), 6),
                        pred_error_px=round(float(getattr(result, "prediction_error_px", 0.0) or 0.0), 6),
                    )
                return detection

            center_raw = getattr(result, "center", None)
            if (
                not isinstance(center_raw, (tuple, list))
                or len(center_raw) < 2
                or self._last_frame is None
            ):
                return detection

            cx = float(center_raw[0])
            cy = float(center_raw[1])
            if not np.isfinite(cx) or not np.isfinite(cy):
                self._inc_metric("frontier_v29_reliability_rejects")
                return detection

            center = self._clip_center(
                (int(round(cx)), int(round(cy))),
                self._last_frame.shape[:2],
            )
            if center == detection.center:
                return detection

            shift_px = float(
                math.hypot(
                    float(center[0] - detection.center[0]),
                    float(center[1] - detection.center[1]),
                )
            )
            max_shift = max(0.0, float(self.cfg.frontier_v29_max_refine_shift_px))
            if shift_px > max_shift:
                self._inc_metric("frontier_v29_reliability_rejects")
                if self.reporter is not None:
                    self.reporter.event(
                        "frontier_v29_reliability_rejected",
                        reason="shift_too_large",
                        shift_px=round(float(shift_px), 6),
                        max_shift_px=round(float(max_shift), 6),
                    )
                return detection

            conf_gain = max(0.0, float(self.cfg.frontier_v29_confidence_gain))
            refined = SpotDetection(
                center=center,
                bbox=self._recenter_bbox(detection.bbox, center, self._last_frame.shape[:2]),
                confidence=float(np.clip(float(detection.confidence) * conf_gain, 0.01, 0.99)),
                label=detection.label,
                class_id=detection.class_id,
            )
            self._inc_metric("frontier_v29_reliability_refines")
            if self.reporter is not None:
                pred_center_raw = getattr(result, "predicted_center", (cx, cy))
                if not isinstance(pred_center_raw, (tuple, list)) or len(pred_center_raw) < 2:
                    pred_center_raw = (cx, cy)
                self.reporter.event(
                    "frontier_v29_reliability_refined",
                    center_before=list(detection.center),
                    center_after=list(refined.center),
                    shift_px=round(float(shift_px), 6),
                    pred_center=[
                        round(float(pred_center_raw[0]), 6),
                        round(float(pred_center_raw[1]), 6),
                    ],
                    pred_error_px=round(float(getattr(result, "prediction_error_px", 0.0) or 0.0), 6),
                    speed_px_s=round(float(getattr(result, "estimated_speed_px_s", 0.0) or 0.0), 6),
                    conf_before=round(float(detection.confidence), 6),
                    conf_after=round(float(refined.confidence), 6),
                    history_count=int(getattr(result, "history_count", 0) or 0),
                )
            return refined
        except Exception as exc:
            self._inc_metric("frontier_v29_reliability_failures")
            LOGGER.warning("Frontier v29 reliability failed; bypassing: %s", exc)
            if self.reporter is not None:
                self.reporter.event("frontier_v29_reliability_failed", error=str(exc))
            return detection

    def _apply_frontier_v30_phase_lock(self, detection: SpotDetection) -> SpotDetection:
        phase_lock = self._frontier_v30_phase_lock
