    def _apply_frontier_v56_assoc(self, detection: SpotDetection) -> SpotDetection:
        assoc_gate = self._frontier_v56_assoc
        if assoc_gate is None or self._last_frame is None:
            return detection
        self._inc_metric("frontier_v56_assoc_calls")
        try:
            result = assoc_gate.update(
                frame=self._last_frame,
                center=(float(detection.center[0]), float(detection.center[1])),
                confidence=float(detection.confidence),
                timestamp_s=time.perf_counter(),
            )
            result_center = getattr(result, "center", None)
            if not isinstance(result_center, (tuple, list)) or len(result_center) < 2:
                self._inc_metric("frontier_v56_assoc_rejects")
                return detection
            cx = float(result_center[0])
            cy = float(result_center[1])
            if not np.isfinite(cx) or not np.isfinite(cy):
                self._inc_metric("frontier_v56_assoc_rejects")
                return detection

            pred_center = getattr(result, "predicted_center", result_center)
            if not isinstance(pred_center, (tuple, list)) or len(pred_center) < 2:
                pred_center = result_center
            pred_x = float(pred_center[0])
            pred_y = float(pred_center[1])
            if not np.isfinite(pred_x) or not np.isfinite(pred_y):
                pred_x = cx
                pred_y = cy

            teacher_consensus_center = getattr(result, "teacher_consensus_center", result_center)
            if not isinstance(teacher_consensus_center, (tuple, list)) or len(teacher_consensus_center) < 2:
                teacher_consensus_center = result_center
            teacher_consensus_x = float(teacher_consensus_center[0])
            teacher_consensus_y = float(teacher_consensus_center[1])
            if not np.isfinite(teacher_consensus_x) or not np.isfinite(teacher_consensus_y):
                teacher_consensus_x = cx
                teacher_consensus_y = cy

            teacher_rescue_used = bool(getattr(result, "teacher_rescue_used", False))
            if teacher_rescue_used:
                self._inc_metric("frontier_v56_assoc_teacher_rescue_hits")
            teacher_rejected = bool(getattr(result, "teacher_rejected", False))
            if teacher_rejected:
                self._inc_metric("frontier_v56_assoc_teacher_entropy_rejects")

            refined = SpotDetection(
                center=(int(round(cx)), int(round(cy))),
                bbox=self._recenter_bbox(
                    detection.bbox,
                    (int(round(cx)), int(round(cy))),
                    self._last_frame.shape[:2],
                ),
                confidence=float(
                    np.clip(
                        float(getattr(result, "confidence", detection.confidence) or detection.confidence),
                        0.0,
                        1.0,
                    )
                ),
                label=detection.label,
                class_id=detection.class_id,
            )

            shift_px = float(
                math.hypot(
                    float(refined.center[0] - detection.center[0]),
                    float(refined.center[1] - detection.center[1]),
                )
            )
            max_shift = max(0.0, float(self.cfg.frontier_v56_max_refine_shift_px))
            if shift_px > max_shift:
                self._inc_metric("frontier_v56_assoc_rejects")
                if self.reporter is not None:
                    self.reporter.event(
                        "frontier_v56_assoc_rejected",
                        reason="refine_shift_too_large",
                        shift_px=round(shift_px, 6),
                        max_shift_px=round(max_shift, 6),
                        assoc_distance_px=round(float(getattr(result, "association_distance_px", 0.0) or 0.0), 6),
                        adaptive_gate_px=round(float(getattr(result, "adaptive_gate_px", 0.0) or 0.0), 6),
                        verifier_score=round(float(getattr(result, "verifier_score", 0.0) or 0.0), 6),
                        teacher_entropy=round(float(getattr(result, "teacher_entropy", 1.0) or 1.0), 6),
                    )
                return detection

            rejected = bool(getattr(result, "rejected", False))
            assoc_distance_px = float(getattr(result, "association_distance_px", 0.0) or 0.0)
            adaptive_gate_px = float(getattr(result, "adaptive_gate_px", 0.0) or 0.0)
            verifier_score = float(getattr(result, "verifier_score", 0.0) or 0.0)
            disagreement_score = float(getattr(result, "disagreement_score", 0.0) or 0.0)
            teacher_entropy = float(getattr(result, "teacher_entropy", 1.0) or 1.0)
            teacher_agreement = float(getattr(result, "teacher_agreement", 0.0) or 0.0)
            innovation_score = float(getattr(result, "innovation_score", 0.0) or 0.0)
            edge_ratio = 0.0
            if adaptive_gate_px > 1e-6:
                edge_ratio = assoc_distance_px / adaptive_gate_px
            if rejected:
                self._inc_metric("frontier_v56_assoc_rejects")
                if self.reporter is not None:
                    self.reporter.event(
                        "frontier_v56_assoc_rejected",
                        reason=str(getattr(result, "reason", "rejected")),
                        assoc_distance_px=round(assoc_distance_px, 6),
                        adaptive_gate_px=round(adaptive_gate_px, 6),
                        edge_ratio=round(edge_ratio, 6),
                        verifier_score=round(verifier_score, 6),
                        disagreement_score=round(disagreement_score, 6),
                        teacher_entropy=round(teacher_entropy, 6),
                        teacher_agreement=round(teacher_agreement, 6),
                        innovation_score=round(innovation_score, 6),
                        pred_center=[round(pred_x, 6), round(pred_y, 6)],
                        teacher_consensus_center=[round(teacher_consensus_x, 6), round(teacher_consensus_y, 6)],
                        teacher_rescue_used=teacher_rescue_used,
                        teacher_rejected=teacher_rejected,
                    )
                return detection

            edge_gate_ratio = max(0.0, float(self.cfg.frontier_v56_edge_gate_ratio))
            edge_low_verifier_threshold = min(1.0, max(0.0, float(self.cfg.frontier_v56_edge_low_verifier_threshold)))
            min_innovation_score = min(1.0, max(0.0, float(self.cfg.frontier_v56_min_innovation_score)))
            if edge_ratio >= edge_gate_ratio and verifier_score < edge_low_verifier_threshold:
                self._inc_metric("frontier_v56_assoc_rejects")
                self._inc_metric("frontier_v56_assoc_edge_rejects")
                if self.reporter is not None:
                    self.reporter.event(
                        "frontier_v56_assoc_rejected",
                        reason="edge_gate_low_verifier",
                        assoc_distance_px=round(assoc_distance_px, 6),
                        adaptive_gate_px=round(adaptive_gate_px, 6),
                        edge_ratio=round(edge_ratio, 6),
                        edge_gate_ratio=round(edge_gate_ratio, 6),
                        verifier_score=round(verifier_score, 6),
                        verifier_threshold=round(edge_low_verifier_threshold, 6),
                        innovation_score=round(innovation_score, 6),
                        teacher_entropy=round(teacher_entropy, 6),
                        teacher_agreement=round(teacher_agreement, 6),
                        pred_center=[round(pred_x, 6), round(pred_y, 6)],
                        teacher_consensus_center=[round(teacher_consensus_x, 6), round(teacher_consensus_y, 6)],
                    )
                return detection

            if (
                innovation_score < min_innovation_score
                and teacher_entropy > float(self.cfg.frontier_v56_teacher_entropy_reject_threshold) * 0.9
            ):
                self._inc_metric("frontier_v56_assoc_rejects")
                self._inc_metric("frontier_v56_assoc_innovation_rejects")
                if self.reporter is not None:
                    self.reporter.event(
                        "frontier_v56_assoc_rejected",
                        reason="low_innovation_high_entropy",
                        innovation_score=round(innovation_score, 6),
                        innovation_threshold=round(min_innovation_score, 6),
                        teacher_entropy=round(teacher_entropy, 6),
                        teacher_entropy_threshold=round(
                            float(self.cfg.frontier_v56_teacher_entropy_reject_threshold) * 0.9,
                            6,
                        ),
                        assoc_distance_px=round(assoc_distance_px, 6),
                        adaptive_gate_px=round(adaptive_gate_px, 6),
                        edge_ratio=round(edge_ratio, 6),
                        verifier_score=round(verifier_score, 6),
                        teacher_agreement=round(teacher_agreement, 6),
                        pred_center=[round(pred_x, 6), round(pred_y, 6)],
                        teacher_consensus_center=[round(teacher_consensus_x, 6), round(teacher_consensus_y, 6)],
                    )
                return detection

            refined_flag = bool(getattr(result, "refined", False))
            if refined_flag:
                self._inc_metric("frontier_v56_assoc_refines")

            if self.reporter is not None:
                self.reporter.event(
                    "frontier_v56_assoc_accepted",
                    center_before=[round(float(detection.center[0]), 6), round(float(detection.center[1]), 6)],
                    center_after=[round(float(refined.center[0]), 6), round(float(refined.center[1]), 6)],
                    conf_before=round(float(detection.confidence), 6),
                    conf_after=round(float(refined.confidence), 6),
                    assoc_distance_px=round(assoc_distance_px, 6),
                    adaptive_gate_px=round(adaptive_gate_px, 6),
                    edge_ratio=round(edge_ratio, 6),
                    fusion_score=round(float(getattr(result, "fusion_score", 0.0) or 0.0), 6),
                    memory_similarity=round(float(getattr(result, "memory_similarity", 0.0) or 0.0), 6),
                    reliability_score=round(float(getattr(result, "reliability_score", 0.0) or 0.0), 6),
                    jitter_score=round(float(getattr(result, "jitter_score", 0.0) or 0.0), 6),
                    verifier_score=round(verifier_score, 6),
                    disagreement_score=round(disagreement_score, 6),
                    teacher_entropy=round(teacher_entropy, 6),
                    teacher_agreement=round(teacher_agreement, 6),
                    innovation_score=round(innovation_score, 6),
                    pred_center=[round(pred_x, 6), round(pred_y, 6)],
                    teacher_consensus_center=[round(teacher_consensus_x, 6), round(teacher_consensus_y, 6)],
                    teacher_rescue_used=teacher_rescue_used,
                    teacher_rejected=teacher_rejected,
                    refined=refined_flag,
                )
            return refined
        except Exception as exc:
            self._inc_metric("frontier_v56_assoc_failures")
            LOGGER.warning("Frontier v56 teacher-consensus association failed; bypassing: %s", exc)
            if self.reporter is not None:
                self.reporter.event("frontier_v56_assoc_failed", error=str(exc))
            return detection

    def _record_frontier_v58_diag(
        self,
        *,
        visibility_score: float,
        drift_ratio: float,
        rejected: bool,
        persistent_reentry_used: bool,
    ) -> None:
        if not self.cfg.frontier_v58_stability_guard_enabled:
            return
        vis = float(np.clip(float(visibility_score), 0.0, 1.0))
        drift = max(0.0, float(drift_ratio))
        rej = 1.0 if rejected else 0.0
        reentry = 1.0 if persistent_reentry_used else 0.0
        self._frontier_v58_diag_history.append((vis, drift, rej, reentry))

    def _apply_frontier_v58_stability_guard(
        self,
        *,
        base_detection: SpotDetection,
        candidate_detection: SpotDetection,
        visibility_score: float,
        drift_ratio: float,
        persistent_reentry_used: bool,
    ) -> SpotDetection:
        if not self.cfg.frontier_v58_stability_guard_enabled:
            return candidate_detection
        self._inc_metric("frontier_v58_guard_checks")
        try:
            min_samples = max(4, int(self.cfg.frontier_v58_min_samples))
            if len(self._frontier_v58_diag_history) < min_samples:
                return candidate_detection

            diag = np.asarray(self._frontier_v58_diag_history, dtype=np.float64)
            visibility_mean = float(np.mean(diag[:, 0]))
            drift_ratio_p95 = float(np.percentile(diag[:, 1], 95))
            reject_rate = float(np.mean(diag[:, 2]))
            reentry_rate = float(np.mean(diag[:, 3]))
            stability_score = (
                visibility_mean
                - 0.35 * max(0.0, drift_ratio_p95 - 1.0)
                - 0.55 * reject_rate
                + reentry_rate * float(self.cfg.frontier_v58_reentry_bonus)
            )

            reasons: List[str] = []
            if visibility_mean < float(self.cfg.frontier_v58_min_visibility_mean):
                reasons.append("low_visibility_mean")
            if drift_ratio_p95 > float(self.cfg.frontier_v58_max_drift_ratio_p95):
                reasons.append("high_drift_p95")
            if reject_rate > float(self.cfg.frontier_v58_max_reject_rate):
                reasons.append("high_reject_rate")
            if stability_score < float(self.cfg.frontier_v58_min_stability_score):
                reasons.append("low_stability_score")
            if not reasons:
                return candidate_detection

            conf_penalty = min(1.0, max(0.0, float(self.cfg.frontier_v58_confidence_penalty)))
            soft_conf = float(np.clip(float(candidate_detection.confidence) * conf_penalty, 0.0, 1.0))
            if (
                persistent_reentry_used
                and float(visibility_score) >= float(self.cfg.frontier_v58_min_visibility_mean)
            ):
                self._inc_metric("frontier_v58_guard_soft_accepts")
                softened = SpotDetection(
                    center=candidate_detection.center,
                    bbox=candidate_detection.bbox,
                    confidence=soft_conf,
                    label=candidate_detection.label,
                    class_id=candidate_detection.class_id,
                )
                if self.reporter is not None:
                    self.reporter.event(
                        "frontier_v58_guard_soft_accept",
                        reasons=reasons,
                        visibility_mean=round(visibility_mean, 6),
                        drift_ratio_p95=round(drift_ratio_p95, 6),
                        reject_rate=round(reject_rate, 6),
                        reentry_rate=round(reentry_rate, 6),
                        stability_score=round(stability_score, 6),
                        confidence_before=round(float(candidate_detection.confidence), 6),
                        confidence_after=round(float(softened.confidence), 6),
                    )
                return softened

            self._inc_metric("frontier_v58_guard_rejects")
            fallback = SpotDetection(
                center=base_detection.center,
                bbox=base_detection.bbox,
                confidence=soft_conf,
                label=base_detection.label,
                class_id=base_detection.class_id,
            )
            if self.reporter is not None:
                self.reporter.event(
                    "frontier_v58_guard_rejected",
                    reasons=reasons,
                    visibility_mean=round(visibility_mean, 6),
                    drift_ratio_p95=round(drift_ratio_p95, 6),
                    reject_rate=round(reject_rate, 6),
                    reentry_rate=round(reentry_rate, 6),
                    stability_score=round(stability_score, 6),
                    confidence_before=round(float(candidate_detection.confidence), 6),
                    confidence_after=round(float(fallback.confidence), 6),
                )
            return fallback
        except Exception as exc:
            self._inc_metric("frontier_v58_guard_failures")
            LOGGER.warning("Frontier v58 stability guard failed; bypassing: %s", exc)
            if self.reporter is not None:
                self.reporter.event("frontier_v58_guard_failed", error=str(exc))
            return candidate_detection

    @staticmethod
    def _coerce_xy_point(raw: object) -> Optional[np.ndarray]:
        if not isinstance(raw, (tuple, list)) or len(raw) < 2:
            return None
        try:
            x = float(raw[0])
            y = float(raw[1])
        except Exception:
            return None
        if not np.isfinite(x) or not np.isfinite(y):
            return None
        return np.asarray([x, y], dtype=np.float64)

    def _apply_frontier_v59_consensus_guard(
        self,
        *,
        base_detection: SpotDetection,
        candidate_detection: SpotDetection,
        assoc_result: object,
        visibility_score: float,
        drift_ratio: float,
    ) -> SpotDetection:
        if not self.cfg.frontier_v59_consensus_guard_enabled:
            return candidate_detection
        self._inc_metric("frontier_v59_consensus_checks")
        try:
            candidate_point = np.asarray(
                [float(candidate_detection.center[0]), float(candidate_detection.center[1])],
                dtype=np.float64,
            )
            hypotheses: List[np.ndarray] = [candidate_point]
            for attr_name in ("predicted_center", "consensus_center", "teacher_consensus_center", "persistence_center"):
                point = self._coerce_xy_point(getattr(assoc_result, attr_name, None))
                if point is not None:
                    hypotheses.append(point)
            if len(hypotheses) < 3:
                return candidate_detection

            matrix = np.asarray(hypotheses, dtype=np.float64)
            robust_center = np.median(matrix, axis=0)
            if robust_center.shape != (2,) or not np.all(np.isfinite(robust_center)):
                return candidate_detection

            distances = np.linalg.norm(matrix - robust_center, axis=1)
            if distances.size == 0:
                return candidate_detection
            spread_px = float(np.percentile(distances, 75))
            candidate_dev_px = float(np.linalg.norm(candidate_point - robust_center))

            visibility = float(np.clip(float(visibility_score), 0.0, 1.0))
            drift = max(0.0, float(drift_ratio))
            relax_floor = float(np.clip(float(self.cfg.frontier_v59_visibility_relax_threshold), 0.0, 1.0))
            relax_gain = max(0.0, visibility - relax_floor)
            drift_penalty = max(0.0, drift - 1.0)
            max_dev = max(0.0, float(self.cfg.frontier_v59_max_candidate_deviation_px))
            max_spread = max(0.0, float(self.cfg.frontier_v59_max_hypothesis_spread_px))
            allowed_dev = (max_dev * (1.0 + 1.4 * relax_gain)) / (1.0 + 0.6 * drift_penalty)
            allowed_spread = (max_spread * (1.0 + 1.0 * relax_gain)) / (1.0 + 0.5 * drift_penalty)
            if candidate_dev_px <= allowed_dev and spread_px <= allowed_spread:
                return candidate_detection

            conf_penalty = min(1.0, max(0.0, float(self.cfg.frontier_v59_confidence_penalty)))
            adjusted_conf = float(np.clip(float(candidate_detection.confidence) * conf_penalty, 0.0, 1.0))
            frame_shape = self._last_frame.shape[:2] if self._last_frame is not None else None
            if frame_shape is None:
                return candidate_detection

            robust_center_int = self._clip_center(
                (int(round(float(robust_center[0]))), int(round(float(robust_center[1])))),
                frame_shape,
            )
            refined_bbox = self._recenter_bbox(candidate_detection.bbox, robust_center_int, frame_shape)
            if spread_px <= allowed_spread * 1.25 and candidate_dev_px > allowed_dev:
                self._inc_metric("frontier_v59_consensus_refines")
                refined = SpotDetection(
                    center=robust_center_int,
                    bbox=refined_bbox,
                    confidence=adjusted_conf,
                    label=candidate_detection.label,
                    class_id=candidate_detection.class_id,
                )
                if self.reporter is not None:
                    self.reporter.event(
                        "frontier_v59_consensus_refined",
                        center_before=[int(candidate_detection.center[0]), int(candidate_detection.center[1])],
                        center_after=[int(refined.center[0]), int(refined.center[1])],
                        candidate_deviation_px=round(candidate_dev_px, 6),
                        spread_px=round(spread_px, 6),
                        allowed_dev_px=round(allowed_dev, 6),
                        allowed_spread_px=round(allowed_spread, 6),
                        visibility_score=round(visibility, 6),
                        drift_ratio=round(drift, 6),
                        hypotheses=len(hypotheses),
                    )
                return refined

            self._inc_metric("frontier_v59_consensus_rejects")
            fallback = SpotDetection(
                center=base_detection.center,
                bbox=base_detection.bbox,
                confidence=adjusted_conf,
                label=base_detection.label,
                class_id=base_detection.class_id,
            )
            if self.reporter is not None:
                self.reporter.event(
                    "frontier_v59_consensus_rejected",
                    reason="hypothesis_divergence",
                    candidate_deviation_px=round(candidate_dev_px, 6),
                    spread_px=round(spread_px, 6),
                    allowed_dev_px=round(allowed_dev, 6),
                    allowed_spread_px=round(allowed_spread, 6),
                    visibility_score=round(visibility, 6),
                    drift_ratio=round(drift, 6),
                    hypotheses=len(hypotheses),
                )
            return fallback
        except Exception as exc:
            self._inc_metric("frontier_v59_consensus_failures")
            LOGGER.warning("Frontier v59 consensus guard failed; bypassing: %s", exc)
            if self.reporter is not None:
                self.reporter.event("frontier_v59_consensus_failed", error=str(exc))
            return candidate_detection

    def _apply_frontier_v63_inertia_guard(
        self,
        *,
        base_detection: SpotDetection,
        candidate_detection: SpotDetection,
        visibility_score: float,
        drift_ratio: float,
        persistent_reentry_used: bool,
    ) -> SpotDetection:
        if not self.cfg.frontier_v63_inertia_guard_enabled:
            return candidate_detection
        self._inc_metric("frontier_v63_inertia_checks")
        try:
            base_point = np.asarray(
                [float(base_detection.center[0]), float(base_detection.center[1])],
                dtype=np.float64,
            )
            candidate_point = np.asarray(
                [float(candidate_detection.center[0]), float(candidate_detection.center[1])],
                dtype=np.float64,
            )
            if not np.all(np.isfinite(base_point)) or not np.all(np.isfinite(candidate_point)):
                return candidate_detection

            visibility = float(np.clip(float(visibility_score), 0.0, 1.0))
            drift = max(0.0, float(drift_ratio))
            candidate_shift_px = float(np.linalg.norm(candidate_point - base_point))

            history_shift_px = candidate_shift_px
            if self._frontier_v63_last_committed_center is not None:
                history_shift_px = float(
                    np.linalg.norm(candidate_point - np.asarray(self._frontier_v63_last_committed_center, dtype=np.float64))
                )
            decision_shift_px = max(candidate_shift_px, history_shift_px)

            hit_max = max(1, int(self.cfg.frontier_v63_hit_counter_max))
            init_delay = max(0, min(hit_max - 1, int(self.cfg.frontier_v63_initialization_delay)))
            point_hit_max = max(1, int(self.cfg.frontier_v63_pointwise_hit_counter_max))
            memory_frames = max(0, int(self.cfg.frontier_v63_memory_frames))
            base_distance_px = max(0.5, float(self.cfg.frontier_v63_base_distance_px))
            relax_floor = float(np.clip(float(self.cfg.frontier_v63_visibility_relax_threshold), 0.0, 1.0))
            visibility_relax = max(0.0, visibility - relax_floor)
            drift_penalty = max(0.0, drift - 1.0)

            inertia = float(np.clip(self._frontier_v63_hit_counter / float(hit_max), 0.0, 1.0))
            point_inertia = float(np.clip(self._frontier_v63_point_hit_counter / float(point_hit_max), 0.0, 1.0))
            inertia_mix = 0.5 * (inertia + point_inertia)
            allowed_shift_px = (
                base_distance_px
                * (
                    1.0
                    + float(self.cfg.frontier_v63_visibility_relax_gain) * visibility_relax
                    + float(self.cfg.frontier_v63_inertia_relax_gain) * inertia_mix
                )
            ) / (1.0 + 0.65 * drift_penalty)
            allowed_shift_px = max(0.5, float(allowed_shift_px))
            warmup_mode = self._frontier_v63_hit_counter < float(init_delay)

            if decision_shift_px <= allowed_shift_px or warmup_mode:
                boosted_conf = float(
                    np.clip(
                        float(candidate_detection.confidence) * float(self.cfg.frontier_v63_confidence_boost),
                        0.0,
                        1.0,
                    )
                )
                accepted = SpotDetection(
                    center=candidate_detection.center,
                    bbox=candidate_detection.bbox,
                    confidence=boosted_conf,
                    label=candidate_detection.label,
                    class_id=candidate_detection.class_id,
                )
                self._frontier_v63_hit_counter = min(float(hit_max), self._frontier_v63_hit_counter + 1.0)
                self._frontier_v63_point_hit_counter = min(
                    float(point_hit_max),
                    self._frontier_v63_point_hit_counter + (0.8 if persistent_reentry_used else 1.0),
                )
                self._frontier_v63_miss_streak = 0
                self._frontier_v63_last_committed_center = candidate_point.copy()
                if boosted_conf != float(candidate_detection.confidence):
                    self._inc_metric("frontier_v63_inertia_refines")
                if self.reporter is not None and (warmup_mode or decision_shift_px > candidate_shift_px + 1e-6):
                    self.reporter.event(
                        "frontier_v63_inertia_accept",
                        warmup_mode=warmup_mode,
                        candidate_shift_px=round(candidate_shift_px, 6),
                        history_shift_px=round(history_shift_px, 6),
                        decision_shift_px=round(decision_shift_px, 6),
                        allowed_shift_px=round(allowed_shift_px, 6),
                        visibility_score=round(visibility, 6),
                        drift_ratio=round(drift, 6),
                        hit_counter=round(float(self._frontier_v63_hit_counter), 6),
                        point_hit_counter=round(float(self._frontier_v63_point_hit_counter), 6),
                    )
                return accepted

            self._frontier_v63_miss_streak += 1
            self._frontier_v63_hit_counter = max(0.0, self._frontier_v63_hit_counter - 1.0)
            self._frontier_v63_point_hit_counter = max(0.0, self._frontier_v63_point_hit_counter - 1.0)

            confidence_penalty = float(np.clip(float(self.cfg.frontier_v63_confidence_penalty), 0.0, 1.0))
            if self._frontier_v63_miss_streak <= memory_frames and visibility >= relax_floor:
                self._inc_metric("frontier_v63_inertia_memory_rescues")
                blended = np.asarray(
                    [
                        0.7 * float(base_point[0]) + 0.3 * float(candidate_point[0]),
                        0.7 * float(base_point[1]) + 0.3 * float(candidate_point[1]),
                    ],
                    dtype=np.float64,
                )
                frame_shape = self._last_frame.shape[:2] if self._last_frame is not None else None
                if frame_shape is not None:
                    blended_center = self._clip_center(
                        (int(round(float(blended[0]))), int(round(float(blended[1])))),
                        frame_shape,
                    )
                    blended_bbox = self._recenter_bbox(base_detection.bbox, blended_center, frame_shape)
                else:
                    blended_center = (
                        int(round(float(blended[0]))),
                        int(round(float(blended[1]))),
                    )
                    blended_bbox = base_detection.bbox
                rescued = SpotDetection(
                    center=blended_center,
                    bbox=blended_bbox,
                    confidence=float(np.clip(float(candidate_detection.confidence) * confidence_penalty, 0.0, 1.0)),
                    label=base_detection.label,
                    class_id=base_detection.class_id,
                )
                self._frontier_v63_last_committed_center = np.asarray(
                    [float(blended_center[0]), float(blended_center[1])],
                    dtype=np.float64,
                )
                if self.reporter is not None:
                    self.reporter.event(
                        "frontier_v63_inertia_memory_rescue",
                        miss_streak=int(self._frontier_v63_miss_streak),
                        memory_frames=int(memory_frames),
                        candidate_shift_px=round(candidate_shift_px, 6),
                        history_shift_px=round(history_shift_px, 6),
                        decision_shift_px=round(decision_shift_px, 6),
                        allowed_shift_px=round(allowed_shift_px, 6),
                        visibility_score=round(visibility, 6),
                        drift_ratio=round(drift, 6),
                    )
                return rescued

            self._inc_metric("frontier_v63_inertia_rejects")
            fallback = SpotDetection(
                center=base_detection.center,
                bbox=base_detection.bbox,
                confidence=float(np.clip(float(base_detection.confidence) * confidence_penalty, 0.0, 1.0)),
                label=base_detection.label,
                class_id=base_detection.class_id,
            )
            if self.reporter is not None:
                self.reporter.event(
                    "frontier_v63_inertia_rejected",
                    miss_streak=int(self._frontier_v63_miss_streak),
                    candidate_shift_px=round(candidate_shift_px, 6),
                    history_shift_px=round(history_shift_px, 6),
                    decision_shift_px=round(decision_shift_px, 6),
                    allowed_shift_px=round(allowed_shift_px, 6),
                    visibility_score=round(visibility, 6),
                    drift_ratio=round(drift, 6),
                )
            return fallback
        except Exception as exc:
            self._inc_metric("frontier_v63_inertia_failures")
            LOGGER.warning("Frontier v63 inertia-memory guard failed; bypassing: %s", exc)
            if self.reporter is not None:
                self.reporter.event("frontier_v63_inertia_failed", error=str(exc))
            return candidate_detection

    def _apply_frontier_v64_adaptive_budget_guard(
        self,
        *,
        base_detection: SpotDetection,
        candidate_detection: SpotDetection,
        visibility_score: float,
        drift_ratio: float,
    ) -> SpotDetection:
        if not self.cfg.frontier_v64_adaptive_budget_guard_enabled:
            return candidate_detection
        self._inc_metric("frontier_v64_adaptive_checks")
        try:
            base_point = np.asarray(
                [float(base_detection.center[0]), float(base_detection.center[1])],
                dtype=np.float64,
            )
            candidate_point = np.asarray(
                [float(candidate_detection.center[0]), float(candidate_detection.center[1])],
                dtype=np.float64,
            )
            if not np.all(np.isfinite(base_point)) or not np.all(np.isfinite(candidate_point)):
                return candidate_detection

            shift_px = float(np.linalg.norm(candidate_point - base_point))
            self._frontier_v64_shift_history.append(shift_px)

            history = np.asarray(self._frontier_v64_shift_history, dtype=np.float64)
            history_std = float(np.std(history)) if history.size >= 2 else 0.0
            history_q80 = float(np.percentile(history, 80)) if history.size >= 1 else shift_px
            visibility = float(np.clip(float(visibility_score), 0.0, 1.0))
            drift = max(0.0, float(drift_ratio))

            base_gate = max(0.5, float(self.cfg.frontier_v64_base_gate_px))
            adaptive_stop = max(0.5, float(self.cfg.frontier_v64_adaptive_stop_px))
            adaptive_step = float(np.clip(float(self.cfg.frontier_v64_adaptive_step), 0.2, 0.99))
            max_iters = max(1, int(self.cfg.frontier_v64_max_iters))
            jitter_gain = max(0.0, float(self.cfg.frontier_v64_jitter_gain))

            relax_floor = float(np.clip(float(self.cfg.frontier_v64_visibility_relax_threshold), 0.0, 1.0))
            visibility_relax = max(0.0, visibility - relax_floor)
            reject_pressure = min(1.0, float(self._frontier_v64_reject_streak) / float(max(1, max_iters)))
            drift_penalty = max(0.0, drift - 1.0)

            relaxed_gate = base_gate + jitter_gain * max(history_std, history_q80 * 0.15)
            relaxed_gate *= (
                1.0
                + float(self.cfg.frontier_v64_visibility_relax_gain) * visibility_relax
                + float(self.cfg.frontier_v64_reject_relax_gain) * reject_pressure
            )
            relaxed_gate /= 1.0 + float(self.cfg.frontier_v64_drift_penalty_gain) * drift_penalty
            relaxed_gate = max(adaptive_stop, float(relaxed_gate))

            chosen_iter = 0
            allowed_gate = relaxed_gate
            matched = False
            for iter_idx in range(max_iters):
                gate = max(adaptive_stop, relaxed_gate * (adaptive_step ** iter_idx))
                chosen_iter = iter_idx
                allowed_gate = gate
                if shift_px <= gate:
                    matched = True
                    break

            if matched:
                confidence_scale = (
                    float(self.cfg.frontier_v64_confidence_boost)
                    if chosen_iter == 0
                    else float(self.cfg.frontier_v64_confidence_penalty)
                )
                adjusted_conf = float(np.clip(float(candidate_detection.confidence) * confidence_scale, 0.0, 1.0))
                accepted = SpotDetection(
                    center=candidate_detection.center,
                    bbox=candidate_detection.bbox,
                    confidence=adjusted_conf,
                    label=candidate_detection.label,
                    class_id=candidate_detection.class_id,
                )
                if chosen_iter > 0:
                    self._inc_metric("frontier_v64_adaptive_refines")
                else:
                    self._inc_metric("frontier_v64_adaptive_soft_accepts")
                self._frontier_v64_reject_streak = max(0, self._frontier_v64_reject_streak - 1)
                if self.reporter is not None and chosen_iter > 0:
                    self.reporter.event(
                        "frontier_v64_adaptive_refined",
                        shift_px=round(shift_px, 6),
                        allowed_gate_px=round(allowed_gate, 6),
                        relaxed_gate_px=round(relaxed_gate, 6),
                        iter_index=int(chosen_iter),
                        max_iters=int(max_iters),
                        visibility_score=round(visibility, 6),
                        drift_ratio=round(drift, 6),
                        history_std_px=round(history_std, 6),
                        reject_streak=int(self._frontier_v64_reject_streak),
                    )
                return accepted

            self._inc_metric("frontier_v64_adaptive_rejects")
            self._frontier_v64_reject_streak = min(max_iters * 3, self._frontier_v64_reject_streak + 1)
            adjusted_conf = float(
                np.clip(
                    float(base_detection.confidence) * float(np.clip(float(self.cfg.frontier_v64_confidence_penalty), 0.0, 1.0)),
                    0.0,
                    1.0,
                )
            )
            fallback = SpotDetection(
                center=base_detection.center,
                bbox=base_detection.bbox,
                confidence=adjusted_conf,
                label=base_detection.label,
                class_id=base_detection.class_id,
            )
            if self.reporter is not None:
                self.reporter.event(
                    "frontier_v64_adaptive_rejected",
                    reason="adaptive_gate_exhausted",
                    shift_px=round(shift_px, 6),
                    allowed_gate_px=round(allowed_gate, 6),
                    relaxed_gate_px=round(relaxed_gate, 6),
                    max_iters=int(max_iters),
                    visibility_score=round(visibility, 6),
                    drift_ratio=round(drift, 6),
                    history_std_px=round(history_std, 6),
                    history_q80_px=round(history_q80, 6),
                    reject_streak=int(self._frontier_v64_reject_streak),
                )
            return fallback
        except Exception as exc:
            self._inc_metric("frontier_v64_adaptive_failures")
            LOGGER.warning("Frontier v64 adaptive-budget guard failed; bypassing: %s", exc)
            if self.reporter is not None:
                self.reporter.event("frontier_v64_adaptive_failed", error=str(exc))
            return candidate_detection

    def _apply_frontier_v65_trajectory_guard(
        self,
        *,
        base_detection: SpotDetection,
        candidate_detection: SpotDetection,
        visibility_score: float,
        drift_ratio: float,
    ) -> SpotDetection:
        if not self.cfg.frontier_v65_trajectory_guard_enabled:
            return candidate_detection
        self._inc_metric("frontier_v65_guard_checks")
        try:
            base_point = np.asarray(
                [float(base_detection.center[0]), float(base_detection.center[1])],
                dtype=np.float64,
            )
            candidate_point = np.asarray(
                [float(candidate_detection.center[0]), float(candidate_detection.center[1])],
                dtype=np.float64,
            )
            if not np.all(np.isfinite(base_point)) or not np.all(np.isfinite(candidate_point)):
                return candidate_detection

            visibility = float(np.clip(float(visibility_score), 0.0, 1.0))
            drift = max(0.0, float(drift_ratio))
            history = self._frontier_v65_center_history

            def _append_center(center: Tuple[int, int]) -> None:
                history.append(np.asarray([float(center[0]), float(center[1])], dtype=np.float64))

            if len(history) < 2:
                warmup_conf = float(
                    np.clip(
                        float(candidate_detection.confidence) * float(self.cfg.frontier_v65_confidence_boost),
                        0.0,
                        1.0,
                    )
                )
                warmup_detection = SpotDetection(
                    center=candidate_detection.center,
                    bbox=candidate_detection.bbox,
                    confidence=warmup_conf,
                    label=candidate_detection.label,
                    class_id=candidate_detection.class_id,
                )
                self._inc_metric("frontier_v65_guard_soft_accepts")
                self._frontier_v65_reject_streak = max(0, self._frontier_v65_reject_streak - 1)
                _append_center(warmup_detection.center)
                return warmup_detection

            hist_arr = np.asarray(tuple(history), dtype=np.float64)
            if hist_arr.ndim != 2 or hist_arr.shape[1] != 2:
                self._frontier_v65_center_history = deque(maxlen=max(4, int(self.cfg.frontier_v65_history_size)))
                _append_center(candidate_detection.center)
                return candidate_detection

            last_point = hist_arr[-1]
            prev_point = hist_arr[-2]
            candidate_step = float(np.linalg.norm(candidate_point - last_point))
            last_step = float(np.linalg.norm(last_point - prev_point))

            step_history = np.linalg.norm(np.diff(hist_arr, axis=0), axis=1) if hist_arr.shape[0] >= 3 else np.asarray([], dtype=np.float64)
            step_p80 = float(np.percentile(step_history, 80)) if step_history.size >= 1 else last_step
            step_med = float(np.median(step_history)) if step_history.size >= 1 else last_step
            base_step = max(1.0, last_step, step_med, step_p80 * 0.8)

            relax_floor = float(np.clip(float(self.cfg.frontier_v65_visibility_relax_threshold), 0.0, 1.0))
            visibility_relax = max(0.0, visibility - relax_floor)
            reject_den = max(1, int(self.cfg.frontier_v65_history_size) // 2)
            reject_pressure = min(1.0, float(self._frontier_v65_reject_streak) / float(reject_den))
            drift_penalty = max(0.0, drift - 1.0)

            step_scale = max(
                1.0,
                float(self.cfg.frontier_v65_max_step_scale)
                * (
                    1.0
                    + float(self.cfg.frontier_v65_visibility_relax_gain) * visibility_relax
                    + 0.18 * reject_pressure
                ),
            )
            allowed_step = base_step * step_scale
            allowed_step = allowed_step / (1.0 + 0.35 * drift_penalty)
            allowed_step = max(0.8, float(allowed_step))

            allowed_accel = max(
                0.5,
                float(self.cfg.frontier_v65_max_accel_px)
                * (
                    1.0
                    + 0.6 * float(self.cfg.frontier_v65_visibility_relax_gain) * visibility_relax
                    + 0.25 * reject_pressure
                )
                / (1.0 + 0.35 * drift_penalty),
            )
            accel = abs(candidate_step - last_step)

            if candidate_step <= allowed_step and accel <= allowed_accel:
                accepted_conf = float(
                    np.clip(
                        float(candidate_detection.confidence) * float(self.cfg.frontier_v65_confidence_boost),
                        0.0,
                        1.0,
                    )
                )
                accepted = SpotDetection(
                    center=candidate_detection.center,
                    bbox=candidate_detection.bbox,
                    confidence=accepted_conf,
                    label=candidate_detection.label,
                    class_id=candidate_detection.class_id,
                )
                self._inc_metric("frontier_v65_guard_soft_accepts")
                self._frontier_v65_reject_streak = max(0, self._frontier_v65_reject_streak - 1)
                _append_center(accepted.center)
                return accepted

            predicted_point = last_point + (last_point - prev_point)
            blended = (0.65 * predicted_point + 0.35 * candidate_point).astype(np.float64)
            if not np.all(np.isfinite(blended)):
                blended = candidate_point.copy()
            blended_step = float(np.linalg.norm(blended - last_point))
            blended_accel = abs(blended_step - last_step)
            frame_shape = self._last_frame.shape[:2] if self._last_frame is not None else None
            if frame_shape is not None:
                blended_center = self._clip_center(
                    (int(round(float(blended[0]))), int(round(float(blended[1])))),
                    frame_shape,
                )
                blended_bbox = self._recenter_bbox(base_detection.bbox, blended_center, frame_shape)
            else:
                blended_center = (int(round(float(blended[0]))), int(round(float(blended[1]))))
                blended_bbox = candidate_detection.bbox

            confidence_penalty = float(np.clip(float(self.cfg.frontier_v65_confidence_penalty), 0.0, 1.0))
            if blended_step <= allowed_step and blended_accel <= allowed_accel * 1.15:
                refined = SpotDetection(
                    center=blended_center,
                    bbox=blended_bbox,
                    confidence=float(np.clip(float(candidate_detection.confidence) * confidence_penalty, 0.0, 1.0)),
                    label=candidate_detection.label,
                    class_id=candidate_detection.class_id,
                )
                self._inc_metric("frontier_v65_guard_refines")
                self._frontier_v65_reject_streak = max(0, self._frontier_v65_reject_streak - 1)
                _append_center(refined.center)
                if self.reporter is not None:
                    self.reporter.event(
                        "frontier_v65_trajectory_refined",
                        candidate_step_px=round(candidate_step, 6),
                        blended_step_px=round(blended_step, 6),
                        allowed_step_px=round(allowed_step, 6),
                        accel_px=round(accel, 6),
                        blended_accel_px=round(blended_accel, 6),
                        allowed_accel_px=round(allowed_accel, 6),
                        visibility_score=round(visibility, 6),
                        drift_ratio=round(drift, 6),
                    )
                return refined

            self._inc_metric("frontier_v65_guard_rejects")
            self._frontier_v65_reject_streak = min(
                max(2, int(self.cfg.frontier_v65_history_size) * 2),
                self._frontier_v65_reject_streak + 1,
            )
            fallback = SpotDetection(
                center=base_detection.center,
                bbox=base_detection.bbox,
                confidence=float(np.clip(float(base_detection.confidence) * confidence_penalty, 0.0, 1.0)),
                label=base_detection.label,
                class_id=base_detection.class_id,
            )
            _append_center(fallback.center)
            if self.reporter is not None:
                self.reporter.event(
                    "frontier_v65_trajectory_rejected",
                    reason="step_or_accel_limit_exceeded",
                    candidate_step_px=round(candidate_step, 6),
                    allowed_step_px=round(allowed_step, 6),
                    accel_px=round(accel, 6),
                    allowed_accel_px=round(allowed_accel, 6),
                    visibility_score=round(visibility, 6),
                    drift_ratio=round(drift, 6),
                    reject_streak=int(self._frontier_v65_reject_streak),
                )
            return fallback
        except Exception as exc:
            self._inc_metric("frontier_v65_guard_failures")
            LOGGER.warning("Frontier v65 trajectory guard failed; bypassing: %s", exc)
            if self.reporter is not None:
                self.reporter.event("frontier_v65_trajectory_failed", error=str(exc))
            return candidate_detection

    def _apply_frontier_v66_curvature_guard(
        self,
        *,
        base_detection: SpotDetection,
        candidate_detection: SpotDetection,
        visibility_score: float,
        drift_ratio: float,
    ) -> SpotDetection:
        if not self.cfg.frontier_v66_curvature_guard_enabled:
            return candidate_detection
        self._inc_metric("frontier_v66_guard_checks")
        try:
            base_point = np.asarray(
                [float(base_detection.center[0]), float(base_detection.center[1])],
                dtype=np.float64,
            )
            candidate_point = np.asarray(
                [float(candidate_detection.center[0]), float(candidate_detection.center[1])],
                dtype=np.float64,
            )
            if not np.all(np.isfinite(base_point)) or not np.all(np.isfinite(candidate_point)):
                return candidate_detection

            visibility = float(np.clip(float(visibility_score), 0.0, 1.0))
            drift = max(0.0, float(drift_ratio))
            history = self._frontier_v66_center_history

            def _append_center(center: Tuple[int, int]) -> None:
                history.append(np.asarray([float(center[0]), float(center[1])], dtype=np.float64))

            if len(history) < 3:
                warmup_conf = float(
                    np.clip(
                        float(candidate_detection.confidence) * float(self.cfg.frontier_v66_confidence_boost),
                        0.0,
                        1.0,
                    )
                )
                warmup_detection = SpotDetection(
                    center=candidate_detection.center,
                    bbox=candidate_detection.bbox,
                    confidence=warmup_conf,
                    label=candidate_detection.label,
                    class_id=candidate_detection.class_id,
                )
                self._inc_metric("frontier_v66_guard_soft_accepts")
                self._frontier_v66_reject_streak = max(0, self._frontier_v66_reject_streak - 1)
                _append_center(warmup_detection.center)
                return warmup_detection

            hist_arr = np.asarray(tuple(history), dtype=np.float64)
            if hist_arr.ndim != 2 or hist_arr.shape[1] != 2:
                self._frontier_v66_center_history = deque(maxlen=max(5, int(self.cfg.frontier_v66_history_size)))
                _append_center(candidate_detection.center)
                return candidate_detection

            last_point = hist_arr[-1]
            prev_point = hist_arr[-2]
            prev2_point = hist_arr[-3]

            prev_vec = last_point - prev_point
            prev2_vec = prev_point - prev2_point
            cand_vec = candidate_point - last_point

            prev_step = float(np.linalg.norm(prev_vec))
            prev2_step = float(np.linalg.norm(prev2_vec))
            candidate_step = float(np.linalg.norm(cand_vec))

            candidate_accel = candidate_step - prev_step
            prev_accel = prev_step - prev2_step
            jerk = abs(candidate_accel - prev_accel)

            if prev_step > 1e-6 and candidate_step > 1e-6:
                cos_val = float(np.dot(cand_vec, prev_vec) / (candidate_step * prev_step))
                cos_val = float(np.clip(cos_val, -1.0, 1.0))
                turn_deg = float(math.degrees(math.acos(cos_val)))
            else:
                turn_deg = 0.0

            predicted = last_point + prev_vec + 0.5 * (prev_vec - prev2_vec)
            if not np.all(np.isfinite(predicted)):
                predicted = last_point + prev_vec
            residual = float(np.linalg.norm(candidate_point - predicted))

            relax_floor = float(np.clip(float(self.cfg.frontier_v66_visibility_relax_threshold), 0.0, 1.0))
            visibility_relax = max(0.0, visibility - relax_floor)
            reject_den = max(1, int(self.cfg.frontier_v66_history_size) // 2)
            reject_pressure = min(1.0, float(self._frontier_v66_reject_streak) / float(reject_den))
            drift_penalty = max(0.0, drift - 1.0)
            relax_gain = max(0.0, float(self.cfg.frontier_v66_visibility_relax_gain))
            relax_scale = (1.0 + relax_gain * visibility_relax + 0.20 * reject_pressure) / (1.0 + 0.30 * drift_penalty)

            allowed_turn_deg = max(
                4.0,
                min(
                    179.0,
                    float(self.cfg.frontier_v66_max_turn_deg) * (1.0 + 0.60 * relax_gain * visibility_relax + 0.18 * reject_pressure),
                ),
            )
            allowed_jerk_px = max(0.25, float(self.cfg.frontier_v66_max_jerk_px) * relax_scale)
            allowed_residual_px = max(0.5, float(self.cfg.frontier_v66_max_residual_px) * relax_scale)

            if turn_deg <= allowed_turn_deg and jerk <= allowed_jerk_px and residual <= allowed_residual_px:
                accepted_conf = float(
                    np.clip(
                        float(candidate_detection.confidence) * float(self.cfg.frontier_v66_confidence_boost),
                        0.0,
                        1.0,
                    )
                )
                accepted = SpotDetection(
                    center=candidate_detection.center,
                    bbox=candidate_detection.bbox,
                    confidence=accepted_conf,
                    label=candidate_detection.label,
                    class_id=candidate_detection.class_id,
                )
                self._inc_metric("frontier_v66_guard_soft_accepts")
                self._frontier_v66_reject_streak = max(0, self._frontier_v66_reject_streak - 1)
                _append_center(accepted.center)
                return accepted

            blend = (0.68 * predicted + 0.32 * candidate_point).astype(np.float64)
            if not np.all(np.isfinite(blend)):
                blend = candidate_point.copy()
            blend_step = float(np.linalg.norm(blend - last_point))
            blend_accel = blend_step - prev_step
            blend_jerk = abs(blend_accel - prev_accel)
            blend_vec = blend - last_point
            blend_turn_deg = 0.0
            if prev_step > 1e-6 and blend_step > 1e-6:
                blend_cos = float(np.dot(blend_vec, prev_vec) / (blend_step * prev_step))
                blend_cos = float(np.clip(blend_cos, -1.0, 1.0))
                blend_turn_deg = float(math.degrees(math.acos(blend_cos)))
            blend_residual = float(np.linalg.norm(blend - predicted))

            frame_shape = self._last_frame.shape[:2] if self._last_frame is not None else None
            if frame_shape is not None:
                blend_center = self._clip_center(
                    (int(round(float(blend[0]))), int(round(float(blend[1])))),
                    frame_shape,
                )
                blend_bbox = self._recenter_bbox(base_detection.bbox, blend_center, frame_shape)
            else:
                blend_center = (int(round(float(blend[0]))), int(round(float(blend[1]))))
                blend_bbox = candidate_detection.bbox

            confidence_penalty = float(np.clip(float(self.cfg.frontier_v66_confidence_penalty), 0.0, 1.0))
            if (
                blend_turn_deg <= allowed_turn_deg * 1.10
                and blend_jerk <= allowed_jerk_px * 1.15
                and blend_residual <= allowed_residual_px * 1.15
            ):
                refined = SpotDetection(
                    center=blend_center,
                    bbox=blend_bbox,
                    confidence=float(np.clip(float(candidate_detection.confidence) * confidence_penalty, 0.0, 1.0)),
                    label=candidate_detection.label,
                    class_id=candidate_detection.class_id,
                )
                self._inc_metric("frontier_v66_guard_refines")
                self._frontier_v66_reject_streak = max(0, self._frontier_v66_reject_streak - 1)
                _append_center(refined.center)
                if self.reporter is not None:
                    self.reporter.event(
                        "frontier_v66_curvature_refined",
                        turn_deg=round(turn_deg, 6),
                        blend_turn_deg=round(blend_turn_deg, 6),
                        allowed_turn_deg=round(allowed_turn_deg, 6),
                        jerk_px=round(jerk, 6),
                        blend_jerk_px=round(blend_jerk, 6),
                        allowed_jerk_px=round(allowed_jerk_px, 6),
                        residual_px=round(residual, 6),
                        blend_residual_px=round(blend_residual, 6),
                        allowed_residual_px=round(allowed_residual_px, 6),
                        visibility_score=round(visibility, 6),
                        drift_ratio=round(drift, 6),
                    )
                return refined

            self._inc_metric("frontier_v66_guard_rejects")
            self._frontier_v66_reject_streak = min(
                max(2, int(self.cfg.frontier_v66_history_size) * 2),
                self._frontier_v66_reject_streak + 1,
            )
            fallback = SpotDetection(
                center=base_detection.center,
                bbox=base_detection.bbox,
                confidence=float(np.clip(float(base_detection.confidence) * confidence_penalty, 0.0, 1.0)),
                label=base_detection.label,
                class_id=base_detection.class_id,
            )
            _append_center(fallback.center)
            if self.reporter is not None:
                self.reporter.event(
                    "frontier_v66_curvature_rejected",
                    reason="curvature_or_jerk_or_residual_exceeded",
                    turn_deg=round(turn_deg, 6),
                    allowed_turn_deg=round(allowed_turn_deg, 6),
                    jerk_px=round(jerk, 6),
                    allowed_jerk_px=round(allowed_jerk_px, 6),
                    residual_px=round(residual, 6),
                    allowed_residual_px=round(allowed_residual_px, 6),
                    visibility_score=round(visibility, 6),
                    drift_ratio=round(drift, 6),
                    reject_streak=int(self._frontier_v66_reject_streak),
                )
            return fallback
        except Exception as exc:
            self._inc_metric("frontier_v66_guard_failures")
            LOGGER.warning("Frontier v66 curvature guard failed; bypassing: %s", exc)
            if self.reporter is not None:
                self.reporter.event("frontier_v66_curvature_failed", error=str(exc))
            return candidate_detection

    def _apply_frontier_v67_adaptive_search_guard(
        self,
        *,
        base_detection: SpotDetection,
        candidate_detection: SpotDetection,
        visibility_score: float,
        drift_ratio: float,
    ) -> SpotDetection:
        if not self.cfg.frontier_v67_adaptive_search_guard_enabled:
            return candidate_detection
        self._inc_metric("frontier_v67_guard_checks")
        try:
            base_point = np.asarray(
                [float(base_detection.center[0]), float(base_detection.center[1])],
                dtype=np.float64,
            )
            candidate_point = np.asarray(
                [float(candidate_detection.center[0]), float(candidate_detection.center[1])],
                dtype=np.float64,
            )
            if not np.all(np.isfinite(base_point)) or not np.all(np.isfinite(candidate_point)):
                return candidate_detection

            visibility = float(np.clip(float(visibility_score), 0.0, 1.0))
            drift = max(0.0, float(drift_ratio))
            history = self._frontier_v67_center_history
            hit_counter_max = max(1, int(self.cfg.frontier_v67_hit_counter_max))
            pointwise_hit_counter_max = max(1, int(self.cfg.frontier_v67_pointwise_hit_counter_max))
            init_delay = max(0, int(self.cfg.frontier_v67_initialization_delay))

            def _append_center(center: Tuple[int, int]) -> None:
                history.append(np.asarray([float(center[0]), float(center[1])], dtype=np.float64))

            def _update_hit_counter(delta: float) -> None:
                self._frontier_v67_hit_counter = float(
                    np.clip(
                        float(self._frontier_v67_hit_counter) + float(delta),
                        -float(pointwise_hit_counter_max),
                        float(hit_counter_max),
                    )
                )

            if len(history) < 2:
                warmup_conf = float(
                    np.clip(
                        float(candidate_detection.confidence) * float(self.cfg.frontier_v67_confidence_boost),
                        0.0,
                        1.0,
                    )
                )
                warmup_detection = SpotDetection(
                    center=candidate_detection.center,
                    bbox=candidate_detection.bbox,
                    confidence=warmup_conf,
                    label=candidate_detection.label,
                    class_id=candidate_detection.class_id,
                )
                self._inc_metric("frontier_v67_guard_soft_accepts")
                self._frontier_v67_reject_streak = max(0, self._frontier_v67_reject_streak - 1)
                _update_hit_counter(1.0)
                _append_center(warmup_detection.center)
                return warmup_detection

            hist_arr = np.asarray(tuple(history), dtype=np.float64)
            if hist_arr.ndim != 2 or hist_arr.shape[1] != 2:
                self._frontier_v67_center_history = deque(maxlen=max(5, int(self.cfg.frontier_v67_history_size)))
                _append_center(candidate_detection.center)
                return candidate_detection

            last_point = hist_arr[-1]
            prev_point = hist_arr[-2]
            predicted = last_point + (last_point - prev_point)
            if not np.all(np.isfinite(predicted)):
                predicted = last_point.copy()

            residual = float(np.linalg.norm(candidate_point - predicted))
            relax_floor = float(np.clip(float(self.cfg.frontier_v67_visibility_relax_threshold), 0.0, 1.0))
            visibility_relax = max(0.0, visibility - relax_floor)
            reject_den = max(1, int(self.cfg.frontier_v67_history_size) // 2)
            reject_pressure = min(1.0, float(self._frontier_v67_reject_streak) / float(reject_den))
            hit_pressure = min(1.0, max(0.0, float(self._frontier_v67_hit_counter)) / float(hit_counter_max))
            drift_penalty = max(0.0, drift - 1.0)
            visibility_gain = max(0.0, float(self.cfg.frontier_v67_visibility_relax_gain))
            in_init_phase = float(self._frontier_v67_hit_counter) < float(init_delay)

            base_gate = max(0.25, float(self.cfg.frontier_v67_base_gate_px))
            adaptive_stop = max(0.25, float(self.cfg.frontier_v67_adaptive_stop_px))
            search_gate = (
                base_gate
                * (
                    1.0
                    + visibility_gain * visibility_relax
                    + 0.20 * reject_pressure
                    + 0.08 * (1.0 - hit_pressure)
                )
                / (1.0 + 0.28 * drift_penalty)
            )
            if in_init_phase:
                search_gate *= 1.15
            search_gate = max(adaptive_stop, float(search_gate))

            adaptive_step = float(np.clip(float(self.cfg.frontier_v67_adaptive_step), 0.05, 0.99))
            max_iters = max(1, int(self.cfg.frontier_v67_max_iters))
            adaptive_iters = 0
            while residual > search_gate and search_gate > adaptive_stop and adaptive_iters < max_iters:
                search_gate = max(adaptive_stop, search_gate * adaptive_step)
                adaptive_iters += 1

            if residual <= search_gate:
                accepted_conf = float(
                    np.clip(
                        float(candidate_detection.confidence) * float(self.cfg.frontier_v67_confidence_boost),
                        0.0,
                        1.0,
                    )
                )
                accepted = SpotDetection(
                    center=candidate_detection.center,
                    bbox=candidate_detection.bbox,
                    confidence=accepted_conf,
                    label=candidate_detection.label,
                    class_id=candidate_detection.class_id,
                )
                self._inc_metric("frontier_v67_guard_soft_accepts")
                self._frontier_v67_reject_streak = max(0, self._frontier_v67_reject_streak - 1)
                _update_hit_counter(1.0)
                _append_center(accepted.center)
                if self.reporter is not None and adaptive_iters > 0:
                    self.reporter.event(
                        "frontier_v67_adaptive_soft_accept",
                        residual_px=round(residual, 6),
                        search_gate_px=round(search_gate, 6),
                        adaptive_iters=int(adaptive_iters),
                        visibility_score=round(visibility, 6),
                        drift_ratio=round(drift, 6),
                        hit_counter=round(float(self._frontier_v67_hit_counter), 6),
                    )
                return accepted

            blend_ratio = float(np.clip(search_gate / max(residual, 1e-6), 0.18, 0.78))
            blended = predicted + blend_ratio * (candidate_point - predicted)
            if not np.all(np.isfinite(blended)):
                blended = candidate_point.copy()
            blended_residual = float(np.linalg.norm(blended - predicted))

            frame_shape = self._last_frame.shape[:2] if self._last_frame is not None else None
            if frame_shape is not None:
                blended_center = self._clip_center(
                    (int(round(float(blended[0]))), int(round(float(blended[1])))),
                    frame_shape,
                )
                blended_bbox = self._recenter_bbox(base_detection.bbox, blended_center, frame_shape)
            else:
                blended_center = (int(round(float(blended[0]))), int(round(float(blended[1]))))
                blended_bbox = candidate_detection.bbox

            confidence_penalty = float(np.clip(float(self.cfg.frontier_v67_confidence_penalty), 0.0, 1.0))
            if blended_residual <= max(search_gate * 1.10, adaptive_stop):
                refined = SpotDetection(
                    center=blended_center,
                    bbox=blended_bbox,
                    confidence=float(np.clip(float(candidate_detection.confidence) * confidence_penalty, 0.0, 1.0)),
                    label=candidate_detection.label,
                    class_id=candidate_detection.class_id,
                )
                self._inc_metric("frontier_v67_guard_refines")
                self._frontier_v67_reject_streak = max(0, self._frontier_v67_reject_streak - 1)
                _update_hit_counter(0.5)
                _append_center(refined.center)
                if self.reporter is not None:
                    self.reporter.event(
                        "frontier_v67_adaptive_refined",
                        residual_px=round(residual, 6),
                        blended_residual_px=round(blended_residual, 6),
                        search_gate_px=round(search_gate, 6),
                        adaptive_iters=int(adaptive_iters),
                        blend_ratio=round(blend_ratio, 6),
                        visibility_score=round(visibility, 6),
                        drift_ratio=round(drift, 6),
                        hit_counter=round(float(self._frontier_v67_hit_counter), 6),
                    )
                return refined

            self._inc_metric("frontier_v67_guard_rejects")
            self._frontier_v67_reject_streak = min(
                max(2, int(self.cfg.frontier_v67_history_size) * 2),
                self._frontier_v67_reject_streak + 1,
            )
            _update_hit_counter(-1.0)
            fallback = SpotDetection(
                center=base_detection.center,
                bbox=base_detection.bbox,
                confidence=float(np.clip(float(base_detection.confidence) * confidence_penalty, 0.0, 1.0)),
                label=base_detection.label,
                class_id=base_detection.class_id,
            )
            _append_center(fallback.center)
            if self.reporter is not None:
                self.reporter.event(
                    "frontier_v67_adaptive_rejected",
                    reason="adaptive_search_residual_exceeded",
                    residual_px=round(residual, 6),
                    search_gate_px=round(search_gate, 6),
                    adaptive_iters=int(adaptive_iters),
                    visibility_score=round(visibility, 6),
                    drift_ratio=round(drift, 6),
                    reject_streak=int(self._frontier_v67_reject_streak),
                    hit_counter=round(float(self._frontier_v67_hit_counter), 6),
                )
            return fallback
        except Exception as exc:
            self._inc_metric("frontier_v67_guard_failures")
            LOGGER.warning("Frontier v67 adaptive-search guard failed; bypassing: %s", exc)
            if self.reporter is not None:
                self.reporter.event("frontier_v67_adaptive_failed", error=str(exc))
            return candidate_detection

    def _apply_frontier_v68_tiled_rescue_guard(
        self,
        *,
        base_detection: SpotDetection,
        candidate_detection: SpotDetection,
        visibility_score: float,
        drift_ratio: float,
    ) -> SpotDetection:
        if not self.cfg.frontier_v68_tiled_rescue_guard_enabled:
            return candidate_detection
        self._inc_metric("frontier_v68_guard_checks")
        try:
            base_point = np.asarray(
                [float(base_detection.center[0]), float(base_detection.center[1])],
                dtype=np.float64,
            )
            candidate_point = np.asarray(
                [float(candidate_detection.center[0]), float(candidate_detection.center[1])],
                dtype=np.float64,
            )
            if not np.all(np.isfinite(base_point)) or not np.all(np.isfinite(candidate_point)):
                return candidate_detection

            visibility = float(np.clip(float(visibility_score), 0.0, 1.0))
            drift = max(0.0, float(drift_ratio))
            history = self._frontier_v68_center_history

            def _append_center(center: Tuple[int, int]) -> None:
                history.append(np.asarray([float(center[0]), float(center[1])], dtype=np.float64))

            def _soft_accept(detection: SpotDetection, *, source: str) -> SpotDetection:
                accepted_conf = float(
                    np.clip(
                        float(detection.confidence) * float(self.cfg.frontier_v68_confidence_boost),
                        0.0,
                        1.0,
                    )
                )
                accepted = SpotDetection(
                    center=detection.center,
                    bbox=detection.bbox,
                    confidence=accepted_conf,
                    label=detection.label,
                    class_id=detection.class_id,
                )
                self._inc_metric("frontier_v68_guard_soft_accepts")
                self._frontier_v68_reject_streak = max(0, self._frontier_v68_reject_streak - 1)
                _append_center(accepted.center)
                if self.reporter is not None and source != "candidate":
                    self.reporter.event(
                        "frontier_v68_tiled_soft_accept",
                        source=source,
                        confidence=round(float(accepted_conf), 6),
                    )
                return accepted

            if len(history) < 2:
                return _soft_accept(candidate_detection, source="warmup")

            hist_arr = np.asarray(tuple(history), dtype=np.float64)
            if hist_arr.ndim != 2 or hist_arr.shape[1] != 2:
                self._frontier_v68_center_history = deque(maxlen=max(5, int(self.cfg.frontier_v68_history_size)))
                _append_center(candidate_detection.center)
                return candidate_detection

            last_point = hist_arr[-1]
            prev_point = hist_arr[-2]
            predicted = last_point + (last_point - prev_point)
            if not np.all(np.isfinite(predicted)):
                predicted = last_point.copy()
            residual = float(np.linalg.norm(candidate_point - predicted))

            relax_floor = float(np.clip(float(self.cfg.frontier_v68_visibility_relax_threshold), 0.0, 1.0))
            visibility_relax = max(0.0, visibility - relax_floor)
            reject_den = max(1, int(self.cfg.frontier_v68_history_size) // 2)
            reject_pressure = min(1.0, float(self._frontier_v68_reject_streak) / float(reject_den))
            drift_penalty = max(0.0, drift - 1.0)
            visibility_gain = max(0.0, float(self.cfg.frontier_v68_visibility_relax_gain))
            drift_penalty_gain = max(0.0, float(self.cfg.frontier_v68_drift_penalty_gain))
            gate = (
                max(0.25, float(self.cfg.frontier_v68_base_gate_px))
                * (1.0 + visibility_gain * visibility_relax + 0.18 * reject_pressure)
                / (1.0 + drift_penalty_gain * drift_penalty)
            )
            gate = max(0.25, float(gate))

            if residual <= gate:
                return _soft_accept(candidate_detection, source="candidate")

            if self._last_frame is None:
                confidence_penalty = float(np.clip(float(self.cfg.frontier_v68_confidence_penalty), 0.0, 1.0))
                fallback = SpotDetection(
                    center=base_detection.center,
                    bbox=base_detection.bbox,
                    confidence=float(np.clip(float(base_detection.confidence) * confidence_penalty, 0.0, 1.0)),
                    label=base_detection.label,
                    class_id=base_detection.class_id,
                )
                self._inc_metric("frontier_v68_guard_rejects")
                self._frontier_v68_reject_streak = min(
                    max(2, int(self.cfg.frontier_v68_history_size) * 2),
                    self._frontier_v68_reject_streak + 1,
                )
                _append_center(fallback.center)
                return fallback

            frame = self._last_frame
            if frame.ndim == 3:
                gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
            else:
                gray = frame
            gray_f = gray.astype(np.float32, copy=False)
            h, w = gray_f.shape[:2]

            predicted_center = self._clip_center(
                (int(round(float(predicted[0]))), int(round(float(predicted[1])))),
                (h, w),
            )
            radius = max(6, int(self.cfg.frontier_v68_tile_search_radius_px))
            tile_size = max(4, int(self.cfg.frontier_v68_tile_size_px))
            overlap = float(np.clip(float(self.cfg.frontier_v68_tile_overlap_ratio), 0.0, 0.95))
            stride = max(1, int(round(float(tile_size) * (1.0 - overlap))))

            x0 = max(0, int(predicted_center[0] - radius))
            y0 = max(0, int(predicted_center[1] - radius))
            x1 = min(w, int(predicted_center[0] + radius + 1))
            y1 = min(h, int(predicted_center[1] + radius + 1))
            if x1 - x0 < 3 or y1 - y0 < 3:
                return _soft_accept(candidate_detection, source="tiny_roi")

            roi = gray_f[y0:y1, x0:x1]
            roi_h, roi_w = roi.shape[:2]
            effective_tile = max(3, min(tile_size, roi_h, roi_w))
            if effective_tile <= 2:
                return _soft_accept(candidate_detection, source="small_tile")
            if effective_tile != tile_size:
                tile_size = effective_tile
                stride = max(1, int(round(float(tile_size) * (1.0 - overlap))))
            max_y = max(0, roi_h - tile_size)
            max_x = max(0, roi_w - tile_size)

            tile_positions_y = list(range(0, max_y + 1, stride))
            tile_positions_x = list(range(0, max_x + 1, stride))
            if tile_positions_y[-1] != max_y:
                tile_positions_y.append(max_y)
            if tile_positions_x[-1] != max_x:
                tile_positions_x.append(max_x)

            best_center: Optional[np.ndarray] = None
            best_contrast = -float("inf")
            best_peak = -float("inf")
            for ty in tile_positions_y:
                for tx in tile_positions_x:
                    patch = roi[ty:ty + tile_size, tx:tx + tile_size]
                    if patch.size == 0:
                        continue
                    min_val, max_val, _, max_loc = cv2.minMaxLoc(patch)
                    patch_std = float(np.std(patch))
                    if not np.isfinite(max_val) or not np.isfinite(min_val) or patch_std <= 1e-6:
                        continue
                    contrast = float(max_val - min_val)
                    if contrast <= best_contrast:
                        continue
                    px = x0 + tx + int(max_loc[0])
                    py = y0 + ty + int(max_loc[1])
                    center_arr = np.asarray([float(px), float(py)], dtype=np.float64)
                    if not np.all(np.isfinite(center_arr)):
                        continue
                    best_contrast = contrast
                    best_peak = float(max_val)
                    best_center = center_arr

            min_contrast = max(0.0, float(self.cfg.frontier_v68_min_peak_contrast))
            if best_center is None or best_contrast < min_contrast:
                confidence_penalty = float(np.clip(float(self.cfg.frontier_v68_confidence_penalty), 0.0, 1.0))
                fallback = SpotDetection(
                    center=base_detection.center,
                    bbox=base_detection.bbox,
                    confidence=float(np.clip(float(base_detection.confidence) * confidence_penalty, 0.0, 1.0)),
                    label=base_detection.label,
                    class_id=base_detection.class_id,
                )
                self._inc_metric("frontier_v68_guard_rejects")
                self._frontier_v68_reject_streak = min(
                    max(2, int(self.cfg.frontier_v68_history_size) * 2),
                    self._frontier_v68_reject_streak + 1,
                )
                _append_center(fallback.center)
                if self.reporter is not None:
                    self.reporter.event(
                        "frontier_v68_tiled_rejected",
                        reason="no_strong_peak",
                        residual_px=round(residual, 6),
                        gate_px=round(gate, 6),
                        min_contrast=round(min_contrast, 6),
                        best_contrast=round(float(best_contrast), 6),
                    )
                return fallback

            self._inc_metric("frontier_v68_rescue_candidates")
            rescue_residual = float(np.linalg.norm(best_center - predicted))
            max_rescue_shift = max(0.25, float(self.cfg.frontier_v68_max_rescue_shift_px))
            if rescue_residual > max_rescue_shift:
                confidence_penalty = float(np.clip(float(self.cfg.frontier_v68_confidence_penalty), 0.0, 1.0))
                fallback = SpotDetection(
                    center=base_detection.center,
                    bbox=base_detection.bbox,
                    confidence=float(np.clip(float(base_detection.confidence) * confidence_penalty, 0.0, 1.0)),
                    label=base_detection.label,
                    class_id=base_detection.class_id,
                )
                self._inc_metric("frontier_v68_guard_rejects")
                self._frontier_v68_reject_streak = min(
                    max(2, int(self.cfg.frontier_v68_history_size) * 2),
                    self._frontier_v68_reject_streak + 1,
                )
                _append_center(fallback.center)
                if self.reporter is not None:
                    self.reporter.event(
                        "frontier_v68_tiled_rejected",
                        reason="rescue_shift_exceeded",
                        rescue_residual_px=round(rescue_residual, 6),
                        max_rescue_shift_px=round(max_rescue_shift, 6),
                    )
                return fallback

            rescue_center = self._clip_center(
                (int(round(float(best_center[0]))), int(round(float(best_center[1])))),
                (h, w),
            )
            rescue_bbox = self._recenter_bbox(base_detection.bbox, rescue_center, (h, w))

            def _bbox_iou(b1: Tuple[int, int, int, int], b2: Tuple[int, int, int, int]) -> float:
                x1 = max(int(b1[0]), int(b2[0]))
                y1 = max(int(b1[1]), int(b2[1]))
                x2 = min(int(b1[2]), int(b2[2]))
                y2 = min(int(b1[3]), int(b2[3]))
                inter_w = max(0, x2 - x1)
                inter_h = max(0, y2 - y1)
                inter = float(inter_w * inter_h)
                if inter <= 0:
                    return 0.0
                area1 = float(max(0, int(b1[2]) - int(b1[0])) * max(0, int(b1[3]) - int(b1[1])))
                area2 = float(max(0, int(b2[2]) - int(b2[0])) * max(0, int(b2[3]) - int(b2[1])))
                denom = area1 + area2 - inter
                if denom <= 1e-6:
                    return 0.0
                return float(inter / denom)

            iou = _bbox_iou(candidate_detection.bbox, rescue_bbox)
            merge_iou = float(np.clip(float(self.cfg.frontier_v68_merge_iou_threshold), 0.0, 1.0))
            candidate_residual = float(np.linalg.norm(candidate_point - predicted))
            rescue_point = np.asarray([float(rescue_center[0]), float(rescue_center[1])], dtype=np.float64)
            if iou >= merge_iou:
                merged = 0.5 * (candidate_point + rescue_point)
                rescue_center = self._clip_center(
                    (int(round(float(merged[0]))), int(round(float(merged[1])))),
                    (h, w),
                )
                rescue_bbox = self._recenter_bbox(base_detection.bbox, rescue_center, (h, w))
                rescue_residual = float(np.linalg.norm(np.asarray(rescue_center, dtype=np.float64) - predicted))

            confidence_penalty = float(np.clip(float(self.cfg.frontier_v68_confidence_penalty), 0.0, 1.0))
            rescue_better = rescue_residual <= candidate_residual
            if rescue_better or rescue_residual <= (gate * 1.25):
                refined = SpotDetection(
                    center=rescue_center,
                    bbox=rescue_bbox,
                    confidence=float(
                        np.clip(float(candidate_detection.confidence) * confidence_penalty, 0.0, 1.0)
                    ),
                    label=candidate_detection.label,
                    class_id=candidate_detection.class_id,
                )
                self._inc_metric("frontier_v68_guard_refines")
                self._frontier_v68_reject_streak = max(0, self._frontier_v68_reject_streak - 1)
                _append_center(refined.center)
                if self.reporter is not None:
                    self.reporter.event(
                        "frontier_v68_tiled_refined",
                        residual_px=round(candidate_residual, 6),
                        rescue_residual_px=round(rescue_residual, 6),
                        gate_px=round(gate, 6),
                        peak=round(float(best_peak), 6),
                        peak_contrast=round(float(best_contrast), 6),
                        bbox_iou=round(float(iou), 6),
                    )
                return refined

            fallback = SpotDetection(
                center=base_detection.center,
                bbox=base_detection.bbox,
                confidence=float(np.clip(float(base_detection.confidence) * confidence_penalty, 0.0, 1.0)),
                label=base_detection.label,
                class_id=base_detection.class_id,
            )
            self._inc_metric("frontier_v68_guard_rejects")
            self._frontier_v68_reject_streak = min(
                max(2, int(self.cfg.frontier_v68_history_size) * 2),
                self._frontier_v68_reject_streak + 1,
            )
            _append_center(fallback.center)
            if self.reporter is not None:
                self.reporter.event(
                    "frontier_v68_tiled_rejected",
                    reason="rescue_not_improving",
                    residual_px=round(candidate_residual, 6),
                    rescue_residual_px=round(rescue_residual, 6),
                    gate_px=round(gate, 6),
                    peak_contrast=round(float(best_contrast), 6),
                    bbox_iou=round(float(iou), 6),
                )
            return fallback
        except Exception as exc:
            self._inc_metric("frontier_v68_guard_failures")
            LOGGER.warning("Frontier v68 tiled-rescue guard failed; bypassing: %s", exc)
            if self.reporter is not None:
                self.reporter.event("frontier_v68_tiled_failed", error=str(exc))
            return candidate_detection

    def _apply_frontier_v69_cmc_guard(
        self,
        *,
        base_detection: SpotDetection,
        candidate_detection: SpotDetection,
        visibility_score: float,
        drift_ratio: float,
    ) -> SpotDetection:
        if not self.cfg.frontier_v69_cmc_guard_enabled:
            return candidate_detection
        self._inc_metric("frontier_v69_guard_checks")
        try:
            base_point = np.asarray(
                [float(base_detection.center[0]), float(base_detection.center[1])],
                dtype=np.float64,
            )
            candidate_point = np.asarray(
                [float(candidate_detection.center[0]), float(candidate_detection.center[1])],
                dtype=np.float64,
            )
            if not np.all(np.isfinite(base_point)) or not np.all(np.isfinite(candidate_point)):
                return candidate_detection

            frame = self._last_frame
            if frame is None:
                return candidate_detection
            if frame.ndim == 3:
                gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
            else:
                gray = frame
            gray_f = gray.astype(np.float32, copy=False)
            prev_gray = self._frontier_v69_prev_gray

            visibility = float(np.clip(float(visibility_score), 0.0, 1.0))
            drift = max(0.0, float(drift_ratio))
            history = self._frontier_v69_center_history

            def _sync_prev_gray() -> None:
                self._frontier_v69_prev_gray = gray_f.copy()

            def _append_center(center: Tuple[int, int]) -> None:
                history.append(np.asarray([float(center[0]), float(center[1])], dtype=np.float64))

            def _soft_accept(
                detection: SpotDetection,
                *,
                source: str,
                residual_px: Optional[float] = None,
                gate_px: Optional[float] = None,
                cmc_shift: Optional[np.ndarray] = None,
                cmc_response: Optional[float] = None,
            ) -> SpotDetection:
                accepted_conf = float(
                    np.clip(
                        float(detection.confidence) * float(self.cfg.frontier_v69_confidence_boost),
                        0.0,
                        1.0,
                    )
                )
                accepted = SpotDetection(
                    center=detection.center,
                    bbox=detection.bbox,
                    confidence=accepted_conf,
                    label=detection.label,
                    class_id=detection.class_id,
                )
                self._inc_metric("frontier_v69_guard_soft_accepts")
                self._frontier_v69_reject_streak = max(0, self._frontier_v69_reject_streak - 1)
                _append_center(accepted.center)
                if self.reporter is not None and source != "candidate":
                    event_payload: Dict[str, object] = {
                        "source": source,
                        "confidence": round(float(accepted_conf), 6),
                    }
                    if residual_px is not None:
                        event_payload["residual_px"] = round(float(residual_px), 6)
                    if gate_px is not None:
                        event_payload["gate_px"] = round(float(gate_px), 6)
                    if cmc_response is not None:
                        event_payload["cmc_response"] = round(float(cmc_response), 6)
                    if cmc_shift is not None and np.size(cmc_shift) >= 2:
                        event_payload["cmc_shift"] = [
                            round(float(cmc_shift[0]), 6),
                            round(float(cmc_shift[1]), 6),
                        ]
                    self.reporter.event("frontier_v69_cmc_soft_accept", **event_payload)
                _sync_prev_gray()
                return accepted

            def _fallback(
                reason: str,
                *,
                residual_px: Optional[float] = None,
                gate_px: Optional[float] = None,
                cmc_response: Optional[float] = None,
                cmc_shift: Optional[np.ndarray] = None,
                rescue_score: Optional[float] = None,
                rescue_residual_px: Optional[float] = None,
                template_std: Optional[float] = None,
            ) -> SpotDetection:
                confidence_penalty = float(np.clip(float(self.cfg.frontier_v69_confidence_penalty), 0.0, 1.0))
                fallback = SpotDetection(
                    center=base_detection.center,
                    bbox=base_detection.bbox,
                    confidence=float(np.clip(float(base_detection.confidence) * confidence_penalty, 0.0, 1.0)),
                    label=base_detection.label,
                    class_id=base_detection.class_id,
                )
                self._inc_metric("frontier_v69_guard_rejects")
                self._frontier_v69_reject_streak = min(
                    max(2, int(self.cfg.frontier_v69_history_size) * 2),
                    self._frontier_v69_reject_streak + 1,
                )
                _append_center(fallback.center)
                if self.reporter is not None:
                    event_payload: Dict[str, object] = {"reason": str(reason)}
                    if residual_px is not None:
                        event_payload["residual_px"] = round(float(residual_px), 6)
                    if gate_px is not None:
                        event_payload["gate_px"] = round(float(gate_px), 6)
                    if cmc_response is not None:
                        event_payload["cmc_response"] = round(float(cmc_response), 6)
                    if cmc_shift is not None and np.size(cmc_shift) >= 2:
                        event_payload["cmc_shift"] = [
                            round(float(cmc_shift[0]), 6),
                            round(float(cmc_shift[1]), 6),
                        ]
                    if rescue_score is not None:
                        event_payload["rescue_score"] = round(float(rescue_score), 6)
                    if rescue_residual_px is not None:
                        event_payload["rescue_residual_px"] = round(float(rescue_residual_px), 6)
                    if template_std is not None:
                        event_payload["template_std"] = round(float(template_std), 6)
                    self.reporter.event("frontier_v69_cmc_rejected", **event_payload)
                _sync_prev_gray()
                return fallback

            if len(history) < 2:
                return _soft_accept(candidate_detection, source="warmup")

            hist_arr = np.asarray(tuple(history), dtype=np.float64)
            if hist_arr.ndim != 2 or hist_arr.shape[1] != 2:
                self._frontier_v69_center_history = deque(maxlen=max(5, int(self.cfg.frontier_v69_history_size)))
                self._frontier_v69_center_history.append(candidate_point.copy())
                _sync_prev_gray()
                return candidate_detection

            last_point = hist_arr[-1]
            prev_point = hist_arr[-2]
            motion = last_point - prev_point
            if not np.all(np.isfinite(motion)):
                motion = np.zeros(2, dtype=np.float64)

            cmc_shift = np.zeros(2, dtype=np.float64)
            cmc_response = 0.0
            phase_response_min = float(np.clip(float(self.cfg.frontier_v69_phase_response_min), 0.0, 1.0))
            if (
                prev_gray is not None
                and prev_gray.shape == gray_f.shape
                and hasattr(cv2, "phaseCorrelate")
            ):
                try:
                    phase_raw = cv2.phaseCorrelate(prev_gray.astype(np.float32, copy=False), gray_f)
                    phase_shift = phase_raw[0] if isinstance(phase_raw, tuple) else (0.0, 0.0)
                    phase_response = phase_raw[1] if isinstance(phase_raw, tuple) and len(phase_raw) >= 2 else 0.0
                    sx = float(phase_shift[0] if isinstance(phase_shift, (tuple, list)) else 0.0)
                    sy = float(phase_shift[1] if isinstance(phase_shift, (tuple, list)) else 0.0)
                    resp = float(phase_response if np.isfinite(phase_response) else 0.0)
                    cmc_response = max(0.0, resp)
                    if np.isfinite(sx) and np.isfinite(sy) and cmc_response >= phase_response_min:
                        cmc_gain = max(0.0, float(self.cfg.frontier_v69_cmc_gain))
                        cmc_shift = np.asarray([sx * cmc_gain, sy * cmc_gain], dtype=np.float64)
                except Exception:
                    cmc_shift = np.zeros(2, dtype=np.float64)
                    cmc_response = 0.0

            predicted = last_point + motion + cmc_shift
            if not np.all(np.isfinite(predicted)):
                predicted = last_point.copy()
            residual = float(np.linalg.norm(candidate_point - predicted))

            relax_floor = float(np.clip(float(self.cfg.frontier_v69_visibility_relax_threshold), 0.0, 1.0))
            visibility_relax = max(0.0, visibility - relax_floor)
            reject_den = max(1, int(self.cfg.frontier_v69_history_size) // 2)
            reject_pressure = min(1.0, float(self._frontier_v69_reject_streak) / float(reject_den))
            drift_penalty = max(0.0, drift - 1.0)
            visibility_gain = max(0.0, float(self.cfg.frontier_v69_visibility_relax_gain))
            reject_gain = max(0.0, float(self.cfg.frontier_v69_reject_relax_gain))
            drift_penalty_gain = max(0.0, float(self.cfg.frontier_v69_drift_penalty_gain))
            response_gain = max(0.0, float(self.cfg.frontier_v69_cmc_response_gain))
            response_relax = max(0.0, cmc_response - phase_response_min)
            gate = (
                max(0.25, float(self.cfg.frontier_v69_base_gate_px))
                * (1.0 + visibility_gain * visibility_relax + reject_gain * reject_pressure + response_gain * response_relax)
                / (1.0 + drift_penalty_gain * drift_penalty)
            )
            gate = max(0.25, float(gate))
            if residual <= gate:
                return _soft_accept(
                    candidate_detection,
                    source="candidate",
                    residual_px=residual,
                    gate_px=gate,
                    cmc_shift=cmc_shift,
                    cmc_response=cmc_response,
                )

            if prev_gray is None or prev_gray.shape != gray_f.shape:
                return _fallback(
                    "no_prev_frame",
                    residual_px=residual,
                    gate_px=gate,
                    cmc_shift=cmc_shift,
                    cmc_response=cmc_response,
                )

            h, w = gray_f.shape[:2]
            template_radius = max(3, int(self.cfg.frontier_v69_template_radius_px))
            last_center = self._clip_center(
                (int(round(float(last_point[0]))), int(round(float(last_point[1])))),
                (h, w),
            )
            tx0 = max(0, int(last_center[0] - template_radius))
            ty0 = max(0, int(last_center[1] - template_radius))
            tx1 = min(w, int(last_center[0] + template_radius + 1))
            ty1 = min(h, int(last_center[1] + template_radius + 1))
            template = prev_gray[ty0:ty1, tx0:tx1]
            if template.size == 0 or template.shape[0] < 3 or template.shape[1] < 3:
                return _fallback(
                    "template_too_small",
                    residual_px=residual,
                    gate_px=gate,
                    cmc_shift=cmc_shift,
                    cmc_response=cmc_response,
                )

            template_std = float(np.std(template))
            min_template_std = max(0.0, float(self.cfg.frontier_v69_template_min_std))
            if not np.isfinite(template_std) or template_std < min_template_std:
                return _fallback(
                    "template_low_std",
                    residual_px=residual,
                    gate_px=gate,
                    cmc_shift=cmc_shift,
                    cmc_response=cmc_response,
                    template_std=template_std,
                )

            max_rescue_shift = max(0.25, float(self.cfg.frontier_v69_max_rescue_shift_px))
            search_radius = max(int(math.ceil(max_rescue_shift)), template_radius + 1)
            predicted_center = self._clip_center(
                (int(round(float(predicted[0]))), int(round(float(predicted[1])))),
                (h, w),
            )
            sx0 = max(0, int(predicted_center[0] - search_radius - template.shape[1] // 2))
            sy0 = max(0, int(predicted_center[1] - search_radius - template.shape[0] // 2))
            sx1 = min(w, int(predicted_center[0] + search_radius + template.shape[1] // 2 + 1))
            sy1 = min(h, int(predicted_center[1] + search_radius + template.shape[0] // 2 + 1))
            roi = gray_f[sy0:sy1, sx0:sx1]
            if (
                roi.size == 0
                or roi.shape[0] < template.shape[0]
                or roi.shape[1] < template.shape[1]
            ):
                return _fallback(
                    "search_roi_too_small",
                    residual_px=residual,
                    gate_px=gate,
                    cmc_shift=cmc_shift,
                    cmc_response=cmc_response,
                    template_std=template_std,
                )

            match_map = cv2.matchTemplate(roi, template, cv2.TM_CCOEFF_NORMED)
            if match_map.size == 0:
                return _fallback(
                    "match_map_empty",
                    residual_px=residual,
                    gate_px=gate,
                    cmc_shift=cmc_shift,
                    cmc_response=cmc_response,
                    template_std=template_std,
                )
            _, max_score, _, max_loc = cv2.minMaxLoc(match_map)
            if not np.isfinite(max_score):
                return _fallback(
                    "match_score_invalid",
                    residual_px=residual,
                    gate_px=gate,
                    cmc_shift=cmc_shift,
                    cmc_response=cmc_response,
                    template_std=template_std,
                )

            rescue_center_arr = np.asarray(
                [
                    float(sx0 + max_loc[0] + template.shape[1] / 2.0),
                    float(sy0 + max_loc[1] + template.shape[0] / 2.0),
                ],
                dtype=np.float64,
            )
            rescue_residual = float(np.linalg.norm(rescue_center_arr - predicted))
            min_score = float(np.clip(float(self.cfg.frontier_v69_template_min_score), -1.0, 1.0))
            self._inc_metric("frontier_v69_rescue_candidates")

            if max_score < min_score:
                return _fallback(
                    "rescue_score_low",
                    residual_px=residual,
                    gate_px=gate,
                    cmc_shift=cmc_shift,
                    cmc_response=cmc_response,
                    rescue_score=float(max_score),
                    rescue_residual_px=rescue_residual,
                    template_std=template_std,
                )
            if rescue_residual > max_rescue_shift:
                return _fallback(
                    "rescue_shift_exceeded",
                    residual_px=residual,
                    gate_px=gate,
                    cmc_shift=cmc_shift,
                    cmc_response=cmc_response,
                    rescue_score=float(max_score),
                    rescue_residual_px=rescue_residual,
                    template_std=template_std,
                )
            if rescue_residual > residual:
                return _fallback(
                    "rescue_not_improving",
                    residual_px=residual,
                    gate_px=gate,
                    cmc_shift=cmc_shift,
                    cmc_response=cmc_response,
                    rescue_score=float(max_score),
                    rescue_residual_px=rescue_residual,
                    template_std=template_std,
                )

            rescue_center = self._clip_center(
                (
                    int(round(float(rescue_center_arr[0]))),
                    int(round(float(rescue_center_arr[1]))),
                ),
                (h, w),
            )
            refined = SpotDetection(
                center=rescue_center,
                bbox=self._recenter_bbox(candidate_detection.bbox, rescue_center, (h, w)),
                confidence=float(
                    np.clip(
                        float(candidate_detection.confidence) * float(self.cfg.frontier_v69_confidence_penalty),
                        0.0,
                        1.0,
                    )
                ),
                label=candidate_detection.label,
                class_id=candidate_detection.class_id,
            )
            self._inc_metric("frontier_v69_guard_refines")
            self._frontier_v69_reject_streak = max(0, self._frontier_v69_reject_streak - 1)
            _append_center(refined.center)
            if self.reporter is not None:
                self.reporter.event(
                    "frontier_v69_cmc_refined",
                    residual_px=round(float(residual), 6),
                    rescue_residual_px=round(float(rescue_residual), 6),
                    gate_px=round(float(gate), 6),
                    rescue_score=round(float(max_score), 6),
                    template_std=round(float(template_std), 6),
                    cmc_response=round(float(cmc_response), 6),
                    cmc_shift=[round(float(cmc_shift[0]), 6), round(float(cmc_shift[1]), 6)],
                )
            _sync_prev_gray()
            return refined
        except Exception as exc:
            self._inc_metric("frontier_v69_guard_failures")
            LOGGER.warning("Frontier v69 CMC guard failed; bypassing: %s", exc)
            if self.reporter is not None:
                self.reporter.event("frontier_v69_cmc_failed", error=str(exc))
            if self._last_frame is not None:
                try:
                    if self._last_frame.ndim == 3:
                        _gray = cv2.cvtColor(self._last_frame, cv2.COLOR_BGR2GRAY)
                    else:
                        _gray = self._last_frame
                    self._frontier_v69_prev_gray = _gray.astype(np.float32, copy=False).copy()
                except Exception:
                    pass
            return candidate_detection

    def _apply_frontier_v70_failover_guard(
        self,
        *,
        base_detection: SpotDetection,
        candidate_detection: SpotDetection,
        visibility_score: float,
        drift_ratio: float,
    ) -> SpotDetection:
        if not self.cfg.frontier_v70_failover_guard_enabled:
            return candidate_detection
        self._inc_metric("frontier_v70_guard_checks")
        try:
            base_point = np.asarray(
                [float(base_detection.center[0]), float(base_detection.center[1])],
                dtype=np.float64,
            )
            candidate_point = np.asarray(
                [float(candidate_detection.center[0]), float(candidate_detection.center[1])],
                dtype=np.float64,
            )
            if not np.all(np.isfinite(base_point)) or not np.all(np.isfinite(candidate_point)):
                return candidate_detection

            history = self._frontier_v70_center_history

            def _append_center(center: Tuple[int, int]) -> None:
                history.append(np.asarray([float(center[0]), float(center[1])], dtype=np.float64))

            reporter_metrics = getattr(self.reporter, "metrics", None)
            current_v69_rejects = int(getattr(reporter_metrics, "frontier_v69_guard_rejects", 0))
            v69_reject_delta = max(0, current_v69_rejects - int(self._frontier_v70_last_v69_rejects))
            self._frontier_v70_last_v69_rejects = current_v69_rejects

            reject_cap = max(2, int(self.cfg.frontier_v70_history_size) * 2)
            if v69_reject_delta > 0:
                self._frontier_v70_reject_streak = min(reject_cap, self._frontier_v70_reject_streak + int(v69_reject_delta))
                self._inc_metric("frontier_v70_guard_rejects")
            else:
                self._frontier_v70_reject_streak = max(0, self._frontier_v70_reject_streak - 1)

            if len(history) < 2:
                _append_center(candidate_detection.center)
                return candidate_detection

            hist_arr = np.asarray(tuple(history), dtype=np.float64)
            if hist_arr.ndim != 2 or hist_arr.shape[1] != 2:
                self._frontier_v70_center_history = deque(maxlen=max(6, int(self.cfg.frontier_v70_history_size)))
                self._frontier_v70_center_history.append(candidate_point.copy())
                return candidate_detection

            consensus_center = np.nanmedian(hist_arr, axis=0)
            if not np.all(np.isfinite(consensus_center)):
                _append_center(candidate_detection.center)
                return candidate_detection

            visibility = float(np.clip(float(visibility_score), 0.0, 1.0))
            drift = max(0.0, float(drift_ratio))
            relax_floor = float(np.clip(float(self.cfg.frontier_v70_visibility_relax_threshold), 0.0, 1.0))
            visibility_relax = max(0.0, visibility - relax_floor)
            drift_penalty = max(0.0, drift - 1.0)
            base_gate = max(0.25, float(self.cfg.frontier_v70_base_gate_px))
            gate = (
                base_gate
                * (1.0 + max(0.0, float(self.cfg.frontier_v70_visibility_relax_gain)) * visibility_relax)
                / (1.0 + max(0.0, float(self.cfg.frontier_v70_drift_penalty_gain)) * drift_penalty)
            )
            gate = max(0.25, float(gate))

            dist_hist = np.linalg.norm(hist_arr - consensus_center, axis=1)
            dist_hist = dist_hist[np.isfinite(dist_hist)]
            if dist_hist.size == 0:
                spread_q = gate
            else:
                q = float(np.clip(float(self.cfg.frontier_v70_consensus_quantile), 0.50, 0.95))
                spread_q = float(np.quantile(dist_hist, q))
                if not np.isfinite(spread_q):
                    spread_q = gate
            spread_gate = max(0.50, spread_q * 2.20 + gate * 0.90)

            candidate_residual = float(np.linalg.norm(candidate_point - consensus_center))
            reject_streak = int(self._frontier_v70_reject_streak)
            reject_refine_threshold = max(1, int(self.cfg.frontier_v70_reject_streak_for_refine))
            circuit_breaker_threshold = max(
                reject_refine_threshold + 1,
                int(self.cfg.frontier_v70_reject_streak_for_circuit_breaker),
            )
            should_intervene = (
                reject_streak >= reject_refine_threshold
                and (v69_reject_delta > 0 or candidate_residual > gate)
            )
            if not should_intervene:
                _append_center(candidate_detection.center)
                return candidate_detection

            blend = float(np.clip(float(self.cfg.frontier_v70_consensus_blend), 0.0, 1.0))
            circuit_breaker = bool(reject_streak >= circuit_breaker_threshold)
            if circuit_breaker:
                blend = float(np.clip(blend + 0.20, 0.0, 1.0))
                self._inc_metric("frontier_v70_circuit_breaker_hits")

            target_point = candidate_point * (1.0 - blend) + consensus_center * blend
            if not np.all(np.isfinite(target_point)):
                target_point = consensus_center.copy()
            target_shift = float(np.linalg.norm(target_point - candidate_point))
            target_residual = float(np.linalg.norm(target_point - consensus_center))
            if target_shift > spread_gate or target_residual > spread_gate:
                _append_center(candidate_detection.center)
                return candidate_detection

            frame_shape = self._last_frame.shape[:2] if self._last_frame is not None else None
            if frame_shape is not None:
                refined_center = self._clip_center(
                    (
                        int(round(float(target_point[0]))),
                        int(round(float(target_point[1]))),
                    ),
                    frame_shape,
                )
                refined_bbox = self._recenter_bbox(candidate_detection.bbox, refined_center, frame_shape)
            else:
                refined_center = (
                    int(round(float(target_point[0]))),
                    int(round(float(target_point[1]))),
                )
                refined_bbox = candidate_detection.bbox

            conf_penalty = float(np.clip(float(self.cfg.frontier_v70_confidence_penalty), 0.0, 1.0))
            conf_boost = max(0.0, float(self.cfg.frontier_v70_confidence_boost))
            if circuit_breaker:
                refined_conf = float(
                    np.clip(
                        float(base_detection.confidence) * conf_penalty,
                        0.0,
                        1.0,
                    )
                )
            else:
                refined_conf = float(
                    np.clip(
                        float(candidate_detection.confidence) * conf_penalty * conf_boost,
                        0.0,
                        1.0,
                    )
                )
            refined = SpotDetection(
                center=refined_center,
                bbox=refined_bbox,
                confidence=refined_conf,
                label=candidate_detection.label,
                class_id=candidate_detection.class_id,
            )
            self._inc_metric("frontier_v70_guard_refines")
            self._inc_metric("frontier_v70_consensus_rescues")
            self._inc_metric("frontier_v70_guard_soft_accepts")
            self._frontier_v70_reject_streak = max(0, reject_streak - (2 if circuit_breaker else 1))
            _append_center(refined.center)
            if self.reporter is not None:
                self.reporter.event(
                    "frontier_v70_failover_refined",
                    residual_px=round(float(candidate_residual), 6),
                    gate_px=round(float(gate), 6),
                    spread_gate_px=round(float(spread_gate), 6),
                    target_shift_px=round(float(target_shift), 6),
                    reject_streak=reject_streak,
                    circuit_breaker=circuit_breaker,
                    blend=round(float(blend), 6),
                )
            return refined
        except Exception as exc:
            self._inc_metric("frontier_v70_guard_failures")
            LOGGER.warning("Frontier v70 failover guard failed; bypassing: %s", exc)
            if self.reporter is not None:
                self.reporter.event("frontier_v70_failover_failed", error=str(exc))
            return candidate_detection

    def _apply_frontier_v71_occlusion_guard(
        self,
        *,
        base_detection: SpotDetection,
        candidate_detection: SpotDetection,
        visibility_score: float,
        drift_ratio: float,
    ) -> SpotDetection:
        if not self.cfg.frontier_v71_occlusion_guard_enabled:
            return candidate_detection
        self._inc_metric("frontier_v71_guard_checks")
        try:
            base_point = np.asarray(
                [float(base_detection.center[0]), float(base_detection.center[1])],
                dtype=np.float64,
            )
            candidate_point = np.asarray(
                [float(candidate_detection.center[0]), float(candidate_detection.center[1])],
                dtype=np.float64,
            )
            if not np.all(np.isfinite(base_point)) or not np.all(np.isfinite(candidate_point)):
                return candidate_detection

            history = self._frontier_v71_center_history

            def _append_center(center: Tuple[int, int]) -> None:
                history.append(np.asarray([float(center[0]), float(center[1])], dtype=np.float64))

            reporter_metrics = getattr(self.reporter, "metrics", None)
            current_v70_rejects = int(getattr(reporter_metrics, "frontier_v70_guard_rejects", 0))
            v70_reject_delta = max(0, current_v70_rejects - int(self._frontier_v71_last_v70_rejects))
            self._frontier_v71_last_v70_rejects = current_v70_rejects
            streak_cap = max(2, int(self.cfg.frontier_v71_history_size) * 2)
            if v70_reject_delta > 0:
                self._frontier_v71_occlusion_streak = min(streak_cap, self._frontier_v71_occlusion_streak + v70_reject_delta)
            else:
                self._frontier_v71_occlusion_streak = max(0, self._frontier_v71_occlusion_streak - 1)

            if len(history) < 2:
                _append_center(candidate_detection.center)
                return candidate_detection

            hist_arr = np.asarray(tuple(history), dtype=np.float64)
            if hist_arr.ndim != 2 or hist_arr.shape[1] != 2:
                self._frontier_v71_center_history = deque(maxlen=max(6, int(self.cfg.frontier_v71_history_size)))
                self._frontier_v71_center_history.append(candidate_point.copy())
                self._frontier_v71_velocity = np.zeros(2, dtype=np.float64)
                return candidate_detection

            consensus_center = np.nanmedian(hist_arr, axis=0)
            if not np.all(np.isfinite(consensus_center)):
                _append_center(candidate_detection.center)
                return candidate_detection

            last_center = hist_arr[-1]
            if not np.all(np.isfinite(last_center)):
                _append_center(candidate_detection.center)
                return candidate_detection

            visibility = float(np.clip(float(visibility_score), 0.0, 1.0))
            visibility_gate = float(np.clip(float(self.cfg.frontier_v71_occlusion_visibility_threshold), 0.0, 1.0))
            drift = max(0.0, float(drift_ratio))
            drift_penalty = max(0.0, drift - 1.0)
            residual_gate = max(0.25, float(self.cfg.frontier_v71_occlusion_residual_gate_px))
            residual_gate = residual_gate / (
                1.0 + max(0.0, float(self.cfg.frontier_v71_drift_penalty_gain)) * drift_penalty
            )
            residual_gate = max(0.25, float(residual_gate))

            candidate_residual = float(np.linalg.norm(candidate_point - consensus_center))
            confidence_drop = max(0.0, float(base_detection.confidence) - float(candidate_detection.confidence))
            conf_drop_gate = max(0.0, float(self.cfg.frontier_v71_confidence_drop_gate))
            reject_trigger = v70_reject_delta > 0 and candidate_residual > residual_gate * 0.55
            occlusion_hit = (visibility <= visibility_gate and (
                candidate_residual > residual_gate or confidence_drop >= conf_drop_gate
            )) or reject_trigger

            instant_velocity = candidate_point - last_center
            if np.all(np.isfinite(instant_velocity)):
                damping = float(np.clip(float(self.cfg.frontier_v71_momentum_damping), 0.0, 0.999))
                self._frontier_v71_velocity = self._frontier_v71_velocity * damping + instant_velocity * (1.0 - damping)

            if not occlusion_hit:
                _append_center(candidate_detection.center)
                return candidate_detection

            self._inc_metric("frontier_v71_occlusion_hits")
            self._frontier_v71_occlusion_streak = min(streak_cap, self._frontier_v71_occlusion_streak + 1)
            occlusion_streak = int(self._frontier_v71_occlusion_streak)

            gain = float(np.clip(float(self.cfg.frontier_v71_momentum_gain), 0.0, 1.0))
            predicted_point = last_center + self._frontier_v71_velocity
            if not np.all(np.isfinite(predicted_point)):
                predicted_point = consensus_center.copy()

            target_point = candidate_point * (1.0 - gain) + predicted_point * gain
            if not np.all(np.isfinite(target_point)):
                self._inc_metric("frontier_v71_guard_rejects")
                _append_center(candidate_detection.center)
                return candidate_detection

            offset = target_point - candidate_point
            offset_norm = float(np.linalg.norm(offset))
            max_offset = max(0.25, float(self.cfg.frontier_v71_max_offset_px))
            if np.isfinite(offset_norm) and offset_norm > max_offset and offset_norm > 0:
                target_point = candidate_point + offset * (max_offset / offset_norm)
                offset = target_point - candidate_point
                offset_norm = float(np.linalg.norm(offset))

            target_residual = float(np.linalg.norm(target_point - consensus_center))
            if not np.isfinite(target_residual) or target_residual > residual_gate * 1.4:
                self._inc_metric("frontier_v71_guard_rejects")
                _append_center(candidate_detection.center)
                return candidate_detection

            frame_shape = self._last_frame.shape[:2] if self._last_frame is not None else None
            if frame_shape is not None:
                refined_center = self._clip_center(
                    (
                        int(round(float(target_point[0]))),
                        int(round(float(target_point[1]))),
                    ),
                    frame_shape,
                )
                refined_bbox = self._recenter_bbox(candidate_detection.bbox, refined_center, frame_shape)
            else:
                refined_center = (
                    int(round(float(target_point[0]))),
                    int(round(float(target_point[1]))),
                )
                refined_bbox = candidate_detection.bbox

            conf_penalty = float(np.clip(float(self.cfg.frontier_v71_confidence_penalty), 0.0, 1.0))
            conf_boost = max(0.0, float(self.cfg.frontier_v71_confidence_boost))
            refined_conf = float(
                np.clip(
                    float(candidate_detection.confidence) * conf_penalty * conf_boost,
                    0.0,
                    1.0,
                )
            )

            refined = SpotDetection(
                center=refined_center,
                bbox=refined_bbox,
                confidence=refined_conf,
                label=candidate_detection.label,
                class_id=candidate_detection.class_id,
            )
            self._inc_metric("frontier_v71_guard_refines")
            self._inc_metric("frontier_v71_guard_soft_accepts")
            self._frontier_v71_occlusion_streak = max(0, occlusion_streak - 1)
            _append_center(refined.center)
            if self.reporter is not None:
                self.reporter.event(
                    "frontier_v71_occlusion_refined",
                    residual_px=round(float(candidate_residual), 6),
                    gate_px=round(float(residual_gate), 6),
                    confidence_drop=round(float(confidence_drop), 6),
                    target_shift_px=round(float(offset_norm), 6),
                    target_residual_px=round(float(target_residual), 6),
                    occlusion_streak=occlusion_streak,
                    v70_reject_delta=int(v70_reject_delta),
                    reject_trigger=bool(reject_trigger),
                )
            return refined
        except Exception as exc:
            self._inc_metric("frontier_v71_guard_failures")
            LOGGER.warning("Frontier v71 occlusion guard failed; bypassing: %s", exc)
            if self.reporter is not None:
                self.reporter.event("frontier_v71_occlusion_failed", error=str(exc))
            return candidate_detection

    def _apply_frontier_v72_memory_verifier_guard(
        self,
        *,
        base_detection: SpotDetection,
        candidate_detection: SpotDetection,
        visibility_score: float,
        drift_ratio: float,
    ) -> SpotDetection:
        if not self.cfg.frontier_v72_memory_verifier_guard_enabled:
            return candidate_detection
        self._inc_metric("frontier_v72_guard_checks")
        try:
            base_point = np.asarray(
                [float(base_detection.center[0]), float(base_detection.center[1])],
                dtype=np.float64,
            )
            candidate_point = np.asarray(
                [float(candidate_detection.center[0]), float(candidate_detection.center[1])],
                dtype=np.float64,
            )
            if not np.all(np.isfinite(base_point)) or not np.all(np.isfinite(candidate_point)):
                return candidate_detection

            history = self._frontier_v72_center_history

            def _append_center(center: Tuple[int, int]) -> None:
                history.append(np.asarray([float(center[0]), float(center[1])], dtype=np.float64))

            reporter_metrics = getattr(self.reporter, "metrics", None)
            current_v71_refines = int(getattr(reporter_metrics, "frontier_v71_guard_refines", 0))
            current_v71_rejects = int(getattr(reporter_metrics, "frontier_v71_guard_rejects", 0))
            v71_refine_delta = max(0, current_v71_refines - int(self._frontier_v72_last_v71_refines))
            v71_reject_delta = max(0, current_v71_rejects - int(self._frontier_v72_last_v71_rejects))
            self._frontier_v72_last_v71_refines = current_v71_refines
            self._frontier_v72_last_v71_rejects = current_v71_rejects

            if len(history) < 2:
                _append_center(candidate_detection.center)
                return candidate_detection

            hist_arr = np.asarray(tuple(history), dtype=np.float64)
            if hist_arr.ndim != 2 or hist_arr.shape[1] != 2:
                self._frontier_v72_center_history = deque(maxlen=max(8, int(self.cfg.frontier_v72_history_size)))
                self._frontier_v72_center_history.append(candidate_point.copy())
                return candidate_detection

            memory_center = np.nanmedian(hist_arr, axis=0)
            if not np.all(np.isfinite(memory_center)):
                _append_center(candidate_detection.center)
                return candidate_detection

            last_center = hist_arr[-1]
            prev_center = hist_arr[-2]
            if not np.all(np.isfinite(last_center)) or not np.all(np.isfinite(prev_center)):
                _append_center(candidate_detection.center)
                return candidate_detection

            memory_velocity = last_center - prev_center
            if not np.all(np.isfinite(memory_velocity)):
                memory_velocity = np.zeros(2, dtype=np.float64)
            predicted_point = last_center + memory_velocity
            if not np.all(np.isfinite(predicted_point)):
                predicted_point = memory_center.copy()

            visibility = float(np.clip(float(visibility_score), 0.0, 1.0))
            drift = max(0.0, float(drift_ratio))
            drift_penalty = max(0.0, drift - 1.0)
            visibility_relax_threshold = float(
                np.clip(float(self.cfg.frontier_v72_visibility_relax_threshold), 0.0, 1.0)
            )
            visibility_relax_gain = max(0.0, float(self.cfg.frontier_v72_visibility_relax_gain))
            drift_penalty_gain = max(0.0, float(self.cfg.frontier_v72_drift_penalty_gain))
            verifier_gate = max(0.25, float(self.cfg.frontier_v72_verifier_residual_gate_px))
            relax_scale = 1.0
            if visibility >= visibility_relax_threshold:
                relax_scale += (visibility - visibility_relax_threshold) * visibility_relax_gain
            if v71_refine_delta > 0:
                relax_scale += 0.10 * min(4.0, float(v71_refine_delta))
            verifier_gate = verifier_gate * relax_scale / (1.0 + drift_penalty_gain * drift_penalty)
            verifier_gate = max(0.25, float(verifier_gate))

            blend = float(np.clip(float(self.cfg.frontier_v72_teacher_blend), 0.0, 1.0))
            teacher_point = candidate_point * (1.0 - blend) + memory_center * blend
            if v71_reject_delta > 0:
                teacher_point = teacher_point * 0.75 + predicted_point * 0.25
            if not np.all(np.isfinite(teacher_point)):
                teacher_point = memory_center.copy()
            consensus_point = (teacher_point + predicted_point + memory_center) / 3.0

            max_offset = max(0.25, float(self.cfg.frontier_v72_max_offset_px))

            def _score(point: np.ndarray) -> Tuple[float, float, float, float]:
                residual = float(np.linalg.norm(point - memory_center))
                trend_residual = float(np.linalg.norm(point - predicted_point))
                candidate_shift = float(np.linalg.norm(point - candidate_point))
                score = 1.0
                score -= residual / (verifier_gate * 1.60)
                score -= trend_residual / (verifier_gate * 1.40)
                score -= candidate_shift / (max_offset * 2.20)
                if not np.isfinite(score):
                    score = -1e6
                return float(score), float(residual), float(trend_residual), float(candidate_shift)

            hypotheses = {
                "candidate": candidate_point,
                "teacher": teacher_point,
                "predicted": predicted_point,
                "consensus": consensus_point,
            }
            scored: List[Tuple[str, float, float, float, float]] = []
            for name, point in hypotheses.items():
                if not np.all(np.isfinite(point)):
                    continue
                score, residual, trend_residual, candidate_shift = _score(point)
                scored.append((name, score, residual, trend_residual, candidate_shift))
            if len(scored) < 2:
                _append_center(candidate_detection.center)
                return candidate_detection
            scored.sort(key=lambda item: item[1], reverse=True)
            best_name, best_score, best_residual, best_trend_residual, best_candidate_shift = scored[0]
            second_score = scored[1][1]
            agreement = float(np.clip(best_score - second_score, 0.0, 1.0))
            agreement_min = float(np.clip(float(self.cfg.frontier_v72_verifier_agreement_min), 0.0, 1.0))

            score_values = np.asarray([item[1] for item in scored], dtype=np.float64)
            score_values = score_values - float(np.nanmax(score_values))
            score_values = np.clip(score_values, -12.0, 12.0)
            weights = np.exp(score_values)
            weight_sum = float(np.sum(weights))
            if weight_sum > 0 and np.isfinite(weight_sum):
                probs = weights / weight_sum
                entropy = float(
                    -np.sum(probs * np.log(np.clip(probs, 1e-12, 1.0))) / np.log(max(2, probs.size))
                )
            else:
                entropy = 1.0
            entropy = float(np.clip(entropy, 0.0, 1.0))
            entropy_ema = float(self._frontier_v72_teacher_entropy_ema)
            entropy_ema = entropy_ema * 0.80 + entropy * 0.20
            self._frontier_v72_teacher_entropy_ema = entropy_ema
            if entropy > max(0.88, entropy_ema + 0.12):
                self._inc_metric("frontier_v72_entropy_spikes")

            if agreement < agreement_min:
                self._inc_metric("frontier_v72_verifier_low_agreement")

            candidate_residual = float(np.linalg.norm(candidate_point - memory_center))
            reject_trigger = (
                candidate_residual > verifier_gate * 1.60
                and agreement < agreement_min * 0.75
                and v71_reject_delta > 0
            )
            if reject_trigger:
                self._inc_metric("frontier_v72_guard_rejects")
                _append_center(candidate_detection.center)
                if self.reporter is not None:
                    self.reporter.event(
                        "frontier_v72_memory_verifier_rejected",
                        candidate_residual_px=round(float(candidate_residual), 6),
                        gate_px=round(float(verifier_gate), 6),
                        agreement=round(float(agreement), 6),
                        agreement_min=round(float(agreement_min), 6),
                        v71_reject_delta=int(v71_reject_delta),
                    )
                return candidate_detection

            should_refine = (
                best_name != "candidate"
                and (
                    agreement >= agreement_min
                    or v71_reject_delta > 0
                    or v71_refine_delta > 0
                )
            )
            if not should_refine:
                _append_center(candidate_detection.center)
                return candidate_detection

            best_point = hypotheses.get(best_name, candidate_point)
            if not np.all(np.isfinite(best_point)):
                _append_center(candidate_detection.center)
                return candidate_detection

            offset = best_point - candidate_point
            offset_norm = float(np.linalg.norm(offset))
            if offset_norm > max_offset and offset_norm > 0:
                best_point = candidate_point + offset * (max_offset / offset_norm)
                offset = best_point - candidate_point
                offset_norm = float(np.linalg.norm(offset))
                best_score, best_residual, best_trend_residual, best_candidate_shift = _score(best_point)

            if not np.isfinite(best_residual) or best_residual > verifier_gate * 1.80:
                self._inc_metric("frontier_v72_guard_rejects")
                _append_center(candidate_detection.center)
                return candidate_detection

            frame_shape = self._last_frame.shape[:2] if self._last_frame is not None else None
            if frame_shape is not None:
                refined_center = self._clip_center(
                    (
                        int(round(float(best_point[0]))),
                        int(round(float(best_point[1]))),
                    ),
                    frame_shape,
                )
                refined_bbox = self._recenter_bbox(candidate_detection.bbox, refined_center, frame_shape)
            else:
                refined_center = (
                    int(round(float(best_point[0]))),
                    int(round(float(best_point[1]))),
                )
                refined_bbox = candidate_detection.bbox

            conf_penalty = float(np.clip(float(self.cfg.frontier_v72_confidence_penalty), 0.0, 1.0))
            conf_boost = max(0.0, float(self.cfg.frontier_v72_confidence_boost))
            refined_conf = float(
                np.clip(
                    float(candidate_detection.confidence) * conf_penalty * conf_boost,
                    0.0,
                    1.0,
                )
            )
            refined = SpotDetection(
                center=refined_center,
                bbox=refined_bbox,
                confidence=refined_conf,
                label=candidate_detection.label,
                class_id=candidate_detection.class_id,
            )
            if best_name != "candidate":
                self._inc_metric("frontier_v72_teacher_switches")
            self._inc_metric("frontier_v72_guard_refines")
            self._inc_metric("frontier_v72_guard_soft_accepts")
            _append_center(refined.center)
            if self.reporter is not None:
                self.reporter.event(
                    "frontier_v72_memory_verifier_refined",
                    selected=str(best_name),
                    verifier_gate_px=round(float(verifier_gate), 6),
                    agreement=round(float(agreement), 6),
                    agreement_min=round(float(agreement_min), 6),
                    entropy=round(float(entropy), 6),
                    entropy_ema=round(float(entropy_ema), 6),
                    residual_px=round(float(best_residual), 6),
                    trend_residual_px=round(float(best_trend_residual), 6),
                    candidate_shift_px=round(float(best_candidate_shift), 6),
                    target_shift_px=round(float(offset_norm), 6),
                    v71_refine_delta=int(v71_refine_delta),
                    v71_reject_delta=int(v71_reject_delta),
                )
            return refined
        except Exception as exc:
            self._inc_metric("frontier_v72_guard_failures")
            LOGGER.warning("Frontier v72 memory-verifier guard failed; bypassing: %s", exc)
            if self.reporter is not None:
                self.reporter.event("frontier_v72_memory_verifier_failed", error=str(exc))
            return candidate_detection

    def _apply_frontier_v73_retrack_guard(
        self,
        *,
        base_detection: SpotDetection,
        candidate_detection: SpotDetection,
    ) -> SpotDetection:
        if not self.cfg.frontier_v73_retrack_guard_enabled or self._last_frame is None:
            return candidate_detection
        self._inc_metric("frontier_v73_guard_checks")
        try:
            reporter_metrics = getattr(self.reporter, "metrics", None)
            current_low_agreement = int(getattr(reporter_metrics, "frontier_v72_verifier_low_agreement", 0))
            current_v72_rejects = int(getattr(reporter_metrics, "frontier_v72_guard_rejects", 0))
            low_agreement_delta = max(0, current_low_agreement - int(self._frontier_v73_last_v72_low_agreement))
            v72_reject_delta = max(0, current_v72_rejects - int(self._frontier_v73_last_v72_rejects))
            self._frontier_v73_last_v72_low_agreement = current_low_agreement
            self._frontier_v73_last_v72_rejects = current_v72_rejects

            if low_agreement_delta > 0:
                self._frontier_v73_low_agreement_streak += int(low_agreement_delta)
            else:
                self._frontier_v73_low_agreement_streak = max(0, int(self._frontier_v73_low_agreement_streak) - 1)

            current_gray = self._to_grayscale(self._last_frame)
            if not isinstance(current_gray, np.ndarray) or current_gray.size == 0:
                return candidate_detection
            if current_gray.ndim != 2:
                current_gray = cv2.cvtColor(current_gray, cv2.COLOR_BGR2GRAY)

            candidate_point = np.asarray(
                [float(candidate_detection.center[0]), float(candidate_detection.center[1])],
                dtype=np.float64,
            )
            if not np.all(np.isfinite(candidate_point)):
                return candidate_detection

            trigger_streak = max(1, int(self.cfg.frontier_v73_low_agreement_streak_trigger))
            triggered = (
                int(self._frontier_v73_low_agreement_streak) >= trigger_streak
                or v72_reject_delta > 0
            )
            if not triggered:
                self._frontier_v73_prev_gray = current_gray.copy()
                self._frontier_v73_prev_center = candidate_point.copy()
                return candidate_detection

            self._inc_metric("frontier_v73_triggered")

            prev_gray = self._frontier_v73_prev_gray
            prev_center = self._frontier_v73_prev_center
            if (
                not isinstance(prev_gray, np.ndarray)
                or prev_gray.size == 0
                or prev_center is None
                or not np.all(np.isfinite(prev_center))
                or prev_gray.shape != current_gray.shape
            ):
                self._frontier_v73_prev_gray = current_gray.copy()
                self._frontier_v73_prev_center = candidate_point.copy()
                return candidate_detection

            patch_radius = max(4, int(self.cfg.frontier_v73_patch_radius_px))
            search_radius = max(patch_radius + 2, int(self.cfg.frontier_v73_search_radius_px))
            min_match_score = float(np.clip(float(self.cfg.frontier_v73_min_match_score), -1.0, 1.0))
            max_shift = max(0.25, float(self.cfg.frontier_v73_max_shift_px))

            height, width = current_gray.shape[:2]
            prev_x = int(round(float(prev_center[0])))
            prev_y = int(round(float(prev_center[1])))
            tx0 = max(0, prev_x - patch_radius)
            ty0 = max(0, prev_y - patch_radius)
            tx1 = min(width, prev_x + patch_radius + 1)
            ty1 = min(height, prev_y + patch_radius + 1)
            template = prev_gray[ty0:ty1, tx0:tx1]
            if template.shape[0] < 6 or template.shape[1] < 6:
                self._frontier_v73_prev_gray = current_gray.copy()
                self._frontier_v73_prev_center = candidate_point.copy()
                return candidate_detection

            cand_x = int(round(float(candidate_point[0])))
            cand_y = int(round(float(candidate_point[1])))
            sx0 = max(0, cand_x - search_radius)
            sy0 = max(0, cand_y - search_radius)
            sx1 = min(width, cand_x + search_radius + 1)
            sy1 = min(height, cand_y + search_radius + 1)
            search = current_gray[sy0:sy1, sx0:sx1]
            if search.shape[0] < template.shape[0] or search.shape[1] < template.shape[1]:
                self._frontier_v73_prev_gray = current_gray.copy()
                self._frontier_v73_prev_center = candidate_point.copy()
                return candidate_detection

            self._inc_metric("frontier_v73_match_attempts")
            response = cv2.matchTemplate(search, template, cv2.TM_CCOEFF_NORMED)
            if response.size == 0:
                self._frontier_v73_prev_gray = current_gray.copy()
                self._frontier_v73_prev_center = candidate_point.copy()
                return candidate_detection
            _, max_val, _, max_loc = cv2.minMaxLoc(response)
            match_score = float(max_val)
            if not np.isfinite(match_score) or match_score < min_match_score:
                self._inc_metric("frontier_v73_match_low_score")
                self._inc_metric("frontier_v73_guard_rejects")
                self._frontier_v73_prev_gray = current_gray.copy()
                self._frontier_v73_prev_center = candidate_point.copy()
                if self.reporter is not None:
                    self.reporter.event(
                        "frontier_v73_retrack_low_score",
                        match_score=round(float(match_score), 6) if np.isfinite(match_score) else None,
                        min_match_score=round(float(min_match_score), 6),
                        streak=int(self._frontier_v73_low_agreement_streak),
                    )
                return candidate_detection

            match_x = sx0 + int(max_loc[0]) + 0.5 * float(template.shape[1] - 1)
            match_y = sy0 + int(max_loc[1]) + 0.5 * float(template.shape[0] - 1)
            matched_point = np.asarray([match_x, match_y], dtype=np.float64)
            if not np.all(np.isfinite(matched_point)):
                self._frontier_v73_prev_gray = current_gray.copy()
                self._frontier_v73_prev_center = candidate_point.copy()
                return candidate_detection

            shift = matched_point - candidate_point
            shift_norm = float(np.linalg.norm(shift))
            if shift_norm > max_shift and shift_norm > 0:
                matched_point = candidate_point + shift * (max_shift / shift_norm)
                shift = matched_point - candidate_point
                shift_norm = float(np.linalg.norm(shift))
            if not np.isfinite(shift_norm):
                self._frontier_v73_prev_gray = current_gray.copy()
                self._frontier_v73_prev_center = candidate_point.copy()
                return candidate_detection

            if shift_norm < 0.75:
                self._inc_metric("frontier_v73_guard_soft_accepts")
                self._frontier_v73_prev_gray = current_gray.copy()
                self._frontier_v73_prev_center = candidate_point.copy()
                return candidate_detection

            refined_center = self._clip_center(
                (int(round(float(matched_point[0]))), int(round(float(matched_point[1])))),
                current_gray.shape[:2],
            )
            refined_bbox = self._recenter_bbox(
                candidate_detection.bbox,
                refined_center,
                current_gray.shape[:2],
            )
            conf_penalty = float(np.clip(float(self.cfg.frontier_v73_confidence_penalty), 0.0, 1.0))
            conf_boost = max(0.0, float(self.cfg.frontier_v73_confidence_boost))
            score_gain = 1.0 + max(0.0, match_score - min_match_score)
            refined_conf = float(
                np.clip(float(candidate_detection.confidence) * conf_penalty * conf_boost * score_gain, 0.0, 1.0)
            )
            refined = SpotDetection(
                center=refined_center,
                bbox=refined_bbox,
                confidence=refined_conf,
                label=candidate_detection.label,
                class_id=candidate_detection.class_id,
            )
            self._inc_metric("frontier_v73_match_success")
            self._inc_metric("frontier_v73_guard_refines")
            self._inc_metric("frontier_v73_guard_soft_accepts")
            self._frontier_v73_prev_gray = current_gray.copy()
            self._frontier_v73_prev_center = np.asarray(
                [float(refined.center[0]), float(refined.center[1])],
                dtype=np.float64,
            )
            if self.reporter is not None:
                self.reporter.event(
                    "frontier_v73_retrack_refined",
                    match_score=round(float(match_score), 6),
                    min_match_score=round(float(min_match_score), 6),
                    shift_px=round(float(shift_norm), 6),
                    streak=int(self._frontier_v73_low_agreement_streak),
                    v72_reject_delta=int(v72_reject_delta),
                )
            return refined
        except Exception as exc:
            self._inc_metric("frontier_v73_guard_failures")
            LOGGER.warning("Frontier v73 retrack guard failed; bypassing: %s", exc)
            if self.reporter is not None:
                self.reporter.event("frontier_v73_retrack_failed", error=str(exc))
            return candidate_detection

    def _apply_frontier_v74_adaptive_retrack_guard(
        self,
        *,
        base_detection: SpotDetection,
        candidate_detection: SpotDetection,
    ) -> SpotDetection:
        if not self.cfg.frontier_v74_adaptive_retrack_guard_enabled or self._last_frame is None:
            return candidate_detection
        self._inc_metric("frontier_v74_guard_checks")
        try:
            reporter_metrics = getattr(self.reporter, "metrics", None)
            current_v73_triggered = int(getattr(reporter_metrics, "frontier_v73_triggered", 0))
            current_v73_refines = int(getattr(reporter_metrics, "frontier_v73_guard_refines", 0))
            current_v73_rejects = int(getattr(reporter_metrics, "frontier_v73_guard_rejects", 0))
            triggered_delta = max(0, current_v73_triggered - int(self._frontier_v74_last_v73_triggered))
            refined_delta = max(0, current_v73_refines - int(self._frontier_v74_last_v73_refines))
            rejected_delta = max(0, current_v73_rejects - int(self._frontier_v74_last_v73_rejects))
            self._frontier_v74_last_v73_triggered = current_v73_triggered
            self._frontier_v74_last_v73_refines = current_v73_refines
            self._frontier_v74_last_v73_rejects = current_v73_rejects

            if triggered_delta <= 0 and refined_delta <= 0 and rejected_delta <= 0:
                return candidate_detection

            budget_cap = max(1, int(self.cfg.frontier_v74_trigger_budget))
            if triggered_delta > 0:
                self._frontier_v74_budget_remaining = budget_cap
            elif rejected_delta > 0 and self._frontier_v74_budget_remaining <= 0:
                self._frontier_v74_budget_remaining = 1

            if self._frontier_v74_cooldown_remaining > 0:
                self._frontier_v74_cooldown_remaining -= 1
                self._inc_metric("frontier_v74_cooldown_skips")
                return candidate_detection

            if self._frontier_v74_budget_remaining <= 0:
                self._inc_metric("frontier_v74_budget_skips")
                return candidate_detection

            self._inc_metric("frontier_v74_triggered")

            current_gray = self._to_grayscale(self._last_frame)
            if not isinstance(current_gray, np.ndarray) or current_gray.size == 0:
                return candidate_detection
            if current_gray.ndim != 2:
                current_gray = cv2.cvtColor(current_gray, cv2.COLOR_BGR2GRAY)

            prev_gray = self._frontier_v73_prev_gray
            prev_center = self._frontier_v73_prev_center
            if (
                not isinstance(prev_gray, np.ndarray)
                or prev_gray.size == 0
                or prev_center is None
                or not np.all(np.isfinite(prev_center))
                or prev_gray.shape != current_gray.shape
            ):
                self._inc_metric("frontier_v74_guard_soft_accepts")
                return candidate_detection

            candidate_point = np.asarray(
                [float(candidate_detection.center[0]), float(candidate_detection.center[1])],
                dtype=np.float64,
            )
            if not np.all(np.isfinite(candidate_point)):
                self._inc_metric("frontier_v74_guard_soft_accepts")
                return candidate_detection

            patch_radius = max(4, int(self.cfg.frontier_v73_patch_radius_px))
            base_search = max(patch_radius + 2, int(self.cfg.frontier_v73_search_radius_px))
            dyn_gain = max(0.0, float(self.cfg.frontier_v74_dynamic_search_gain))
            dyn_max = max(base_search, int(self.cfg.frontier_v74_dynamic_search_max_px))
            history_shift = float(np.mean(self._frontier_v74_shift_history)) if self._frontier_v74_shift_history else 0.0
            stress_signal = float(max(0, triggered_delta) + max(0, rejected_delta))
            dynamic_extra = int(round((history_shift + stress_signal) * dyn_gain))
            dynamic_extra = max(0, dynamic_extra)
            search_radius = min(dyn_max, base_search + dynamic_extra)
            search_radius = max(patch_radius + 2, int(search_radius))
            self._inc_metric("frontier_v74_dynamic_search_used")

            height, width = current_gray.shape[:2]
            prev_x = int(round(float(prev_center[0])))
            prev_y = int(round(float(prev_center[1])))
            tx0 = max(0, prev_x - patch_radius)
            ty0 = max(0, prev_y - patch_radius)
            tx1 = min(width, prev_x + patch_radius + 1)
            ty1 = min(height, prev_y + patch_radius + 1)
            template = prev_gray[ty0:ty1, tx0:tx1]
            if template.shape[0] < 6 or template.shape[1] < 6:
                self._inc_metric("frontier_v74_guard_soft_accepts")
                return candidate_detection

            cand_x = int(round(float(candidate_point[0])))
            cand_y = int(round(float(candidate_point[1])))
            sx0 = max(0, cand_x - search_radius)
            sy0 = max(0, cand_y - search_radius)
            sx1 = min(width, cand_x + search_radius + 1)
            sy1 = min(height, cand_y + search_radius + 1)
            search = current_gray[sy0:sy1, sx0:sx1]
            if search.shape[0] < template.shape[0] or search.shape[1] < template.shape[1]:
                self._inc_metric("frontier_v74_guard_soft_accepts")
                return candidate_detection

            response = cv2.matchTemplate(search, template, cv2.TM_CCOEFF_NORMED)
            if response.size == 0:
                self._inc_metric("frontier_v74_guard_soft_accepts")
                return candidate_detection
            _, match_score, _, max_loc = cv2.minMaxLoc(response)
            match_score = float(match_score)

            response_flat = response.reshape(-1).astype(np.float64, copy=False)
            peak_idx = int(np.argmax(response_flat))
            peak_val = float(response_flat[peak_idx]) if response_flat.size > 0 else float(match_score)
            if response_flat.size <= 1:
                psr = float("inf")
            else:
                sidelobe = np.delete(response_flat, peak_idx)
                side_mean = float(np.mean(sidelobe))
                side_std = float(np.std(sidelobe))
                psr = (peak_val - side_mean) / max(side_std, 1e-6)
            psr_min = max(0.0, float(self.cfg.frontier_v74_psr_min))
            if not np.isfinite(psr) or psr < psr_min:
                self._inc_metric("frontier_v74_psr_rejects")
                self._inc_metric("frontier_v74_guard_rejects")
                self._frontier_v74_cooldown_remaining = max(0, int(self.cfg.frontier_v74_cooldown_frames))
                self._frontier_v74_budget_remaining = max(0, int(self._frontier_v74_budget_remaining) - 1)
                if self.reporter is not None:
                    self.reporter.event(
                        "frontier_v74_psr_rejected",
                        psr=None if not np.isfinite(psr) else round(float(psr), 6),
                        psr_min=round(float(psr_min), 6),
                        match_score=None if not np.isfinite(match_score) else round(float(match_score), 6),
                        search_radius_px=int(search_radius),
                    )
                return candidate_detection

            match_x = sx0 + int(max_loc[0]) + 0.5 * float(template.shape[1] - 1)
            match_y = sy0 + int(max_loc[1]) + 0.5 * float(template.shape[0] - 1)
            matched_point = np.asarray([match_x, match_y], dtype=np.float64)
            if not np.all(np.isfinite(matched_point)):
                self._inc_metric("frontier_v74_guard_soft_accepts")
                return candidate_detection

            max_shift = max(0.25, float(self.cfg.frontier_v73_max_shift_px))
            shift = matched_point - candidate_point
            shift_norm = float(np.linalg.norm(shift))
            if shift_norm > max_shift and shift_norm > 0:
                matched_point = candidate_point + shift * (max_shift / shift_norm)
                shift = matched_point - candidate_point
                shift_norm = float(np.linalg.norm(shift))
            if not np.isfinite(shift_norm):
                self._inc_metric("frontier_v74_guard_soft_accepts")
                return candidate_detection

            self._frontier_v74_shift_history.append(float(shift_norm))
            if shift_norm < 0.60:
                self._inc_metric("frontier_v74_guard_soft_accepts")
                self._frontier_v74_cooldown_remaining = max(0, int(self.cfg.frontier_v74_cooldown_frames))
                self._frontier_v74_budget_remaining = max(0, int(self._frontier_v74_budget_remaining) - 1)
                return candidate_detection

            refined_center = self._clip_center(
                (int(round(float(matched_point[0]))), int(round(float(matched_point[1])))),
                current_gray.shape[:2],
            )
            refined_bbox = self._recenter_bbox(
                candidate_detection.bbox,
                refined_center,
                current_gray.shape[:2],
            )
            conf_penalty = float(np.clip(float(self.cfg.frontier_v74_confidence_penalty), 0.0, 1.0))
            conf_boost = max(0.0, float(self.cfg.frontier_v74_confidence_boost))
            refined_conf = float(
                np.clip(float(candidate_detection.confidence) * conf_penalty * conf_boost, 0.0, 1.0)
            )
            refined = SpotDetection(
                center=refined_center,
                bbox=refined_bbox,
                confidence=refined_conf,
                label=candidate_detection.label,
                class_id=candidate_detection.class_id,
            )
            self._inc_metric("frontier_v74_guard_refines")
            self._frontier_v74_cooldown_remaining = max(0, int(self.cfg.frontier_v74_cooldown_frames))
            self._frontier_v74_budget_remaining = max(0, int(self._frontier_v74_budget_remaining) - 1)
            if self.reporter is not None:
                self.reporter.event(
                    "frontier_v74_adaptive_retrack_refined",
                    shift_px=round(float(shift_norm), 6),
                    search_radius_px=int(search_radius),
                    dynamic_extra_px=int(dynamic_extra),
                    psr=round(float(psr), 6),
                    match_score=round(float(match_score), 6),
                    cooldown_remaining=int(self._frontier_v74_cooldown_remaining),
                    budget_remaining=int(self._frontier_v74_budget_remaining),
                )
            return refined
        except Exception as exc:
            self._inc_metric("frontier_v74_guard_failures")
            LOGGER.warning("Frontier v74 adaptive retrack guard failed; bypassing: %s", exc)
            if self.reporter is not None:
                self.reporter.event("frontier_v74_adaptive_retrack_failed", error=str(exc))
            return candidate_detection

    def _apply_frontier_v75_bidirectional_retrack_guard(
        self,
        *,
        base_detection: SpotDetection,
        candidate_detection: SpotDetection,
    ) -> SpotDetection:
        if not self.cfg.frontier_v75_bidirectional_retrack_guard_enabled or self._last_frame is None:
            return candidate_detection
        self._inc_metric("frontier_v75_guard_checks")
        try:
            reporter_metrics = getattr(self.reporter, "metrics", None)
            current_v74_triggered = int(getattr(reporter_metrics, "frontier_v74_triggered", 0))
            current_v74_refines = int(getattr(reporter_metrics, "frontier_v74_guard_refines", 0))
            current_v74_rejects = int(getattr(reporter_metrics, "frontier_v74_guard_rejects", 0))
            current_v74_psr_rejects = int(getattr(reporter_metrics, "frontier_v74_psr_rejects", 0))
            v74_trigger_delta = max(0, current_v74_triggered - int(self._frontier_v75_last_v74_triggered))
            v74_refine_delta = max(0, current_v74_refines - int(self._frontier_v75_last_v74_refines))
            v74_reject_delta = max(0, current_v74_rejects - int(self._frontier_v75_last_v74_rejects))
            v74_psr_reject_delta = max(0, current_v74_psr_rejects - int(self._frontier_v75_last_v74_psr_rejects))
            self._frontier_v75_last_v74_triggered = current_v74_triggered
            self._frontier_v75_last_v74_refines = current_v74_refines
            self._frontier_v75_last_v74_rejects = current_v74_rejects
            self._frontier_v75_last_v74_psr_rejects = current_v74_psr_rejects

            should_intervene = (
                v74_reject_delta > 0
                or v74_psr_reject_delta > 0
                or (v74_trigger_delta > 0 and v74_refine_delta <= 0)
            )
            if not should_intervene:
                return candidate_detection

            self._inc_metric("frontier_v75_triggered")

            current_gray = self._to_grayscale(self._last_frame)
            if not isinstance(current_gray, np.ndarray) or current_gray.size == 0:
                self._inc_metric("frontier_v75_guard_soft_accepts")
                return candidate_detection
            if current_gray.ndim != 2:
                current_gray = cv2.cvtColor(current_gray, cv2.COLOR_BGR2GRAY)

            prev_gray = self._frontier_v73_prev_gray
            prev_center = self._frontier_v73_prev_center
            if (
                not isinstance(prev_gray, np.ndarray)
                or prev_gray.size == 0
                or prev_center is None
                or not np.all(np.isfinite(prev_center))
                or prev_gray.shape != current_gray.shape
            ):
                self._inc_metric("frontier_v75_guard_soft_accepts")
                return candidate_detection

            candidate_point = np.asarray(
                [float(candidate_detection.center[0]), float(candidate_detection.center[1])],
                dtype=np.float64,
            )
            if not np.all(np.isfinite(candidate_point)):
                self._inc_metric("frontier_v75_guard_soft_accepts")
                return candidate_detection

            patch_radius = max(4, int(self.cfg.frontier_v73_patch_radius_px))
            base_search = max(patch_radius + 2, int(self.cfg.frontier_v73_search_radius_px))
            dyn_cap = max(base_search, int(self.cfg.frontier_v74_dynamic_search_max_px))
            history_shift = float(np.mean(self._frontier_v74_shift_history)) if self._frontier_v74_shift_history else 0.0
            stress = float(max(0, v74_reject_delta) + max(0, v74_psr_reject_delta))
            search_radius = base_search + int(round(0.25 * max(0.0, history_shift) + 2.0 * stress))
            search_radius = int(max(patch_radius + 2, min(dyn_cap, search_radius)))

            height, width = current_gray.shape[:2]
            prev_x = int(round(float(prev_center[0])))
            prev_y = int(round(float(prev_center[1])))
            tx0 = max(0, prev_x - patch_radius)
            ty0 = max(0, prev_y - patch_radius)
            tx1 = min(width, prev_x + patch_radius + 1)
            ty1 = min(height, prev_y + patch_radius + 1)
            template = prev_gray[ty0:ty1, tx0:tx1]
            if template.shape[0] < 6 or template.shape[1] < 6:
                self._inc_metric("frontier_v75_guard_soft_accepts")
                return candidate_detection

            cand_x = int(round(float(candidate_point[0])))
            cand_y = int(round(float(candidate_point[1])))
            sx0 = max(0, cand_x - search_radius)
            sy0 = max(0, cand_y - search_radius)
            sx1 = min(width, cand_x + search_radius + 1)
            sy1 = min(height, cand_y + search_radius + 1)
            search = current_gray[sy0:sy1, sx0:sx1]
            if search.shape[0] < template.shape[0] or search.shape[1] < template.shape[1]:
                self._inc_metric("frontier_v75_guard_soft_accepts")
                return candidate_detection

            response = cv2.matchTemplate(search, template, cv2.TM_CCOEFF_NORMED)
            if response.size == 0:
                self._inc_metric("frontier_v75_guard_soft_accepts")
                return candidate_detection

            response_flat = response.reshape(-1).astype(np.float64, copy=False)
            peak_idx = int(np.argmax(response_flat))
            peak_val = float(response_flat[peak_idx]) if response_flat.size > 0 else float("nan")
            if response_flat.size > 1:
                response_2 = response_flat.copy()
                response_2[peak_idx] = -float("inf")
                second_val = float(np.max(response_2))
            else:
                second_val = -float("inf")
            peak_margin = float(peak_val - second_val) if np.isfinite(peak_val) and np.isfinite(second_val) else float("inf")
            min_peak_margin = max(0.0, float(self.cfg.frontier_v75_min_peak_margin))
            if (not np.isfinite(peak_val)) or (not np.isfinite(peak_margin)) or peak_margin < min_peak_margin:
                self._inc_metric("frontier_v75_ambiguity_rejects")
                self._inc_metric("frontier_v75_guard_rejects")
                if self.reporter is not None:
                    self.reporter.event(
                        "frontier_v75_ambiguous_peak_rejected",
                        peak_val=None if not np.isfinite(peak_val) else round(float(peak_val), 6),
                        second_val=None if not np.isfinite(second_val) else round(float(second_val), 6),
                        peak_margin=None if not np.isfinite(peak_margin) else round(float(peak_margin), 6),
                        min_peak_margin=round(float(min_peak_margin), 6),
                        search_radius_px=int(search_radius),
                    )
                return candidate_detection

            _, match_score, _, max_loc = cv2.minMaxLoc(response)
            match_score = float(match_score)
            match_x = sx0 + int(max_loc[0]) + 0.5 * float(template.shape[1] - 1)
            match_y = sy0 + int(max_loc[1]) + 0.5 * float(template.shape[0] - 1)
            matched_point = np.asarray([match_x, match_y], dtype=np.float64)
            if not np.all(np.isfinite(matched_point)):
                self._inc_metric("frontier_v75_guard_soft_accepts")
                return candidate_detection

            templ_h, templ_w = template.shape[:2]
            half_w = templ_w // 2
            half_h = templ_h // 2
            match_cx = int(round(float(matched_point[0])))
            match_cy = int(round(float(matched_point[1])))
            cx0 = match_cx - half_w
            cy0 = match_cy - half_h
            cx1 = cx0 + templ_w
            cy1 = cy0 + templ_h
            if cx0 < 0 or cy0 < 0 or cx1 > width or cy1 > height:
                self._inc_metric("frontier_v75_guard_soft_accepts")
                return candidate_detection
            current_patch = current_gray[cy0:cy1, cx0:cx1]
            if current_patch.shape != template.shape:
                self._inc_metric("frontier_v75_guard_soft_accepts")
                return candidate_detection

            phase_response = float("nan")
            try:
                _, phase_response = cv2.phaseCorrelate(
                    template.astype(np.float32, copy=False),
                    current_patch.astype(np.float32, copy=False),
                )
            except Exception:
                phase_response = float("nan")
            phase_min = max(0.0, float(self.cfg.frontier_v75_phase_response_min))
            if np.isfinite(phase_response) and phase_response < phase_min:
                self._inc_metric("frontier_v75_phase_rejects")
                self._inc_metric("frontier_v75_guard_rejects")
                if self.reporter is not None:
                    self.reporter.event(
                        "frontier_v75_phase_rejected",
                        phase_response=round(float(phase_response), 6),
                        phase_min=round(float(phase_min), 6),
                        peak_margin=round(float(peak_margin), 6),
                    )
                return candidate_detection

            back_radius = max(patch_radius + 2, int(round(float(search_radius) * 0.75)))
            bx0 = max(0, prev_x - back_radius)
            by0 = max(0, prev_y - back_radius)
            bx1 = min(width, prev_x + back_radius + 1)
            by1 = min(height, prev_y + back_radius + 1)
            back_search = prev_gray[by0:by1, bx0:bx1]
            if back_search.shape[0] < current_patch.shape[0] or back_search.shape[1] < current_patch.shape[1]:
                self._inc_metric("frontier_v75_guard_soft_accepts")
                return candidate_detection

            back_response = cv2.matchTemplate(back_search, current_patch, cv2.TM_CCOEFF_NORMED)
            if back_response.size == 0:
                self._inc_metric("frontier_v75_guard_soft_accepts")
                return candidate_detection
            _, _, _, back_loc = cv2.minMaxLoc(back_response)
            back_x = bx0 + int(back_loc[0]) + 0.5 * float(current_patch.shape[1] - 1)
            back_y = by0 + int(back_loc[1]) + 0.5 * float(current_patch.shape[0] - 1)
            back_point = np.asarray([back_x, back_y], dtype=np.float64)
            if not np.all(np.isfinite(back_point)):
                self._inc_metric("frontier_v75_guard_soft_accepts")
                return candidate_detection

            backward_error = float(np.linalg.norm(back_point - np.asarray(prev_center, dtype=np.float64)))
            backward_max_error = max(0.25, float(self.cfg.frontier_v75_backward_max_error_px))
            if not np.isfinite(backward_error) or backward_error > backward_max_error:
                self._inc_metric("frontier_v75_backward_rejects")
                self._inc_metric("frontier_v75_guard_rejects")
                if self.reporter is not None:
                    self.reporter.event(
                        "frontier_v75_backward_rejected",
                        backward_error_px=None if not np.isfinite(backward_error) else round(float(backward_error), 6),
                        backward_max_error_px=round(float(backward_max_error), 6),
                        peak_margin=round(float(peak_margin), 6),
                        phase_response=None if not np.isfinite(phase_response) else round(float(phase_response), 6),
                    )
                return candidate_detection

            max_shift = max(0.25, float(self.cfg.frontier_v75_max_shift_px))
            shift = matched_point - candidate_point
            shift_norm = float(np.linalg.norm(shift))
            if shift_norm > max_shift and shift_norm > 0:
                matched_point = candidate_point + shift * (max_shift / shift_norm)
                shift = matched_point - candidate_point
                shift_norm = float(np.linalg.norm(shift))
            if not np.isfinite(shift_norm):
                self._inc_metric("frontier_v75_guard_soft_accepts")
                return candidate_detection

            self._frontier_v74_shift_history.append(float(shift_norm))
            if shift_norm < 0.60:
                self._inc_metric("frontier_v75_guard_soft_accepts")
                self._frontier_v73_prev_gray = current_gray.copy()
                self._frontier_v73_prev_center = candidate_point.copy()
                return candidate_detection

            refined_center = self._clip_center(
                (int(round(float(matched_point[0]))), int(round(float(matched_point[1])))),
                current_gray.shape[:2],
            )
            refined_bbox = self._recenter_bbox(
                candidate_detection.bbox,
                refined_center,
                current_gray.shape[:2],
            )
            conf_penalty = float(np.clip(float(self.cfg.frontier_v75_confidence_penalty), 0.0, 1.0))
            conf_boost = max(0.0, float(self.cfg.frontier_v75_confidence_boost))
            score_gain = 1.0 + min(0.15, max(0.0, float(peak_margin) - float(min_peak_margin)))
            refined_conf = float(
                np.clip(float(candidate_detection.confidence) * conf_penalty * conf_boost * score_gain, 0.0, 1.0)
            )
            refined = SpotDetection(
                center=refined_center,
                bbox=refined_bbox,
                confidence=refined_conf,
                label=candidate_detection.label,
                class_id=candidate_detection.class_id,
            )
            self._frontier_v73_prev_gray = current_gray.copy()
            self._frontier_v73_prev_center = np.asarray(
                [float(refined.center[0]), float(refined.center[1])],
                dtype=np.float64,
            )
            self._inc_metric("frontier_v75_guard_refines")
            if self.reporter is not None:
                self.reporter.event(
                    "frontier_v75_bidirectional_retrack_refined",
                    shift_px=round(float(shift_norm), 6),
                    backward_error_px=round(float(backward_error), 6),
                    peak_margin=round(float(peak_margin), 6),
                    phase_response=None if not np.isfinite(phase_response) else round(float(phase_response), 6),
                    match_score=None if not np.isfinite(match_score) else round(float(match_score), 6),
                    search_radius_px=int(search_radius),
                )
            return refined
        except Exception as exc:
            self._inc_metric("frontier_v75_guard_failures")
            LOGGER.warning("Frontier v75 bidirectional retrack guard failed; bypassing: %s", exc)
            if self.reporter is not None:
                self.reporter.event("frontier_v75_bidirectional_retrack_failed", error=str(exc))
            return candidate_detection

    def _apply_frontier_v76_verifier_fusion_guard(
        self,
        *,
        base_detection: SpotDetection,
        candidate_detection: SpotDetection,
    ) -> SpotDetection:
        if not self.cfg.frontier_v76_verifier_fusion_guard_enabled or self._last_frame is None:
            return candidate_detection
        self._inc_metric("frontier_v76_guard_checks")
        try:
            reporter_metrics = getattr(self.reporter, "metrics", None)
            current_v75_triggered = int(getattr(reporter_metrics, "frontier_v75_triggered", 0))
            current_v75_refines = int(getattr(reporter_metrics, "frontier_v75_guard_refines", 0))
            current_v75_rejects = int(getattr(reporter_metrics, "frontier_v75_guard_rejects", 0))
            current_v75_ambiguity = int(getattr(reporter_metrics, "frontier_v75_ambiguity_rejects", 0))
            current_v75_backward = int(getattr(reporter_metrics, "frontier_v75_backward_rejects", 0))
            current_v75_phase = int(getattr(reporter_metrics, "frontier_v75_phase_rejects", 0))

            v75_trigger_delta = max(0, current_v75_triggered - int(self._frontier_v76_last_v75_triggered))
            v75_refine_delta = max(0, current_v75_refines - int(self._frontier_v76_last_v75_refines))
            v75_reject_delta = max(0, current_v75_rejects - int(self._frontier_v76_last_v75_rejects))
            v75_ambiguity_delta = max(0, current_v75_ambiguity - int(self._frontier_v76_last_v75_ambiguity_rejects))
            v75_backward_delta = max(0, current_v75_backward - int(self._frontier_v76_last_v75_backward_rejects))
            v75_phase_delta = max(0, current_v75_phase - int(self._frontier_v76_last_v75_phase_rejects))

            self._frontier_v76_last_v75_triggered = current_v75_triggered
            self._frontier_v76_last_v75_refines = current_v75_refines
            self._frontier_v76_last_v75_rejects = current_v75_rejects
            self._frontier_v76_last_v75_ambiguity_rejects = current_v75_ambiguity
            self._frontier_v76_last_v75_backward_rejects = current_v75_backward
            self._frontier_v76_last_v75_phase_rejects = current_v75_phase

            stress_signals = (
                max(0, v75_reject_delta)
                + max(0, v75_ambiguity_delta)
                + max(0, v75_backward_delta)
                + max(0, v75_phase_delta)
            )
            should_intervene = (v75_trigger_delta > 0 and v75_refine_delta <= 0) or stress_signals > 0
            if not should_intervene:
                return candidate_detection

            self._inc_metric("frontier_v76_triggered")

            current_gray = self._to_grayscale(self._last_frame)
            if not isinstance(current_gray, np.ndarray) or current_gray.size == 0:
                self._inc_metric("frontier_v76_guard_soft_accepts")
                return candidate_detection
            if current_gray.ndim != 2:
                current_gray = cv2.cvtColor(current_gray, cv2.COLOR_BGR2GRAY)

            prev_gray = self._frontier_v73_prev_gray
            prev_center = self._frontier_v73_prev_center
            if (
                not isinstance(prev_gray, np.ndarray)
                or prev_gray.size == 0
                or prev_center is None
                or not np.all(np.isfinite(prev_center))
                or prev_gray.shape != current_gray.shape
            ):
                self._inc_metric("frontier_v76_guard_soft_accepts")
                return candidate_detection

            candidate_point = np.asarray(
                [float(candidate_detection.center[0]), float(candidate_detection.center[1])],
                dtype=np.float64,
            )
            if not np.all(np.isfinite(candidate_point)):
                self._inc_metric("frontier_v76_guard_soft_accepts")
                return candidate_detection

            patch_radius = max(4, int(self.cfg.frontier_v73_patch_radius_px))
            base_search = max(patch_radius + 2, int(self.cfg.frontier_v73_search_radius_px))
            search_cap = max(base_search, int(self.cfg.frontier_v74_dynamic_search_max_px))
            history_shift = float(np.mean(self._frontier_v74_shift_history)) if self._frontier_v74_shift_history else 0.0
            search_radius = base_search + int(round(0.35 * max(0.0, history_shift) + 1.5 * float(stress_signals)))
            search_radius = int(max(patch_radius + 2, min(search_cap, search_radius)))

            height, width = current_gray.shape[:2]
            prev_x = int(round(float(prev_center[0])))
            prev_y = int(round(float(prev_center[1])))
            tx0 = max(0, prev_x - patch_radius)
            ty0 = max(0, prev_y - patch_radius)
            tx1 = min(width, prev_x + patch_radius + 1)
            ty1 = min(height, prev_y + patch_radius + 1)
            template = prev_gray[ty0:ty1, tx0:tx1]
            if template.shape[0] < 6 or template.shape[1] < 6:
                self._inc_metric("frontier_v76_guard_soft_accepts")
                return candidate_detection

            cand_x = int(round(float(candidate_point[0])))
            cand_y = int(round(float(candidate_point[1])))
            sx0 = max(0, cand_x - search_radius)
            sy0 = max(0, cand_y - search_radius)
            sx1 = min(width, cand_x + search_radius + 1)
            sy1 = min(height, cand_y + search_radius + 1)
            search = current_gray[sy0:sy1, sx0:sx1]
            if search.shape[0] < template.shape[0] or search.shape[1] < template.shape[1]:
                self._inc_metric("frontier_v76_guard_soft_accepts")
                return candidate_detection

            response = cv2.matchTemplate(search, template, cv2.TM_CCOEFF_NORMED)
            if response.size == 0:
                self._inc_metric("frontier_v76_guard_soft_accepts")
                return candidate_detection

            response_flat = response.reshape(-1).astype(np.float64, copy=False)
            peak_idx = int(np.argmax(response_flat))
            peak_val = float(response_flat[peak_idx]) if response_flat.size > 0 else float("nan")
            if response_flat.size > 1:
                response_2 = response_flat.copy()
                response_2[peak_idx] = -float("inf")
                second_val = float(np.max(response_2))
            else:
                second_val = -float("inf")
            peak_margin = float(peak_val - second_val) if np.isfinite(peak_val) and np.isfinite(second_val) else float("nan")

            _, match_score, _, max_loc = cv2.minMaxLoc(response)
            match_score = float(match_score)
            match_x = sx0 + int(max_loc[0]) + 0.5 * float(template.shape[1] - 1)
            match_y = sy0 + int(max_loc[1]) + 0.5 * float(template.shape[0] - 1)
            matched_point = np.asarray([match_x, match_y], dtype=np.float64)
            if not np.all(np.isfinite(matched_point)):
                self._inc_metric("frontier_v76_guard_soft_accepts")
                return candidate_detection

            phase_response = float("nan")
            backward_error = float("nan")
            templ_h, templ_w = template.shape[:2]
            half_w = templ_w // 2
            half_h = templ_h // 2
            match_cx = int(round(float(matched_point[0])))
            match_cy = int(round(float(matched_point[1])))
            cx0 = match_cx - half_w
            cy0 = match_cy - half_h
            cx1 = cx0 + templ_w
            cy1 = cy0 + templ_h
            current_patch = None
            if cx0 >= 0 and cy0 >= 0 and cx1 <= width and cy1 <= height:
                current_patch = current_gray[cy0:cy1, cx0:cx1]
                if isinstance(current_patch, np.ndarray) and current_patch.shape == template.shape:
                    try:
                        _, phase_response = cv2.phaseCorrelate(
                            template.astype(np.float32, copy=False),
                            current_patch.astype(np.float32, copy=False),
                        )
                    except Exception:
                        phase_response = float("nan")

                    back_radius = max(patch_radius + 2, int(round(float(search_radius) * 0.75)))
                    bx0 = max(0, prev_x - back_radius)
                    by0 = max(0, prev_y - back_radius)
                    bx1 = min(width, prev_x + back_radius + 1)
                    by1 = min(height, prev_y + back_radius + 1)
                    back_search = prev_gray[by0:by1, bx0:bx1]
                    if back_search.shape[0] >= current_patch.shape[0] and back_search.shape[1] >= current_patch.shape[1]:
                        back_response = cv2.matchTemplate(back_search, current_patch, cv2.TM_CCOEFF_NORMED)
                        if back_response.size > 0:
                            _, _, _, back_loc = cv2.minMaxLoc(back_response)
                            back_x = bx0 + int(back_loc[0]) + 0.5 * float(current_patch.shape[1] - 1)
                            back_y = by0 + int(back_loc[1]) + 0.5 * float(current_patch.shape[0] - 1)
                            back_point = np.asarray([back_x, back_y], dtype=np.float64)
                            if np.all(np.isfinite(back_point)):
                                backward_error = float(
                                    np.linalg.norm(back_point - np.asarray(prev_center, dtype=np.float64))
                                )

            min_score = float(np.clip(float(self.cfg.frontier_v73_min_match_score), -1.0, 1.0))
            score_denom = max(1e-6, 1.0 - min_score)
            score_component = float(np.clip((match_score - min_score) / score_denom, 0.0, 1.0))
            peak_component = float(np.clip(peak_margin / 0.10, 0.0, 1.0)) if np.isfinite(peak_margin) else 0.0
            phase_component = float(np.clip(phase_response, 0.0, 1.0)) if np.isfinite(phase_response) else 0.4
            backward_max = max(0.25, float(self.cfg.frontier_v75_backward_max_error_px))
            if np.isfinite(backward_error):
                backward_component = float(np.clip(1.0 - (backward_error / max(backward_max, 1e-6)), 0.0, 1.0))
            else:
                backward_component = 0.4

            reliability = float(
                np.clip(
                    0.42 * score_component
                    + 0.26 * peak_component
                    + 0.18 * phase_component
                    + 0.14 * backward_component,
                    0.0,
                    1.0,
                )
            )
            min_reliability = float(np.clip(float(self.cfg.frontier_v76_min_reliability_score), 0.0, 1.0))
            if reliability < min_reliability:
                self._inc_metric("frontier_v76_reliability_rejects")
                self._inc_metric("frontier_v76_guard_rejects")
                if self.reporter is not None:
                    self.reporter.event(
                        "frontier_v76_reliability_rejected",
                        reliability=round(float(reliability), 6),
                        min_reliability=round(float(min_reliability), 6),
                        match_score=None if not np.isfinite(match_score) else round(float(match_score), 6),
                        peak_margin=None if not np.isfinite(peak_margin) else round(float(peak_margin), 6),
                        phase_response=None if not np.isfinite(phase_response) else round(float(phase_response), 6),
                        backward_error_px=None if not np.isfinite(backward_error) else round(float(backward_error), 6),
                        search_radius_px=int(search_radius),
                    )
                return candidate_detection

            blend_min = float(np.clip(float(self.cfg.frontier_v76_blend_strength_min), 0.0, 1.0))
            blend_max = float(np.clip(float(self.cfg.frontier_v76_blend_strength_max), 0.01, 1.0))
            blend_max = max(blend_min, blend_max)
            blend = blend_min + (blend_max - blend_min) * reliability
            stress_scale = max(0.65, 1.0 - min(0.35, 0.08 * float(stress_signals)))
            blend *= stress_scale
            blend = float(np.clip(blend, blend_min, blend_max))

            shift = (matched_point - candidate_point) * blend
            shift_norm = float(np.linalg.norm(shift))
            max_shift = max(0.25, float(self.cfg.frontier_v76_max_shift_px))
            if shift_norm > max_shift and shift_norm > 0:
                shift *= max_shift / shift_norm
                shift_norm = float(np.linalg.norm(shift))
                self._inc_metric("frontier_v76_shift_clamps")
            if not np.isfinite(shift_norm):
                self._inc_metric("frontier_v76_guard_soft_accepts")
                return candidate_detection
            if shift_norm < 0.35:
                self._inc_metric("frontier_v76_guard_soft_accepts")
                self._frontier_v73_prev_gray = current_gray.copy()
                self._frontier_v73_prev_center = candidate_point.copy()
                return candidate_detection

            refined_point = candidate_point + shift
            refined_center = self._clip_center(
                (int(round(float(refined_point[0]))), int(round(float(refined_point[1])))),
                current_gray.shape[:2],
            )
            refined_bbox = self._recenter_bbox(
                candidate_detection.bbox,
                refined_center,
                current_gray.shape[:2],
            )

            conf_penalty = float(np.clip(float(self.cfg.frontier_v76_confidence_penalty), 0.0, 1.0))
            conf_boost = max(0.0, float(self.cfg.frontier_v76_confidence_boost))
            reliability_gain = 1.0 + min(0.10, max(0.0, reliability - min_reliability))
            refined_conf = float(
                np.clip(float(candidate_detection.confidence) * conf_penalty * conf_boost * reliability_gain, 0.0, 1.0)
            )
            refined = SpotDetection(
                center=refined_center,
                bbox=refined_bbox,
                confidence=refined_conf,
                label=candidate_detection.label,
                class_id=candidate_detection.class_id,
            )

            self._frontier_v73_prev_gray = current_gray.copy()
            self._frontier_v73_prev_center = np.asarray(
                [float(refined.center[0]), float(refined.center[1])],
                dtype=np.float64,
            )
            self._frontier_v74_shift_history.append(float(shift_norm))
            self._inc_metric("frontier_v76_guard_refines")
            if self.reporter is not None:
                self.reporter.event(
                    "frontier_v76_verifier_fusion_refined",
                    shift_px=round(float(shift_norm), 6),
                    blend=round(float(blend), 6),
                    reliability=round(float(reliability), 6),
                    match_score=None if not np.isfinite(match_score) else round(float(match_score), 6),
                    peak_margin=None if not np.isfinite(peak_margin) else round(float(peak_margin), 6),
                    phase_response=None if not np.isfinite(phase_response) else round(float(phase_response), 6),
                    backward_error_px=None if not np.isfinite(backward_error) else round(float(backward_error), 6),
                    search_radius_px=int(search_radius),
                )
            return refined
        except Exception as exc:
            self._inc_metric("frontier_v76_guard_failures")
            LOGGER.warning("Frontier v76 verifier-fusion guard failed; bypassing: %s", exc)
            if self.reporter is not None:
                self.reporter.event("frontier_v76_verifier_fusion_failed", error=str(exc))
            return candidate_detection

    def _apply_frontier_v77_hysteresis_guard(
        self,
        *,
        base_detection: SpotDetection,
        candidate_detection: SpotDetection,
    ) -> SpotDetection:
        if not self.cfg.frontier_v77_hysteresis_guard_enabled or self._last_frame is None:
            return candidate_detection
        self._inc_metric("frontier_v77_guard_checks")
        try:
            reporter_metrics = getattr(self.reporter, "metrics", None)
            current_v76_triggered = int(getattr(reporter_metrics, "frontier_v76_triggered", 0))
            current_v76_refines = int(getattr(reporter_metrics, "frontier_v76_guard_refines", 0))
            current_v76_reliability_rejects = int(getattr(reporter_metrics, "frontier_v76_reliability_rejects", 0))

            v76_trigger_delta = max(0, current_v76_triggered - int(self._frontier_v77_last_v76_triggered))
            v76_refine_delta = max(0, current_v76_refines - int(self._frontier_v77_last_v76_refines))
            v76_reject_delta = max(
                0,
                current_v76_reliability_rejects - int(self._frontier_v77_last_v76_reliability_rejects),
            )
            self._frontier_v77_last_v76_triggered = current_v76_triggered
            self._frontier_v77_last_v76_refines = current_v76_refines
            self._frontier_v77_last_v76_reliability_rejects = current_v76_reliability_rejects

            stress_hit = (v76_trigger_delta > 0 and v76_refine_delta <= 0) or v76_reject_delta > 0
            if stress_hit:
                self._frontier_v77_stress_streak = min(12, int(self._frontier_v77_stress_streak) + 1)
                self._inc_metric("frontier_v77_hysteresis_hits")
            else:
                self._frontier_v77_stress_streak = max(0, int(self._frontier_v77_stress_streak) - 1)

            if not stress_hit and self._frontier_v77_stress_streak <= 0:
                return candidate_detection
            self._inc_metric("frontier_v77_triggered")

            current_gray = self._to_grayscale(self._last_frame)
            if not isinstance(current_gray, np.ndarray) or current_gray.size == 0:
                self._inc_metric("frontier_v77_guard_soft_accepts")
                return candidate_detection
            if current_gray.ndim != 2:
                current_gray = cv2.cvtColor(current_gray, cv2.COLOR_BGR2GRAY)

            prev_gray = self._frontier_v73_prev_gray
            prev_center = self._frontier_v73_prev_center
            if (
                not isinstance(prev_gray, np.ndarray)
                or prev_gray.size == 0
                or prev_center is None
                or not np.all(np.isfinite(prev_center))
                or prev_gray.shape != current_gray.shape
            ):
                self._inc_metric("frontier_v77_guard_soft_accepts")
                return candidate_detection

            candidate_point = np.asarray(
                [float(candidate_detection.center[0]), float(candidate_detection.center[1])],
                dtype=np.float64,
            )
            if not np.all(np.isfinite(candidate_point)):
                self._inc_metric("frontier_v77_guard_soft_accepts")
                return candidate_detection

            patch_radius = max(4, int(self.cfg.frontier_v73_patch_radius_px))
            height, width = current_gray.shape[:2]
            prev_x = int(round(float(prev_center[0])))
            prev_y = int(round(float(prev_center[1])))
            tx0 = max(0, prev_x - patch_radius)
            ty0 = max(0, prev_y - patch_radius)
            tx1 = min(width, prev_x + patch_radius + 1)
            ty1 = min(height, prev_y + patch_radius + 1)
            template = prev_gray[ty0:ty1, tx0:tx1]
            if template.shape[0] < 6 or template.shape[1] < 6:
                self._inc_metric("frontier_v77_guard_soft_accepts")
                return candidate_detection

            templ_h, templ_w = template.shape[:2]
            cand_x = int(round(float(candidate_point[0])))
            cand_y = int(round(float(candidate_point[1])))
            cx0 = cand_x - templ_w // 2
            cy0 = cand_y - templ_h // 2
            cx1 = cx0 + templ_w
            cy1 = cy0 + templ_h
            if cx0 < 0 or cy0 < 0 or cx1 > width or cy1 > height:
                self._inc_metric("frontier_v77_guard_soft_accepts")
                return candidate_detection

            current_patch = current_gray[cy0:cy1, cx0:cx1]
            if not isinstance(current_patch, np.ndarray) or current_patch.shape != template.shape:
                self._inc_metric("frontier_v77_guard_soft_accepts")
                return candidate_detection

            template_f = template.astype(np.float32, copy=False)
            current_f = current_patch.astype(np.float32, copy=False)
            phase_shift_xy, phase_response = cv2.phaseCorrelate(template_f, current_f)
            phase_shift = np.asarray(
                [float(phase_shift_xy[0]), float(phase_shift_xy[1])],
                dtype=np.float64,
            )
            if not np.all(np.isfinite(phase_shift)):
                self._inc_metric("frontier_v77_guard_soft_accepts")
                return candidate_detection

            iter_shift = None
            phase_iter_func = getattr(cv2, "phaseCorrelateIterative", None)
            if callable(phase_iter_func):
                try:
                    iter_xy = phase_iter_func(template_f, current_f)
                    if isinstance(iter_xy, (tuple, list)) and len(iter_xy) >= 2:
                        candidate_iter = np.asarray([float(iter_xy[0]), float(iter_xy[1])], dtype=np.float64)
                        if np.all(np.isfinite(candidate_iter)):
                            iter_shift = candidate_iter
                except Exception:
                    iter_shift = None

            shift_vec = phase_shift.copy()
            if iter_shift is not None:
                shift_vec = 0.55 * phase_shift + 0.45 * iter_shift

            if not np.all(np.isfinite(shift_vec)):
                self._inc_metric("frontier_v77_guard_soft_accepts")
                return candidate_detection

            predicted_point = candidate_point.copy()
            history_points = list(self._frontier_v72_center_history)
            if len(history_points) >= 2:
                p_last = np.asarray(history_points[-1], dtype=np.float64)
                p_prev = np.asarray(history_points[-2], dtype=np.float64)
                if np.all(np.isfinite(p_last)) and np.all(np.isfinite(p_prev)):
                    motion_blend = float(np.clip(float(self.cfg.frontier_v77_motion_blend), 0.0, 1.0))
                    velocity = p_last - p_prev
                    predicted_point = p_last + velocity * motion_blend
                    if not np.all(np.isfinite(predicted_point)):
                        predicted_point = candidate_point.copy()

            option_plus = candidate_point + shift_vec
            option_minus = candidate_point - shift_vec
            if np.linalg.norm(option_plus - predicted_point) <= np.linalg.norm(option_minus - predicted_point):
                phase_center = option_plus
            else:
                phase_center = option_minus

            pred_error = float(np.linalg.norm(phase_center - predicted_point))
            consensus_base = max(0.25, float(self.cfg.frontier_v77_consensus_gate_px))
            consensus_gate = float(consensus_base * (1.0 + 0.10 * float(self._frontier_v77_stress_streak)))

            phase_component = float(np.clip(float(phase_response), 0.0, 1.0)) if np.isfinite(phase_response) else 0.0
            if iter_shift is not None:
                iter_gap = float(np.linalg.norm(phase_shift - iter_shift))
                agreement_component = float(np.clip(1.0 - iter_gap / 3.0, 0.0, 1.0))
            else:
                agreement_component = max(0.2, phase_component)
            predict_component = float(np.clip(1.0 - pred_error / max(consensus_gate, 1e-6), 0.0, 1.0))
            streak_component = float(np.clip(float(self._frontier_v77_stress_streak) / 8.0, 0.0, 1.0))
            reliability = float(
                np.clip(
                    0.38 * phase_component
                    + 0.24 * agreement_component
                    + 0.30 * predict_component
                    + 0.08 * streak_component,
                    0.0,
                    1.0,
                )
            )

            base_threshold = float(np.clip(float(self.cfg.frontier_v76_min_reliability_score), 0.0, 1.0))
            relax_per_streak = max(0.0, float(self.cfg.frontier_v77_reliability_relax_per_streak))
            reliability_floor = float(np.clip(float(self.cfg.frontier_v77_reliability_floor), 0.0, 1.0))
            relaxed_threshold = max(
                reliability_floor,
                base_threshold - relax_per_streak * float(self._frontier_v77_stress_streak),
            )
            accept_threshold = base_threshold if reliability >= base_threshold else relaxed_threshold

            if pred_error > consensus_gate:
                self._inc_metric("frontier_v77_consensus_rejects")
                self._inc_metric("frontier_v77_guard_rejects")
                if self.reporter is not None:
                    self.reporter.event(
                        "frontier_v77_consensus_rejected",
                        pred_error_px=round(float(pred_error), 6),
                        consensus_gate_px=round(float(consensus_gate), 6),
                        reliability=round(float(reliability), 6),
                    )
                return candidate_detection

            if reliability < accept_threshold:
                self._inc_metric("frontier_v77_guard_rejects")
                if self.reporter is not None:
                    self.reporter.event(
                        "frontier_v77_reliability_rejected",
                        reliability=round(float(reliability), 6),
                        base_threshold=round(float(base_threshold), 6),
                        relaxed_threshold=round(float(relaxed_threshold), 6),
                        stress_streak=int(self._frontier_v77_stress_streak),
                    )
                return candidate_detection

            shift = phase_center - candidate_point
            shift_norm = float(np.linalg.norm(shift))
            max_shift = max(0.25, float(self.cfg.frontier_v77_max_shift_px))
            if shift_norm > max_shift and shift_norm > 0:
                shift *= max_shift / shift_norm
                shift_norm = float(np.linalg.norm(shift))
                self._inc_metric("frontier_v77_shift_clamps")
            if not np.isfinite(shift_norm):
                self._inc_metric("frontier_v77_guard_soft_accepts")
                return candidate_detection
            if shift_norm < 0.25:
                self._inc_metric("frontier_v77_guard_soft_accepts")
                self._frontier_v73_prev_gray = current_gray.copy()
                self._frontier_v73_prev_center = candidate_point.copy()
                return candidate_detection

            refined_point = candidate_point + shift
            refined_center = self._clip_center(
                (int(round(float(refined_point[0]))), int(round(float(refined_point[1])))),
                current_gray.shape[:2],
            )
            refined_bbox = self._recenter_bbox(
                candidate_detection.bbox,
                refined_center,
                current_gray.shape[:2],
            )

            conf_penalty = float(np.clip(float(self.cfg.frontier_v77_confidence_penalty), 0.0, 1.0))
            conf_boost = max(0.0, float(self.cfg.frontier_v77_confidence_boost))
            reliability_gain = 1.0 + min(0.08, max(0.0, reliability - accept_threshold))
            refined_conf = float(
                np.clip(
                    float(candidate_detection.confidence) * conf_penalty * conf_boost * reliability_gain,
                    0.0,
                    1.0,
                )
            )
            refined = SpotDetection(
                center=refined_center,
                bbox=refined_bbox,
                confidence=refined_conf,
                label=candidate_detection.label,
                class_id=candidate_detection.class_id,
            )
            self._frontier_v73_prev_gray = current_gray.copy()
            self._frontier_v73_prev_center = np.asarray(
                [float(refined.center[0]), float(refined.center[1])],
                dtype=np.float64,
            )
            self._frontier_v74_shift_history.append(float(shift_norm))
            self._inc_metric("frontier_v77_guard_refines")
            if self.reporter is not None:
                self.reporter.event(
                    "frontier_v77_hysteresis_refined",
                    shift_px=round(float(shift_norm), 6),
                    reliability=round(float(reliability), 6),
                    base_threshold=round(float(base_threshold), 6),
                    relaxed_threshold=round(float(relaxed_threshold), 6),
                    phase_response=None if not np.isfinite(phase_response) else round(float(phase_response), 6),
                    pred_error_px=round(float(pred_error), 6),
                    consensus_gate_px=round(float(consensus_gate), 6),
                    stress_streak=int(self._frontier_v77_stress_streak),
                )
            return refined
        except Exception as exc:
            self._inc_metric("frontier_v77_guard_failures")
            LOGGER.warning("Frontier v77 hysteresis guard failed; bypassing: %s", exc)
            if self.reporter is not None:
                self.reporter.event("frontier_v77_hysteresis_failed", error=str(exc))
            return candidate_detection

    def _apply_frontier_v78_consistency_bandit_guard(
        self,
        *,
        base_detection: SpotDetection,
        candidate_detection: SpotDetection,
    ) -> SpotDetection:
        if not self.cfg.frontier_v78_consistency_bandit_guard_enabled or self._last_frame is None:
            return candidate_detection
        self._inc_metric("frontier_v78_guard_checks")
        try:
            reporter_metrics = getattr(self.reporter, "metrics", None)
            current_v77_triggered = int(getattr(reporter_metrics, "frontier_v77_triggered", 0))
            current_v77_refines = int(getattr(reporter_metrics, "frontier_v77_guard_refines", 0))
            current_v77_rejects = int(getattr(reporter_metrics, "frontier_v77_guard_rejects", 0))

            v77_trigger_delta = max(0, current_v77_triggered - int(self._frontier_v78_last_v77_triggered))
            v77_refine_delta = max(0, current_v77_refines - int(self._frontier_v78_last_v77_refines))
            v77_reject_delta = max(0, current_v77_rejects - int(self._frontier_v78_last_v77_rejects))

            self._frontier_v78_last_v77_triggered = current_v77_triggered
            self._frontier_v78_last_v77_refines = current_v77_refines
            self._frontier_v78_last_v77_rejects = current_v77_rejects

            stress_hit = (v77_trigger_delta > 0 and v77_refine_delta <= 0) or v77_reject_delta > 0
            if stress_hit:
                self._frontier_v78_pressure_streak = min(12, int(self._frontier_v78_pressure_streak) + 1)
            else:
                self._frontier_v78_pressure_streak = max(0, int(self._frontier_v78_pressure_streak) - 1)

            if not stress_hit and self._frontier_v78_pressure_streak <= 0:
                return candidate_detection
            self._inc_metric("frontier_v78_triggered")

            current_gray = self._to_grayscale(self._last_frame)
            if not isinstance(current_gray, np.ndarray) or current_gray.size == 0:
                self._inc_metric("frontier_v78_guard_soft_accepts")
                return candidate_detection
            if current_gray.ndim != 2:
                current_gray = cv2.cvtColor(current_gray, cv2.COLOR_BGR2GRAY)

            prev_gray = self._frontier_v73_prev_gray
            prev_center = self._frontier_v73_prev_center
            if (
                not isinstance(prev_gray, np.ndarray)
                or prev_gray.size == 0
                or prev_center is None
                or not np.all(np.isfinite(prev_center))
                or prev_gray.shape != current_gray.shape
            ):
                self._inc_metric("frontier_v78_guard_soft_accepts")
                return candidate_detection

            candidate_point = np.asarray(
                [float(candidate_detection.center[0]), float(candidate_detection.center[1])],
                dtype=np.float64,
            )
            if not np.all(np.isfinite(candidate_point)):
                self._inc_metric("frontier_v78_guard_soft_accepts")
                return candidate_detection

            patch_radius = max(4, int(self.cfg.frontier_v73_patch_radius_px))
            base_search = max(patch_radius + 2, int(self.cfg.frontier_v73_search_radius_px))
            search_cap = max(base_search, int(self.cfg.frontier_v74_dynamic_search_max_px))
            history_shift = float(np.mean(self._frontier_v74_shift_history)) if self._frontier_v74_shift_history else 0.0
            stress_signal = float(max(0, v77_trigger_delta) + 2 * max(0, v77_reject_delta))
            explore_gain = max(0.0, float(self.cfg.frontier_v78_exploration_gain))
            dynamic_extra = int(
                round(
                    explore_gain
                    * (
                        max(0.0, history_shift)
                        + stress_signal
                        + 0.8 * float(self._frontier_v78_pressure_streak)
                    )
                )
            )
            search_radius = int(max(patch_radius + 2, min(search_cap, base_search + max(0, dynamic_extra))))

            height, width = current_gray.shape[:2]
            prev_x = int(round(float(prev_center[0])))
            prev_y = int(round(float(prev_center[1])))
            tx0 = max(0, prev_x - patch_radius)
            ty0 = max(0, prev_y - patch_radius)
            tx1 = min(width, prev_x + patch_radius + 1)
            ty1 = min(height, prev_y + patch_radius + 1)
            template = prev_gray[ty0:ty1, tx0:tx1]
            if template.shape[0] < 6 or template.shape[1] < 6:
                self._inc_metric("frontier_v78_guard_soft_accepts")
                return candidate_detection

            cand_x = int(round(float(candidate_point[0])))
            cand_y = int(round(float(candidate_point[1])))
            sx0 = max(0, cand_x - search_radius)
            sy0 = max(0, cand_y - search_radius)
            sx1 = min(width, cand_x + search_radius + 1)
            sy1 = min(height, cand_y + search_radius + 1)
            search = current_gray[sy0:sy1, sx0:sx1]
            if search.shape[0] < template.shape[0] or search.shape[1] < template.shape[1]:
                self._inc_metric("frontier_v78_guard_soft_accepts")
                return candidate_detection

            response = cv2.matchTemplate(search, template, cv2.TM_CCOEFF_NORMED)
            if response.size == 0:
                self._inc_metric("frontier_v78_guard_soft_accepts")
                return candidate_detection

            response_flat = response.reshape(-1).astype(np.float64, copy=False)
            peak_idx = int(np.argmax(response_flat))
            peak_val = float(response_flat[peak_idx]) if response_flat.size > 0 else float("nan")
            if response_flat.size > 1:
                response_2 = response_flat.copy()
                response_2[peak_idx] = -float("inf")
                second_val = float(np.max(response_2))
            else:
                second_val = -float("inf")
            peak_margin = float(peak_val - second_val) if np.isfinite(peak_val) and np.isfinite(second_val) else float("nan")

            _, match_score, _, max_loc = cv2.minMaxLoc(response)
            match_score = float(match_score)
            match_x = sx0 + int(max_loc[0]) + 0.5 * float(template.shape[1] - 1)
            match_y = sy0 + int(max_loc[1]) + 0.5 * float(template.shape[0] - 1)
            matched_point = np.asarray([match_x, match_y], dtype=np.float64)
            if not np.all(np.isfinite(matched_point)):
                self._inc_metric("frontier_v78_guard_soft_accepts")
                return candidate_detection

            predicted_point = candidate_point.copy()
            history_points = list(self._frontier_v72_center_history)
            if len(history_points) >= 2:
                p_last = np.asarray(history_points[-1], dtype=np.float64)
                p_prev = np.asarray(history_points[-2], dtype=np.float64)
                if np.all(np.isfinite(p_last)) and np.all(np.isfinite(p_prev)):
                    velocity = p_last - p_prev
                    predicted_point = p_last + velocity
                    if not np.all(np.isfinite(predicted_point)):
                        predicted_point = candidate_point.copy()

            templ_h, templ_w = template.shape[:2]
            cx0 = cand_x - templ_w // 2
            cy0 = cand_y - templ_h // 2
            cx1 = cx0 + templ_w
            cy1 = cy0 + templ_h
            phase_response = float("nan")
            phase_center = candidate_point.copy()
            if cx0 >= 0 and cy0 >= 0 and cx1 <= width and cy1 <= height:
                current_patch = current_gray[cy0:cy1, cx0:cx1]
                if isinstance(current_patch, np.ndarray) and current_patch.shape == template.shape:
                    try:
                        shift_xy, phase_response = cv2.phaseCorrelate(
                            template.astype(np.float32, copy=False),
                            current_patch.astype(np.float32, copy=False),
                        )
                        shift_vec = np.asarray([float(shift_xy[0]), float(shift_xy[1])], dtype=np.float64)
                        if np.all(np.isfinite(shift_vec)):
                            plus_point = candidate_point + shift_vec
                            minus_point = candidate_point - shift_vec
                            if np.linalg.norm(plus_point - predicted_point) <= np.linalg.norm(minus_point - predicted_point):
                                phase_center = plus_point
                            else:
                                phase_center = minus_point
                    except Exception:
                        phase_response = float("nan")

            template_weight = float(np.clip(float(self.cfg.frontier_v78_template_weight), 0.0, 1.0))
            streak_gain = min(0.20, 0.03 * float(self._frontier_v78_pressure_streak))
            blend_template = float(np.clip(template_weight + streak_gain, 0.20, 0.90))
            blend_phase = 1.0 - blend_template
            blended_point = matched_point * blend_template + phase_center * blend_phase
            if not np.all(np.isfinite(blended_point)):
                self._inc_metric("frontier_v78_guard_soft_accepts")
                return candidate_detection

            pred_error = float(np.linalg.norm(blended_point - predicted_point))
            consensus_base = max(0.25, float(self.cfg.frontier_v78_consensus_gate_px))
            consensus_gate = float(consensus_base * (1.0 + 0.10 * float(self._frontier_v78_pressure_streak)))

            min_score = float(np.clip(float(self.cfg.frontier_v73_min_match_score), -1.0, 1.0))
            score_denom = max(1e-6, 1.0 - min_score)
            score_component = float(np.clip((match_score - min_score) / score_denom, 0.0, 1.0))
            margin_component = float(np.clip(peak_margin / 0.10, 0.0, 1.0)) if np.isfinite(peak_margin) else 0.0
            phase_component = float(np.clip(phase_response, 0.0, 1.0)) if np.isfinite(phase_response) else 0.35
            consensus_component = float(np.clip(1.0 - pred_error / max(consensus_gate, 1e-6), 0.0, 1.0))
            streak_component = float(np.clip(float(self._frontier_v78_pressure_streak) / 8.0, 0.0, 1.0))
            reliability = float(
                np.clip(
                    0.40 * score_component
                    + 0.20 * margin_component
                    + 0.24 * phase_component
                    + 0.12 * consensus_component
                    + 0.04 * streak_component,
                    0.0,
                    1.0,
                )
            )

            base_threshold = float(np.clip(float(self.cfg.frontier_v76_min_reliability_score), 0.0, 1.0))
            reliability_floor = float(np.clip(float(self.cfg.frontier_v78_reliability_floor), 0.0, 1.0))
            relax_step = max(0.0, float(self.cfg.frontier_v78_exploration_gain)) * 0.22
            relaxed_threshold = max(
                reliability_floor,
                base_threshold - relax_step * float(self._frontier_v78_pressure_streak),
            )
            accept_threshold = base_threshold if reliability >= base_threshold else relaxed_threshold

            if pred_error > consensus_gate:
                self._inc_metric("frontier_v78_consensus_rejects")
                self._inc_metric("frontier_v78_guard_rejects")
                if self.reporter is not None:
                    self.reporter.event(
                        "frontier_v78_consensus_rejected",
                        pred_error_px=round(float(pred_error), 6),
                        consensus_gate_px=round(float(consensus_gate), 6),
                        reliability=round(float(reliability), 6),
                    )
                return candidate_detection

            if reliability < accept_threshold:
                self._inc_metric("frontier_v78_guard_rejects")
                if self.reporter is not None:
                    self.reporter.event(
                        "frontier_v78_reliability_rejected",
                        reliability=round(float(reliability), 6),
                        base_threshold=round(float(base_threshold), 6),
                        relaxed_threshold=round(float(relaxed_threshold), 6),
                        pressure_streak=int(self._frontier_v78_pressure_streak),
                    )
                return candidate_detection

            shift = blended_point - candidate_point
            shift_norm = float(np.linalg.norm(shift))
            max_shift = max(0.25, float(self.cfg.frontier_v78_max_shift_px))
            if shift_norm > max_shift and shift_norm > 0:
                shift *= max_shift / shift_norm
                shift_norm = float(np.linalg.norm(shift))
                self._inc_metric("frontier_v78_shift_clamps")
            if not np.isfinite(shift_norm):
                self._inc_metric("frontier_v78_guard_soft_accepts")
                return candidate_detection
            if shift_norm < 0.20:
                self._inc_metric("frontier_v78_guard_soft_accepts")
                self._frontier_v73_prev_gray = current_gray.copy()
                self._frontier_v73_prev_center = candidate_point.copy()
                return candidate_detection

            refined_point = candidate_point + shift
            refined_center = self._clip_center(
                (int(round(float(refined_point[0]))), int(round(float(refined_point[1])))),
                current_gray.shape[:2],
            )
            refined_bbox = self._recenter_bbox(
                candidate_detection.bbox,
                refined_center,
                current_gray.shape[:2],
            )

            conf_penalty = float(np.clip(float(self.cfg.frontier_v78_confidence_penalty), 0.0, 1.0))
            conf_boost = max(0.0, float(self.cfg.frontier_v78_confidence_boost))
            reliability_gain = 1.0 + min(0.10, max(0.0, reliability - accept_threshold))
            refined_conf = float(
                np.clip(
                    float(candidate_detection.confidence) * conf_penalty * conf_boost * reliability_gain,
                    0.0,
                    1.0,
                )
            )
            refined = SpotDetection(
                center=refined_center,
                bbox=refined_bbox,
                confidence=refined_conf,
                label=candidate_detection.label,
                class_id=candidate_detection.class_id,
            )

            self._frontier_v73_prev_gray = current_gray.copy()
            self._frontier_v73_prev_center = np.asarray(
                [float(refined.center[0]), float(refined.center[1])],
                dtype=np.float64,
            )
            self._frontier_v74_shift_history.append(float(shift_norm))
            self._inc_metric("frontier_v78_guard_refines")
            if self.reporter is not None:
                self.reporter.event(
                    "frontier_v78_consistency_bandit_refined",
                    shift_px=round(float(shift_norm), 6),
                    reliability=round(float(reliability), 6),
                    base_threshold=round(float(base_threshold), 6),
                    relaxed_threshold=round(float(relaxed_threshold), 6),
                    match_score=None if not np.isfinite(match_score) else round(float(match_score), 6),
                    peak_margin=None if not np.isfinite(peak_margin) else round(float(peak_margin), 6),
                    phase_response=None if not np.isfinite(phase_response) else round(float(phase_response), 6),
                    pred_error_px=round(float(pred_error), 6),
                    consensus_gate_px=round(float(consensus_gate), 6),
                    pressure_streak=int(self._frontier_v78_pressure_streak),
                    search_radius_px=int(search_radius),
                )
            return refined
        except Exception as exc:
            self._inc_metric("frontier_v78_guard_failures")
            LOGGER.warning("Frontier v78 consistency-bandit guard failed; bypassing: %s", exc)
            if self.reporter is not None:
                self.reporter.event("frontier_v78_consistency_bandit_failed", error=str(exc))
            return candidate_detection

    def _apply_frontier_v57_assoc(self, detection: SpotDetection) -> SpotDetection:
        assoc_gate = self._frontier_v57_assoc
        if assoc_gate is None or self._last_frame is None:
            return detection
        self._inc_metric("frontier_v57_assoc_calls")
        try:
            result = assoc_gate.update(
                frame=self._last_frame,
                center=(float(detection.center[0]), float(detection.center[1])),
                confidence=float(detection.confidence),
                timestamp_s=time.perf_counter(),
            )
            result_center = getattr(result, "center", None)
            if not isinstance(result_center, (tuple, list)) or len(result_center) < 2:
                self._inc_metric("frontier_v57_assoc_rejects")
                return detection
            cx = float(result_center[0])
            cy = float(result_center[1])
            if not np.isfinite(cx) or not np.isfinite(cy):
                self._inc_metric("frontier_v57_assoc_rejects")
                return detection

            refined = SpotDetection(
                center=(int(round(cx)), int(round(cy))),
                bbox=self._recenter_bbox(
                    detection.bbox,
                    (int(round(cx)), int(round(cy))),
                    self._last_frame.shape[:2],
                ),
                confidence=float(
                    np.clip(
                        float(getattr(result, "confidence", detection.confidence) or detection.confidence),
                        0.0,
                        1.0,
                    )
                ),
                label=detection.label,
                class_id=detection.class_id,
            )

            shift_px = float(
                math.hypot(
                    float(refined.center[0] - detection.center[0]),
                    float(refined.center[1] - detection.center[1]),
                )
            )
            max_shift = max(0.0, float(self.cfg.frontier_v57_max_refine_shift_px))
            if shift_px > max_shift:
                self._inc_metric("frontier_v57_assoc_rejects")
                self._inc_metric("frontier_v57_assoc_drift_rejects")
                if self.reporter is not None:
                    self.reporter.event(
                        "frontier_v57_assoc_rejected",
                        reason="refine_shift_too_large",
                        shift_px=round(shift_px, 6),
                        max_shift_px=round(max_shift, 6),
                    )
                return detection

            rejected = bool(getattr(result, "rejected", False))
            visibility_score = float(getattr(result, "visibility_score", 0.0) or 0.0)
            drift_ratio = float(getattr(result, "drift_ratio", 0.0) or 0.0)
            memory_stability = float(getattr(result, "memory_stability", 0.0) or 0.0)
            persistent_reentry_used = bool(getattr(result, "persistent_reentry_used", False))
            self._record_frontier_v58_diag(
                visibility_score=visibility_score,
                drift_ratio=drift_ratio,
                rejected=rejected,
                persistent_reentry_used=persistent_reentry_used,
            )
            if persistent_reentry_used:
                self._inc_metric("frontier_v57_assoc_reentry_hits")
            if rejected:
                self._inc_metric("frontier_v57_assoc_rejects")
                if visibility_score < float(self.cfg.frontier_v57_visibility_min_score):
                    self._inc_metric("frontier_v57_assoc_visibility_rejects")
                if drift_ratio > float(self.cfg.frontier_v57_drift_guard_ratio):
                    self._inc_metric("frontier_v57_assoc_drift_rejects")
                if self.reporter is not None:
                    self.reporter.event(
                        "frontier_v57_assoc_rejected",
                        reason=str(getattr(result, "reason", "rejected")),
                        visibility_score=round(visibility_score, 6),
                        drift_ratio=round(drift_ratio, 6),
                        memory_stability=round(memory_stability, 6),
                        persistent_reentry_used=persistent_reentry_used,
                    )
                return detection

            refined_flag = bool(getattr(result, "refined", False))
            if refined_flag:
                self._inc_metric("frontier_v57_assoc_refines")

            if self.reporter is not None:
                self.reporter.event(
                    "frontier_v57_assoc_accepted",
                    center_before=[round(float(detection.center[0]), 6), round(float(detection.center[1]), 6)],
                    center_after=[round(float(refined.center[0]), 6), round(float(refined.center[1]), 6)],
                    conf_before=round(float(detection.confidence), 6),
                    conf_after=round(float(refined.confidence), 6),
                    visibility_score=round(visibility_score, 6),
                    drift_ratio=round(drift_ratio, 6),
                    memory_stability=round(memory_stability, 6),
                    persistent_reentry_used=persistent_reentry_used,
                    refined=refined_flag,
                )
            refined = self._apply_frontier_v58_stability_guard(
                base_detection=detection,
                candidate_detection=refined,
                visibility_score=visibility_score,
                drift_ratio=drift_ratio,
                persistent_reentry_used=persistent_reentry_used,
            )
            refined = self._apply_frontier_v59_consensus_guard(
                base_detection=detection,
                candidate_detection=refined,
                assoc_result=result,
                visibility_score=visibility_score,
                drift_ratio=drift_ratio,
            )
            refined = self._apply_frontier_v63_inertia_guard(
                base_detection=detection,
                candidate_detection=refined,
                visibility_score=visibility_score,
                drift_ratio=drift_ratio,
                persistent_reentry_used=persistent_reentry_used,
            )
            refined = self._apply_frontier_v64_adaptive_budget_guard(
                base_detection=detection,
                candidate_detection=refined,
                visibility_score=visibility_score,
                drift_ratio=drift_ratio,
            )
            refined = self._apply_frontier_v65_trajectory_guard(
                base_detection=detection,
                candidate_detection=refined,
                visibility_score=visibility_score,
                drift_ratio=drift_ratio,
            )
            refined = self._apply_frontier_v66_curvature_guard(
                base_detection=detection,
                candidate_detection=refined,
                visibility_score=visibility_score,
                drift_ratio=drift_ratio,
            )
            refined = self._apply_frontier_v67_adaptive_search_guard(
                base_detection=detection,
                candidate_detection=refined,
                visibility_score=visibility_score,
                drift_ratio=drift_ratio,
            )
            refined = self._apply_frontier_v68_tiled_rescue_guard(
                base_detection=detection,
                candidate_detection=refined,
                visibility_score=visibility_score,
                drift_ratio=drift_ratio,
            )
            refined = self._apply_frontier_v69_cmc_guard(
                base_detection=detection,
                candidate_detection=refined,
                visibility_score=visibility_score,
                drift_ratio=drift_ratio,
            )
            refined = self._apply_frontier_v70_failover_guard(
                base_detection=detection,
                candidate_detection=refined,
                visibility_score=visibility_score,
                drift_ratio=drift_ratio,
            )
            refined = self._apply_frontier_v71_occlusion_guard(
                base_detection=detection,
                candidate_detection=refined,
                visibility_score=visibility_score,
                drift_ratio=drift_ratio,
            )
            refined = self._apply_frontier_v72_memory_verifier_guard(
                base_detection=detection,
                candidate_detection=refined,
                visibility_score=visibility_score,
                drift_ratio=drift_ratio,
            )
            refined = self._apply_frontier_v73_retrack_guard(
                base_detection=detection,
                candidate_detection=refined,
            )
            refined = self._apply_frontier_v74_adaptive_retrack_guard(
                base_detection=detection,
                candidate_detection=refined,
            )
            refined = self._apply_frontier_v75_bidirectional_retrack_guard(
                base_detection=detection,
                candidate_detection=refined,
            )
            refined = self._apply_frontier_v76_verifier_fusion_guard(
                base_detection=detection,
                candidate_detection=refined,
            )
            refined = self._apply_frontier_v77_hysteresis_guard(
                base_detection=detection,
                candidate_detection=refined,
            )
            refined = self._apply_frontier_v78_consistency_bandit_guard(
                base_detection=detection,
                candidate_detection=refined,
            )
            return refined
        except Exception as exc:
            self._inc_metric("frontier_v57_assoc_failures")
            LOGGER.warning("Frontier v57 visibility-persistence association failed; bypassing: %s", exc)
            if self.reporter is not None:
                self.reporter.event("frontier_v57_assoc_failed", error=str(exc))
            return detection

    def _smooth_detection(self, detection: SpotDetection) -> SpotDetection:
        detection = self._apply_frontier_v7_phase_refine(detection)
        detection = self._apply_frontier_v27_mle_refine(detection)
        detection = self._apply_frontier_v28_consensus(detection)
        detection = self._apply_frontier_v29_reliability(detection)
        detection = self._apply_frontier_v30_phase_lock(detection)
        detection = self._apply_frontier_v31_profile_gate(detection)
        detection = self._apply_frontier_v32_coherence(detection)
        detection = self._apply_frontier_v33_response(detection)
        detection = self._apply_frontier_v34_assoc(detection)
        detection = self._apply_frontier_v35_assoc(detection)
        detection = self._apply_frontier_v36_assoc(detection)
        detection = self._apply_frontier_v37_assoc(detection)
        detection = self._apply_frontier_v38_assoc(detection)
        detection = self._apply_frontier_v39_assoc(detection)
        detection = self._apply_frontier_v40_assoc(detection)
        detection = self._apply_frontier_v41_assoc(detection)
        detection = self._apply_frontier_v42_assoc(detection)
        detection = self._apply_frontier_v43_assoc(detection)
        detection = self._apply_frontier_v44_assoc(detection)
        detection = self._apply_frontier_v45_assoc(detection)
        detection = self._apply_frontier_v46_assoc(detection)
        detection = self._apply_frontier_v47_assoc(detection)
        detection = self._apply_frontier_v50_assoc(detection)
        detection = self._apply_frontier_v51_assoc(detection)
        detection = self._apply_frontier_v52_assoc(detection)
        detection = self._apply_frontier_v53_assoc(detection)
        detection = self._apply_frontier_v54_assoc(detection)
        detection = self._apply_frontier_v55_assoc(detection)
        detection = self._apply_frontier_v56_assoc(detection)
        detection = self._apply_frontier_v57_assoc(detection)

        # --- 亚像素质心定位 ---
        if self._subpixel is not None and self._last_frame is not None:
            sub_result = self._subpixel.compute(self._last_frame, detection.bbox)
            if sub_result is not None:
                detection = SpotDetection(
                    center=(int(round(sub_result.cx)), int(round(sub_result.cy))),
                    bbox=detection.bbox,
                    confidence=detection.confidence,
                    label=detection.label,
                    class_id=detection.class_id,
                )

        # --- 卡尔曼滤波平滑 ---
        if self._kalman is not None:
            smoothed = self._kalman.update(detection.center[0], detection.center[1])
            if smoothed != detection.center:
                detection = SpotDetection(
                    center=smoothed,
                    bbox=detection.bbox,
                    confidence=detection.confidence,
                    label=detection.label,
                    class_id=detection.class_id,
                )

        # --- 原有滑动窗口平滑 ---
        self._det_history.append((int(detection.center[0]), int(detection.center[1])))
        if len(self._det_history) <= 1:
            return detection

        xs = [p[0] for p in self._det_history]
        ys = [p[1] for p in self._det_history]
        smoothed_center = (
            int(round(sum(xs) / len(xs))),
            int(round(sum(ys) / len(ys))),
        )
        if smoothed_center == detection.center:
            return detection
        return SpotDetection(
            center=smoothed_center,
            bbox=detection.bbox,
            confidence=detection.confidence,
            label=detection.label,
            class_id=detection.class_id,
        )

    def _apply_frontier_temporal_ensemble(
        self,
        frame: np.ndarray,
        detection: Optional[SpotDetection],
        *,
        tag: str,
        attempt: int,
        source: str,
    ) -> Optional[SpotDetection]:
        tracker = self._frontier_temporal_ensemble
        if tracker is None:
            return detection

        observations: List[Tuple[float, float, float]] = []
        if detection is not None:
            observations.append(
                (
                    float(detection.center[0]),
                    float(detection.center[1]),
                    float(np.clip(float(detection.confidence), 0.0, 1.0)),
                )
            )

        self._inc_metric("frontier_temporal_updates")
        try:
            result = tracker.update(observations, frame=frame)
        except Exception as exc:
            self._inc_metric("frontier_temporal_failures")
            LOGGER.warning("Frontier temporal ensemble update failed; bypassing: %s", exc)
            if self.reporter is not None:
                self.reporter.event(
                    "frontier_temporal_failed",
                    tag=tag,
                    attempt=attempt,
                    source=source,
                    error=str(exc),
                )
            return detection

        result_center = getattr(result, "center", None)
        if result_center is None:
            return detection
        if not isinstance(result_center, (tuple, list)) or len(result_center) < 2:
            return detection

        cx = float(result_center[0])
        cy = float(result_center[1])
        if not np.isfinite(cx) or not np.isfinite(cy):
            self._inc_metric("frontier_temporal_rejects")
            return detection

        clipped_center = self._clip_center((int(round(cx)), int(round(cy))), frame.shape[:2])
        tracker_conf = float(np.clip(float(getattr(result, "confidence", 0.0) or 0.0), 0.0, 1.0))

        if detection is not None:
            shift_px = float(
                math.hypot(
                    float(clipped_center[0] - detection.center[0]),
                    float(clipped_center[1] - detection.center[1]),
                )
            )
            max_shift = max(0.0, float(self.cfg.frontier_temporal_max_refine_shift_px))
            if shift_px > max_shift:
                self._inc_metric("frontier_temporal_rejects")
                if self.reporter is not None:
                    self.reporter.event(
                        "frontier_temporal_refine_rejected",
                        tag=tag,
                        attempt=attempt,
                        source=source,
                        reason="shift_too_large",
                        shift_px=round(shift_px, 6),
                        max_shift_px=round(max_shift, 6),
                    )
                return detection

            refined_bbox = self._recenter_bbox(detection.bbox, clipped_center, frame.shape[:2])
            refined = SpotDetection(
                center=clipped_center,
                bbox=refined_bbox,
                confidence=max(float(detection.confidence), tracker_conf),
                label=detection.label,
                class_id=detection.class_id,
            )
            if clipped_center != detection.center:
                self._inc_metric("frontier_temporal_refines")
                if self.reporter is not None:
                    pred = getattr(result, "predicted_position", None)
                    self.reporter.event(
                        "frontier_temporal_refined",
                        tag=tag,
                        attempt=attempt,
                        source=source,
                        center_before=list(detection.center),
                        center_after=list(refined.center),
                        shift_px=round(shift_px, 6),
                        ensemble_conf=round(float(tracker_conf), 6),
                        predicted_center=None if pred is None else [round(float(pred[0]), 3), round(float(pred[1]), 3)],
                        track_age=int(getattr(result, "track_age", 0) or 0),
                        ensemble_size=int(getattr(result, "ensemble_size", 0) or 0),
                    )
            return refined

        min_conf = float(np.clip(float(self.cfg.frontier_temporal_low_conf_threshold), 0.0, 1.0))
        if tracker_conf < min_conf:
            self._inc_metric("frontier_temporal_rejects")
            if self.reporter is not None:
                self.reporter.event(
                    "frontier_temporal_recovery_rejected",
                    tag=tag,
                    attempt=attempt,
                    source=source,
                    reason="low_confidence",
                    confidence=round(tracker_conf, 6),
                    min_confidence=round(min_conf, 6),
                )
            return None

        if self._last_detection is not None:
            bbox = self._recenter_bbox(self._last_detection.bbox, clipped_center, frame.shape[:2])
            class_id = int(self._last_detection.class_id)
        else:
            h, w = frame.shape[:2]
            radius = max(8, int(round(min(h, w) * 0.04)))
            x1 = max(0, clipped_center[0] - radius)
            y1 = max(0, clipped_center[1] - radius)
            x2 = min(w, clipped_center[0] + radius + 1)
            y2 = min(h, clipped_center[1] + radius + 1)
            bbox = (x1, y1, x2, y2)
            class_id = -4

        recovered = SpotDetection(
            center=clipped_center,
            bbox=bbox,
            confidence=float(np.clip(tracker_conf, 0.05, 0.95)),
            label="temporal_ensemble_recovery",
            class_id=class_id,
        )
        self._inc_metric("frontier_temporal_recoveries")
        if self.reporter is not None:
            pred = getattr(result, "predicted_position", None)
            self.reporter.event(
                "frontier_temporal_recovery_hit",
                tag=tag,
                attempt=attempt,
                source=source,
                center=list(recovered.center),
                conf=round(float(recovered.confidence), 6),
                predicted_center=None if pred is None else [round(float(pred[0]), 3), round(float(pred[1]), 3)],
                track_age=int(getattr(result, "track_age", 0) or 0),
                ensemble_size=int(getattr(result, "ensemble_size", 0) or 0),
                was_tracker_recovered=bool(getattr(result, "is_recovered", False)),
            )
        return recovered

    def _calc_axis_steps(self, axis: str, pixel_error: int) -> int:
        """Calculate motor steps for a given pixel error, using PID or adaptive/fixed step."""
        # PID mode: let the controller determine step size
        pid = self._pid_x if axis == "x" else self._pid_y
        if pid is not None:
            requested = int(pid.update(measurement=float(pixel_error)))
        else:
            # Legacy adaptive/fixed mode
            base = self.cfg.x_move_step if axis == "x" else self.cfg.y_move_step
            if not self.cfg.adaptive_step:
                requested = int(base)
            else:
                gain = max(0.1, float(self.cfg.adaptive_px_to_step))
                raw = int(round(abs(pixel_error) * gain))
                lower = max(1, int(self.cfg.adaptive_step_min))
                upper = max(lower, int(self.cfg.adaptive_step_max))
                requested = max(lower, min(upper, raw))

        if self._frontier_step_guard is None:
            return requested

        jitter_px = 0.0
        if len(self._det_history) >= 2:
            xs = [p[0] for p in self._det_history]
            ys = [p[1] for p in self._det_history]
            jitter_px = float(np.std(xs) + np.std(ys)) * 0.5
        result = self._frontier_step_guard.clamp(
            requested_step=int(requested),
            jitter_px=jitter_px,
            focus_score=float(self._last_focus_score),
        )
        if bool(result.clamped):
            self._inc_metric("frontier_step_clamps")
            if self.reporter is not None:
                self.reporter.event(
                    "frontier_step_clamped",
                    axis=str(axis),
                    requested_step=int(result.requested_step),
                    clamped_step=int(result.clamped_step),
                    dynamic_limit=int(result.dynamic_limit),
                    jitter_px=round(float(jitter_px), 6),
                    focus_score=round(float(self._last_focus_score), 6),
                )
        return int(result.clamped_step)

    def _compute_frontier_act_accept_threshold(self, *, attempt: int) -> float:
        base = float(np.clip(float(self.cfg.accept_conf_thres), 0.0, 1.0))
        if not bool(self.cfg.frontier_act_assoc_enabled):
            self._act_last_accept_threshold = base
            return base

        min_conf = float(np.clip(float(self.cfg.frontier_act_min_conf), 0.0, 1.0))
        max_conf = float(np.clip(float(self.cfg.frontier_act_max_conf), min_conf, 1.0))
        if max_conf < min_conf:
            max_conf = min_conf

        history = list(self._act_conf_history)
        if history:
            hist_mean = float(np.mean(history))
            hist_std = float(np.std(history))
            stability = float(np.clip(hist_mean - hist_std, 0.0, 1.0))
        else:
            hist_mean = base
            hist_std = 0.0
            stability = base

        miss_budget = max(0, int(self._track_miss_streak)) + max(0, int(attempt) - 1)
        relax = float(self.cfg.frontier_act_miss_relax_gain) * float(miss_budget)
        stability_term = float(self.cfg.frontier_act_stability_gain) * max(0.0, stability - base)
        threshold = base - relax + stability_term
        threshold = float(np.clip(threshold, min_conf, max_conf))

        prev_threshold = float(self._act_last_accept_threshold)
        if abs(prev_threshold - threshold) > 1e-6:
            self._act_last_accept_threshold = threshold
            self._inc_metric("frontier_act_threshold_updates")
            if self.reporter is not None:
                self.reporter.event(
                    "frontier_act_threshold_updated",
                    attempt=int(attempt),
                    prev_threshold=round(prev_threshold, 6),
                    new_threshold=round(threshold, 6),
                    miss_streak=int(self._track_miss_streak),
                    history_len=len(history),
                    history_mean=round(hist_mean, 6),
                    history_std=round(hist_std, 6),
                    stability=round(stability, 6),
                )
        return threshold

    def _gate_detection_confidence(
        self,
        detection: SpotDetection,
        *,
        tag: str,
        attempt: int,
    ) -> Optional[SpotDetection]:
        conf = float(detection.confidence)
        accept_conf = self._compute_frontier_act_accept_threshold(attempt=attempt)
        dynamic_floor = accept_conf
        if bool(self.cfg.frontier_low_score_assoc_enabled):
            decay = max(0.0, float(self.cfg.frontier_low_score_decay_per_attempt))
            floor_min = float(np.clip(float(self.cfg.frontier_low_score_min_conf), 0.0, 1.0))
            dynamic_floor = max(0.0, floor_min - decay * max(0, int(attempt) - 1))
            dynamic_floor = min(dynamic_floor, accept_conf)

        if conf >= accept_conf:
            self._track_miss_streak = 0
            self._last_detection = detection
            if bool(self.cfg.frontier_act_assoc_enabled):
                self._act_conf_history.append(float(np.clip(conf, 0.0, 1.0)))
                self._inc_metric("frontier_act_accepts")
            return detection

        if conf < dynamic_floor:
            if bool(self.cfg.frontier_act_assoc_enabled):
                self._inc_metric("frontier_act_rejects")
            if self.reporter is not None:
                self.reporter.metrics.low_conf_rejects += 1
                if bool(self.cfg.frontier_low_score_assoc_enabled):
                    self._inc_metric("frontier_low_score_assoc_rejects")
                self.reporter.event(
                    "low_conf_rejected",
                    tag=tag,
                    attempt=attempt,
                    conf=round(conf, 4),
                    accept_conf_thres=round(float(accept_conf), 4),
                    dynamic_low_score_floor=round(float(dynamic_floor), 4),
                    frontier_act_enabled=bool(self.cfg.frontier_act_assoc_enabled),
                    reason="below_low_score_floor",
                )
            return None

        if self._last_detection is None:
            if bool(self.cfg.frontier_act_assoc_enabled):
                self._inc_metric("frontier_act_rejects")
            if self.reporter is not None:
                self.reporter.metrics.low_conf_rejects += 1
                if bool(self.cfg.frontier_low_score_assoc_enabled):
                    self._inc_metric("frontier_low_score_assoc_rejects")
                self.reporter.event(
                    "low_conf_rejected",
                    tag=tag,
                    attempt=attempt,
                    conf=round(conf, 4),
                    accept_conf_thres=round(float(accept_conf), 4),
                    dynamic_low_score_floor=round(float(dynamic_floor), 4),
                    frontier_act_enabled=bool(self.cfg.frontier_act_assoc_enabled),
                    reason="no_history",
                )
            return None

        jump_px = math.hypot(
            float(detection.center[0] - self._last_detection.center[0]),
            float(detection.center[1] - self._last_detection.center[1]),
        )
        max_jump = float(self.cfg.track_max_jump_px)
        adaptive_jump = max_jump
        if bool(self.cfg.track_adaptive_jump_enabled):
            jitter_px = 0.0
            if len(self._det_history) >= 2:
                xs = [p[0] for p in self._det_history]
                ys = [p[1] for p in self._det_history]
                jitter_px = float(np.std(xs) + np.std(ys)) * 0.5
            adaptive_jump = max_jump + float(self.cfg.track_adaptive_jump_gain) * jitter_px
            adaptive_jump = float(np.clip(
                adaptive_jump,
                float(self.cfg.track_adaptive_jump_min_px),
                float(self.cfg.track_adaptive_jump_max_px),
            ))
        if jump_px > adaptive_jump:
            if bool(self.cfg.frontier_act_assoc_enabled):
                self._inc_metric("frontier_act_rejects")
            if self.reporter is not None:
                self.reporter.metrics.low_conf_rejects += 1
                self.reporter.metrics.jump_rejects += 1
                if bool(self.cfg.frontier_low_score_assoc_enabled):
                    self._inc_metric("frontier_low_score_assoc_rejects")
                if bool(self.cfg.track_adaptive_jump_enabled):
                    self.reporter.metrics.adaptive_jump_rejects += 1
                self.reporter.event(
                    "low_conf_rejected",
                    tag=tag,
                    attempt=attempt,
                    conf=round(conf, 4),
                    accept_conf_thres=round(float(accept_conf), 4),
                    dynamic_low_score_floor=round(float(dynamic_floor), 4),
                    jump_px=round(float(jump_px), 3),
                    track_max_jump_px=round(float(max_jump), 3),
                    adaptive_jump_px=round(float(adaptive_jump), 3),
                    frontier_act_enabled=bool(self.cfg.frontier_act_assoc_enabled),
                    reason="jump_too_large",
                )
            return None

        self._track_miss_streak = 0
        self._last_detection = detection
        if bool(self.cfg.frontier_act_assoc_enabled):
            self._act_conf_history.append(float(np.clip(conf, 0.0, 1.0)))
            self._inc_metric("frontier_act_accepts")
        if bool(self.cfg.frontier_low_score_assoc_enabled):
            self._inc_metric("frontier_low_score_assoc_accepts")
        if self.reporter is not None:
            self.reporter.event(
                "low_conf_accepted_by_track",
                tag=tag,
                attempt=attempt,
                conf=round(conf, 4),
                jump_px=round(float(jump_px), 3),
                dynamic_low_score_floor=round(float(dynamic_floor), 4),
                accept_conf_thres=round(float(accept_conf), 4),
                frontier_act_enabled=bool(self.cfg.frontier_act_assoc_enabled),
            )
        return detection

    def _reuse_last_detection_if_buffered(self, *, tag: str, attempt: int) -> Optional[SpotDetection]:
        if self._last_detection is None:
            return None
        max_buffer = max(0, int(self.cfg.track_buffer_frames))
        if max_buffer <= 0:
            return None
        if self._track_miss_streak >= max_buffer:
            return None

        self._track_miss_streak += 1
        reused = SpotDetection(
            center=(int(self._last_detection.center[0]), int(self._last_detection.center[1])),
            bbox=tuple(int(v) for v in self._last_detection.bbox),
            confidence=float(self._last_detection.confidence),
            label=str(self._last_detection.label),
            class_id=int(self._last_detection.class_id),
        )
        if self.reporter is not None:
            self.reporter.metrics.buffered_reuse += 1
            self.reporter.metrics.detect_success += 1
            self.reporter.event(
                "detection_buffer_reused",
                tag=tag,
                attempt=attempt,
                center=list(reused.center),
                streak=int(self._track_miss_streak),
                track_buffer_frames=max_buffer,
            )
        return reused

    def _attempt_recovery_scan(
        self,
        tag: str,
        target: Optional[Tuple[int, int]] = None,
    ) -> Optional[SpotDetection]:
        step = max(1, int(self.cfg.recovery_scan_step))
        cycles = max(1, int(self.cfg.recovery_scan_cycles))
        # Cross pattern with reverse return keeps displacement near zero after a cycle.
        pattern = [(step, 0), (0, step), (-step, 0), (0, -step), (-step, 0), (0, -step), (step, 0), (0, step)]

        if self.reporter is not None:
            self.reporter.metrics.recovery_attempts += 1
            self.reporter.event("recovery_scan_start", tag=tag, step=step, cycles=cycles)

        LOGGER.warning("%s: entering recovery scan, step=%d cycles=%d", tag, step, cycles)
        for cycle_idx in range(1, cycles + 1):
            for dx_steps, dy_steps in pattern:
                if dx_steps != 0:
                    if self._safety is not None and not self._safety.check_move_x(dx_steps):
                        raise RuntimeError(f"Safety: recovery X move blocked. {self._safety.state.last_violation}")
                    self.xy_stage.move_x(dx_steps)
                    if self._safety is not None:
                        self._safety.record_move_x(dx_steps)
                    if self._trajectory is not None:
                        self._trajectory.record_move_x(dx_steps)
                    if self.reporter is not None:
                        self.reporter.metrics.x_move_commands += 1
                if dy_steps != 0:
                    if self._safety is not None and not self._safety.check_move_y(dy_steps):
                        raise RuntimeError(f"Safety: recovery Y move blocked. {self._safety.state.last_violation}")
                    self.xy_stage.move_y(dy_steps)
                    if self._safety is not None:
                        self._safety.record_move_y(dy_steps)
                    if self._trajectory is not None:
                        self._trajectory.record_move_y(dy_steps)
                    if self.reporter is not None:
                        self.reporter.metrics.y_move_commands += 1

                time.sleep(self.cfg.settle_time_s)
                frame = self.window.grab_frame()
                self._last_frame = frame
                detect_frame = self._prepare_detection_frame(frame)
                detection = self._detect_with_runtime_metrics(
                    detect_frame,
                    tag=f"{tag} recovery",
                    attempt=cycle_idx,
                    source="recovery_scan_primary",
                )
                focus_score: Optional[float] = None
                if self.reporter is not None:
                    self.reporter.metrics.detect_attempts += 1
                miss_recorded = False
                if detection is not None and self._lodestar is not None:
                    self._bootstrap_lodestar_reference(
                        detect_frame,
                        detection,
                        tag=f"{tag} recovery",
                        attempt=cycle_idx,
                    )
                if detection is not None:
                    detection = self._apply_frontier_v25_stack(
                        frame,
                        detection,
                        tag=f"{tag} recovery",
                        attempt=cycle_idx,
                    )
                if detection is not None:
                    detection = self._refine_with_sam2_segmenter(
                        frame,
                        detection,
                        tag=f"{tag} recovery",
                        attempt=cycle_idx,
                        source="primary",
                    )
                if detection is not None:
                    detection = self._apply_frontier_v26_aberration_gate(
                        frame,
                        detection,
                        tag=f"{tag} recovery",
                        attempt=cycle_idx,
                        source="primary",
                    )
                    detection = self._apply_frontier_optics_quality_gate(
                        frame,
                        detection,
                        tag=f"{tag} recovery",
                        attempt=cycle_idx,
                        source="primary",
                    )
                if detection is not None:
                    focus_score = self._focus_score(frame, detection.bbox)
                    if focus_score < float(self.cfg.min_focus_score):
                        if self.reporter is not None:
                            self.reporter.metrics.focus_rejects += 1
                            self.reporter.metrics.detect_miss += 1
                            miss_recorded = True
                        detection = None
                    else:
                        detection = self._gate_detection_confidence(
                            detection,
                            tag=f"{tag} recovery",
                            attempt=cycle_idx,
                        )
                        if detection is not None:
                            if not self._passes_uncertainty_gate(
                                detect_frame,
                                detection,
                                tag=f"{tag} recovery",
                                attempt=cycle_idx,
                            ):
                                detection = None
                        if detection is not None:
                            detection = self._apply_domain_probe(
                                frame,
                                detection,
                                tag=f"{tag} recovery",
                                attempt=cycle_idx,
                            )

                if detection is None:
                    detection = self._detect_with_lodestar_fallback(
                        detect_frame,
                        tag=f"{tag} recovery",
                        attempt=cycle_idx,
                    )
                    if detection is not None:
                        detection = self._refine_with_sam2_segmenter(
                            frame,
                            detection,
                            tag=f"{tag} recovery",
                            attempt=cycle_idx,
                            source="lodestar_fallback",
                        )
                        detection = self._apply_frontier_v26_aberration_gate(
                            frame,
                            detection,
                            tag=f"{tag} recovery",
                            attempt=cycle_idx,
                            source="lodestar_fallback",
                        )
                        if detection is not None:
                            detection = self._apply_frontier_optics_quality_gate(
                                frame,
                                detection,
                                tag=f"{tag} recovery",
                                attempt=cycle_idx,
                                source="lodestar_fallback",
                            )
                        if detection is not None:
                            detection = self._smooth_detection(detection)

                if detection is None:
                    detection = self._detect_with_stardist_fallback(
                        detect_frame,
                        tag=f"{tag} recovery",
                        attempt=cycle_idx,
                    )
                    if detection is not None:
                        detection = self._refine_with_sam2_segmenter(
                            frame,
                            detection,
                            tag=f"{tag} recovery",
                            attempt=cycle_idx,
                            source="stardist_fallback",
                        )
                        detection = self._apply_frontier_v26_aberration_gate(
                            frame,
                            detection,
                            tag=f"{tag} recovery",
                            attempt=cycle_idx,
                            source="stardist_fallback",
                        )
                        if detection is not None:
                            detection = self._apply_frontier_optics_quality_gate(
                                frame,
                                detection,
                                tag=f"{tag} recovery",
                                attempt=cycle_idx,
                                source="stardist_fallback",
                            )
                        if detection is not None:
                            detection = self._smooth_detection(detection)

                if detection is None:
                    detection = self._detect_with_frontier_v27_wavelet(
                        detect_frame,
                        tag=f"{tag} recovery",
                        attempt=cycle_idx,
                    )
                    if detection is not None:
                        detection = self._smooth_detection(detection)

                temporal_before_none = detection is None
                detection = self._apply_frontier_temporal_ensemble(
                    frame,
                    detection,
                    tag=f"{tag} recovery",
                    attempt=cycle_idx,
                    source="recovery_scan",
                )
                if temporal_before_none and detection is not None:
                    focus_score = self._focus_score(frame, detection.bbox)
                    if focus_score < float(self.cfg.min_focus_score):
                        detection = None
                        self._inc_metric("frontier_temporal_rejects")
                        if self.reporter is not None:
                            self.reporter.metrics.focus_rejects += 1
                            self.reporter.event(
                                "frontier_temporal_recovery_rejected",
                                tag=f"{tag} recovery",
                                attempt=cycle_idx,
                                source="recovery_scan",
                                reason="focus_too_low",
                                focus_score=round(float(focus_score), 3),
                                min_focus_score=float(self.cfg.min_focus_score),
                            )

                if detection is None:
                    if self.reporter is not None and not miss_recorded:
                        self.reporter.metrics.detect_miss += 1
                    self._show_preview(frame, None, target=target, title=f"{tag} recovery")
                    continue

                detection = self._smooth_detection(detection)
                if self._frontier_memory is not None:
                    self._frontier_memory.update(frame, detection.center)
                self._last_detection = detection
                self._track_miss_streak = 0
                self._update_klt_reference(frame, detection)
                if self.reporter is not None:
                    self.reporter.metrics.detect_success += 1
                    self.reporter.metrics.recovery_success += 1
                    self.reporter.event(
                        "recovery_scan_success",
                        tag=tag,
                        cycle=cycle_idx,
                        center=list(detection.center),
                        conf=round(float(detection.confidence), 4),
                        focus_score=None if focus_score is None else round(float(focus_score), 3),
                    )
                self._show_preview(frame, detection, target=target, title=f"{tag} recovery", focus_score=focus_score)
                return detection

        if self.reporter is not None:
            self.reporter.event("recovery_scan_failed", tag=tag, cycles=cycles)
        return None

    def _focus_score(self, frame: np.ndarray, bbox: Tuple[int, int, int, int]) -> float:
        """Compute Laplacian variance focus score and cache the result."""
        x1, y1, x2, y2 = bbox
        h, w = frame.shape[:2]
        x1 = max(0, min(int(x1), w - 1))
        x2 = max(x1 + 1, min(int(x2), w))
        y1 = max(0, min(int(y1), h - 1))
        y2 = max(y1 + 1, min(int(y2), h))
        crop = frame[y1:y2, x1:x2]
        if crop.size <= 1:
            self._last_focus_score = 0.0
            return 0.0
        gray = cv2.cvtColor(crop, cv2.COLOR_BGR2GRAY)
        score = float(cv2.Laplacian(gray, cv2.CV_64F).var())
        self._last_focus_score = score
        return score

    def _show_preview(
        self,
        frame: np.ndarray,
        detection: Optional[SpotDetection],
        target: Optional[Tuple[int, int]],
        title: str,
        focus_score: Optional[float] = None,
    ) -> None:
        if not self.cfg.preview:
            return

        canvas = frame.copy()
        if detection is not None:
            x1, y1, x2, y2 = detection.bbox
            cv2.rectangle(canvas, (x1, y1), (x2, y2), (0, 255, 0), 2)
            cv2.circle(canvas, detection.center, 5, (0, 255, 0), -1)
            # Use passed focus_score or cached value to avoid redundant Laplacian computation
            fs = focus_score if focus_score is not None else self._last_focus_score
            focus_str = f"F={fs:.1f}"
            cv2.putText(
                canvas,
                f"{detection.label} {detection.confidence:.2f} {detection.center} {focus_str}",
                (x1, max(20, y1 - 10)),
                cv2.FONT_HERSHEY_SIMPLEX,
                0.65,
                (0, 255, 0),
                2,
            )
        if target is not None:
            cv2.drawMarker(canvas, target, (0, 0, 255), cv2.MARKER_CROSS, 20, 2)
            cv2.putText(
                canvas,
                f"Target {target}",
                (10, 28),
                cv2.FONT_HERSHEY_SIMPLEX,
                0.8,
                (0, 0, 255),
                2,
            )
        cv2.putText(
            canvas,
            title,
            (10, canvas.shape[0] - 18),
            cv2.FONT_HERSHEY_SIMPLEX,
            0.75,
            (255, 255, 0),
            2,
        )
        cv2.imshow(self.preview_window_name, canvas)
        cv2.waitKey(1)

    def _is_converged(
        self,
        p1: Tuple[int, int],
        p2: Tuple[int, int],
        p3: Tuple[int, int],
    ) -> bool:
        tol = self.cfg.tolerance_px
        return (
            abs(p1[0] - p2[0]) <= tol
            and abs(p1[1] - p2[1]) <= tol
            and abs(p1[0] - p3[0]) <= tol
            and abs(p1[1] - p3[1]) <= tol
        )

