def resolve_default_model_path() -> Optional[str]:
    candidates = []
    env_model = os.environ.get("SPOTZOOM_MODEL_PATH")
    if env_model:
        candidates.append(Path(env_model))
    candidates.append(script_dir / "best.pt")
    candidates.append(script_dir / "best_all.pt")

    for candidate in candidates:
        if candidate.exists():
            return str(candidate)
    return None


def _classic_backend_available() -> bool:
    return _ml_classic_detector is not None and hasattr(_ml_classic_detector, "ClassicSpotDetector")


def _requested_detector_backend(args: argparse.Namespace) -> str:
    return str(getattr(args, "detector_backend", "auto")).strip().lower()


def _check_yolo_backend_prereqs(args: argparse.Namespace) -> Tuple[bool, Optional[str]]:
    if not args.model_path:
        return False, "YOLO model path is missing. Provide --model-path or SPOTZOOM_MODEL_PATH."
    model_path = Path(args.model_path)
    if not model_path.exists():
        return False, f"YOLO model path not found: {args.model_path}"

    if args.yolo_python:
        python_exe = str(Path(args.yolo_python))
        if not Path(python_exe).exists():
            return False, f"--yolo-python path does not exist: {python_exe}"
        if not _module_available_in_python(python_exe, "ultralytics"):
            return False, _format_ultralytics_install_hint(python_exe)
        return True, None

    if not _module_available_in_current_python("ultralytics"):
        return False, _format_ultralytics_install_hint(sys.executable)
    return True, None


def _resolve_detector_backend(args: argparse.Namespace) -> str:
    backend = _requested_detector_backend(args)
    if backend == "classic":
        return "classic"
    if backend == "yolo":
        return "yolo"
    if backend != "auto":
        raise RuntimeError(f"Unsupported detector backend: {backend}")

    yolo_ok, _ = _check_yolo_backend_prereqs(args)
    if yolo_ok:
        return "yolo"
    if _classic_backend_available():
        return "classic"
    raise RuntimeError("No available detector backend for --detector-backend=auto (YOLO unavailable, classic module unavailable)")


def _build_classic_detector(args: argparse.Namespace) -> SpotClassicDetector:
    if not _classic_backend_available():
        raise RuntimeError("classic_spot_detector module is unavailable")
    return SpotClassicDetector(
        target_class_name=args.target_class_name if args.target_class_name else None,
        target_class_id=args.target_class_id,
        method=args.classic_method,
        selection=args.classic_selection,
        min_area=args.classic_min_area,
        max_area=args.classic_max_area,
        min_circularity=args.classic_min_circularity,
        min_intensity_ratio=args.classic_min_intensity_ratio,
        morph_kernel_size=args.classic_morph_kernel_size,
    )


def _build_yolo_detector(args: argparse.Namespace):
    yolo_ok, yolo_error = _check_yolo_backend_prereqs(args)
    if not yolo_ok:
        raise RuntimeError(yolo_error or "YOLO backend prerequisites are not satisfied")

    if args.yolo_python:
        python_exe = str(Path(args.yolo_python))
        return SpotYOLOWorkerClient(
            python_exe=python_exe,
            model_path=args.model_path,
            target_class_name=args.target_class_name if args.target_class_name else None,
            target_class_id=args.target_class_id,
            conf_threshold=args.conf_thres,
        )

    return SpotYOLODetector(
        model_path=args.model_path,
        target_class_name=args.target_class_name if args.target_class_name else None,
        target_class_id=args.target_class_id,
        conf_threshold=args.conf_thres,
    )


def build_detector(args, resolved_backend: Optional[str] = None):
    """Build and return the configured detector backend."""
    backend = resolved_backend or _resolve_detector_backend(args)
    if backend == "classic":
        if _requested_detector_backend(args) == "auto":
            LOGGER.warning("YOLO backend unavailable; falling back to classic detector")
        return _build_classic_detector(args)
    return _build_yolo_detector(args)


def _percentile_linear(values: List[float], percentile: float) -> float:
    """Compute a percentile using linear interpolation over sorted samples."""
    if not values:
        return 0.0
    pct = min(100.0, max(0.0, float(percentile)))
    ordered = sorted(float(v) for v in values)
    if len(ordered) == 1:
        return ordered[0]
    rank = (pct / 100.0) * (len(ordered) - 1)
    lo = int(math.floor(rank))
    hi = int(math.ceil(rank))
    if lo == hi:
        return ordered[lo]
    weight = rank - lo
    return ordered[lo] * (1.0 - weight) + ordered[hi] * weight


def _worker_stats_payload(
    started_perf: float,
    request_counters: Dict[str, int],
    latency_samples_ms: List[float],
) -> Dict:
    count = len(latency_samples_ms)
    mean_ms = float(sum(latency_samples_ms) / count) if count else 0.0
    return {
        "uptime_s": round(max(0.0, time.perf_counter() - started_perf), 3),
        "requests_total": int(request_counters.get("requests_total", 0)),
        "detect_requests": int(request_counters.get("detect_requests", 0)),
        "detect_success": int(request_counters.get("detect_success", 0)),
        "detect_miss": int(request_counters.get("detect_miss", 0)),
        "parse_errors": int(request_counters.get("parse_errors", 0)),
        "decode_errors": int(request_counters.get("decode_errors", 0)),
        "inference_errors": int(request_counters.get("inference_errors", 0)),
        "unsupported_commands": int(request_counters.get("unsupported_commands", 0)),
        "latency_ms": {
            "count": count,
            "mean_ms": round(mean_ms, 4),
            "p50_ms": round(_percentile_linear(latency_samples_ms, 50.0), 4),
            "p95_ms": round(_percentile_linear(latency_samples_ms, 95.0), 4),
            "p99_ms": round(_percentile_linear(latency_samples_ms, 99.0), 4),
            "max_ms": round(max(latency_samples_ms), 4) if count else 0.0,
        },
    }


def worker_main(args: argparse.Namespace) -> int:
    # Worker IPC requires stdout to carry JSON-only protocol frames.
    LOGGER.setLevel(logging.ERROR)
    for _handler in LOGGER.handlers:
        _handler.setLevel(logging.ERROR)
    started_perf = time.perf_counter()
    request_counters = {
        "requests_total": 0,
        "detect_requests": 0,
        "detect_success": 0,
        "detect_miss": 0,
        "parse_errors": 0,
        "decode_errors": 0,
        "inference_errors": 0,
        "unsupported_commands": 0,
    }
    latency_samples_ms: List[float] = []
    requested_backend = _requested_detector_backend(args)
    resolved_backend = requested_backend

    def _emit(payload: Dict) -> None:
        print(json.dumps(payload, ensure_ascii=False), flush=True)

    def _load_frame_from_request(request: Dict):
        image_b64 = request.get("image_jpg_b64")
        if image_b64:
            try:
                frame_bytes = base64.b64decode(image_b64)
                frame_array = np.frombuffer(frame_bytes, dtype=np.uint8)
                frame = cv2.imdecode(frame_array, cv2.IMREAD_COLOR)
                if frame is None:
                    return None, "Decoded JPEG payload is empty or unsupported"
                return frame, None
            except Exception as exc:
                return None, f"Failed to decode JPEG payload: {exc}"

        image_path = request.get("image_path") or args.frame_source_image
        if not image_path:
            return None, "Missing image input: provide image_path or image_jpg_b64"
        frame = cv2.imread(str(image_path))
        if frame is None:
            return None, f"Cannot read image file: {image_path}"
        return frame, None

    try:
        resolved_backend = _resolve_detector_backend(args)
        detector = build_detector(args, resolved_backend=resolved_backend)
    except Exception as exc:
        _emit({"ok": False, "error": str(exc)})
        return 1

    _emit(
        {
            "ok": True,
            "status": "ready",
            "backend": resolved_backend,
            "requested_backend": requested_backend,
            "supported_commands": ["detect", "warmup", "health", "stats", "ping", "quit"],
        }
    )

    try:
        for raw in sys.stdin:
            raw = raw.strip()
            if not raw:
                continue
            request_counters["requests_total"] += 1
            try:
                request = json.loads(raw)
            except json.JSONDecodeError as exc:
                request_counters["parse_errors"] += 1
                _emit({"ok": False, "error": f"Invalid JSON from stdin: {exc}"})
                continue
            cmd = str(request.get("cmd", "")).strip().lower()
            if cmd == "quit":
                break
            if cmd in {"health", "ping"}:
                _emit(
                    {
                        "ok": True,
                        "status": "ready",
                        "backend": resolved_backend,
                        "requested_backend": requested_backend,
                        "model_path": args.model_path,
                        "stats": _worker_stats_payload(started_perf, request_counters, latency_samples_ms),
                    }
                )
                continue
            if cmd == "stats":
                _emit(
                    {
                        "ok": True,
                        "backend": resolved_backend,
                        "requested_backend": requested_backend,
                        "stats": _worker_stats_payload(started_perf, request_counters, latency_samples_ms),
                    }
                )
                continue
            if cmd not in {"detect", "warmup"}:
                request_counters["unsupported_commands"] += 1
                _emit({"ok": False, "error": f"Unsupported command: {cmd}"})
                continue

            frame, frame_error = _load_frame_from_request(request)
            if frame is None:
                request_counters["decode_errors"] += 1
                _emit({"ok": False, "error": frame_error})
                continue

            if cmd == "warmup":
                try:
                    warmup_count = int(request.get("count", 1))
                except Exception:
                    warmup_count = 1
                warmup_count = max(1, min(64, warmup_count))
                start_warmup = time.perf_counter()
                warmup_failed = False
                for _ in range(warmup_count):
                    request_counters["detect_requests"] += 1
                    infer_t0 = time.perf_counter()
                    try:
                        detection = detector.detect(frame)
                    except Exception as exc:
                        request_counters["inference_errors"] += 1
                        _emit({"ok": False, "error": f"Warmup inference failed: {exc}"})
                        warmup_failed = True
                        break
                    latency_samples_ms.append((time.perf_counter() - infer_t0) * 1000.0)
                    if detection is None:
                        request_counters["detect_miss"] += 1
                    else:
                        request_counters["detect_success"] += 1
                if warmup_failed:
                    continue
                _emit(
                    {
                        "ok": True,
                        "status": "warmed",
                        "iterations": warmup_count,
                        "elapsed_ms": round((time.perf_counter() - start_warmup) * 1000.0, 3),
                        "stats": _worker_stats_payload(started_perf, request_counters, latency_samples_ms),
                    }
                )
                continue

            request_counters["detect_requests"] += 1
            infer_t0 = time.perf_counter()
            try:
                detection = detector.detect(frame)
            except Exception as exc:
                request_counters["inference_errors"] += 1
                _emit({"ok": False, "error": f"Detector inference failed: {exc}"})
                continue
            latency_samples_ms.append((time.perf_counter() - infer_t0) * 1000.0)

            if detection is None:
                request_counters["detect_miss"] += 1
            else:
                request_counters["detect_success"] += 1

            _emit(
                {
                    "ok": True,
                    "backend": resolved_backend,
                    "detection": None if detection is None else detection.to_payload(),
                }
            )
    finally:
        detector_close = getattr(detector, "close", None)
        if callable(detector_close):
            detector_close()
    return 0


def build_xy_stage(args):
    """Build and return the XY stage driver based on command-line arguments."""
    if args.xy_driver == "dryrun":
        return DryRunStage()
    if args.xy_driver == "thorlabs":
        return ThorlabsXYStage(
            device_id=args.device_id,
            x_channel=args.x_channel,
            y_channel=args.y_channel,
            x_hw_sign=args.x_hw_sign,
            y_hw_sign=args.y_hw_sign,
            horizontal_velocity=args.horizontal_velocity,
            horizontal_acceleration=args.horizontal_acceleration,
            vertical_velocity=args.vertical_velocity,
            vertical_acceleration=args.vertical_acceleration,
            max_voltage=args.max_voltage,
            dll_dir=args.thorlabs_dll_dir,
        )
    if args.xy_driver == "newport":
        return NewportXYStage(
            conn=args.newport_conn,
            x_axis=args.newport_x_axis,
            y_axis=args.newport_y_axis,
            x_hw_sign=args.x_hw_sign,
            y_hw_sign=args.y_hw_sign,
            backend=args.newport_backend,
            timeout=args.newport_timeout,
            multiaddr=args.newport_multiaddr,
            scan=not args.newport_no_scan,
            velocity=args.newport_velocity,
            acceleration=args.newport_acceleration,
            wait_each_move=not args.newport_no_wait,
        )
    if args.xy_driver == "newport-mrc4":
        return NewportMRC4MirrorStage(
            conn=args.newport_conn,
            mirror1_x_axis=args.mrc_mirror1_x_axis,
            mirror1_y_axis=args.mrc_mirror1_y_axis,
            mirror2_x_axis=args.mrc_mirror2_x_axis,
            mirror2_y_axis=args.mrc_mirror2_y_axis,
            mirror1_x_sign=args.mrc_mirror1_x_sign,
            mirror1_y_sign=args.mrc_mirror1_y_sign,
            mirror2_x_sign=args.mrc_mirror2_x_sign,
            mirror2_y_sign=args.mrc_mirror2_y_sign,
            backend=args.newport_backend,
            timeout=args.newport_timeout,
            multiaddr=args.newport_multiaddr,
            scan=not args.newport_no_scan,
            velocity=args.newport_velocity,
            acceleration=args.newport_acceleration,
            wait_each_move=not args.newport_no_wait,
            virtual_axis_mode=args.mrc_virtual_axis_mode,
        )
    raise ValueError(f"Unsupported xy_driver: {args.xy_driver}")


def build_z_stage(args, window):
    """Build and return the Z axis driver based on command-line arguments."""
    if args.z_driver == "dryrun":
        return DryRunZAxis()
    if args.z_driver == "wheel":
        return ToupViewWheelZAxis(window=window, up_click_sign=args.z_up_sign)
    if args.z_driver == "xps":
        return XPSZAxis(
            ip=args.xps_ip,
            port=args.xps_port,
            username=args.xps_user,
            password=args.xps_password,
            group_name=args.xps_group,
        )
    if args.z_driver == "picomotor":
        return NewportPicomotorZAxis(
            conn=args.z_picomotor_conn,
            axis=args.z_picomotor_axis,
            hw_sign=args.z_picomotor_sign,
            backend=args.newport_backend,
            timeout=args.newport_timeout,
            multiaddr=args.newport_multiaddr,
            scan=not args.newport_no_scan,
            velocity=args.z_picomotor_velocity,
            acceleration=args.z_picomotor_acceleration,
        )
    raise ValueError(f"Unsupported z_driver: {args.z_driver}")


def _startup_uses_real_xy_driver(args: argparse.Namespace) -> bool:
    return str(args.xy_driver).strip().lower() in {"thorlabs", "newport", "newport-mrc4"}


def _startup_uses_real_z_motor_driver(args: argparse.Namespace) -> bool:
    return str(args.z_driver).strip().lower() in {"xps", "picomotor"}


def _wait_startup_motion_if_needed(stage, axis: Optional[str] = None) -> None:
    wait_method = getattr(stage, "wait_startup_axis", None)
    if callable(wait_method):
        wait_method(axis=axis)


def _run_startup_motion_probe(
    *,
    label: str,
    forward,
    backward,
    timeout_s: float,
    reporter: Optional["RunReporter"] = None,
) -> None:
    reporter_payload = {"label": str(label), "timeout_s": round(float(timeout_s), 6)}
    if reporter is not None:
        reporter.event("startup_motion_probe_started", **reporter_payload)

    forward_started = time.perf_counter()
    forward()
    forward_elapsed = time.perf_counter() - forward_started
    if forward_elapsed > timeout_s:
        raise RuntimeError(
            f"{label} 正向启动运动自检超时：{forward_elapsed:.3f}s > {timeout_s:.3f}s"
        )

    backward_started = time.perf_counter()
    backward()
    backward_elapsed = time.perf_counter() - backward_started
    if backward_elapsed > timeout_s:
        raise RuntimeError(
            f"{label} 反向启动运动自检超时：{backward_elapsed:.3f}s > {timeout_s:.3f}s"
        )

    LOGGER.info(
        "启动运动自检通过：%s forward=%.3fs backward=%.3fs threshold=%.3fs",
        label,
        forward_elapsed,
        backward_elapsed,
        timeout_s,
    )
    if reporter is not None:
        reporter.event(
            "startup_motion_probe_passed",
            **reporter_payload,
            forward_elapsed_ms=round(forward_elapsed * 1000.0, 4),
            backward_elapsed_ms=round(backward_elapsed * 1000.0, 4),
        )


def run_startup_motion_check(
    args: argparse.Namespace,
    *,
    xy_stage,
    z_stage,
    reporter: Optional["RunReporter"] = None,
) -> None:
    if not bool(args.startup_motion_check_enabled):
        LOGGER.info("已禁用启动运动自检")
        if reporter is not None:
            reporter.event("startup_motion_check_skipped", reason="disabled")
        return

    xy_real = _startup_uses_real_xy_driver(args)
    z_real = _startup_uses_real_z_motor_driver(args)
    if not xy_real and not z_real:
        if reporter is not None:
            reporter.event("startup_motion_check_skipped", reason="no_real_motor_driver")
        return

    timeout_s = max(0.01, float(args.startup_motion_check_timeout))
    xy_steps = max(1, int(args.startup_motion_check_xy_steps))
    z_step = max(1e-6, float(args.startup_motion_check_z_step))

    LOGGER.info(
        "开始启动运动自检：xy_real=%s z_real=%s timeout=%.3fs xy_steps=%d z_step=%.6f",
        xy_real,
        z_real,
        timeout_s,
        xy_steps,
        z_step,
    )
    if reporter is not None:
        reporter.event(
            "startup_motion_check_started",
            xy_real=xy_real,
            z_real=z_real,
            timeout_s=round(timeout_s, 6),
            xy_steps=xy_steps,
            z_step=round(z_step, 6),
        )

    try:
        if xy_real and xy_stage is not None:
            _run_startup_motion_probe(
                label=f"xy:{args.xy_driver}:x",
                timeout_s=timeout_s,
                reporter=reporter,
                forward=lambda: (
                    xy_stage.move_x(xy_steps),
                    _wait_startup_motion_if_needed(xy_stage, "x"),
                ),
                backward=lambda: (
                    xy_stage.move_x(-xy_steps),
                    _wait_startup_motion_if_needed(xy_stage, "x"),
                ),
            )
            _run_startup_motion_probe(
                label=f"xy:{args.xy_driver}:y",
                timeout_s=timeout_s,
                reporter=reporter,
                forward=lambda: (
                    xy_stage.move_y(xy_steps),
                    _wait_startup_motion_if_needed(xy_stage, "y"),
                ),
                backward=lambda: (
                    xy_stage.move_y(-xy_steps),
                    _wait_startup_motion_if_needed(xy_stage, "y"),
                ),
            )

        if z_real and z_stage is not None:
            _run_startup_motion_probe(
                label=f"z:{args.z_driver}",
                timeout_s=timeout_s,
                reporter=reporter,
                forward=lambda: (z_stage.move_up(z_step), _wait_startup_motion_if_needed(z_stage)),
                backward=lambda: (z_stage.move_down(z_step), _wait_startup_motion_if_needed(z_stage)),
            )
    except Exception as exc:
        if reporter is not None:
            reporter.event("startup_motion_check_failed", error=str(exc))
        raise

    if reporter is not None:
        reporter.event("startup_motion_check_passed")


def check_environment(args: argparse.Namespace) -> int:
    """Validate dependencies, model path, and configuration; return 0 if OK, 1 on errors."""
    errors = []
    warnings = []

    backend = _requested_detector_backend(args)
    if backend not in ("auto", "yolo", "classic"):
        errors.append(f"Unsupported --detector-backend: {backend}")

    yolo_ok, yolo_error = _check_yolo_backend_prereqs(args)
    classic_ok = _classic_backend_available()
    if backend == "yolo":
        if not yolo_ok and yolo_error:
            errors.append(yolo_error)
    elif backend == "classic":
        if not classic_ok:
            errors.append("classic_spot_detector module is unavailable")
        if args.yolo_python:
            warnings.append("--yolo-python is ignored when --detector-backend=classic")
    elif backend == "auto":
        if not yolo_ok:
            if classic_ok:
                warnings.append(
                    f"YOLO backend unavailable in auto mode; classic detector will be used. Reason: {yolo_error}"
                )
            else:
                if yolo_error:
                    errors.append(yolo_error)
                errors.append("classic_spot_detector module is unavailable for auto fallback")

    if args.frame_source_image:
        sim_path = Path(args.frame_source_image).expanduser()
        if not sim_path.exists():
            errors.append(f"--frame-source-image not found: {sim_path}")
        elif cv2.imread(str(sim_path)) is None:
            errors.append(f"--frame-source-image cannot be decoded by OpenCV: {sim_path}")
        if args.select_roi:
            warnings.append("--frame-source-image with ROI selection may block headless runs; consider --skip-roi")
    else:
        for module_name in ("pyautogui", "win32gui", "win32api", "win32con"):
            if not _module_available_in_current_python(module_name):
                errors.append(f"Missing dependency: {module_name}")

    motor_uses_pylablib = (
        args.xy_driver in ("thorlabs", "newport", "newport-mrc4")
        or args.z_driver == "picomotor"
    )
    if motor_uses_pylablib and not _module_available_in_current_python("pylablib"):
        errors.append("Missing dependency for motor control: pylablib")

    if args.z_driver == "xps":
        xps_dir = project_root / "XPS" / "__analysis_tmp" / "XPS-Q-Drivers" / "XPS-Q_Drivers" / "XPS-Q_Python_Drivers"
        if not xps_dir.exists():
            errors.append(f"XPS Python driver path not found: {xps_dir}")
    if args.newport_timeout <= 0:
        errors.append("--newport-timeout must be > 0")
    if args.newport_velocity is not None and args.newport_velocity <= 0:
        errors.append("--newport-velocity must be > 0 when provided")
    if args.newport_acceleration is not None and args.newport_acceleration <= 0:
        errors.append("--newport-acceleration must be > 0 when provided")
    if args.xy_driver == "newport":
        if args.newport_x_axis <= 0 or args.newport_y_axis <= 0:
            errors.append("--newport-x-axis and --newport-y-axis must be > 0")
        if args.newport_x_axis == args.newport_y_axis:
            errors.append("--newport-x-axis and --newport-y-axis must be different")
    if args.xy_driver == "newport-mrc4":
        mrc_axes = [
            args.mrc_mirror1_x_axis,
            args.mrc_mirror1_y_axis,
            args.mrc_mirror2_x_axis,
            args.mrc_mirror2_y_axis,
        ]
        if any(axis <= 0 for axis in mrc_axes):
            errors.append("All MRC mirror axes must be > 0")
        if len(set(mrc_axes)) != 4:
            errors.append("MRC 4-axis mapping requires four distinct Picomotor axes")
        if str(args.mrc_virtual_axis_mode).strip().lower() not in {"mirror1", "mirror2", "shared"}:
            errors.append("--mrc-virtual-axis-mode must be one of: mirror1, mirror2, shared")
    if args.z_driver == "picomotor":
        if args.z_picomotor_axis <= 0:
            errors.append("--z-picomotor-axis must be > 0")
        if args.z_picomotor_velocity is not None and args.z_picomotor_velocity <= 0:
            errors.append("--z-picomotor-velocity must be > 0 when provided")
        if args.z_picomotor_acceleration is not None and args.z_picomotor_acceleration <= 0:
            errors.append("--z-picomotor-acceleration must be > 0 when provided")
        if args.xy_driver == "newport-mrc4" and args.z_picomotor_conn == args.newport_conn:
            errors.append(
                "--z-picomotor-conn must point to a dedicated 8742 controller when --xy-driver=newport-mrc4"
            )

    if args.enable_recovery_scan and args.recovery_scan_step <= 0:
        errors.append("--recovery-scan-step must be > 0 when recovery scan is enabled")
    if args.classic_min_area <= 0:
        errors.append("--classic-min-area must be > 0")
    if args.classic_max_area < 0:
        errors.append("--classic-max-area must be >= 0")
    if args.classic_min_circularity < 0 or args.classic_min_circularity > 1:
        errors.append("--classic-min-circularity must be in [0, 1]")
    if args.classic_min_intensity_ratio <= 0:
        errors.append("--classic-min-intensity-ratio must be > 0")
    if args.classic_morph_kernel_size < 3:
        errors.append("--classic-morph-kernel-size must be >= 3")
    if args.classic_morph_kernel_size % 2 == 0:
        warnings.append("--classic-morph-kernel-size is even; runtime will round it to the next odd value")
    if args.min_focus_score < 0:
        errors.append("--min-focus-score must be >= 0")
    if args.accept_conf_thres < 0 or args.accept_conf_thres > 1:
        errors.append("--accept-conf-thres must be in [0, 1]")
    if args.track_buffer_frames < 0:
        errors.append("--track-buffer-frames must be >= 0")
    if args.track_max_jump_px < 0:
        errors.append("--track-max-jump-px must be >= 0")
    if args.track_adaptive_jump_gain < 0:
        errors.append("--track-adaptive-jump-gain must be >= 0")
    if args.track_adaptive_jump_min_px <= 0:
        errors.append("--track-adaptive-jump-min-px must be > 0")
    if args.track_adaptive_jump_max_px < args.track_adaptive_jump_min_px:
        errors.append("--track-adaptive-jump-max-px must be >= --track-adaptive-jump-min-px")
    if args.kalman_process_noise <= 0:
        errors.append("--kalman-process-noise must be > 0")
    if args.kalman_measurement_noise <= 0:
        errors.append("--kalman-measurement-noise must be > 0")
    if args.kalman_enabled and _ml_kalman is None:
        warnings.append("kalman requested but kalman_tracker module is unavailable")
    if args.frontier_low_score_min_conf < 0 or args.frontier_low_score_min_conf > 1:
        errors.append("--frontier-low-score-min-conf must be in [0, 1]")
    if args.frontier_low_score_decay_per_attempt < 0:
        errors.append("--frontier-low-score-decay-per-attempt must be >= 0")
    if args.frontier_act_history_size <= 0:
        errors.append("--frontier-act-history-size must be > 0")
    if args.frontier_act_min_conf < 0 or args.frontier_act_min_conf > 1:
        errors.append("--frontier-act-min-conf must be in [0, 1]")
    if args.frontier_act_max_conf < 0 or args.frontier_act_max_conf > 1:
        errors.append("--frontier-act-max-conf must be in [0, 1]")
    if args.frontier_act_max_conf < args.frontier_act_min_conf:
        errors.append("--frontier-act-max-conf must be >= --frontier-act-min-conf")
    if args.frontier_act_miss_relax_gain < 0:
        errors.append("--frontier-act-miss-relax-gain must be >= 0")
    if args.frontier_act_stability_gain < 0:
        errors.append("--frontier-act-stability-gain must be >= 0")
    if args.frontier_klt_max_corners <= 0:
        errors.append("--frontier-klt-max-corners must be > 0")
    if args.frontier_klt_quality_level <= 0 or args.frontier_klt_quality_level > 1:
        errors.append("--frontier-klt-quality-level must be in (0, 1]")
    if args.frontier_klt_min_distance <= 0:
        errors.append("--frontier-klt-min-distance must be > 0")
    if args.frontier_klt_bidirectional_error_px <= 0:
        errors.append("--frontier-klt-bidirectional-error-px must be > 0")
    if args.frontier_klt_min_tracked_points <= 0:
        errors.append("--frontier-klt-min-tracked-points must be > 0")
    if args.frontier_klt_confidence_decay <= 0 or args.frontier_klt_confidence_decay > 1:
        errors.append("--frontier-klt-confidence-decay must be in (0, 1]")
    if args.frontier_klt_max_shift_px < 0:
        errors.append("--frontier-klt-max-shift-px must be >= 0")
    if args.frontier_klt_recovery_enabled:
        if not hasattr(cv2, "goodFeaturesToTrack") or not hasattr(cv2, "calcOpticalFlowPyrLK"):
            errors.append("OpenCV build does not include KLT optical flow APIs required by --frontier-klt-recovery")
    if args.frontier_phase_min_response < 0 or args.frontier_phase_min_response > 1:
        errors.append("--frontier-phase-min-response must be in [0, 1]")
    if args.frontier_phase_max_shift_px < 0:
        errors.append("--frontier-phase-max-shift-px must be >= 0")
    if args.frontier_phase_confidence_decay <= 0 or args.frontier_phase_confidence_decay > 1:
        errors.append("--frontier-phase-confidence-decay must be in (0, 1]")
    if args.frontier_phase_recovery_enabled and not hasattr(cv2, "phaseCorrelate"):
        errors.append("OpenCV build does not include phaseCorrelate required by --frontier-phase-recovery")
    if args.frontier_v40_assoc_enabled and not hasattr(cv2, "phaseCorrelate"):
        errors.append("OpenCV build does not include phaseCorrelate required by --frontier-v40-assoc-gate")
    if str(args.frontier_ecc_motion_model).strip().lower() not in {"translation", "euclidean", "affine"}:
        errors.append("--frontier-ecc-motion-model must be one of: translation, euclidean, affine")
    if args.frontier_ecc_max_iterations <= 0:
        errors.append("--frontier-ecc-max-iterations must be > 0")
    if args.frontier_ecc_termination_eps <= 0:
        errors.append("--frontier-ecc-termination-eps must be > 0")
    if args.frontier_ecc_gauss_filt_size < 0:
        errors.append("--frontier-ecc-gauss-filt-size must be >= 0")
    if args.frontier_ecc_gauss_filt_size > 0 and args.frontier_ecc_gauss_filt_size % 2 == 0:
        warnings.append("--frontier-ecc-gauss-filt-size is even; runtime will round it to the next odd value")
    if args.frontier_ecc_min_correlation < -1 or args.frontier_ecc_min_correlation > 1:
        errors.append("--frontier-ecc-min-correlation must be in [-1, 1]")
