    g_v3.add_argument("--autofocus-scan-range", type=int, default=200)
    g_v3.add_argument("--autofocus-scan-steps", type=int, default=20)
    g_v3.add_argument("--autofocus-stability-window", type=int, default=5)
    g_v3.add_argument("--synth-aberration-levels", type=int, default=5)
    g_v3.add_argument("--synth-noise-levels", type=int, default=5)
